insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'bank', 0, $official_bank_source${"code":"ECO201","courseId":"da06b311-1382-53a8-8057-d3513764c222","seedActor":"00000000-0000-4000-8000-000000000042","actor":"00000000-0000-4000-8000-000000000043","bankCount":820,"shell":{"contentKey":"introduction-microeconomics","titles":["Introduction to Microeconomics"],"level":"200-level","semesters":["first-semester"]}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 1, $official_bank_source${"itemId":"01473ba7-6c53-5476-ad78-d3cf016e0ce0","questionId":"eb718e75-1653-5db6-bb45-7ba8c0ee4fce","sourceKey":"bank:ECO201:E201-0001","payload":{"prompt":"According to Adam Smith, everyday actions in a free market are motivated by ______.","options":["Invisible hand","Market forces","pricing","Self-interest"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"Adam Smith argued that in a free market people go about their everyday buying, selling and working out of self-interest, each trying to do the best for themselves. The invisible hand in option A is not the motive itself; it is his name for the way all these self-interested actions end up coordinated, as if guided, to benefit society. Market forces and pricing (options B and C) are the mechanism through which this happens, not what motivates individuals."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 2, $official_bank_source${"itemId":"5e8d3f0f-b7fc-5ae2-8ba9-00d1fdc39434","questionId":"7759a06f-8b6a-5fcd-823b-772c03fcd1e3","sourceKey":"bank:ECO201:E201-0002","payload":{"prompt":"Microeconomics knowledge underlines the saying that we all live in a world ______.","options":["Filled with wants","Filled with scarcity","Filled with rent","Filled with riches"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Microeconomics starts from scarcity: our wants are unlimited but the resources to satisfy them are limited, so we must make choices. Option A (wants) is only half the story, because wants alone would not create an economic problem if resources were unlimited. Rent and riches (options C and D) have nothing to do with this basic idea."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 3, $official_bank_source${"itemId":"6d80df41-259f-5b4a-be86-6777477a7012","questionId":"36a8234a-2441-5628-b028-7606ce876b98","sourceKey":"bank:ECO201:E201-0003","payload":{"prompt":"______ measures the choice of building roads that Governor Ambode gave up many years ago.","options":["Waste of public funds","Public cost","Opportunity sacrificed","Opportunity cost"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"Opportunity cost is the value of the next best alternative given up when a choice is made, so the roads the governor did not build measure the opportunity cost of what he chose instead. Option C, 'opportunity sacrificed', sounds similar but is not the economic term. Options A and B are not measures of a forgone alternative at all."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 4, $official_bank_source${"itemId":"2bb296c0-9da2-5181-bd72-f5cee9336bd2","questionId":"1004424f-07f4-5f41-807f-8757494dae60","sourceKey":"bank:ECO201:E201-0006","payload":{"prompt":"When resources are organised to produce the maximum output possible, it is known as ______.","options":["production","optimality","efficiency","Market behaviour"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Efficiency means organising resources so that the maximum possible output is obtained from them, with nothing wasted. Production (option A) is simply the act of making goods, whether efficient or not. Optimality (option B) is a broader idea about the best overall outcome, and market behaviour (option D) is unrelated."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 5, $official_bank_source${"itemId":"36cd2458-ea45-5507-a7ce-96e0dd11ba64","questionId":"859f869e-ff13-5d18-85b7-7246fd7f8d7f","sourceKey":"bank:ECO201:E201-0007","payload":{"prompt":"Several rich countries are immune to scarcity.","options":["True always","True sometimes","False always","False sometimes"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Scarcity affects every country, rich or poor, because human wants are unlimited while resources are always limited, so the statement is always false. Rich countries may have more resources, but they still have to choose between competing uses, which is exactly what scarcity means. Options A, B and D all suggest that some countries can escape scarcity at some point, which never happens."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 6, $official_bank_source${"itemId":"ad8c49e7-b440-55f4-9663-08be7b278b09","questionId":"53d02ead-d6af-5925-8b6f-0e1137f3f404","sourceKey":"bank:ECO201:E201-0008","payload":{"prompt":"______ explains why Yaba Local Government Area Council gave up some projects in order to provide what the people wants.","options":["Election","Resource constraints","People's wish","Loyalty constraint"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Resource constraints mean a council has limited funds and resources, so providing some projects forces it to give others up. This is the problem of scarcity and choice in action. Elections, people's wishes and loyalty (options A, C and D) may influence which projects are chosen, but they do not explain why some must be given up."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 7, $official_bank_source${"itemId":"3048a3ff-0a87-5c77-84ed-43c442442d70","questionId":"ce4e2930-3a7c-5f68-8078-9d140d62d8d6","sourceKey":"bank:ECO201:E201-0011","payload":{"prompt":"An economy that behaves almost as if it is guided by some power is known as ______.","options":["Superpower economy","Free market economy","Perfect market economy","Imperfect market economy"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"A free market economy works as if guided by an invisible power: without any central planner, prices coordinate the self-interested decisions of millions of buyers and sellers. Option C, perfect market economy, is not a standard term for this idea, and option D refers to markets with imperfections. A 'superpower economy' (option A) is about a country's global strength, not how its markets work."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 8, $official_bank_source${"itemId":"164caa9b-4cfe-5ed6-acd6-a79d572ffc10","questionId":"cfedbdcc-f243-521d-97aa-61508e979695","sourceKey":"bank:ECO201:E201-0013","payload":{"prompt":"Which of the following cost highlights the choice that you must make relative to the alternatives given up for your academic excellence?","options":["Private cost","Fixed cost","Opportunity cost","Social cost"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Opportunity cost is the value of the best alternative you give up when you make a choice, such as the leisure or other activities you sacrifice to achieve academic excellence. Private cost (option A) and social cost (option D) refer to who bears a cost, not to alternatives forgone. Fixed cost (option B) is a production cost that does not change with output, so it has nothing to do with choosing between alternatives."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 9, $official_bank_source${"itemId":"807a8952-16f3-5b31-b0fd-6409c933b86f","questionId":"a4f6c4b7-c681-5259-868c-61bc4bb0a4ab","sourceKey":"bank:ECO201:E201-0016","payload":{"prompt":"In any given market system, people respond to the same ______.","options":["Set of commodity","Set of prices","Set of regulations","Set of market forces"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"In a market system all buyers and sellers face and respond to the same set of prices, and these prices signal what to produce and how much to buy. Market forces (option D) are demand and supply, which create those prices; people react to the price signals themselves. Commodities and regulations (options A and C) differ across people and markets."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 10, $official_bank_source${"itemId":"b02d3218-ce78-5bdf-8470-aac6049d16f0","questionId":"fa54dcc3-8832-570e-8dee-71881ebff57c","sourceKey":"bank:ECO201:E201-0017","payload":{"prompt":"A typical economy has four resources, namely ______.","options":["Land, labour, capital, & entrepreneur","Air, water, land, & golds","Natural, physical, air, & technology","All of the above"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"The four factors of production are land, labour, capital and the entrepreneur (entrepreneurship), which organises the other three. Option B is a list of natural items, not the factors of production, and option C mixes unrelated categories. Since only option A is correct, option D, 'all of the above', is wrong."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 11, $official_bank_source${"itemId":"faca7dc6-83b2-597b-a8ba-a164759c06ca","questionId":"a2a3c19f-7810-5cc2-844b-2cf5c22a87d9","sourceKey":"bank:ECO201:E201-0019","payload":{"prompt":"In microeconomics, ______ is interpreted as \"all other things are held constant.\"","options":["Ceteris pardon me","centeris paribus","ceteris paribus","ceteris pardonibus"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Ceteris paribus is Latin for 'other things being equal' and is used to hold every other influence constant while we study the effect of one variable. Options B and D are misspellings, and option A is a joke version of the phrase."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 12, $official_bank_source${"itemId":"1e29aa8d-b02a-58eb-ae40-55bae24206c2","questionId":"ed7ea8b2-849e-55fc-b6be-d51745cfd3ba","sourceKey":"bank:ECO201:E201-0026","payload":{"prompt":"Variables classified according to whether the factors that determine them come from inside or outside the model are best described as ______ and ______ variables.","options":["Independent and dependent","Endogenous and exogenous","Dependent and exogenous","Endogenous and dependence"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Variables are classified as endogenous when they are determined within the model (for example, equilibrium price and quantity) and exogenous when they are determined outside it and simply taken as given (for example, weather or government policy). Option A, independent and dependent, describes the direction of a relationship in an equation, not where a variable's determinants come from. Options C and D mix the two classifications."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 13, $official_bank_source${"itemId":"3c693602-ad18-5bbc-b440-f8b6248e0f8f","questionId":"3a2acaa6-234b-54c2-a244-9f49f83265dc","sourceKey":"bank:ECO201:E201-0035","payload":{"prompt":"The assumptions on which the production possibility frontier is based include the following except ______","options":["Resources are sufficient for all production","Resources are limited in supply","Resources are fully utilized","Resources are used on just two commodities"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"The production possibility frontier assumes resources are limited, fully employed and used to produce only two goods; it would make no sense if resources were sufficient for all production, because then there would be no scarcity and no trade-off. Options B, C and D are all standard assumptions of the frontier."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 14, $official_bank_source${"itemId":"444001e5-24c6-5a1c-a66f-548ee2bdfff8","questionId":"3a4b821f-0a2f-5d46-bf2b-1b59b9da8ca9","sourceKey":"bank:ECO201:E201-0042","payload":{"prompt":"Market failure occurs when ______.","options":["The market operates efficiently without government intervention","The market cannot allocate resources efficiently","Government intervention is not necessary","There is perfect competition in the market"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Market failure happens when the free market, left on its own, fails to allocate resources efficiently, for example because of externalities or public goods. Options A and C describe the opposite situation, where the market works well without help. Option D, perfect competition, is the case in which markets are most efficient, not where they fail."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 15, $official_bank_source${"itemId":"d18b4a19-f7fb-52f4-9e11-42e96547c6f4","questionId":"bb109d75-15cc-5b96-97aa-f86faaa8feab","sourceKey":"bank:ECO201:E201-0051","payload":{"prompt":"Which of the following best describes the concept of opportunity cost in economics? ______.","options":["The monetary value assigned to the utility derived from a commodity","The total time or money invested in producing a commodity","The value of the next best alternative that is forgone when a choice is made","The cost incurred in retraining resources to achieve optimal production"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Opportunity cost is the value of the next best alternative you give up when you make a choice, because scarce resources used for one thing cannot be used for another. For example, the time you spend at a party is time you could have spent reading for an exam. Option B describes the total amount spent on production, which is an accounting cost rather than what is sacrificed, and option A describes the money value of utility, which is a different idea."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 16, $official_bank_source${"itemId":"696256a4-509f-5897-93c7-8b835fb3b3fc","questionId":"4330f565-9bde-5145-856a-425cf8845608","sourceKey":"bank:ECO201:E201-0101","payload":{"prompt":"Which of the following is an example of a capital input?","options":["Money.","Shares of stock","Long-term bonds.","A hammer."],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"Capital as a factor of production means man-made goods used to produce other goods, such as tools, machines and buildings, so a hammer is a capital input. Options A, B and C are financial assets: money, shares and bonds are claims used to buy or finance inputs, not inputs that physically take part in production."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 17, $official_bank_source${"itemId":"3c329e8c-b523-5f26-84d6-d19719c3d87a","questionId":"6c636d29-417f-53eb-b2c1-67c118d7af5c","sourceKey":"bank:ECO201:E201-0102","payload":{"prompt":"Which of the following is an example of an intermediate product?","options":["A personal computer","A barrel of crude oil.","A sports car.","A house."],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"An intermediate product is a good that is used up as an input in producing another good, and crude oil is refined into petrol, diesel and other products. Options A, C and D are normally bought by final users for their own use, so they are final goods rather than intermediate ones."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 18, $official_bank_source${"itemId":"0554e04c-aad4-59aa-b57a-5c376dd33a42","questionId":"357173bf-e8cc-500f-b6c9-eb7394ec71f6","sourceKey":"bank:ECO201:E201-0256","payload":{"prompt":"The curve showing the different combinations of goods that an economy can produce with its given resources is known as:","options":["Indifference curve","Production possibility curve","Revealed preference curve","None of these"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"A production possibility curve shows the maximum combinations of two goods an economy can produce when it uses all its resources fully and efficiently, so it highlights scarcity, choice and opportunity cost. Option A, the indifference curve, shows combinations of goods that give a consumer equal satisfaction, not production possibilities. Option C relates to consumer choices revealed through purchases."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 19, $official_bank_source${"itemId":"a061e1fa-6dcd-5a58-bcb7-f8f271b8a7ea","questionId":"bdbe2671-46f8-5dd7-9eac-612433527a18","sourceKey":"bank:ECO201:E201-0259","payload":{"prompt":"In a free enterprise economy, the problems of what, how and for whom to produce are solved by :","options":["A Planning Committee","The price mechanism","The Planning Commission","None of these"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"In a free enterprise economy, the questions of what, how and for whom to produce are answered by the price mechanism, the free interaction of demand and supply in markets. Prices signal what consumers want, guide firms on how to produce at least cost, and decide who can afford the output. Options A and C describe central planning bodies, which belong to a planned economy rather than a free enterprise one."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 20, $official_bank_source${"itemId":"39a141ef-c16b-5fcc-a534-72f199510f23","questionId":"d7a29567-32ed-5428-8b5a-a87bc17961f6","sourceKey":"bank:ECO201:E201-0263","payload":{"prompt":"The fundamental problem faced by an economy is one of:","options":["Exchange","Decision making by the government","Economic welfare","Scarcity of resources and multiplicity of wants"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"Every economy faces the basic problem that human wants are many and unlimited while the resources to satisfy them are scarce, so choices must be made. Exchange (option A) and government decisions (option B) are ways of dealing with the problem, not the problem itself, and economic welfare (option C) is a goal rather than the root problem."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 21, $official_bank_source${"itemId":"6b59cd03-21dd-52d6-8252-631ce036dc4a","questionId":"4ac4fb76-8cd8-5da4-a67f-864e8b31aeee","sourceKey":"bank:ECO201:E201-0273","payload":{"prompt":"Microeconomic theory studies how a free enterprise economy determines:","options":["The price of goods","The price of services","The price of resources","All of these"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"Microeconomics explains price determination in individual markets, and this covers the prices of goods, the prices of services and the prices of resources such as wages, rent and interest (factor pricing). Options A, B and C are each only part of the picture, so D is the complete answer."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 22, $official_bank_source${"itemId":"6ed0ae85-7f9f-553c-b4f1-e416497fb9e7","questionId":"4b7e3fe1-2749-51cc-9035-d2aaef0f4dd5","sourceKey":"bank:ECO201:E201-0274","payload":{"prompt":"Which aspect of taxation involves normative economics?","options":["The incidence of the tax","The fairness of the tax","The effect of the tax on incentives to work","All of the above"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Normative economics deals with value judgements about what ought to be, and whether a tax is fair is a matter of opinion and values. The incidence of a tax (option A) and its effect on incentives to work (option C) are positive questions, because they can be checked against facts and evidence. That is why D is wrong too."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 23, $official_bank_source${"itemId":"aa803162-cc46-5a86-9e40-92f82fbdfce9","questionId":"ae7534c5-e4ba-5a5d-8df0-0eb40b0f20dd","sourceKey":"bank:ECO201:E201-0275","payload":{"prompt":"Microeconomics deals primarily with:","options":["Comparative statics, general equilibrium and positive economics","Comparative statics, partial equilibrium and normative economics","Dynamics, partial equilibrium and positive economics","Comparative statics, partial equilibrium and positive economics"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"Microeconomics mainly compares equilibrium positions before and after a change (comparative statics), looks at one market at a time while holding other things constant (partial equilibrium), and explains how the economy actually works (positive economics). Option A is wrong because general equilibrium looks at all markets together, option B is wrong because the main focus is positive rather than normative, and option C is wrong because the time path of adjustment (dynamics) is not its main concern."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 24, $official_bank_source${"itemId":"e1aed81d-bd7e-511e-b9fe-cb1ede52ff27","questionId":"5037484a-8a57-5fd8-aa8f-0dfe180e7d2d","sourceKey":"bank:ECO201:E201-0276","payload":{"prompt":"Which of the following is incorrect?","options":["Microeconomics is concerned primarily with the problem of what, how and for whom to produce","Microeconomics is concerned primarily with the economic behaviour of individual decision-making units when at equilibrium","Microeconomics is concerned primarily with the time path and processes by which one equilibrium position evolves into another","Microeconomics is concerned primarily with comparative statics rather than dynamics"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Statement C is the incorrect one: the time path and process by which one equilibrium moves to another is the subject of dynamics, and microeconomics is mainly concerned with comparative statics, as option D correctly says. Options A and B are also correct descriptions, since microeconomics deals with what, how and for whom to produce and with the behaviour of individual households and firms in equilibrium."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 25, $official_bank_source${"itemId":"505d9bce-bd00-5f4d-b796-86d21c0dc9de","questionId":"8dce168c-eca9-5f8f-8ad6-fbbc373433bd","sourceKey":"bank:ECO201:E201-0277","payload":{"prompt":"Which of the following statements is most closely associated with general equilibrium analysis?","options":["Everything depends on everything else","The equilibrium price of a factor depends on the balancing of the forces of demand and supply for that factor","The equilibrium price of a good or service depends on the balancing of the forces of demand and supply for that good or service","None of these"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"General equilibrium analysis studies all markets together and recognises that they are interconnected, so a change in one market affects prices and quantities in others - in short, everything depends on everything else. Options B and C describe price being set by demand and supply in a single market, which is partial equilibrium analysis."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 26, $official_bank_source${"itemId":"8d969067-13ee-53f6-a83b-094dd94e7e53","questionId":"1fbcba46-473f-583f-86d2-234f3abad390","sourceKey":"bank:ECO201:E201-0278","payload":{"prompt":"The meaning of the word 'economic' is most closely associated with the word:","options":["Free","Scarce","Unlimited","Unrestricted"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Economics exists because resources are scarce relative to wants, so anything described as 'economic' involves scarcity and the need to choose. Options A, C and D (free, unlimited, unrestricted) describe the opposite situation, where there would be no economic problem to solve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 27, $official_bank_source${"itemId":"d697fb0f-fb03-54d7-b27d-6d48b02342de","questionId":"70897da8-0b1f-50d9-9abc-8c46cc0b4260","sourceKey":"bank:ECO201:E201-0280","payload":{"prompt":"Microeconomics studies the decision making behavior of:","options":["Society as a whole","An individual or household","The central bank in setting the money supply","Economy as a whole"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Microeconomics studies the decisions of individual economic units, such as a consumer, a household or a single firm. Options A and D (society or the economy as a whole) describe macroeconomics, and option C, the control of the money supply, is a macroeconomic policy question rather than individual decision making."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 28, $official_bank_source${"itemId":"3f2bc06c-599c-5269-aedd-fc16b0ccfa60","questionId":"702eea32-7bbc-518f-8a6e-41f604f43f70","sourceKey":"bank:ECO201:E201-0282","payload":{"prompt":"A function refers to :","options":["The demand for a commodity","The supply of a commodity","The demand and supply of a commodity service or resource","The relationship between one dependent variable and one or more independent variables."],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"A function expresses the relationship between one dependent variable and one or more independent variables, for example quantity demanded depending on own price, income and tastes. Options A, B and C are particular examples where functions are used, but they do not define what a function is."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 29, $official_bank_source${"itemId":"5a6846a7-39c1-5505-bfec-8c0ec3b4294e","questionId":"d8534ed3-bd29-5fb7-85ef-3be945b4436d","sourceKey":"bank:ECO201:E201-0284","payload":{"prompt":"The subject matter of economics is the study of:","options":["Wealth","Welfare","Scarcity","Scarcity and Choice"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"Economics studies how people make choices in using scarce resources to satisfy unlimited wants, so its subject matter is scarcity and choice together. Option C, scarcity alone, is only half of the idea, because it is the need to choose that scarcity creates which economics analyses. Options A and B, wealth and welfare, are older and narrower views of the subject."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 30, $official_bank_source${"itemId":"85ee15b7-8b5d-58cf-94ca-8f83f346639f","questionId":"007c80da-8328-5577-991f-15a1f54b2c44","sourceKey":"bank:ECO201:E201-0287","payload":{"prompt":"Microeconomics deals with:","options":["The theory of factor pricing","The theory of product pricing","The theory of economic welfare","All the above"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"Microeconomics covers the pricing of products, the pricing of factors of production (wages, rent, interest and profit) and welfare economics, which asks whether resources are allocated efficiently. Since A, B and C all fall within its scope, D is the correct answer."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 31, $official_bank_source${"itemId":"77230a20-768e-5c3c-ad97-b1365f48a622","questionId":"afb94ced-9d6d-5e5f-bc33-1501a02015a3","sourceKey":"bank:ECO201:E201-0295","payload":{"prompt":"A market:","options":["Necessarily refers to a meeting place between buyers and sellers","Does not necessarily refer to a meeting place between buyers and sellers","Extends over the entire nation","Extends over a city."],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"In economics, a market is any arrangement that brings buyers and sellers into contact so they can trade, whether face to face, by phone or online. So it does not have to be a physical meeting place. Option A is wrong because many markets, such as online or foreign exchange markets, have no single location, and options C and D wrongly tie a market to a particular area when its extent depends on the good being traded."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 32, $official_bank_source${"itemId":"acb18849-18c7-570d-abcb-b03f3661c71c","questionId":"3d40f414-0b82-50bb-aab4-ec84e8123e02","sourceKey":"bank:ECO201:FND-001","payload":{"prompt":"The branch of economics that studies the behaviour of individual economic agents such as households and firms, and how they make decisions about the allocation of scarce resources, is called","options":["Econometrics","Microeconomics","Macroeconomics","Development economics"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Microeconomics looks at the small units of the economy: individual households, consumers and firms and how they allocate scarce resources. Option C, macroeconomics, studies the economy as a whole, while A (econometrics) is the use of statistics to test economic theories."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 33, $official_bank_source${"itemId":"096d5e6a-198f-5522-ba6c-34e071c6bc4a","questionId":"750969fa-0439-5f70-95fc-0d75bd81533f","sourceKey":"bank:ECO201:FND-002","payload":{"prompt":"In microeconomics, attention is focused mainly on","options":["The preparation of national income accounts and the balance of payments","The total output, general price level and total employment of the whole economy","Specific markets and how demand and supply determine prices, production and consumption","The control of money supply and interest rates by the central bank"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Microeconomics concentrates on individual markets and the way demand and supply in them fix prices, output and consumption. Options B, A and D all deal with aggregates of the whole economy or with monetary policy, which are macroeconomic matters."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 34, $official_bank_source${"itemId":"4b9e6cea-9942-5f1a-9d7c-f31e9370d127","questionId":"a055b359-8274-508a-b42d-356b2e08052c","sourceKey":"bank:ECO201:FND-003","payload":{"prompt":"Which of the following is a microeconomic question?","options":["Why did Nigeria's inflation rate rise last year?","What determines the price of tomatoes in Mile 12 market?","What is the national rate of unemployment in Nigeria?","How fast did Nigeria's real GDP grow this year?"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"The price of one commodity in one market is a typical microeconomic question because it concerns an individual market. Options A, C and D concern economy-wide aggregates (the general price level, total unemployment and national output), which belong to macroeconomics."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 35, $official_bank_source${"itemId":"167e7898-d5e6-5171-9808-1027bd74fc14","questionId":"95d47a4a-8935-522f-8a78-880cb6cd63d8","sourceKey":"bank:ECO201:FND-004","payload":{"prompt":"Which of the following is NOT a microeconomic issue?","options":["Pricing decision of a bakery in Yaba","A household's demand for rice","Determination of the general price level of the whole economy","Wages paid in the market for bricklayers"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"The general price level of the whole economy is an aggregate, so it is studied in macroeconomics. Options A, B and D each refer to a single firm, a single household or a single market, which is exactly what microeconomics studies."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 36, $official_bank_source${"itemId":"34285375-12bb-5a4e-b17c-e7030644e00b","questionId":"d7871c1e-8fc8-5d58-ae09-370f1fb4a822","sourceKey":"bank:ECO201:FND-005","payload":{"prompt":"Because it deals largely with how the prices of goods and factors are determined, microeconomics is also commonly called","options":["Growth theory","Income theory","Price theory","Employment theory"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Microeconomics is often called price theory because explaining how prices of individual goods and factors are determined is at its centre. Income theory (option B) is a name associated with macroeconomics, which explains national income and employment, and A refers to the study of long-run growth of the whole economy."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 37, $official_bank_source${"itemId":"8e82cd9f-34a9-562d-a6ca-bb30558caa40","questionId":"083682ef-e31b-54e3-97f8-d08cb9cb080e","sourceKey":"bank:ECO201:FND-006","payload":{"prompt":"Which of the following is a role of microeconomics?","options":["Examining how firms decide what to produce, how much to produce and at what cost","Measuring the gross domestic product of a country","Setting the target for the overall inflation rate","Recording a country's trade with the rest of the world in the balance of payments"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"Microeconomics studies how firms decide what and how much to produce and at what cost. Options B, C and D deal with national aggregates and economy-wide policy, which belong to macroeconomics."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 38, $official_bank_source${"itemId":"b4d4ba77-b822-574b-b8c2-e0f026abd2c4","questionId":"b60e99ec-6afb-5335-8e60-3c0e8d9b5e85","sourceKey":"bank:ECO201:FND-007","payload":{"prompt":"An economist studies how buyers and sellers of soft drinks in Lagos adjust their purchases and output after the government introduces a N10-per-litre tax on sugary drinks. This study best illustrates which role of microeconomics?","options":["Identifying situations where markets fail to allocate resources efficiently","Studying how different market structures affect pricing and output","Explaining how scarce resources are allocated across the whole economy","Assessing how individuals and firms respond to taxes, subsidies, price controls or regulations"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"The study is about how people and firms react to a tax, which is the role of assessing responses to taxes, subsidies, price controls and regulations. Option A would apply if the focus were on a market that misallocates resources, and option B would require comparing markets with different numbers of sellers; neither is the focus here."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 39, $official_bank_source${"itemId":"515a29a6-24ed-584f-8333-5f090b9fe8d7","questionId":"af2be2d6-86db-55e5-9752-c7721b7f587f","sourceKey":"bank:ECO201:FND-008","payload":{"prompt":"A cement factory in Ogun State pours waste into a river used by nearby farmers, and the cost of the damage is not reflected in the price of cement. Studying such a case falls under which role of microeconomics?","options":["Identifying situations where markets fail to allocate resources efficiently","Explaining how prices are determined in a competitive market","Predicting demand patterns of consumers","Understanding how consumers choose what goods to buy"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"When the price of cement leaves out the damage done to farmers, the market is not allocating resources efficiently, which is a market failure. Option B is about normal price determination, while C and D concern consumer demand and choices, which are not the issue in this case."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 40, $official_bank_source${"itemId":"1cb68f90-5cca-5540-a6d2-33fab1168301","questionId":"ee0a6e98-c9c8-5549-aae1-6c5b1cb5b196","sourceKey":"bank:ECO201:FND-009","payload":{"prompt":"Which of the following is NOT within the scope of microeconomics?","options":["Production and costs","Factor pricing and distribution","Consumer behaviour","Determination of national income and aggregate employment"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"National income and aggregate employment are totals for the whole economy, so they belong to macroeconomics. Consumer behaviour (option C), production and costs (option A) and factor pricing and distribution (option B) are all part of the scope of microeconomics."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 41, $official_bank_source${"itemId":"a4050fac-0c81-5b99-8e96-56cc8747b222","questionId":"de6a7f3c-093b-5f9f-996a-eb8dc4e53f54","sourceKey":"bank:ECO201:FND-010","payload":{"prompt":"Which of the following falls within the scope of microeconomics?","options":["Monetary policy and the control of inflation","Theory of the firm and market structure","Long-run growth of national output","Government budget deficits and national debt"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"The theory of the firm and market structure studies how individual firms behave in different kinds of markets, so it is a core part of microeconomics. Options A, D and C are concerned with the whole economy and belong to macroeconomics."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 42, $official_bank_source${"itemId":"0e691d80-0979-5fc4-8cb1-636b2a91f985","questionId":"23f964c3-cac2-5138-8df7-d76c520d6730","sourceKey":"bank:ECO201:FND-011","payload":{"prompt":"The part of microeconomics that explains how wages, rent, interest and profit are determined and how income is shared among the owners of factors of production is","options":["Factor pricing and distribution","Production and costs","Welfare economics","Consumer behaviour"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"Factor pricing and distribution explains the rewards to labour, land, capital and entrepreneurship and how income is shared among them. Option C, welfare economics, judges whether resource allocation is efficient and improves well-being, and option B studies how output relates to inputs and costs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 43, $official_bank_source${"itemId":"fa1dc049-9db2-5fae-b556-ddb235fbc5f3","questionId":"f67ecdcb-76b8-59a1-a46f-bfebb6872a07","sourceKey":"bank:ECO201:FND-012","payload":{"prompt":"The manager of a bottled-water company uses estimates of demand and production costs to choose the price and output that maximise profit. This shows the relevance of microeconomics as","options":["A tool for predicting and managing market failures","A means of understanding market structures","A guide to policy formulation and evaluation","A decision-making tool"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"Here a firm is using demand and cost analysis to make its own business choice, which is the use of microeconomics as a decision-making tool. Option C refers to government using microeconomics to design and judge policies, and option A is about markets that misallocate resources, neither of which describes a manager setting price and output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 44, $official_bank_source${"itemId":"f284a1f5-d51d-5414-b304-011ec8c86706","questionId":"a903f47f-e37d-5895-94d6-17be42d2d157","sourceKey":"bank:ECO201:FND-013","payload":{"prompt":"The basic economic problem that arises because human wants are unlimited while the resources available to satisfy them are limited is","options":["Choice","Scarcity","Market failure","Opportunity cost"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Scarcity means that resources are limited relative to unlimited wants. Choice (option A) and opportunity cost (option D) are consequences of scarcity rather than the problem itself, and market failure (option C) is when markets allocate resources inefficiently."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 45, $official_bank_source${"itemId":"568db6f8-a613-52ff-b526-fd5d6d4fb5f8","questionId":"add36d86-09ad-5e40-9a23-4c68d52a1ebb","sourceKey":"bank:ECO201:FND-014","payload":{"prompt":"Individuals, firms and governments must make choices mainly because","options":["Governments regulate economic activity","Money is used as a medium of exchange","Prices of goods are usually high","Resources are scarce relative to wants"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"Because resources are scarce compared with wants, not every want can be satisfied, so economic agents must choose among alternatives. Options B, C and A describe features of some economies, but choice would still be necessary without money, high prices or regulation as long as resources are scarce."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 46, $official_bank_source${"itemId":"c354a904-d338-5304-b390-d5a930e9c54e","questionId":"b4028289-a674-5509-a862-25b77308f19f","sourceKey":"bank:ECO201:FND-015","payload":{"prompt":"The value of the next best alternative forgone when a choice is made is called","options":["Sunk cost","Marginal cost","Total cost","Opportunity cost"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"Opportunity cost is the next best alternative given up when a choice is made. Marginal cost (option B) is the extra cost of producing one more unit, sunk cost (option A) is a cost already incurred that cannot be recovered, and total cost (option C) is the whole cost of producing a given output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 47, $official_bank_source${"itemId":"c2e3b0f2-c61b-50d2-aa47-be5849bf28d8","questionId":"519fa56f-921e-5f09-b011-c56d03bfcc11","sourceKey":"bank:ECO201:FND-016","payload":{"prompt":"Ada has N15,000. She can buy a scientific calculator, a pair of shoes or a cinema ticket with it, and she ranks them in that order: calculator first, shoes second, cinema third. If she buys the calculator, her opportunity cost is","options":["The cinema ticket","The pair of shoes","The calculator","The shoes and the cinema ticket together"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Opportunity cost is only the next best alternative given up, and Ada's second choice is the pair of shoes. The calculator (option C) is what she chose, not what she gave up, and option D wrongly adds all forgone alternatives instead of taking only the next best one."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 48, $official_bank_source${"itemId":"f6d6517d-373d-54b3-bc7e-70af9fe84ff6","questionId":"8da75715-17c2-5b4b-891f-9aeabb0efe04","sourceKey":"bank:ECO201:FND-017","payload":{"prompt":"Using all his land and labour, a farmer in Oyo State can produce either 40 bags of maize or 20 bags of cassava, with a constant rate of trade-off between them. What is the opportunity cost of producing one bag of cassava?","options":["2 bags of maize","0.5 bag of maize","40 bags of maize","20 bags of maize"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"Giving up 40 bags of maize to get 20 bags of cassava means each bag of cassava costs 40 / 20 = 2 bags of maize. Option B (0.5) is the opportunity cost of one bag of maize in terms of cassava, the inverse ratio, and options D and C use totals instead of dividing."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 49, $official_bank_source${"itemId":"ddb56b12-dbbc-5e42-88be-4a59fa171b14","questionId":"62f81b56-0428-5e5e-b6aa-164c5491d0a5","sourceKey":"bank:ECO201:FND-018","payload":{"prompt":"On an economy's production possibility curve, point A shows 10 units of cloth and 50 units of food, while point B shows 14 units of cloth and 42 units of food. Moving from A to B, the opportunity cost of each extra unit of cloth is","options":["2 units of food","8 units of food","4 units of food","0.5 unit of food"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"Moving from A to B gives 4 more units of cloth at the cost of 8 units of food, so each unit of cloth costs 8 / 4 = 2 units of food. Option D inverts the ratio, while options C and B give only the change in cloth or the total change in food rather than the cost per unit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 50, $official_bank_source${"itemId":"01a54ab1-6844-5a73-9293-702192381274","questionId":"db470b92-ac74-546f-8595-f85c91f1be9c","sourceKey":"bank:ECO201:FND-019","payload":{"prompt":"An economy's production possibilities are: P (0 cloth, 100 food), Q (10 cloth, 90 food), R (20 cloth, 70 food), S (30 cloth, 40 food), T (40 cloth, 0 food). Moving from R to S, the opportunity cost of one unit of cloth is","options":["4 units of food","2 units of food","1 unit of food","3 units of food"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"From R to S the economy gains 10 units of cloth and gives up 70 - 40 = 30 units of food, so one unit of cloth costs 30 / 10 = 3 units of food. Option B (2) is the cost between Q and R, option C (1) is between P and Q, and option A (4) is between S and T; the rising figures show increasing opportunity cost."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 51, $official_bank_source${"itemId":"2fedcb1c-5bfb-5c31-aa62-c82c1e96216e","questionId":"37fccd6e-016b-581e-bb92-cda7eaafc986","sourceKey":"bank:ECO201:FND-020","payload":{"prompt":"A point lying inside (below) an economy's production possibility curve indicates that","options":["The economy has experienced economic growth","Some resources are unemployed or used inefficiently","The output combination cannot be attained with present resources","The economy is producing efficiently with all resources fully employed"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"A point inside the PPC means the economy could produce more of at least one good without producing less of the other, so resources are idle or wasted. Option C describes a point outside the curve, option D describes a point on the curve, and growth (option A) is shown by the curve itself shifting outward."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 52, $official_bank_source${"itemId":"30d24026-d5b3-536a-b148-189952fb70de","questionId":"6e34e1c7-f36e-51f7-80d9-66d9983650ce","sourceKey":"bank:ECO201:FND-021","payload":{"prompt":"A combination of goods that lies outside (beyond) an economy's production possibility curve is","options":["Evidence of unemployed resources","Unattainable with the present resources and technology","Attainable and efficient","Attainable but inefficient"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Points beyond the PPC need more resources or better technology than the economy currently has, so they are unattainable for now. Options D and A describe points inside the curve, and option C describes points on the curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 53, $official_bank_source${"itemId":"85bec4a1-0f9e-5b80-bfc5-7d6152bf4320","questionId":"0efef968-17b8-5383-b7f4-05b4d7a14eec","sourceKey":"bank:ECO201:FND-022","payload":{"prompt":"A production possibility curve is usually concave to the origin (bowed outward) because","options":["Opportunity cost is constant along the curve","Resources are equally suited to producing both goods","Opportunity cost increases as more of one good is produced","Marginal utility diminishes as more of a good is consumed"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"As an economy shifts more resources into one good, it must use resources less suited to it, so each extra unit costs more of the other good; this increasing opportunity cost bows the curve outward. Options A and B would give a straight-line PPC, and option D is about consumer satisfaction, not production."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 54, $official_bank_source${"itemId":"1aad59bc-1f69-5dfc-b2fb-e7c53faa003c","questionId":"c2bd3f82-0f6d-547d-96c4-171ab052f237","sourceKey":"bank:ECO201:FND-023","payload":{"prompt":"Which of the following would shift Nigeria's production possibility curve outward?","options":["A change in consumers' tastes towards imported goods","A reduction in unemployment of existing resources","An improvement in technology used in production","A rise in the price of one of the goods"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Better technology (or more resources) raises the maximum output the economy can produce, so the whole PPC shifts outward. Option B moves the economy from a point inside the curve towards the curve without shifting it, and options A and D change what is demanded, not what can be produced."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 55, $official_bank_source${"itemId":"a727e275-52f8-5e51-ad82-53afe7ffdd62","questionId":"8e3d2e88-5e40-529d-b497-30f6116cc5f2","sourceKey":"bank:ECO201:FND-024","payload":{"prompt":"In economics, the phrase ceteris paribus means","options":["Other things being equal (held constant)","At the margin","In the long run","All variables change at the same time"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"Ceteris paribus means other things remain equal, so the economist changes one variable and holds all other influences constant. Option D is the opposite of the assumption, and options C and B refer to the time period and to small changes, which are different ideas."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 56, $official_bank_source${"itemId":"3edcc73f-6f6e-565d-881d-783be4b7cf40","questionId":"8e6d05cf-d9d5-52db-88dd-ce928ba0736d","sourceKey":"bank:ECO201:FND-025","payload":{"prompt":"\"If the price of garri rises, the quantity of garri demanded will fall, assuming consumers' income, tastes and the prices of other goods remain unchanged.\" The assumption at the end of this statement is known as the","options":["Comparative static assumption","Rationality assumption","Ceteris paribus assumption","Laissez-faire assumption"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Holding income, tastes and other prices unchanged so the effect of the price of garri alone can be seen is the ceteris paribus (other things being equal) assumption. Option B, rationality, is about consumers knowing what they want and maximising satisfaction, and option D, laissez-faire, is a policy of non-interference by government."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 57, $official_bank_source${"itemId":"100a6631-4579-5f26-820b-17b209bd4430","questionId":"094b62d2-3947-5dd1-bbc3-810068d75ecb","sourceKey":"bank:ECO201:FND-026","payload":{"prompt":"Which of the following is a positive economic statement?","options":["It is unfair that petrol prices are so high","Federal universities should charge lower school fees","The government ought to raise the minimum wage","An increase in the minimum wage will raise unemployment among unskilled workers"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"A positive statement describes what is or what will happen and can be tested against facts, as with the claim about the effect of the minimum wage on unemployment. Options C, A and B contain value judgements (\"ought\", \"unfair\", \"should\"), so they are normative."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 58, $official_bank_source${"itemId":"407c9978-db8b-5995-ac57-7b9c854aa4a1","questionId":"6428bc2a-ef54-54d0-993b-4e36f72fa637","sourceKey":"bank:ECO201:FND-027","payload":{"prompt":"Which of the following is a normative economic statement?","options":["A tax on cigarettes will reduce the quantity of cigarettes sold","Nigeria's inflation rate was higher in 2024 than in 2020","A fall in the price of rice will increase the quantity of rice demanded","The government should provide free healthcare for children under five"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"A normative statement expresses a value judgement about what ought to be, and the word \"should\" signals this. Options C, B and A are positive statements because each can be checked against evidence, whether or not it turns out to be true."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 59, $official_bank_source${"itemId":"bd1a9836-1c57-5f4f-b794-b4b8391c41ca","questionId":"2d8d2681-a18f-55c9-bbee-a6385bfba2c2","sourceKey":"bank:ECO201:FND-028","payload":{"prompt":"The type of economic analysis that studies an equilibrium position at a given point in time, without considering the process of change, is","options":["Dynamic analysis","Static analysis","General equilibrium analysis","Comparative static analysis"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Static analysis looks at one equilibrium as if frozen at a moment in time. Comparative static analysis (option D) compares two equilibria, and dynamic analysis (option A) traces the path of change over time; general equilibrium (option C) concerns the interdependence of all markets, not the treatment of time."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 60, $official_bank_source${"itemId":"9f25e80d-8a04-519c-91c5-5c7ec30ab51a","questionId":"2449981c-38d9-5775-a057-c7427871e027","sourceKey":"bank:ECO201:FND-029","payload":{"prompt":"Comparing the old equilibrium price and quantity of a good with the new equilibrium after a change in demand, without tracing the path between them, is called","options":["Dynamic analysis","Comparative static analysis","Partial equilibrium analysis","Static analysis"],"correctOption":1,"section":"Foundations of Microeconomics","explanation":"Comparative static analysis compares two equilibrium positions, before and after a change, without studying how the economy moves from one to the other. Static analysis (option D) looks at only one equilibrium, and dynamic analysis (option A) is the one that traces the time path of adjustment."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 61, $official_bank_source${"itemId":"2c831f61-4c54-55bc-9364-d7af61c34b9b","questionId":"6cdbc480-1bab-5aa3-964a-e9c92854d82c","sourceKey":"bank:ECO201:FND-030","payload":{"prompt":"After a ban on rice imports, an economist traces month by month how the price of local rice changes until it settles at a new equilibrium. This is an example of","options":["Normative analysis","Comparative static analysis","Dynamic analysis","Static analysis"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Tracing the time path of adjustment, period by period, from one equilibrium to another is dynamic analysis. Comparative statics (option B) would only compare the starting and final equilibria, and normative analysis (option A) involves value judgements about what ought to be."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 62, $official_bank_source${"itemId":"528f1ba5-82c3-5b1e-8400-633069243e6b","questionId":"698831d7-91ce-52a9-b934-0886117133d2","sourceKey":"bank:ECO201:FND-031","payload":{"prompt":"Analysis of a single market in isolation, assuming that conditions in all other markets remain unchanged, is called","options":["Partial equilibrium analysis","General equilibrium analysis","Macroeconomic analysis","Dynamic analysis"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"Partial equilibrium analysis studies one market on its own and uses the ceteris paribus assumption to hold other markets constant. General equilibrium analysis (option B) instead studies all markets together and the links between them, and dynamic analysis (option D) is about the time path of change."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 63, $official_bank_source${"itemId":"194a54bb-5efa-5d70-ba33-50a541c14ed5","questionId":"b7a76040-ad32-5d15-bf17-f3ff075cb144","sourceKey":"bank:ECO201:FND-032","payload":{"prompt":"The approach that studies the simultaneous determination of prices and quantities in all markets, taking account of their interdependence, is","options":["Partial equilibrium analysis","Static analysis","Comparative static analysis","General equilibrium analysis"],"correctOption":3,"section":"Foundations of Microeconomics","explanation":"General equilibrium analysis considers all markets at once and how a change in one affects the others. Partial equilibrium analysis (option A) looks at only one market and ignores these feedback effects, while options C and B describe how time is treated rather than how many markets are studied."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 64, $official_bank_source${"itemId":"e86acd81-e46e-5ea5-8979-84e25eeaa63c","questionId":"99b958ec-de0b-5c83-96ca-7e8c519b248f","sourceKey":"bank:ECO201:FND-033","payload":{"prompt":"An analyst studies how a new tax on bread affects the price and quantity of bread only, ignoring any effects on the markets for flour, butter and tea. The analyst is using","options":["Dynamic analysis","Normative analysis","Partial equilibrium analysis","General equilibrium analysis"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"Looking at the bread market alone while ignoring its links with related markets is partial equilibrium analysis. General equilibrium analysis (option D) would trace the effects on flour, butter, tea and other markets as well."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 65, $official_bank_source${"itemId":"e9eab836-6af1-5585-82d0-c32a5c0efd7c","questionId":"611d75df-b1f7-5a19-8c32-6796f4012692","sourceKey":"bank:ECO201:FND-034","payload":{"prompt":"The main difference between partial and general equilibrium analysis is that partial equilibrium analysis","options":["Ignores the feedback effects between markets, while general equilibrium analysis takes them into account","Is normative, while general equilibrium analysis is positive","Deals with the long run only, while general equilibrium analysis deals with the short run only","Studies all markets at once, while general equilibrium analysis studies one market"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"Partial equilibrium analysis isolates one market and assumes other markets are unaffected, while general equilibrium analysis allows for the interdependence and feedback among all markets. Option D reverses the two approaches, and options C and B confuse them with the time period and with positive versus normative economics."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 66, $official_bank_source${"itemId":"9d3ab596-a959-531c-82a1-c827e4ff3f5e","questionId":"57bd3a45-71d5-5e65-a90d-daabb1ce9ce6","sourceKey":"bank:ECO201:FND-035","payload":{"prompt":"The system by which prices, set by the free interaction of demand and supply, guide the allocation of resources in an economy is called the","options":["Market failure","Opportunity cost","Price mechanism","Command system"],"correctOption":2,"section":"Foundations of Microeconomics","explanation":"The price mechanism lets prices formed by demand and supply signal to buyers and sellers how resources should be used. A command system (option D) relies on government directives instead of prices, and market failure (option A) describes cases where markets do not allocate resources efficiently."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 67, $official_bank_source${"itemId":"4d06c59b-41ec-5894-b140-c56c3014b1fc","questionId":"2349e666-4d42-5d9a-a744-3a5a41e19134","sourceKey":"bank:ECO201:FND-036","payload":{"prompt":"An economist compares how a single electricity distribution company in an area sets its tariff with how many sellers of sachet water in the same area set their prices. This study mainly concerns","options":["How different market structures affect pricing and output decisions","How the general price level is determined","How opportunity cost is measured","How individuals respond to subsidies"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"Comparing a single seller with many sellers is a comparison of market structures and their effect on prices and output. Option D is about responses to subsidies, which are not involved, and option B is a macroeconomic question about the whole economy."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 68, $official_bank_source${"itemId":"dba54030-05f6-5eef-94cd-9ef68773611e","questionId":"e89c3b72-2f96-53c0-9576-2375c919beaa","sourceKey":"bank:ECO201:FND-037","payload":{"prompt":"The basic microeconomic concept that measures the responsiveness of quantity demanded or supplied to a change in one of its determinants, such as price, is","options":["Elasticity","Profit maximisation","Opportunity cost","Utility"],"correctOption":0,"section":"Foundations of Microeconomics","explanation":"Elasticity measures how strongly quantity demanded or supplied responds to a change in price, income or another determinant. Utility (option D) is the satisfaction from consumption, and profit maximisation (option B) is the assumed goal of the firm."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 69, $official_bank_source${"itemId":"86182ede-bb03-51ea-ab18-90806497325b","questionId":"12223b27-b6ad-529c-9bdc-2aa7855fe49b","sourceKey":"bank:ECO201:E201-0028","payload":{"prompt":"When is a consumer said to be rational?","options":["He seeks to maximize dissatisfaction","He knows the prices of goods and services","he knows his income limits","Options B & C"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"A rational consumer knows what he wants and has full knowledge of the prices of goods and services and of his own income, so both B and C apply. Option A is the opposite of rationality, since a rational consumer seeks to maximize satisfaction, not dissatisfaction. Choosing B or C alone leaves out one part of the consumer's knowledge."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 70, $official_bank_source${"itemId":"1f3cbb86-7f54-5d32-a372-271a08163b2d","questionId":"bb7ea850-85c4-59e6-a941-ad6fc0250f0c","sourceKey":"bank:ECO201:E201-0030","payload":{"prompt":"When a commodity is said to have utility, it means?","options":["It enables satisfaction","It can be consumed","It maximizes satisfaction","None of the above"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Utility is the want-satisfying power of a commodity, so saying a commodity has utility means it can give satisfaction. Option C goes too far, because utility does not require maximum satisfaction. Option B is not enough on its own, since being consumable does not guarantee satisfaction."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 71, $official_bank_source${"itemId":"5fb47359-20ae-5dce-8504-c14e5e291bc8","questionId":"e705d4ae-82ba-5d89-b290-28957b918827","sourceKey":"bank:ECO201:E201-0048","payload":{"prompt":"Given that the marginal utilities of two goods Z and Y are MUz and MUy respectively, and their prices are Pz and Py, if MUz/Pz is less than MUy/Py, a rational consumer will buy ______.","options":["More of Z and less of Y","More of Y and less of Z","Both Z and Y in equal amounts","The same amount of money on both Z and Y"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"When MUz/Pz is less than MUy/Py, the last naira spent on Y gives more satisfaction than the last naira spent on Z, so the consumer should buy more Y and less Z. As he does, MUy falls and MUz rises (diminishing marginal utility) until MUz/Pz = MUy/Py. Option A is the reverse, and options C and D ignore the condition for equilibrium."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 72, $official_bank_source${"itemId":"ba1408bb-9ad0-5822-9ba6-f9cc7adbcd32","questionId":"09126479-6b3d-51d8-9408-07f2614370aa","sourceKey":"bank:ECO201:E201-0050","payload":{"prompt":"When total utility increases, marginal utility is ______.","options":["Negative and increasing","Negative and declining","Zero","Positive and declining"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Total utility rises as long as each extra unit adds something positive, so marginal utility is positive, and by the law of diminishing marginal utility it is falling as consumption increases. Option C, zero, is the point where total utility reaches its peak, not where it is rising. Negative marginal utility (options A and B) makes total utility fall."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 73, $official_bank_source${"itemId":"5b49bebb-6925-5dc5-a4dc-b739de4fa1ea","questionId":"a1936a0e-6dba-51b1-9ec2-0adfe7235c5a","sourceKey":"bank:ECO201:E201-0061","payload":{"prompt":"When a consumer begins consuming a good, total utility typically: ______","options":["Falls immediately","Remains constant","Increases fast","Increases slowly"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The first units of a good give the highest marginal utility, so when a consumer starts consuming a good, total utility rises quickly. As more units are consumed, marginal utility diminishes and total utility rises more and more slowly until it peaks at the saturation point. Option D describes what happens later in consumption, not at the start, and options A and B would need marginal utility to be negative or zero from the first unit."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 74, $official_bank_source${"itemId":"3e303e16-53d7-588f-92dc-44cacb9cdc67","questionId":"db569db7-03d8-5a53-8c36-22f0ac3c5028","sourceKey":"bank:ECO201:E201-0062","payload":{"prompt":"The typical shape of the total utility curve is: ______","options":["Downward sloping","Upward sloping then bending downward","Horizontally bending","Vertically bending forward"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Total utility rises at first as more units are consumed, flattens out at the saturation point where marginal utility is zero, and then falls once marginal utility turns negative. That gives a curve that slopes upward and then bends downward. Option A ignores the rising portion, and options C and D are not shapes used to describe total utility."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 75, $official_bank_source${"itemId":"7b3e3e20-e5cf-5440-9a4c-91b86f612717","questionId":"f860385e-95de-5ba8-8249-e1d8041c5f4c","sourceKey":"bank:ECO201:E201-0063","payload":{"prompt":"Which of the following is correct? ______","options":["AU rises when MU < AU","AU falls when MU > AU","AU is constant when MU > AU","AU rises when MU > AU"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Average utility is pulled up whenever the extra unit adds more than the current average, so AU rises when MU > AU, is at its maximum when MU = AU, and falls when MU < AU. Options A and B state these relationships the wrong way round, and option C is wrong because AU cannot stay constant while MU is above it."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 76, $official_bank_source${"itemId":"aec5f008-38b4-5f3b-a7b0-295983071653","questionId":"68b4afa9-6488-5090-979f-e8872b0b3cca","sourceKey":"bank:ECO201:E201-0069","payload":{"prompt":"The cardinalist approach assumes that utility is: ______.","options":["Rankable in utils","Measurable in utils","Uncertain","No idea"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The cardinal approach assumes utility can be measured in numbers, using imaginary units called utils, so we can say one unit gives 10 utils and another 6 utils. Option A, ranking, describes the ordinal approach, which only orders bundles as preferred, indifferent or less preferred without measuring how much. Option C does not describe either approach."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 77, $official_bank_source${"itemId":"f0f4f9e9-b99a-5071-8029-47aea6c51044","questionId":"51519875-4b96-5a4e-8245-0eabf6a0e584","sourceKey":"bank:ECO201:E201-0071","payload":{"prompt":"When total utility increases at a decreasing rate, marginal utility is: ______","options":["Diminishing","Increasing","Constant","Negative"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Marginal utility is the extra satisfaction from one more unit, so it measures how fast total utility is rising. If total utility is increasing at a decreasing rate, each extra unit adds less than the one before, which means marginal utility is diminishing. Option B would make total utility rise faster and faster, and option D would make total utility fall."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 78, $official_bank_source${"itemId":"5c70ae0b-1b11-58db-a398-b593e5564769","questionId":"0f06368d-b3c8-51fa-8772-7fb57a5113e3","sourceKey":"bank:ECO201:E201-0072","payload":{"prompt":"When marginal utility is negative, total utility: ______","options":["Is increasing","Is constant","Is decreasing","Is at maximum"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Marginal utility is the change in total utility from one more unit, so a negative marginal utility means the extra unit actually reduces total satisfaction and total utility is falling. This happens after the saturation point. Option D, maximum total utility, occurs where marginal utility is zero, not negative."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 79, $official_bank_source${"itemId":"5192cb9e-6028-53b9-8a21-a4306a3b21c3","questionId":"3fa350a6-9dcf-54e6-bb4e-7ad144c9cf9b","sourceKey":"bank:ECO201:E201-0081","payload":{"prompt":"Total utility reaches its maximum when marginal utility is: ______","options":["Positive","Zero","Negative","Constant"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Total utility keeps rising as long as each extra unit adds positive satisfaction, and starts falling once marginal utility turns negative. It therefore reaches its maximum, the saturation point, where marginal utility is zero. Option A means total utility is still rising, and option C means it is already falling."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 80, $official_bank_source${"itemId":"09bd2c32-ce73-5ca2-b36c-d7c21596a603","questionId":"5e01c874-bd48-5cd6-bf01-6eba0bd47e16","sourceKey":"bank:ECO201:E201-0082","payload":{"prompt":"Average utility is defined as: ______","options":["TU x Q","TU / Q","MU x Q","MU / Q"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Average utility is total utility divided by the number of units consumed, AU = TU / Q. For example, if 4 units give 40 utils in total, average utility is 40 / 4 = 10 utils. Option A, TU x Q, has no economic meaning, and options C and D use marginal utility instead of total utility."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 81, $official_bank_source${"itemId":"28a9897c-bb39-5fcc-88bd-e332985b193b","questionId":"7fe09608-b58d-58c6-bc51-16f3e1775f85","sourceKey":"bank:ECO201:E201-0091","payload":{"prompt":"If a consumer continues consumption beyond the saturation point, total utility: ______","options":["Increases rapidly","Remains constant","Decreases","Becomes zero"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"At the saturation point marginal utility is zero and total utility is at its maximum. Consuming beyond it gives negative marginal utility, as each extra unit causes discomfort, so total utility decreases. Option B describes the saturation point itself, not what happens beyond it, and option A would need marginal utility to be high and positive."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 82, $official_bank_source${"itemId":"860091da-667a-5990-ac73-a334ec4aae42","questionId":"14500148-b634-5b99-807c-9c3d3ad4637c","sourceKey":"bank:ECO201:E201-0099","payload":{"prompt":"The cardinal theorists of consumer behaviour postulate consumer equilibrium is achieved when: ______.","options":["Indifference curve is tangent to the budget line","MU per unit of price is equal to zero","MU per unit of price is equal across goods","MU of every good is equal, whatever its price"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Cardinal theorists say a consumer buying several goods is in equilibrium when the marginal utility per naira spent is the same for every good, MUx/Px = MUy/Py. If one good gave more utility per naira, the consumer could do better by shifting spending towards it. Option D ignores prices: equal MUs only give equilibrium if the goods also cost the same. Option A is the ordinal (indifference curve) condition, and option B is wrong because MU per naira is generally positive at equilibrium, not zero."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 83, $official_bank_source${"itemId":"25aa8fd0-ed0a-5d38-abf1-ddba952b2db1","questionId":"925875b3-56ae-586d-8e0c-5593949472d4","sourceKey":"bank:ECO201:E201-0360","payload":{"prompt":"The want-satisfying power of a commodity is called:","options":["Satisfaction","Utility","Value","Marginal Utility"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Utility is the power of a commodity to satisfy a human want. Option A, satisfaction, is the result a consumer gets from using the good, not the power of the good itself, and option D, marginal utility, is only the extra utility from one more unit."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 84, $official_bank_source${"itemId":"d1edc55b-b5a8-5805-af5f-6cfe49b64dee","questionId":"bc9dbfad-624a-52ef-81f6-b0ec5dfb1c75","sourceKey":"bank:ECO201:E201-0361","payload":{"prompt":"Utility is the concept which is:","options":["Objective","Subjective","Both","None"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Utility is subjective because it depends on each person's tastes and feelings, so the same good can give very different satisfaction to different people. Option A is wrong because utility cannot be observed like weight or price; it exists in the mind of the consumer."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 85, $official_bank_source${"itemId":"87902251-3c22-53ba-af2f-809eda7abdd1","questionId":"4bf090ea-9fc7-593c-878b-a0ec5e563653","sourceKey":"bank:ECO201:E201-0362","payload":{"prompt":"Change in utility resulting from one unit change in consumption is called:","options":["Total Utility","Extra Utility","Marginal Utility","Average Utility"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Marginal utility is the change in total utility from consuming one more unit of a good: MU = change in TU / change in Q. Option A, total utility, is the overall satisfaction from all units consumed, and option B is not the standard name used in economics."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 86, $official_bank_source${"itemId":"ceeb0246-7921-5c6b-ae39-51d0662ab4b9","questionId":"5c384ce2-ff5b-5ad3-a7b5-ef708a47f344","sourceKey":"bank:ECO201:E201-0365","payload":{"prompt":"Saturation point is the point where:","options":["TU = 0","MU = 0","MU is +ve","TU = 1"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The saturation point is where the consumer has had so much of a good that one more unit adds no satisfaction at all, so MU = 0 and total utility is at its maximum. Option A is wrong because TU is at its highest, not zero, at this point, and option C describes the stage before saturation."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 87, $official_bank_source${"itemId":"8fd1dc3b-c0e1-5128-bbee-7c5f7d389851","questionId":"f89722d9-243a-52af-8b5d-62c13376f349","sourceKey":"bank:ECO201:E201-0366","payload":{"prompt":"Measurable utility is the postulate of:","options":["Neo-Classical school","Ordinalist school","Behaviourist school","Keynesians"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The idea that utility can be measured in cardinal units such as utils comes from the neo-classical economists, especially Alfred Marshall, whose approach is known as the cardinal utility theory. Option B is wrong because the ordinalists argued that utility can only be ranked, not measured."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 88, $official_bank_source${"itemId":"08df9e77-9fa2-56df-a8ea-f32732c13f23","questionId":"18d1f360-f671-5fd2-af3d-4a22420ec88b","sourceKey":"bank:ECO201:E201-0367","payload":{"prompt":"Which of the following is Gossen's first law:","options":["Law of Diminishing Marginal Utility","Law of Equi Marginal Utility","Law of substitution","Law of Diminishing Returns"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Gossen's first law is the law of diminishing marginal utility: as a person consumes more units of a good, the extra satisfaction from each additional unit falls. Option B, the law of equi-marginal utility (MUx/Px = MUy/Py), is known as Gossen's second law."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 89, $official_bank_source${"itemId":"a848c485-b300-5fa8-b75c-1ce798b10877","questionId":"00922caf-ee27-57b0-9c13-000f6a07bad1","sourceKey":"bank:ECO201:E201-0372","payload":{"prompt":"Which of the following is a cardinalist approach to demand analysis:","options":["Marshallian utility analysis","Indifference Curve Analysis","Revealed Preference Theory","None of these"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Marshallian utility analysis assumes utility can be measured in cardinal numbers (utils), so it is the cardinalist approach. Option B, indifference curve analysis, is ordinal because it only ranks combinations of goods, and option C, revealed preference, is based on observed choices rather than measured utility."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 90, $official_bank_source${"itemId":"9818c442-0d20-57d3-9835-8fedb07d68ca","questionId":"f75c18e3-5ee6-5c5e-8b0b-12975853e719","sourceKey":"bank:ECO201:E201-0456","payload":{"prompt":"A consumer finds that MUx/Px > MUy/Py. What should the consumer do to attain equilibrium?","options":["Buy less of X and more of Y until MUx/Px = MUy/Py","Buy more of X and less of Y until MUx/Px = MUy/Py","Buy more of both X and Y until their marginal utilities are equal","Keep the same purchases, since the consumer is already in equilibrium"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The last naira spent on X gives more utility than the last naira spent on Y, so switching spending towards X raises total utility. As more X is bought its marginal utility falls, and as less Y is bought MUy rises, by the law of diminishing marginal utility, until MUx/Px = MUy/Py. Option A moves in the wrong direction, and option D is wrong because equilibrium requires the two ratios to be equal."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 91, $official_bank_source${"itemId":"ad4ca722-58ca-5c78-b0c1-3e4d671a4d1c","questionId":"1e907e3c-6d48-59df-81f8-de34e2e44bf8","sourceKey":"bank:ECO201:CRD-001","payload":{"prompt":"In consumer theory, utility refers to","options":["The satisfaction a consumer derives from consuming a good or service","The usefulness of a good as judged by society's moral standards","The quantity of a good bought at a given price","The price a consumer pays for a good"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Utility is the satisfaction, happiness or benefit a person gets from consuming a good or service. It is not the price paid (option D) or the quantity bought (option C), and it has no moral meaning (option B): even a harmful good can yield utility to the person who wants it."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 92, $official_bank_source${"itemId":"2c98b026-417b-598f-8c94-f5ed243fbd0e","questionId":"465a91c2-306b-54bc-afac-c3563ff04ccb","sourceKey":"bank:ECO201:CRD-003","payload":{"prompt":"The two approaches to the study of consumer behaviour are the","options":["Partial and general equilibrium approaches","Cardinal and ordinal approaches","Static and dynamic approaches","Positive and normative approaches"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Consumer behaviour is analysed by the cardinal approach, which measures utility in numbers, and the ordinal approach, which only ranks preferences. The other pairs are real economic distinctions, but they describe types of statements (option D), treatment of time (option C) or the number of markets studied (option A)."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 93, $official_bank_source${"itemId":"3f4a74b0-f250-51a8-82ed-643ce3781aa2","questionId":"b03bda6b-679d-56c8-ae1b-6a01a7e337c0","sourceKey":"bank:ECO201:CRD-004","payload":{"prompt":"Which of the following is NOT an assumption of the cardinal utility theory?","options":["Utility can be measured in utils","Diminishing marginal rate of substitution","Constant marginal utility of money","Rationality of the consumer"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Diminishing marginal rate of substitution belongs to the ordinal (indifference curve) approach, not the cardinal approach. Rationality (option D), measurable utility in utils (option A) and constant marginal utility of money (option C) are all assumptions of cardinal utility theory, along with diminishing marginal utility."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 94, $official_bank_source${"itemId":"8aa78362-a0c5-50ed-adaa-3c5c3c7e4d96","questionId":"18f610b6-c77a-53e7-9cf1-9e7d6c6b0e59","sourceKey":"bank:ECO201:CRD-005","payload":{"prompt":"Which of the following is an assumption of the cardinal utility theory?","options":["Diminishing marginal utility","Indifference curves are convex to the origin","Utility can only be ranked, not measured","Increasing marginal utility of money"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Cardinal theory assumes that the more a consumer has of a good, the less an extra unit adds, which is diminishing marginal utility. Options C and B are features of the ordinal approach, and option D contradicts the cardinal assumption that the marginal utility of money is constant."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 95, $official_bank_source${"itemId":"b6e2df5e-9380-59a4-83d5-07fb4c96b871","questionId":"e6d53a2c-6305-5537-b13d-5a7e0403caee","sourceKey":"bank:ECO201:CRD-006","payload":{"prompt":"The cardinal assumption that each additional N1 gives the consumer the same level of satisfaction is known as","options":["Cardinality","Constant marginal utility of money","Diminishing marginal utility","Rationality"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Constant marginal utility of money means every extra naira is worth the same satisfaction to the consumer. Diminishing marginal utility (option C) refers to goods consumed, not money, and cardinality (option A) is the assumption that utility can be measured in utils."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 96, $official_bank_source${"itemId":"b5a01032-940f-51d8-840a-81775e7d608d","questionId":"38df59dc-1fda-5d63-b5ea-c11c4307b177","sourceKey":"bank:ECO201:CRD-007","payload":{"prompt":"In the cardinal approach, the assumption of constant marginal utility of money is important because it","options":["Guarantees that total utility always rises","Allows money to serve as a stable measuring rod of utility","Ensures that consumers can rank but not measure utility","Makes the demand curve slope upward"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"If each naira always carries the same satisfaction, the amount of money a consumer is willing to pay can be used as a fixed yardstick for utility. Option A is wrong because total utility can fall once marginal utility is negative, option D is wrong because the demand curve slopes downward, and option C describes the ordinal approach."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 97, $official_bank_source${"itemId":"52d075e9-9f95-5f7b-abe1-fc66e0bf84ca","questionId":"adf7e0bd-9264-5f26-bc13-4d270f937dd8","sourceKey":"bank:ECO201:CRD-008","payload":{"prompt":"The theory of consumer behaviour (the axiom of utility maximisation) assumes that the consumer","options":["Is rational and has full knowledge of available commodities, their prices and his or her income","Aims to minimise spending regardless of satisfaction","Can influence the market price by the amount he or she buys","Has unlimited income to spend on all goods"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Utility maximisation assumes a rational consumer who knows the available goods, their prices and his or her own income. Option D contradicts the basic idea of a limited budget, option C contradicts the assumption that prices are given, and option B reverses the goal of maximising satisfaction."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 98, $official_bank_source${"itemId":"1ab9143c-1e58-5e9b-98b6-b6a5eb2effed","questionId":"ac2fc21e-6986-5c1f-82b0-5f25fb59138f","sourceKey":"bank:ECO201:CRD-009","payload":{"prompt":"Marginal utility is best defined as","options":["The extra utility obtained from consuming one additional unit of a commodity","The total satisfaction obtained from all units consumed","The satisfaction obtained from the first unit only","Total utility divided by the number of units consumed"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Marginal means extra, so marginal utility is the additional utility from one more unit, measured as the change in total utility divided by the change in quantity. Option B is total utility, and option D is average utility, which is a different measure."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 99, $official_bank_source${"itemId":"d53cc120-7d85-5db5-beac-2cdfba4c51e7","questionId":"5f3150a6-2fd2-5952-ab01-1ed7cfe46592","sourceKey":"bank:ECO201:CRD-010","payload":{"prompt":"\"Holding taste constant, as a person's consumption of a commodity increases, each additional unit yields less and less utility.\" This statement is the","options":["Law of diminishing returns","Law of diminishing marginal utility","Law of demand","Law of equi-marginal utility"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The law of diminishing marginal utility says that each extra unit of a commodity adds less satisfaction than the one before. The law of demand (option C) relates price to quantity demanded, the equi-marginal law (option D) is about allocating income across goods, and diminishing returns (option A) concerns production."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 100, $official_bank_source${"itemId":"dd0417fd-67bf-5254-be46-cbb45513305f","questionId":"9f795337-c3be-55ef-8751-c75e422dbed7","sourceKey":"bank:ECO201:CRD-011","payload":{"prompt":"After a long walk in the sun, a student drinks sachets of water one after the other. The first sachet gives great relief, the second gives less, and the fourth gives very little extra satisfaction. This illustrates","options":["The law of equi-marginal utility","Constant marginal utility of money","Consumer surplus","The law of diminishing marginal utility"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Each additional sachet adds less satisfaction than the one before, which is the law of diminishing marginal utility. Option B refers to money, not water, consumer surplus (option C) compares willingness to pay with price paid, and the equi-marginal law (option A) involves choosing between two or more goods."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 101, $official_bank_source${"itemId":"83a1b6aa-f953-5fe9-b478-6d58c127659e","questionId":"c5cc27be-2b80-5a01-a201-4b1eee5502cb","sourceKey":"bank:ECO201:CRD-012","payload":{"prompt":"Which of the following is NOT a condition for the law of diminishing marginal utility to hold?","options":["The consumer must be rational","Units consumed must be identical","There must be a long time gap between the consumption of successive units","Consumption must occur continuously"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The law requires that units be consumed one after another without a significant time gap, so a long gap is the opposite of a condition. Identical units (option B), rational consumers (option A) and continuous consumption (option D) are genuine conditions for the law to hold."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 102, $official_bank_source${"itemId":"2c245ae4-b10b-579c-b723-c6e83fceb31c","questionId":"880e6665-2736-5598-ad02-9e555686e989","sourceKey":"bank:ECO201:CRD-013","payload":{"prompt":"Chidi eats a plate of amala at 8 a.m. and a second identical plate at 7 p.m., and enjoys the second as much as the first. The law of diminishing marginal utility fails here mainly because which condition is not met?","options":["Units consumed must be identical","Consumption must be continuous, without a significant time gap","Utility must be measurable in utils","The marginal utility of money must be constant"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The two plates were eaten eleven hours apart, so consumption was not continuous and Chidi's appetite returned. Option A is met because the plates are identical, and options D and C are assumptions of cardinal theory that do not explain why the second plate was equally satisfying."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 103, $official_bank_source${"itemId":"c4365240-bb54-593d-b91c-dd17664ecb70","questionId":"806dd165-6402-5b92-b958-7ba2cd441b3a","sourceKey":"bank:ECO201:CRD-014","payload":{"prompt":"When marginal utility is positive but falling, total utility","options":["Increases at a diminishing rate","Increases at an increasing rate","Is at its maximum","Decreases"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Each extra unit still adds something to total utility, but less than before, so total utility rises more and more slowly. Total utility is at its maximum (option C) only when marginal utility is zero, and it decreases (option D) only when marginal utility is negative."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 104, $official_bank_source${"itemId":"6c6baae3-50ed-5a05-96c4-74a101ef7ea6","questionId":"ed0153c9-6111-558f-a03f-119cdb5abf33","sourceKey":"bank:ECO201:CRD-016","payload":{"prompt":"If a consumer keeps consuming a good after marginal utility becomes negative, total utility will","options":["Remain at its maximum","Rise at an increasing rate","Rise at a diminishing rate","Fall"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"A negative marginal utility means each extra unit reduces satisfaction, so total utility declines. Total utility rises (options C and B) only when marginal utility is positive, and it is at its maximum (option A) when marginal utility is zero."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 105, $official_bank_source${"itemId":"73b945ed-3973-5fdc-8fd7-2c6cb7241a23","questionId":"8c891e4c-c32c-5ee6-b568-49baf2b8c890","sourceKey":"bank:ECO201:CRD-017","payload":{"prompt":"The point on the total utility curve where total utility is highest and marginal utility is zero is called the","options":["Equilibrium point","Break-even point","Bliss (saturation) point","Shutdown point"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The bliss or saturation point shows the highest level of satisfaction, beyond which further consumption gives negative marginal utility. The break-even and shutdown points (options B and D) belong to the theory of the firm, and the consumer's equilibrium (option A) is where marginal utility equals price, not where it is zero."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 106, $official_bank_source${"itemId":"940c034f-244d-54e4-8231-1e47f9d11800","questionId":"d1a855ac-706c-5562-bb3b-a5ea3e8ec25e","sourceKey":"bank:ECO201:CRD-018","payload":{"prompt":"Under the cardinal approach, with marginal utility measured in naira, a consumer buying a single good X is in equilibrium when","options":["MUx > Px","MUx = Px","TUx = Px","MUx = 0"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"With utility measured in money, the consumer keeps buying until the satisfaction from the last unit just equals its price, so MUx = Px. Option D (MUx = 0) is the bliss point, which a consumer paying a positive price would not reach, and option A means the consumer can still gain by buying more."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 107, $official_bank_source${"itemId":"f401a191-277b-5a60-b0e8-d1573340f660","questionId":"1603c40f-bf92-56a2-a627-0cd93c0b4999","sourceKey":"bank:ECO201:CRD-019","payload":{"prompt":"Under the cardinal approach, a consumer who spends all income on two goods X and Y is in equilibrium when","options":["MUx x Px = MUy x Py","Px/MUx = MUy/Py","MUx/Px = MUy/Py","MUx = MUy"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Equilibrium requires that the marginal utility from each good be proportional to its price, so the last naira spent on X gives the same utility as the last naira spent on Y. Option D ignores prices, and options B and A combine utility and price in the wrong way."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 108, $official_bank_source${"itemId":"5f2370ff-aa95-5b33-b0df-e2bf0b7694fe","questionId":"375b506c-7c4d-58e4-b829-6f2cebec5920","sourceKey":"bank:ECO201:CRD-020","payload":{"prompt":"The principle that a consumer maximises utility by allocating income so that the last naira spent on each good yields the same marginal utility is the","options":["Law of demand","Law of equi-marginal utility","Principle of opportunity cost","Law of diminishing marginal utility"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The law of equi-marginal utility says income is best allocated when marginal utility per naira is equal across all goods. The law of diminishing marginal utility (option D) is about one good's extra units giving less satisfaction; it helps the adjustment but is not the allocation rule itself."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 109, $official_bank_source${"itemId":"b3101c6e-2dcb-5136-8603-29d4c6bdb099","questionId":"7518856d-d52e-5436-ac4d-4784036c2150","sourceKey":"bank:ECO201:CRD-021","payload":{"prompt":"If MUx/Px > MUy/Py, the consumer can increase total utility by","options":["Buying more of X and less of Y","Buying more of Y and less of X","Buying more of both X and Y","Keeping the present combination"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"A higher MUx/Px means the last naira spent on X gives more satisfaction than the last naira spent on Y, so money should be moved from Y to X. Option B would widen the gap, option C is not possible because income is already fully spent, and option D ignores the gain available."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 110, $official_bank_source${"itemId":"91d79efb-830c-5335-b701-81064e412e4f","questionId":"d03af794-e5b3-5d14-84ec-b4ab2da1555a","sourceKey":"bank:ECO201:CRD-022","payload":{"prompt":"When a consumer with MUx/Px > MUy/Py buys more X and less Y, the ratios move towards equality because","options":["The law of diminishing marginal utility lowers MUx and raises MUy","The prices of X and Y adjust to the consumer's purchases","The marginal utility of money rises as more X is bought","Total utility from X falls to zero"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"By the law of diminishing marginal utility, consuming more X lowers MUx and consuming less Y raises MUy, so the ratios approach each other until equilibrium is restored. Option B is wrong because prices are given to the consumer, and option C contradicts the assumption of constant marginal utility of money."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 111, $official_bank_source${"itemId":"28573092-b07c-5929-92be-e16938335261","questionId":"0de59bf9-5ca2-562e-ad4e-1b199330c3ec","sourceKey":"bank:ECO201:CRD-023","payload":{"prompt":"Which of the following is NOT an assumption of the cardinal analysis of the equilibrium of a consumer buying two goods?","options":["The consumer spends all of his or her disposable income on the two products","The market prices Px and Py are given","The consumer can change the market prices of X and Y by his or her purchases","The consumer buys only two products, X and Y"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"In the analysis the consumer is a price taker, so he or she cannot influence the prices of X and Y. Options D, B and A are the stated assumptions: two goods, given prices and full spending of disposable income."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 112, $official_bank_source${"itemId":"e38f342d-660e-5a9b-934d-41548a17bfed","questionId":"d64688ca-c3f2-5b6b-9ef0-df5d918602f6","sourceKey":"bank:ECO201:CRD-024","payload":{"prompt":"In the cardinal approach, the demand curve slopes downward because","options":["The marginal utility of money falls as the price falls","Total utility falls as consumption rises","The consumer's income rises when the price falls","Marginal utility falls as consumption rises, so the price the consumer is willing to pay for extra units falls"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The demand curve is the marginal utility curve measured in money: as each extra unit gives less satisfaction, the consumer will pay less for it, so a lower price is needed to sell more. Option B is wrong because total utility keeps rising as long as marginal utility is positive, and option A contradicts the assumption that the marginal utility of money is constant."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 113, $official_bank_source${"itemId":"c47465c2-b636-5f46-b757-04690f1c3692","questionId":"73bcd8bf-8840-59f3-8941-90844fcb6be2","sourceKey":"bank:ECO201:CRD-025","payload":{"prompt":"In the cardinal approach, the consumer's demand curve is derived from the","options":["Total utility curve","Average utility curve","Marginal utility curve measured in money terms","Production possibility curve"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The demand curve comes from the marginal utility curve once marginal utility is expressed in naira, because the consumer buys an extra unit only if its price does not exceed its marginal utility. The total utility curve (option A) shows overall satisfaction, not the value of each extra unit, and the PPC (option D) is about production."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 114, $official_bank_source${"itemId":"cf6ad093-258d-5a38-8dba-e6bdac4619fa","questionId":"e90f2b5d-f172-5df6-ae7c-e4562072edcf","sourceKey":"bank:ECO201:CRD-026","payload":{"prompt":"Consumer surplus is the difference between","options":["What a consumer is willing to pay for a good and what the consumer actually pays","The price of a good and its cost of production","Total utility and marginal utility","The consumer's income and total spending"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Consumer surplus is the extra benefit a consumer enjoys because he or she would have paid more than the market price. Option B is the seller's margin, not the buyer's gain, and option D is savings, which has nothing to do with willingness to pay."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 115, $official_bank_source${"itemId":"3bd38282-86dd-5443-8db7-f12946e89c43","questionId":"25a29240-6aa3-59e4-8df9-c87cfc5b9661","sourceKey":"bank:ECO201:CRD-027","payload":{"prompt":"On a demand (or marginal utility in money) diagram, consumer surplus is shown by the area","options":["Below the price line up to the quantity bought","Below the demand curve and above the price line","Above the demand curve and below the price line","Under the whole demand curve"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Consumer surplus is the area under the demand curve (what the consumer is willing to pay) minus what is actually paid, which leaves the area between the demand curve and the price line. Option A is the amount actually spent, and option D is the total willingness to pay before subtracting spending."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 116, $official_bank_source${"itemId":"f87ac2ee-2867-51ea-aed7-42e87b77b073","questionId":"34c5f785-acbb-5927-84bf-7fb01b1ac0a4","sourceKey":"bank:ECO201:CRD-028","payload":{"prompt":"Which of the following is NOT a feature of the traditional theory of demand?","options":["It examines demand in only one market","It focuses only on the demand of final consumers","It starts with an examination of consumer behaviour","It concentrates on the demand for investment goods"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The traditional theory of demand neglects the demand for investment goods, so concentrating on it is not one of its features. Focusing on final consumers (option B), studying one market at a time (option A) and starting from consumer behaviour (option C) are its genuine features."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 117, $official_bank_source${"itemId":"311e547e-999c-56c2-95d2-18f69990b1b5","questionId":"333c23ac-2126-5949-8f6f-86f840a216a6","sourceKey":"bank:ECO201:CRD-029","payload":{"prompt":"Tola's total utility (in utils) from sticks of suya is: (units, TU) = 1, 10; 2, 18; 3, 24; 4, 28; 5, 30; 6, 30; 7, 28. What is the marginal utility of the 3rd stick?","options":["24 utils","8 utils","4 utils","6 utils"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Marginal utility of the 3rd stick is the change in total utility: 24 - 18 = 6 utils. Option A is total utility at 3 sticks, option B is either the MU of the 2nd stick or the average utility 24 / 3, and option C is the MU of the 4th stick."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 118, $official_bank_source${"itemId":"1e655b88-ffb7-5fc9-a246-71ed2f3e9ab2","questionId":"af3c08ef-db46-52b0-a2db-f316f128becf","sourceKey":"bank:ECO201:CRD-030","payload":{"prompt":"Tola's total utility (in utils) from sticks of suya is: (units, TU) = 1, 10; 2, 18; 3, 24; 4, 28; 5, 30; 6, 30; 7, 28. Marginal utility becomes zero at which stick?","options":["The 4th stick","The 7th stick","The 5th stick","The 6th stick"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Total utility is 30 at both 5 and 6 sticks, so the 6th stick adds 30 - 30 = 0 utils. The 5th stick (option C) still adds 2 utils, and the 7th stick (option B) has negative marginal utility of -2."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 119, $official_bank_source${"itemId":"96d06dd3-f8a8-5c8e-8e3f-e38acdafc1ba","questionId":"e16fb643-6e61-5f47-8c3f-60fdf1b9ce5f","sourceKey":"bank:ECO201:CRD-031","payload":{"prompt":"Tola's total utility (in utils) from sticks of suya is: (units, TU) = 1, 10; 2, 18; 3, 24; 4, 28; 5, 30; 6, 30; 7, 28. What is the marginal utility of the 7th stick?","options":["0 utils","2 utils","-2 utils","28 utils"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"The 7th stick changes total utility from 30 to 28, so its marginal utility is 28 - 30 = -2 utils, showing that consumption has gone past the bliss point. Option D is total utility, option A is the MU of the 6th stick, and option B drops the negative sign."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 120, $official_bank_source${"itemId":"79ec9786-6e9f-51d5-a858-8cee8b4f93fb","questionId":"9052956b-bf1e-5528-9355-c390342700d8","sourceKey":"bank:ECO201:CRD-032","payload":{"prompt":"The marginal utilities of the first four oranges a consumer eats are 12, 9, 6 and 3 utils respectively. What is the total utility from the four oranges?","options":["27 utils","12 utils","3 utils","30 utils"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Total utility is the sum of the marginal utilities of all units consumed: 12 + 9 + 6 + 3 = 30 utils. Option C is only the MU of the 4th orange, option B is only the MU of the first, and option A leaves out the last orange."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 121, $official_bank_source${"itemId":"611da876-db5f-5655-a407-ab531f99ab51","questionId":"59d87242-c525-515d-accb-503d0a56a1c3","sourceKey":"bank:ECO201:CRD-033","payload":{"prompt":"When a consumer increases consumption of a drink from 4 to 7 bottles, total utility rises from 40 utils to 52 utils. Using MU = change in TU / change in quantity, the marginal utility per bottle over this range is","options":["12 utils","7.43 utils","13 utils","4 utils"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"MU = change in TU / change in quantity = (52 - 40) / (7 - 4) = 12 / 3 = 4 utils per bottle. Option A forgets to divide by the change in quantity, and option B is average utility (52 / 7), not marginal utility."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 122, $official_bank_source${"itemId":"cc20e50a-f7d5-5706-8e13-232570e42b9b","questionId":"be2a3d02-b3ca-51bb-9df4-438d2117d1e0","sourceKey":"bank:ECO201:CRD-034","payload":{"prompt":"Bisi's marginal utility, measured in naira, from successive bananas is N100, N80, N60, N40 and N20. If a banana costs N60 and she buys a unit only when its marginal utility is at least equal to its price, how many bananas will she buy?","options":["5","2","3","4"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"She buys each banana whose marginal utility is at least N60, which are the 1st (N100), 2nd (N80) and 3rd (N60); at the 3rd banana MU = P, so she is in equilibrium. Option B stops one unit early, and options D and A include bananas worth less to her than their price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 123, $official_bank_source${"itemId":"b906a911-69fd-510a-842b-f1447f010ef4","questionId":"ee2e91f1-e4c4-5d51-81fb-0936eef3c75d","sourceKey":"bank:ECO201:CRD-035","payload":{"prompt":"Bisi's marginal utility, measured in naira, from successive bananas is N100, N80, N60, N40 and N20, and she buys a unit only when its marginal utility is at least equal to its price. If the price of a banana falls from N60 to N40, her quantity demanded rises from 3 to","options":["4","2","3","5"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"At N40 she also buys the 4th banana, whose marginal utility is exactly N40, so quantity demanded rises to 4; this is how a falling MU curve gives a downward-sloping demand curve. Option D includes the 5th banana, which is worth only N20 to her, and option C ignores the price fall."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 124, $official_bank_source${"itemId":"40f9f13d-d621-5a0c-85df-017438cc8564","questionId":"0056f777-21c6-5e04-b2ba-37112e923da3","sourceKey":"bank:ECO201:CRD-036","payload":{"prompt":"Bisi's marginal utility, measured in naira, from successive bananas is N100, N80, N60, N40 and N20. At a price of N40 she buys 4 bananas. Taking consumer surplus as total willingness to pay minus the amount actually paid, her consumer surplus is","options":["N160","N120","N100","N280"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Her total willingness to pay for 4 bananas is 100 + 80 + 60 + 40 = N280 and she actually pays 4 x 40 = N160, so consumer surplus is 280 - 160 = N120. Option D is total willingness to pay and option A is total spending, neither of which is the surplus."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 125, $official_bank_source${"itemId":"842d306a-e283-56ae-9915-34316ac6acb5","questionId":"a5a4156d-b499-5183-96b9-aff0573de561","sourceKey":"bank:ECO201:CRD-037","payload":{"prompt":"A student is willing to pay up to N5,000 for a used scientific calculator but buys it at Yaba market for N3,500. Her consumer surplus is","options":["N5,000","N3,500","N1,500","N8,500"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Consumer surplus is willingness to pay minus the price actually paid: 5,000 - 3,500 = N1,500. Option B is the price paid, option A is her maximum willingness to pay, and option D wrongly adds the two."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 126, $official_bank_source${"itemId":"13704b54-793b-5fb4-aee7-0212268abd6d","questionId":"335b18be-c799-532a-9907-362e03b0abbb","sourceKey":"bank:ECO201:CRD-038","payload":{"prompt":"A consumer's marginal utility, measured in naira, from the Qth plate of jollof rice is MU = 1000 - 100Q. If a plate costs N600, how many plates will the consumer buy in equilibrium?","options":["10","6","4","5"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Equilibrium for one good is where MU = P, so 1000 - 100Q = 600, giving 100Q = 400 and Q = 4. Option B uses 600 / 100, option A is where MU would fall to zero (the bliss point), and option D adds a plate worth only N500, less than its price."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 127, $official_bank_source${"itemId":"e073b7c1-31a9-52e4-a693-11a2e57f1205","questionId":"bfbdef0a-0946-5e24-a4f3-969f38d8aa49","sourceKey":"bank:ECO201:CRD-039","payload":{"prompt":"A consumer's marginal utility, measured in naira, from the Qth plate of jollof rice is MU = 1000 - 100Q, and the consumer buys 4 plates at N600 each. Treating plates as whole units and consumer surplus as total willingness to pay minus total amount paid, the consumer surplus is","options":["N600","N2,400","N300","N3,000"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Willingness to pay for plates 1 to 4 is 900 + 800 + 700 + 600 = N3,000, and the amount paid is 4 x 600 = N2,400, so consumer surplus is 3,000 - 2,400 = N600. Option D is total willingness to pay, option B is total spending, and option C is only the surplus on the first plate (900 - 600)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 128, $official_bank_source${"itemId":"aa981ca1-bc0b-5fcb-8c76-a9bcc505abc3","questionId":"91ed0e35-b3a4-5965-8917-5d8548b42b3b","sourceKey":"bank:ECO201:CRD-040","payload":{"prompt":"For a consumer, the last unit of X bought gives 30 utils and costs N10, while the last unit of Y bought gives 40 utils and costs N20. To increase total utility with the same income, the consumer should","options":["Buy more Y and less X","Buy less of both goods","Make no change because MUy > MUx","Buy more X and less Y"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"MUx/Px = 30 / 10 = 3 utils per naira while MUy/Py = 40 / 20 = 2 utils per naira, so a naira moved from Y to X adds satisfaction. Option A and option C compare marginal utilities without dividing by prices, which is the common mistake."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 129, $official_bank_source${"itemId":"006d5b66-4e06-54bb-9760-3a4dcfe1c8c9","questionId":"3fb07ae3-41a6-50b6-87dc-7617783c5e77","sourceKey":"bank:ECO201:CRD-041","payload":{"prompt":"At a consumer's present purchases, MUx = 24 utils, Px = N8 and MUy = 36 utils. For the consumer to be in equilibrium, the price of Y must be","options":["N4.50","N5.33","N8","N12"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Equilibrium requires MUx/Px = MUy/Py, so 24 / 8 = 36 / Py, giving 3 = 36 / Py and Py = N12. Option C wrongly assumes the prices must be equal, option B inverts the utilities (24 x 8 / 36), and option A divides MUy by Px (36 / 8)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 130, $official_bank_source${"itemId":"1be99e1f-e916-5554-b4b2-41a1159f9209","questionId":"44058318-cf9c-585e-9c08-c9a35e58915c","sourceKey":"bank:ECO201:CRD-042","payload":{"prompt":"A consumer in equilibrium buys X at N10 and Y at N4. If the marginal utility of the last unit of X is 50 utils, the marginal utility of the last unit of Y must be","options":["50 utils","20 utils","5 utils","125 utils"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"In equilibrium MUx/Px = MUy/Py, so 50 / 10 = MUy / 4, giving MUy = 5 x 4 = 20 utils. Option D multiplies by the wrong price ratio (50 x 10 / 4), option A ignores prices, and option C is only the MU per naira of X."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 131, $official_bank_source${"itemId":"f3021a86-1b99-5c7e-92d4-fc5d90fec26a","questionId":"e6ad3b99-64f5-5b55-be24-443544c4c0f1","sourceKey":"bank:ECO201:CRD-043","payload":{"prompt":"The equi-marginal condition extends to three goods as MUx/Px = MUy/Py = MUz/Pz. A consumer in equilibrium pays N2 for X, N4 for Y and N6 for Z. If MUx = 10 utils, what is MUz?","options":["60 utils","10 utils","20 utils","30 utils"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"MUx/Px = 10 / 2 = 5 utils per naira, so MUz = 5 x 6 = 30 utils (and MUy = 5 x 4 = 20 utils). Option C is MUy, option B wrongly sets marginal utilities equal, and option A multiplies MUx by Pz without dividing by Px."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 132, $official_bank_source${"itemId":"7172b1d6-23fd-5823-84aa-b7c8bfd652d9","questionId":"5598f9a4-a455-5388-ba40-964169020833","sourceKey":"bank:ECO201:CRD-044","payload":{"prompt":"In the cardinal approach, a consumer of a single good X is in equilibrium when MUx = Px x MUm, where MUm is the constant marginal utility of money. If MUm = 2 utils per naira and Px = N15, the marginal utility of the last unit of X bought is","options":["30 utils","15 utils","7.5 utils","17 utils"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Using the stated condition, MUx = Px x MUm = 15 x 2 = 30 utils. Option C divides instead of multiplying, option D adds the two figures, and option B ignores the marginal utility of money."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 133, $official_bank_source${"itemId":"d3f1125a-fa90-58fa-b7c7-68c59b8ff7b0","questionId":"800d032d-ed3a-508e-a95a-fc8e7edf1bf2","sourceKey":"bank:ECO201:CRD-045","payload":{"prompt":"Emeka has N20 to spend on X (price N4) and Y (price N2). His marginal utilities (in utils) for successive units are: X: 40, 32, 24, 16, 8; Y: 24, 20, 16, 12, 8, 4. To maximise utility while spending all N20, how many units of X should he buy?","options":["2","4","3","5"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"MU per naira for X is 10, 8, 6, 4, 2 and for Y is 12, 10, 8, 6, 4, 2; the ratios are equal at 6 when he buys 3 X and 4 Y, which costs 3 x 4 + 4 x 2 = N20. Option A (2 X with 6 Y) and option B (4 X with 2 Y) also cost N20 but give only 156 utils instead of 168, and option D (5 X) leaves no money for Y."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 134, $official_bank_source${"itemId":"cd1f8616-0344-5b00-90f4-9728375e7ac8","questionId":"98995fcc-54aa-5af6-a00e-322330249a1b","sourceKey":"bank:ECO201:CRD-046","payload":{"prompt":"Emeka has N20 to spend on X (price N4) and Y (price N2). His marginal utilities (in utils) for successive units are: X: 40, 32, 24, 16, 8; Y: 24, 20, 16, 12, 8, 4. In his utility-maximising equilibrium, how many units of Y does he buy?","options":["3","5","4","6"],"correctOption":2,"section":"Consumer Behaviour: Cardinal Utility","explanation":"At 3 X and 4 Y, MUx/Px = 24 / 4 = 6 and MUy/Py = 12 / 2 = 6, and spending is 12 + 8 = N20, so both conditions hold. Option A (3 Y) leaves N2 unspent, option D (6 Y) forces him down to 2 X and lower total utility, and option B (5 Y) together with 3 X would cost N22, more than his income."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 135, $official_bank_source${"itemId":"4ba8f89f-2604-56e4-9c9d-0d9f7ce49ac8","questionId":"9c6b4fcd-033a-5a27-8cb9-7767bfa768e1","sourceKey":"bank:ECO201:CRD-047","payload":{"prompt":"Emeka has N20 to spend on X (price N4) and Y (price N2). His marginal utilities (in utils) for successive units are: X: 40, 32, 24, 16, 8; Y: 24, 20, 16, 12, 8, 4. What is his total utility at the utility-maximising combination?","options":["36 utils","168 utils","96 utils","156 utils"],"correctOption":1,"section":"Consumer Behaviour: Cardinal Utility","explanation":"At equilibrium he buys 3 X and 4 Y, so total utility is (40 + 32 + 24) + (24 + 20 + 16 + 12) = 96 + 72 = 168 utils. Option D (156) is the total for the other affordable combinations such as 2 X and 6 Y, option C counts only the utility from X, and option A adds only the MUs of the last units bought (24 + 12)."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 136, $official_bank_source${"itemId":"aaa70275-e4a6-50fb-b8dc-399f42581ffd","questionId":"8266c1d8-7185-5996-b870-72698a5672db","sourceKey":"bank:ECO201:CRD-048","payload":{"prompt":"Emeka has N20 to spend on X (price N4) and Y (price N2). His marginal utilities (in utils) for successive units are: X: 40, 32, 24, 16, 8; Y: 24, 20, 16, 12, 8, 4. If Emeka buys 2 units of X and 6 units of Y (spending all N20), what should he do to raise his total utility?","options":["Buy more X and less Y","Buy more Y and less X","Keep the same combination","Buy more of both goods"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"At 2 X and 6 Y, MUx/Px = 32 / 4 = 8 while MUy/Py = 4 / 2 = 2, so a naira spent on X gives far more satisfaction; he should switch spending from Y to X until the ratios are equal. Option B widens the gap, and option D is impossible because his income is already fully spent."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 137, $official_bank_source${"itemId":"6312af29-a8be-5976-9175-b636e5ee6552","questionId":"42299838-fddb-5f80-96cf-6df0ca329c9f","sourceKey":"bank:ECO201:CRD-049","payload":{"prompt":"Which of the following total utility schedules, for units 1, 2, 3 and 4 of a good, shows diminishing marginal utility throughout?","options":["10, 18, 24, 28","10, 21, 33, 46","10, 20, 30, 40","10, 18, 30, 40"],"correctOption":0,"section":"Consumer Behaviour: Cardinal Utility","explanation":"For 10, 18, 24, 28 the marginal utilities are 10, 8, 6 and 4, which fall steadily, as the law of diminishing marginal utility predicts. Option C has constant MU of 10, option B has rising MU (10, 11, 12, 13), and option D has MU of 10, 8, 12, 10, which does not fall throughout."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 138, $official_bank_source${"itemId":"cf4c71d4-29df-51ee-ace5-608713bf8148","questionId":"f0d5ce67-8eb6-5ffe-b620-cc2f2c7c676c","sourceKey":"bank:ECO201:ORD-002","payload":{"prompt":"Under the cardinal utility approach, utility is assumed to be","options":["shown only by the slope of the budget line","independent of the quantity of the good consumed","capable only of being ranked in order of preference","measurable in absolute units such as utils"],"correctOption":3,"section":"Consumer Behaviour: Cardinal Utility","explanation":"Cardinal utility treats satisfaction as something that can be counted, for example 20 utils from one plate of rice. Option C is the ordinal assumption, option A confuses utility with the price ratio, and option B contradicts the idea that utility changes as more of a good is consumed."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 139, $official_bank_source${"itemId":"d431a5d8-5a71-510e-89e6-d81f804ee7ba","questionId":"159107f2-77e5-560d-8ded-3ea94d63522b","sourceKey":"bank:ECO201:E201-0021","payload":{"prompt":"The optimum point of a utility-maximizing consumer is ______.","options":["One attainable on low indifference curve","One unattainable on high indifference curve","One attainable on high indifference curve","One unattainable on low indifference curve"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"A utility-maximizing consumer reaches equilibrium at the point on the highest indifference curve that can be attained, where the budget line just touches (is tangent to) an indifference curve. Option B is wrong because points on higher curves beyond the budget line cannot be afforded. Option A gives an attainable point on a lower curve, which leaves the consumer less satisfied than he could be."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 140, $official_bank_source${"itemId":"76f2d9b5-86a7-5924-b97d-783659da1be5","questionId":"7c30b3fd-8587-5591-adae-bbc4893c9061","sourceKey":"bank:ECO201:E201-0025","payload":{"prompt":"In the ordinal approach to the theory of consumer behaviour, which among the following are objective factors.","options":["Price and taste","Price and preferences","Income and preferences","Price and income"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"In the ordinal approach, price and income are objective factors because they are external facts that can be measured and are the same for anyone checking them; together they fix the budget line. Taste and preferences (in options A, B and C) are subjective, since they exist in the consumer's own mind and are shown by indifference curves."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 141, $official_bank_source${"itemId":"d83c797a-8a6b-546d-977e-0275ccdabfe7","questionId":"550e5d2f-89e0-50b3-ac45-029cd95748de","sourceKey":"bank:ECO201:E201-0031","payload":{"prompt":"One of the following is not a property of an indifference curve.","options":["It slopes downward from left to the right","It gives the same level of satisfaction at all points on the curve","It has no shape for some commodities","Two indifference curves do not intersect"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Every indifference curve has a definite shape: it slopes downward, is convex to the origin, and two curves never cross. Saying it has no shape for some commodities is not a property. Options A, B and D are all genuine properties of indifference curves."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 142, $official_bank_source${"itemId":"11b67e83-c36d-5b5f-b078-7fc809ade88b","questionId":"da6b8f01-9e7f-5ed1-8fe6-e49d93641019","sourceKey":"bank:ECO201:E201-0032","payload":{"prompt":"Which approach to the theory of consumer adopts the concept of indifference curve?","options":["Both the ordinal and the cardinal approaches","Cardinalist approach","ordinalist approach","marginalist approach"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The ordinalist approach uses indifference curves, because it only needs consumers to rank bundles of goods, not measure satisfaction in utils. The cardinalist approach (option B) measures utility in numbers and uses total and marginal utility instead. So option A is wrong, and option D, marginalist, is not the approach associated with indifference curves."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 143, $official_bank_source${"itemId":"615bfddd-e760-5317-bd95-144fdcb3d3a0","questionId":"1516e949-8eab-56f0-8872-8012a6d1ba22","sourceKey":"bank:ECO201:E201-0047","payload":{"prompt":"If she spends all of her income on lemons and tangerines, Isabella can just afford 30 lemons and 8 tangerines per day. She could also use her entire budget to buy 6 lemons and 14 tangerines per day. The price of lemons is N6 each. How much is Isabella's income per day? ______.","options":["N300","N372","N180","N580"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Both bundles cost the whole income, so 30L + 8T = 6L + 14T, which gives 24L = 6T, so one tangerine costs 4 lemons. With lemons at N6, a tangerine costs N24, and income = 30(6) + 8(24) = 180 + 192 = N372; check: 6(6) + 14(24) = 36 + 336 = N372. Option C, N180, counts only the 30 lemons and leaves out the tangerines."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 144, $official_bank_source${"itemId":"caf6172d-d48c-56e0-8abf-0a0a14829145","questionId":"5a08b628-3b43-59d2-987d-c160a3f7ebc4","sourceKey":"bank:ECO201:E201-0053","payload":{"prompt":"Which of the following best describes the price consumption curve for a straight-line demand curve extended to both axes? ______.","options":["Always falls","Always rises","Falls then rises","Rises then falls"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Along a straight-line demand curve, demand is elastic on the upper part, unit elastic at the midpoint and inelastic on the lower part. As price falls in the elastic range spending on the good rises, so less money is left for other goods and the price consumption curve falls; at unit elasticity it is flat, and in the inelastic range spending on the good falls, so the curve rises. Options A and B would only hold if demand were elastic or inelastic all the way along, and option D reverses the order."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 145, $official_bank_source${"itemId":"859da543-2eac-51d9-9a7b-04472db5bd15","questionId":"3dfc5a75-7813-53bf-af42-2705997ad8ae","sourceKey":"bank:ECO201:E201-0055","payload":{"prompt":"Which property of preferences means \"more is always better\"?","options":["Convexity","Monotonicity","Transitivity","Completeness"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Monotonicity is the property that more of a good is always better than less, so a bundle with more of at least one good and no less of the other is preferred. Option A, convexity, is about preferring balanced bundles and gives indifference curves their bowed shape. Option C, transitivity, is about consistency in ranking, and option D, completeness, means the consumer can compare any two bundles."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 146, $official_bank_source${"itemId":"cf015ea8-b24a-57c3-9d8d-ca16502b3cad","questionId":"95d667ee-a535-54d1-be16-4aff4db03be8","sourceKey":"bank:ECO201:E201-0056","payload":{"prompt":"If a consumer gives up some quantity of one good to gain more of another while staying equally satisfied, the indifference curve must be: ______.","options":["Downward sloping","Upward sloping","Horizontal","Vertical"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"To stay equally satisfied, a consumer who gets more of one good must give up some of the other, so as one quantity rises the other falls. That inverse relationship makes the indifference curve slope downward from left to right. An upward-sloping curve (option B) would mean more of both goods gives the same satisfaction, which goes against more being better, and horizontal or vertical curves (options C and D) would mean one good adds nothing to satisfaction."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 147, $official_bank_source${"itemId":"61d88b26-e730-5d4f-829e-5f7b4fc2f0b9","questionId":"2b50caec-edbf-5dc3-91e1-38e899832372","sourceKey":"bank:ECO201:E201-0057","payload":{"prompt":"As a consumer substitutes one good for another, they are willing to give up less and less of the second good. This implies that indifference curves are: ______.","options":["Straight lines","Concave","Vertical to the origin","Convex to the origin"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"When a consumer is willing to give up less and less of one good for each extra unit of the other, the marginal rate of substitution is diminishing. A diminishing MRS makes the indifference curve flatter as you move down it, which means it is convex to the origin. Option A, a straight line, would mean a constant MRS (perfect substitutes), and option B, concave, would mean an increasing MRS."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 148, $official_bank_source${"itemId":"1b939f0a-b0ea-57e6-8460-b164cd36986d","questionId":"e7465719-6932-5b94-abdd-3bdc7c85de63","sourceKey":"bank:ECO201:E201-0058","payload":{"prompt":"If two indifference curves were to cross, it would violate: ______.","options":["Law of demand","Transitivity of preferences","Diminishing marginal utility","Income effect"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"If two indifference curves crossed, the bundle at the crossing point would give the same satisfaction as bundles on both curves, so all those bundles would have to be equally good. But one curve lies above the other elsewhere, so some bundle would be both preferred and equally preferred at the same time, which breaks transitivity of preferences. Option A, the law of demand, and option D, the income effect, are about responses to price and income changes, not the shape of the preference map, and option C, diminishing marginal utility, belongs to the cardinal approach."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 149, $official_bank_source${"itemId":"e59989a3-9d17-5186-bc79-626f304e16ee","questionId":"c12bb8f2-22bb-504d-ae47-0e3aafcd6c30","sourceKey":"bank:ECO201:E201-0060","payload":{"prompt":"Indifference curves typically do not touch the axes because: ______","options":["Goods are free","Consumers prefer balanced bundles","One good alone gives maximum satisfaction","Prices are constant"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Indifference curves are normally drawn without touching the axes because the consumer is assumed to consume some of both goods, preferring a mix to a bundle of only one good. A point on an axis would mean consuming none of one good. Option C says the opposite of this assumption, and options A and D have nothing to do with the shape of the indifference map."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 150, $official_bank_source${"itemId":"be4e2a81-3a1d-5dba-952f-52f7ddad8f76","questionId":"c1c9b4e6-18d8-5f52-a7dd-161a377f5b6e","sourceKey":"bank:ECO201:E201-0079","payload":{"prompt":"The ordinalist approach to utility focuses on: ______.","options":["Numerical measurement of preferences","Ranking of preferences","Total and marginal utility schedules","Budget line measurement"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The ordinal approach holds that satisfaction cannot be measured in numbers, but a consumer can rank bundles in order of preference, and indifference curves are built on that ranking. Options A and C describe the cardinal approach, which measures utility in utils and works with total and marginal utility schedules. Option D is wrong because the budget line only shows what the consumer can afford, not how preferences are treated."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 151, $official_bank_source${"itemId":"1616162b-d529-51f1-9c00-c8e253ec280c","questionId":"3ca548c2-7249-57d9-98c1-11791cbb8030","sourceKey":"bank:ECO201:E201-0089","payload":{"prompt":"______ is a popular analytical tool among the ordinal theorists of consumer behaviour.","options":["Marginal utility schedule","Indifference curves","Law of Diminishing MU","Total utility curve"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Ordinal theorists rank preferences instead of measuring utility, and the indifference curve is their main tool for showing those rankings. Options A, C and D, the marginal utility schedule, the law of diminishing marginal utility and the total utility curve, are all tools of the cardinal approach, which assumes utility can be measured in utils."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 152, $official_bank_source${"itemId":"6b38931d-dd0d-5bb7-999c-7f7614096ee6","questionId":"5190e25a-0c93-5ab0-b46b-e0bb41943d22","sourceKey":"bank:ECO201:E201-0373","payload":{"prompt":"Which of the following is a property of an indifference curve?","options":["Convex to the origin","Concave to the origin","Sloping upward from left to right","Two ICs intersect each other"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Indifference curves are normally convex to the origin, because the marginal rate of substitution diminishes as the consumer moves along the curve. Option C is wrong because indifference curves slope downward, and option D is wrong because two indifference curves can never intersect."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 153, $official_bank_source${"itemId":"5048337b-5158-52b0-94e6-b243cb3c3ec2","questionId":"54e90e24-c104-5ba4-9ce3-16f073822c51","sourceKey":"bank:ECO201:E201-0375","payload":{"prompt":"A movement from one point to another along an indifference curve makes the satisfaction:","options":["Increasing","Decreasing","Unaltered","None"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Every point on an indifference curve gives the consumer the same level of satisfaction, which is why he is indifferent between them. So moving along the curve leaves satisfaction unchanged. Options A and B describe moving to a higher or lower indifference curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 154, $official_bank_source${"itemId":"53fe364f-7caf-5cb6-a8c9-4146a6258982","questionId":"8f5746c6-4b5a-57cc-ba58-4d044acc7b93","sourceKey":"bank:ECO201:E201-0378","payload":{"prompt":"As moving from left to right through an indifference curve, the MRS of X for Y","options":["Increases","Remains the same","Decreases","Both A and C"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"As the consumer moves down the indifference curve, getting more X and less Y, he is willing to give up fewer units of Y for each extra unit of X. So the marginal rate of substitution of X for Y diminishes. Option A would mean a concave curve, and option B a straight-line indifference curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 155, $official_bank_source${"itemId":"454522ad-c9c6-5fd8-af6b-783b3f9bd91a","questionId":"a50e54c5-9b4f-580f-9ac7-69f16d560d1f","sourceKey":"bank:ECO201:E201-0381","payload":{"prompt":"With good X measured on the horizontal axis and good Y on the vertical axis, a horizontal indifference curve indicates that:","options":["Good X is a neuter","Good Y is a neuter","X and Y are perfect substitutes","X and Y are perfect complements"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"A horizontal indifference curve means the consumer stays equally satisfied whatever amount of X he has, as long as Y is unchanged. Good X therefore adds nothing to satisfaction, so it is a neuter. Option B would give a vertical indifference curve, and option C gives a downward-sloping straight line."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 156, $official_bank_source${"itemId":"1f02e2f5-7c30-565c-8716-2b40ad37d415","questionId":"4aa6e32a-c884-57a5-9550-4d9fed9d0c3e","sourceKey":"bank:ECO201:E201-0382","payload":{"prompt":"On a budget line for goods X and Y, if the price of Y alone changes, the X intercept will:","options":["Rotate upwards","Rotate downwards","Not change","Shift parallel"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The X intercept of the budget line is M / Px, the most X the consumer can buy with all his income. It depends only on income and the price of X, so a change in the price of Y alone leaves it unchanged, and the budget line pivots around it. Option D is wrong because a parallel shift happens only when income changes with prices constant."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 157, $official_bank_source${"itemId":"551e2d49-7d1d-554c-aaf4-5e0568a8eac0","questionId":"42bd9035-b92b-5ec3-9483-496142bcdd96","sourceKey":"bank:ECO201:ORD-001","payload":{"prompt":"The approach to consumer behaviour which assumes that a consumer can rank bundles of goods in order of preference, but cannot measure satisfaction in absolute units, is called the","options":["cardinal utility approach","ordinal utility approach","total utility approach","marginal utility approach"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The ordinal approach only requires the consumer to say which bundle she prefers, or that she is indifferent, without attaching numbers to satisfaction. Options A, D and C all belong to the cardinal tradition, which assumes utility can be measured in units such as utils."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 158, $official_bank_source${"itemId":"b9c58df3-1387-5f97-85cf-977c45474342","questionId":"4ad1e60c-a27b-52c8-a649-e4a4c01a12f2","sourceKey":"bank:ECO201:ORD-003","payload":{"prompt":"The main difference between the cardinal and the ordinal approaches to consumer behaviour is that","options":["ordinal analysis assumes the consumer has unlimited income","ordinal analysis measures satisfaction in numbers, while cardinal analysis only ranks bundles","cardinal analysis ignores prices, while ordinal analysis uses prices","cardinal analysis measures satisfaction in numbers, while ordinal analysis only ranks bundles"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Cardinal theory assumes utility can be quantified, while ordinal theory only needs the consumer to order bundles by preference. Option B reverses the two approaches, option C is false because both use prices, and option A is wrong because ordinal theory uses a budget constraint."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 159, $official_bank_source${"itemId":"2bd49841-7d0a-5564-9196-99c763a43ead","questionId":"67407866-e578-57d2-a373-6badcd94ba30","sourceKey":"bank:ECO201:ORD-004","payload":{"prompt":"Which of the following is NOT an assumption of the ordinal (indifference curve) theory of consumer behaviour?","options":["Preferences are transitive","Preferences are complete","Satisfaction can be measured in utils","More of a good is preferred to less (non-satiation)"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Ordinal theory deliberately drops the idea that satisfaction can be measured in utils; that is the cardinal assumption. Completeness (B), transitivity (A) and non-satiation (D) are all core assumptions of ordinal theory."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 160, $official_bank_source${"itemId":"3b41959e-3035-5997-88bd-d7f59d4a6842","questionId":"e02d54c6-9692-5aa0-bf15-5d275880dd49","sourceKey":"bank:ECO201:ORD-005","payload":{"prompt":"The assumption that, for any two bundles A and B, a consumer can always say that she prefers A to B, prefers B to A, or is indifferent between them is called","options":["completeness","non-satiation","transitivity","diminishing marginal rate of substitution"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Completeness means the consumer is able to compare and rank any pair of bundles. Transitivity (C) is about consistency across three or more bundles, non-satiation (B) means more is preferred to less, and option D describes the shape of indifference curves."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 161, $official_bank_source${"itemId":"2e01429f-d749-576e-9e4c-67d69f0623ef","questionId":"2fe8f065-565f-54b7-b63b-44d8498ab9ff","sourceKey":"bank:ECO201:ORD-006","payload":{"prompt":"Chidi prefers jollof rice to fried rice, and fried rice to ofada rice. For his preferences to be consistent, he must also prefer jollof rice to ofada rice. This requirement is the assumption of","options":["completeness","convexity","non-satiation","transitivity"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Transitivity says that if A is preferred to B and B to C, then A must be preferred to C, exactly as with Chidi's rice choices. Completeness (A) only says he can compare any two bundles, non-satiation (C) says more is better, and convexity (B) is about the shape of indifference curves."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 162, $official_bank_source${"itemId":"95cf0a77-0093-548d-ac1b-0b10eaa59f96","questionId":"4a3d061e-70f8-5d1d-93b7-19d0b9dbb6b2","sourceKey":"bank:ECO201:ORD-007","payload":{"prompt":"In ordinal utility theory, the assumption that a consumer always prefers more of a good to less, other things being equal, is known as","options":["diminishing marginal utility","transitivity","completeness","non-satiation"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Non-satiation (more is better) means extra units of a good never make the consumer worse off. Completeness (C) and transitivity (B) are about ranking bundles, while diminishing marginal utility (A) is a cardinal idea about utils falling with consumption."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 163, $official_bank_source${"itemId":"1a5eb71e-76ca-58a0-8fd2-fde987c3ffeb","questionId":"4292005b-41a4-501b-84ab-dd20471e58aa","sourceKey":"bank:ECO201:ORD-008","payload":{"prompt":"A curve showing all combinations of two goods that give a consumer the same level of satisfaction is called","options":["an Engel curve","a budget line","an indifference curve","a price consumption curve"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Every point on an indifference curve gives equal satisfaction, so the consumer is indifferent between them. A budget line (B) shows affordable bundles, a price consumption curve (D) joins equilibrium points as price changes, and an Engel curve (A) relates income to quantity demanded."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 164, $official_bank_source${"itemId":"020efebb-17f3-5ef4-aaeb-926faf362a4c","questionId":"3e620114-605d-5a92-b691-72bb3b36a4e1","sourceKey":"bank:ECO201:ORD-009","payload":{"prompt":"A set of indifference curves for a consumer, each curve representing a different level of satisfaction, is called","options":["an indifference map","a demand schedule","a budget set","an income consumption curve"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"An indifference map is the whole family of indifference curves, with curves further from the origin showing higher satisfaction. A budget set (C) is the set of affordable bundles, an income consumption curve (D) traces equilibria as income changes, and a demand schedule (B) is a price-quantity table."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 165, $official_bank_source${"itemId":"2bce0c5d-b4f1-5c10-80a2-011722f5f14d","questionId":"2d605c7b-4926-551d-8e9c-0dbfd85a1d3f","sourceKey":"bank:ECO201:ORD-010","payload":{"prompt":"Indifference curves slope downward from left to right because","options":["the consumer's income rises as we move along the curve","to keep satisfaction unchanged, more of one good must be matched by less of the other, given that more is preferred to less","the prices of both goods fall as we move along the curve","the marginal rate of substitution rises as more of X is consumed"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"If the consumer gets more X and more is always better, she can only stay equally satisfied by giving up some Y, which gives the negative slope. Option D is wrong because MRS falls, not rises, and options C and A are wrong because prices and income do not appear on an indifference curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 166, $official_bank_source${"itemId":"0bb30a2b-0f78-527f-b4a7-dd0b588aabf5","questionId":"9130b3e0-a049-5a2e-9b92-690b548e6f94","sourceKey":"bank:ECO201:ORD-011","payload":{"prompt":"An indifference curve is normally convex to the origin because of","options":["an increasing marginal rate of substitution","the transitivity of preferences","a diminishing marginal rate of substitution","a constant marginal rate of substitution"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Convexity means the curve becomes flatter as we move down it, which is what a falling MRS of X for Y produces. An increasing MRS (A) would make the curve concave, a constant MRS (D) gives a straight line, and transitivity (B) explains why curves do not cross, not their shape."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 167, $official_bank_source${"itemId":"ac7c7488-db0d-5554-a81a-414f4b6e1284","questionId":"9d2167b7-2e24-59d2-9f4e-57d5d76f2c11","sourceKey":"bank:ECO201:ORD-012","payload":{"prompt":"Two indifference curves of the same consumer cannot intersect because an intersection would","options":["make the marginal rate of substitution diminish","mean that the budget line has become vertical","imply that the same bundle gives two different levels of satisfaction, violating transitivity and non-satiation","imply that the consumer is in equilibrium at the crossing point"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"At a crossing point one bundle would lie on two curves representing different satisfaction levels, which leads to contradictory rankings. Option B is irrelevant because budget lines are separate from preferences, option A describes convexity, and option D confuses an intersection of two indifference curves with tangency to a budget line."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 168, $official_bank_source${"itemId":"51d90d38-1931-521d-b6d5-539570eaa55d","questionId":"a7093f95-cf49-557c-9ca3-68ba60718966","sourceKey":"bank:ECO201:ORD-013","payload":{"prompt":"A bundle on a higher indifference curve is preferred to a bundle on a lower one because","options":["the consumer's income is lower on higher curves","the MRS is constant on higher curves","bundles on a higher curve always cost less","a higher curve contains bundles with more of at least one good and no less of the other"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Given non-satiation, moving out to a higher curve means getting more goods, so satisfaction is greater. Option C is wrong because higher curves usually need more spending, option B is not true in general, and option A reverses the link between income and attainable curves."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 169, $official_bank_source${"itemId":"cb5fa4ad-d787-51f6-a687-5d6595d42cf6","questionId":"fd6e750c-ef10-5086-b266-ba0a09ebefe1","sourceKey":"bank:ECO201:ORD-014","payload":{"prompt":"Which of the following is NOT a property of normal indifference curves?","options":["They are convex to the origin","They may intersect when the consumer's tastes are strong","They slope downward from left to right","A higher curve represents a higher level of satisfaction"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Indifference curves of one consumer never intersect, because that would break consistent ranking of bundles. Downward slope (C), convexity (A) and higher curves meaning more satisfaction (D) are all standard properties."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 170, $official_bank_source${"itemId":"184eb435-d4e2-5543-a443-c654bf323bdc","questionId":"fb79efcc-95ad-525c-a1bf-a57e2d5ff958","sourceKey":"bank:ECO201:ORD-015","payload":{"prompt":"The rate at which a consumer is willing to give up units of good Y to obtain one more unit of good X while remaining on the same indifference curve is the","options":["price ratio Px/Py","marginal utility of X","marginal rate of transformation","marginal rate of substitution of X for Y"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The marginal rate of substitution measures the consumer's willingness to trade one good for another at constant satisfaction. The marginal rate of transformation (C) is about production, the price ratio (A) is the market rate of exchange shown by the budget line, and marginal utility (B) is the extra satisfaction from one good alone."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 171, $official_bank_source${"itemId":"63afea03-6c86-5731-90c7-18157f678551","questionId":"eafb0b40-9cb9-5cfb-ad72-71187d0f1200","sourceKey":"bank:ECO201:ORD-016","payload":{"prompt":"The marginal rate of substitution of X for Y (MRSxy) is equal to","options":["MUx x MUy","MUx / MUy","Px x Py","MUy / MUx"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Along an indifference curve the utility gained from extra X must equal the utility lost from less Y, so MRSxy = MUx/MUy. Option D is the inverse, giving MRSyx, while options C and A are not ratios of marginal utilities at all."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 172, $official_bank_source${"itemId":"c4d81af3-c242-5d12-961f-f08d1eceeefd","questionId":"2b2e220f-e9f1-55fe-87a6-e7fa285ca623","sourceKey":"bank:ECO201:ORD-017","payload":{"prompt":"As a consumer moves down an indifference curve, acquiring more X and less Y, MRSxy falls because","options":["the more X she has relative to Y, the less Y she is willing to give up for an extra unit of X","the price of X falls as she buys more of it","X becomes an inferior good at high quantities","her money income rises as she consumes more X"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"When X becomes plentiful and Y scarce, each additional X is worth less to her in terms of Y, so she gives up fewer units of Y for it. Options B and D bring in prices and income, which do not change along an indifference curve, and option C confuses tastes with the income effect."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 173, $official_bank_source${"itemId":"6a71bba8-5031-55f5-82c5-ad3578f317db","questionId":"03675306-9ed2-52e0-9b46-6828b1325391","sourceKey":"bank:ECO201:ORD-018","payload":{"prompt":"If two goods are perfect substitutes for a consumer, her indifference curves are","options":["straight downward-sloping lines with a constant MRS","convex to the origin with a diminishing MRS","horizontal straight lines","L-shaped (right-angled)"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Perfect substitutes are always traded at the same rate, so the MRS is constant and each indifference curve is a straight line. L-shaped curves (D) describe perfect complements, option B describes ordinary goods, and horizontal lines (C) would mean X gives no satisfaction."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 174, $official_bank_source${"itemId":"2b528d89-1472-5e1c-af17-1ca876cc1c62","questionId":"e4b14855-e0c0-5835-81db-be0aaba427be","sourceKey":"bank:ECO201:ORD-019","payload":{"prompt":"Bisi regards a 75cl bottle of one brand of table water as exactly as good as a 75cl bottle of another brand, and always swaps them one-for-one. Her indifference curves between the two brands are","options":["vertical straight lines","convex curves with a diminishing MRS","straight lines with a constant MRS of 1","L-shaped curves"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Since she will always give up one bottle of one brand for one of the other, the two brands are perfect substitutes and the MRS is fixed at 1, giving straight-line indifference curves. L-shaped curves (D) are for goods used in fixed proportions, option B applies to imperfect substitutes, and vertical lines (A) would mean she does not value one brand at all."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 175, $official_bank_source${"itemId":"8db2af88-d6c0-527d-80f5-7288152716f1","questionId":"e0d47184-5eb7-5393-a6ab-efb8598cd415","sourceKey":"bank:ECO201:ORD-020","payload":{"prompt":"Goods that are consumed only in fixed proportions, such as left shoes and right shoes, have indifference curves that are","options":["L-shaped (right-angled)","straight downward-sloping lines","concave to the origin","upward-sloping"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Extra left shoes add nothing without matching right shoes, so each indifference curve has a corner at the fixed ratio and is L-shaped. Straight lines (B) describe perfect substitutes, while upward-sloping (D) or concave (C) curves break the usual assumptions about preferences."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 176, $official_bank_source${"itemId":"47a244d5-35d9-5e3b-9348-4a95fcefd8f3","questionId":"2a73045f-2b41-59b6-bad8-bc802c46ab1d","sourceKey":"bank:ECO201:ORD-021","payload":{"prompt":"A line showing all combinations of two goods that a consumer can buy when she spends all her income at given prices is called","options":["the indifference curve","the production possibility frontier","the budget line","the income consumption curve"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The budget line (price line) marks the boundary of what the consumer can afford with her income at given prices. An indifference curve (A) shows equal satisfaction, the income consumption curve (D) traces equilibria as income changes, and the production possibility frontier (B) belongs to production, not consumer theory."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 177, $official_bank_source${"itemId":"0adc419b-1892-578f-9cc4-76cd39ff027f","questionId":"0f0000ea-73df-5382-b528-6839d068a042","sourceKey":"bank:ECO201:ORD-022","payload":{"prompt":"If a consumer's money income rises while the prices of both goods remain unchanged, her budget line will","options":["shift inward parallel to the original line","shift outward parallel to the original line","become steeper","rotate outward about the vertical intercept"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"With prices fixed the slope -Px/Py does not change, and higher income raises both intercepts, so the line moves out parallel. A rotation (D) happens when only one price changes, an inward shift (A) follows a fall in income, and a steeper line (C) needs a rise in Px relative to Py."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 178, $official_bank_source${"itemId":"0ec34616-ed0f-5b9b-9a5e-c21af26cae71","questionId":"0c61029c-b959-57bf-b6ee-4cf13b4046db","sourceKey":"bank:ECO201:ORD-023","payload":{"prompt":"With good X on the horizontal axis, a fall in the price of X, with income and the price of Y unchanged, causes the budget line to","options":["rotate outward along the Y-axis, keeping the same X-intercept","rotate inward along the X-axis","shift outward parallel to itself","rotate outward along the X-axis, keeping the same Y-intercept"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The maximum amount of Y (M/Py) is unchanged, but the maximum amount of X (M/Px) rises, so the line pivots outward on the X-axis and becomes flatter. A parallel shift (C) needs an income change, option B describes a rise in Px, and option A describes a fall in Py."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 179, $official_bank_source${"itemId":"e4f3b9e6-466e-5207-9f7a-5357f82393ef","questionId":"d8481eca-9bdd-57d1-abb1-c114c69f5db2","sourceKey":"bank:ECO201:ORD-024","payload":{"prompt":"If a consumer's money income and the prices of both goods all double at the same time, her budget line will","options":["shift inward parallel to itself","become twice as steep","shift outward parallel to itself","remain exactly where it was"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Both intercepts M/Px and M/Py, and the slope -Px/Py, are unchanged when M, Px and Py are multiplied by the same number. Options C and A would need real income to change, and option B would need the price ratio to change."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 180, $official_bank_source${"itemId":"2e97a482-ac9a-56a6-9b38-70424efcfd35","questionId":"a23504ca-2adc-5461-9d26-1fe7eae25ee4","sourceKey":"bank:ECO201:ORD-025","payload":{"prompt":"In indifference curve analysis, a consumer maximising satisfaction (with an interior solution) is in equilibrium where","options":["Px = Py","MRSxy = Px / Py","MUx = MUy","MRSxy = Py / Px"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"At equilibrium the rate at which she is willing to swap Y for X (MRSxy) equals the rate at which the market lets her swap them (Px/Py). Option D inverts the price ratio, option C ignores prices, and option A is a statement about prices, not about the consumer's choice."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 181, $official_bank_source${"itemId":"d734c3dc-50d0-5933-9e88-26bf824e69dd","questionId":"0176bc77-962b-5949-8b7a-515993f96a84","sourceKey":"bank:ECO201:ORD-026","payload":{"prompt":"Graphically, the consumer's equilibrium in ordinal analysis occurs","options":["where the budget line is tangent to the highest attainable indifference curve","where the budget line meets the X-axis","on the highest indifference curve in the map, whatever the budget","where an indifference curve cuts the budget line from above"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The best affordable bundle is on the highest indifference curve the budget line can reach, which it just touches at a tangency point. A point where a curve cuts the line (D) can be improved upon, option C ignores the budget constraint, and the X-intercept (B) is only optimal in special corner cases."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 182, $official_bank_source${"itemId":"02bf763f-bdc6-5727-b750-9a1cab0028dd","questionId":"67a56d28-c750-516e-a802-f318010a7326","sourceKey":"bank:ECO201:ORD-027","payload":{"prompt":"A consumer is spending all her income on goods X and Y, but at her current bundle MRSxy is greater than Px/Py. To raise her satisfaction she should","options":["buy less of both goods","buy more X and less Y","buy more Y and less X","make no change, since all income is already spent"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"MRSxy > Px/Py means she values an extra unit of X, in terms of Y, more than the market charges for it, so swapping some Y for X moves her to a higher indifference curve. Option C moves her in the wrong direction, option D ignores the tangency condition, and option A would leave income unspent."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 183, $official_bank_source${"itemId":"5b38ab29-15ea-56bc-bc44-e654da25346a","questionId":"f334d612-2baf-5e5d-a839-18c7cbe2d195","sourceKey":"bank:ECO201:ORD-028","payload":{"prompt":"The locus of consumer equilibrium points traced out as the price of good X changes, with money income and the price of Y held constant, is the","options":["budget line","Engel curve","income consumption curve","price consumption curve"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The price consumption curve joins the tangency points that result as the budget line rotates when Px changes. The income consumption curve (C) comes from income changes, the Engel curve (B) plots income against quantity, and a budget line (A) is a single affordability constraint."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 184, $official_bank_source${"itemId":"2b0cb5ca-5944-5e46-82a1-6c40531b2346","questionId":"99a70a9b-e64b-5f01-a9e1-d55675336b62","sourceKey":"bank:ECO201:ORD-029","payload":{"prompt":"The locus of consumer equilibrium points traced out as money income changes, with the prices of both goods held constant, is the","options":["indifference map","demand curve","income consumption curve","price consumption curve"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The income consumption curve joins the tangency points formed as the budget line shifts in parallel when income changes. The price consumption curve (D) comes from a price change, the demand curve (B) relates price to quantity, and the indifference map (A) shows preferences only."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 185, $official_bank_source${"itemId":"b3b25c8d-399c-50f5-ba2b-2999b68ea5ae","questionId":"a57592d0-597c-5d77-83cb-578d99fbea8f","sourceKey":"bank:ECO201:ORD-030","payload":{"prompt":"In indifference curve analysis, the individual's demand curve for good X is derived from the","options":["Engel curve","price consumption curve","income consumption curve","indifference map alone"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Each point on the price consumption curve pairs a price of X with the quantity chosen, which gives the demand curve. The income consumption curve (C) gives the Engel curve (A) instead, and the indifference map (D) alone has no prices in it."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 186, $official_bank_source${"itemId":"c04edf18-aec3-5410-9d6b-05cef92c836f","questionId":"a6412606-d043-5111-afbf-14ab4bae946f","sourceKey":"bank:ECO201:ORD-031","payload":{"prompt":"A curve showing the relationship between a consumer's income and the quantity of a good she demands, with prices held constant, is called","options":["an indifference curve","a demand curve","an Engel curve","a price consumption curve"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The Engel curve plots income against quantity demanded and is derived from the income consumption curve. A demand curve (B) plots price against quantity, the price consumption curve (D) shows equilibria as price changes, and an indifference curve (A) shows equal satisfaction."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 187, $official_bank_source${"itemId":"eea915fd-63ab-5874-905f-8e725a9161df","questionId":"ca8c3f66-8458-5d45-bc3f-22de988f59c7","sourceKey":"bank:ECO201:ORD-032","payload":{"prompt":"For an inferior good, the Engel curve is","options":["negatively sloped, since quantity demanded falls as income rises","identical to the demand curve","vertical at all income levels","positively sloped, since quantity demanded rises as income rises"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"An inferior good is bought less as income rises, so its Engel curve slopes downward. Option D describes a normal good, option C would mean quantity never responds to income, and option B confuses income with price on the vertical axis."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 188, $official_bank_source${"itemId":"88a7c3d6-65d4-59b4-83f4-dc1c5b949a8c","questionId":"928b2fc1-39ab-576a-8897-ad7ecbeb4230","sourceKey":"bank:ECO201:ORD-033","payload":{"prompt":"With X on the horizontal axis, the income consumption curve bends back towards the Y-axis as income rises. This shows that","options":["X is a necessity with positive income elasticity","X is an inferior good","Y is an inferior good","X is a luxury good"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"A curve bending towards the Y-axis means less X is bought at higher incomes, which is the definition of an inferior good, while Y is still rising and so normal. Option C gets the goods the wrong way round, and options D and A are both normal goods whose consumption rises with income."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 189, $official_bank_source${"itemId":"1adc547d-49a4-5cd1-92e4-71b319f5baa2","questionId":"cee2eb97-1dc9-5839-b00c-a83ae9c48b83","sourceKey":"bank:ECO201:ORD-034","payload":{"prompt":"Ngozi has N2,000 a week to spend on boli (X) at N100 each and packs of groundnut (Y) at N50 each. What is the maximum quantity of boli she can buy?","options":["2","40","20","13.3"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Spending all N2,000 on boli gives M/Px = 2,000/100 = 20, the X-intercept of her budget line. Option B divides by the price of groundnut instead, option D divides by the sum of both prices, and option A is just the price ratio Px/Py."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 190, $official_bank_source${"itemId":"5beea4f3-1cfd-5eca-8bf6-4e01333b8a95","questionId":"6ac5553b-997b-5adb-8a85-202a9559fb0d","sourceKey":"bank:ECO201:ORD-035","payload":{"prompt":"A student has N3,600 to spend on bread (X) at N120 per loaf and sachets of milk (Y) at N90 each. With Y on the vertical axis, what is the vertical intercept of the budget line?","options":["17.1 sachets of milk","30 sachets of milk","1.33 sachets of milk","40 sachets of milk"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The vertical intercept is the most Y she can buy, M/Py = 3,600/90 = 40. Option B uses the price of bread (3,600/120 = 30), option A divides by both prices added together, and option C is only the price ratio 120/90."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 191, $official_bank_source${"itemId":"f55691d1-30e9-513e-9ec0-74459e105f29","questionId":"609c6807-6ab4-5102-887f-4097a64bd649","sourceKey":"bank:ECO201:ORD-036","payload":{"prompt":"A consumer with an income of N1,500 buys X at N150 and Y at N50. With Y on the vertical axis, the slope of her budget line is","options":["-30","-3","-10","-1/3"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The slope is -Px/Py = -150/50 = -3, meaning one more unit of X costs her 3 units of Y. Option D inverts the price ratio, while options A and C are the Y-intercept (30) and X-intercept (10) mistaken for the slope."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 192, $official_bank_source${"itemId":"6317b52c-ee7d-537e-a977-44e1f4cfb39e","questionId":"89c36061-c561-5b25-8b8e-ba15014692d6","sourceKey":"bank:ECO201:ORD-037","payload":{"prompt":"Ngozi's income is N2,000, the price of X is N100 and the price of Y is N50. Which equation describes her budget line with Y on the vertical axis?","options":["Y = 40 - 2X","Y = 40 - 0.5X","Y = 20 - 2X","Y = 20 - 0.5X"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"From 100X + 50Y = 2,000, dividing by 50 gives Y = 40 - 2X, so the intercept is M/Py = 40 and the slope is -Px/Py = -2. Option C uses the X-intercept as the vertical intercept, while options B and D invert the price ratio."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 193, $official_bank_source${"itemId":"ceb155f7-6f13-5bbe-b54c-872d15940937","questionId":"8eef7cb7-43fe-59c6-8713-76bce687711b","sourceKey":"bank:ECO201:ORD-038","payload":{"prompt":"A consumer has income N2,000; Px = N100 and Py = N50. If her income rises to N3,000 with prices unchanged, the new maximum quantity of X she can buy is","options":["60","20","30","40"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The new X-intercept is 3,000/100 = 30, and since prices have not changed the budget line shifts out parallel. Option B is the old intercept, option A is the new Y-intercept (3,000/50), and option D is the old Y-intercept."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 194, $official_bank_source${"itemId":"d2b71249-2506-54df-97a4-085674854c16","questionId":"84473c0c-1900-59a3-8a86-6c013c9191f4","sourceKey":"bank:ECO201:ORD-039","payload":{"prompt":"With income N2,000, Px = N100 and Py = N50, the price of X falls to N50. What are the new X-intercept and Y-intercept of the budget line?","options":["X-intercept 40, Y-intercept 80","X-intercept 20, Y-intercept 40","X-intercept 40, Y-intercept 20","X-intercept 40, Y-intercept 40"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The new X-intercept is 2,000/50 = 40, while the Y-intercept stays at 2,000/50 = 40 because Py and income are unchanged; the line rotates outward on the X-axis. Option B is the original line, and options A and C wrongly change the Y-intercept."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 195, $official_bank_source${"itemId":"fc20906c-e6bc-58d2-bd04-b2383706032f","questionId":"ae330b03-9eec-5e8e-9d95-efaeffbd27d5","sourceKey":"bank:ECO201:ORD-040","payload":{"prompt":"Emeka has N2,000 and buys 12 units of X at N100 each and 15 units of Y at N50 each. How much of his income is left unspent?","options":["N0","N50","N250","N1,950"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The bundle costs 12 x 100 + 15 x 50 = 1,200 + 750 = N1,950, so N50 is left and the bundle lies just inside the budget line. Option A assumes it is on the line, option D is the cost of the bundle rather than what is left, and option C comes from an arithmetic slip."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 196, $official_bank_source${"itemId":"e8745cd9-a8fb-55e1-9909-90fc8002b802","questionId":"22449121-d449-58bb-b9b7-1cc8d60249ef","sourceKey":"bank:ECO201:ORD-041","payload":{"prompt":"A consumer's budget line cuts the X-axis at 25 units and the Y-axis at 50 units. If the price of Y is N40, what is the price of X?","options":["N80","N50","N20","N40"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Income is 50 x N40 = N2,000 (the Y-intercept times Py), and since the X-intercept is M/Px, Px = 2,000/25 = N80. Option D assumes the two prices are equal, option C inverts the ratio of intercepts, and option B confuses the Y-intercept with a price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 197, $official_bank_source${"itemId":"1ae2b0f1-8bb7-5b0c-bc96-046d1481efd4","questionId":"02be2ca0-7bb1-5b83-9f1f-c7e43f063ff1","sourceKey":"bank:ECO201:ORD-042","payload":{"prompt":"With income N2,000, Px = N100 and Py = N50, the price of X rises to N200. With Y on the vertical axis, the slope of the new budget line is","options":["-1, so the line becomes flatter","-4, so the line becomes steeper","-0.25, so the line becomes flatter","-2, so the slope is unchanged"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"The new slope is -Px/Py = -200/50 = -4, steeper than the original -2, because X is now dearer relative to Y. Option D ignores the price change, option C inverts the price ratio, and option A has no basis in the figures."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 198, $official_bank_source${"itemId":"1481e8a9-a430-5526-b888-702748d729cb","questionId":"d316c6ad-69b3-5356-9c49-ffac7e3913b5","sourceKey":"bank:ECO201:ORD-043","payload":{"prompt":"Tolu's utility function is U = XY. Her income is N1,200, the price of X is N20 and the price of Y is N30. Using MRSxy = Y/X = Px/Py and her budget constraint, how many units of X does she buy in equilibrium?","options":["20","24","60","30"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Y/X = 20/30 gives 30Y = 20X, so she spends equal amounts on each good; 20X = 600 gives X = 30 (and Y = 20). Option C spends the whole income on X, option A is the quantity of Y, and option B divides income by the sum of prices."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 199, $official_bank_source${"itemId":"c8560256-ee14-5573-a99b-3d4391af0eed","questionId":"e22a234d-622a-5cec-beae-89100f9699bd","sourceKey":"bank:ECO201:ORD-044","payload":{"prompt":"A consumer has U = XY, income N900, Px = N15 and Py = N45. In equilibrium (MRSxy = Y/X = Px/Py) she buys how many units of Y?","options":["30","20","10","15"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"With U = XY she spends half her income on each good, so 45Y = 450 and Y = 10 (while X = 30). Option B spends the whole N900 on Y, option A is the quantity of X, and option D divides income by Px + Py."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 200, $official_bank_source${"itemId":"b7139918-c5ad-52bd-8751-0df962c7872a","questionId":"912eb3b1-13c2-53b7-b757-f09680d0b6d7","sourceKey":"bank:ECO201:ORD-045","payload":{"prompt":"Tolu has U = XY, income N1,200, Px = N20 and Py = N30. What is the maximum level of utility she can reach?","options":["300","1,200","50","600"],"correctOption":3,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Her equilibrium is X = 30 and Y = 20, so U = 30 x 20 = 600. Option B confuses utility with income, option A halves the correct answer, and option C adds X and Y instead of multiplying them."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 201, $official_bank_source${"itemId":"7ba582cb-9d18-571f-addb-385e58730897","questionId":"bcad74d4-6f46-5099-8c85-afc468579c2b","sourceKey":"bank:ECO201:ORD-046","payload":{"prompt":"For the utility function U = XY, MRSxy = MUx/MUy = Y/X. What is MRSxy at the bundle X = 4, Y = 10?","options":["14","40","2.5","0.4"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"MUx = Y and MUy = X, so MRSxy = Y/X = 10/4 = 2.5: she would give up 2.5 units of Y for one more X. Option D is X/Y, the inverse, option B is the utility level XY, and option A is X + Y."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 202, $official_bank_source${"itemId":"542c5a84-c987-5b6b-a84b-5634c9fc0be1","questionId":"8d72fbb7-04fe-55f0-805e-a3aebdff35ee","sourceKey":"bank:ECO201:ORD-047","payload":{"prompt":"A consumer with U = XY (so MRSxy = Y/X) has N300, buys X at N10 and Y at N20, and currently consumes 10 X and 10 Y. Which statement is correct?","options":["MRSxy = 1 exceeds Px/Py = 0.5, so she should buy more X and less Y","MRSxy = 1 exceeds Px/Py = 0.5, so she should buy more Y and less X","MRSxy equals Px/Py, so she is already in equilibrium","MRSxy = 1 is less than Px/Py = 2, so she should buy more Y and less X"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"MRSxy = 10/10 = 1 while Px/Py = 10/20 = 0.5, so she values X more highly than the market price ratio and gains by switching spending towards X. Option B moves the wrong way, option C ignores the gap between the two ratios, and option D inverts the price ratio."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 203, $official_bank_source${"itemId":"46466897-53bb-5471-9f63-2bd997c2275a","questionId":"328b12ef-4a50-5e54-8c24-8e4c01f23213","sourceKey":"bank:ECO201:ORD-048","payload":{"prompt":"A consumer has U = XY, so her demand for X is X = M/(2Px). With Px = N10 and Py = N5, her income rises from N200 to N400. Along her income consumption curve, her purchase of X rises from 10 units to","options":["20 units","30 units","10 units","40 units"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"At M = 400, X = 400/(2 x 10) = 20, so X doubles as income doubles and X is a normal good. Option D uses M/Px and forgets that half of income goes on Y, option C assumes no change, and option B has no basis in the formula."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 204, $official_bank_source${"itemId":"d8b44fcd-2395-55d8-bb0c-faf1cb36f81b","questionId":"53395dab-3fd6-5662-8bd8-563a7c9a23c9","sourceKey":"bank:ECO201:ORD-049","payload":{"prompt":"A consumer has U = XY, so X = M/(2Px). Her income is N600 and Py = N10. If the price of X falls from N30 to N20, her quantity of X along the price consumption curve rises from 10 to","options":["20","30","15","10"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"At Px = 20, X = 600/(2 x 20) = 15, up from 600/60 = 10, which is one point on her downward-sloping demand curve. Option B is M/Px without halving, option D assumes no response, and option A is a miscalculation."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 205, $official_bank_source${"itemId":"e0738112-b233-59dd-b3a8-48d95483daf8","questionId":"ab8006b6-a033-5170-b741-85834a934a0c","sourceKey":"bank:ECO201:ORD-050","payload":{"prompt":"A consumer with utility U = XY maximises utility subject to Px.X + Py.Y = M. Her demand function for X is","options":["X = M / (Px + Py)","X = M / (2Px)","X = M / Px","X = 2M / Px"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Setting MRSxy = Y/X equal to Px/Py gives Px.X = Py.Y, so she spends half of M on X and X = M/(2Px). Option C spends all income on X, option D doubles it, and option A wrongly buys equal quantities of both goods."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 206, $official_bank_source${"itemId":"492c3abe-974e-52a1-b39e-81dfa3ad8c84","questionId":"b63ae080-087d-5232-8425-2b27b23993e4","sourceKey":"bank:ECO201:ORD-051","payload":{"prompt":"A consumer has U = XY and an income of N5,000. Whatever the prices, how much will she spend on good X in equilibrium?","options":["N2,500","It cannot be found without the prices","N1,250","N5,000"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"With U = XY the tangency condition gives Px.X = Py.Y, so exactly half of income, N2,500, is spent on X whatever the prices. Option D spends all income on X, option C is a quarter of income, and option B misses that the spending share is fixed for this utility function."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 207, $official_bank_source${"itemId":"6cfa12af-21c1-5595-a227-25629615dc0c","questionId":"ad79fd69-8d90-596c-aeda-434800c76371","sourceKey":"bank:ECO201:ORD-052","payload":{"prompt":"Kemi always takes one cup of tea with exactly one sachet of milk, so U = min(X, Y), where X is cups of tea and Y is sachets of milk. Her income is N1,200, tea costs N40 a cup and milk N20 a sachet. How many cups of tea does she buy?","options":["10","30","20","60"],"correctOption":2,"section":"Consumer Behaviour: Ordinal Utility","explanation":"For perfect complements she buys equal quantities, so 40X + 20X = 1,200 gives X = Y = 20. Option B spends all income on tea, option D spends it all on milk, and option A halves the correct answer."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 208, $official_bank_source${"itemId":"a4c2720c-a9a7-5086-a9e1-12e63dd00541","questionId":"745df804-517d-55d2-ae19-d628687c1b70","sourceKey":"bank:ECO201:ORD-053","payload":{"prompt":"A consumer treats brands X and Y of garri as perfect substitutes, U = X + Y. Her income is N2,000, X costs N50 a cup and Y costs N40 a cup. Her utility-maximising bundle is","options":["0 of X and 50 of Y","22.2 of each","40 of X and 0 of Y","20 of X and 25 of Y"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"With perfect substitutes exchanged one-for-one she buys only the cheaper brand, so she spends N2,000 on Y at N40, getting 50 cups (utility 50). Option C buys only the dearer brand (utility 40), option B splits equally (utility 44.4), and option D gives utility 45, all lower."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 209, $official_bank_source${"itemId":"eaf8ff4b-f4ee-57e9-8efc-9958f5b3109b","questionId":"3ff26eed-f75e-5680-854f-61ed4c10b0b3","sourceKey":"bank:ECO201:ORD-054","payload":{"prompt":"A consumer is indifferent between the bundles (X=1, Y=20), (X=2, Y=14), (X=3, Y=10) and (X=4, Y=8). What is MRSxy when moving from the third bundle to the fourth?","options":["4","2","6","8"],"correctOption":1,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Moving from (3, 10) to (4, 8) she gives up 2 units of Y for 1 more X, so MRSxy = 2; the values 6, 4, 2 show a diminishing MRS. Option C is the MRS for the first move, option A is for the second move, and option D is the quantity of Y in the fourth bundle."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 210, $official_bank_source${"itemId":"46b42176-bb01-5cd8-92ad-eb100099fa27","questionId":"df06bd3f-d3e9-5628-b165-239d330c2dd8","sourceKey":"bank:ECO201:ORD-055","payload":{"prompt":"A consumer has U = XY, so X = M/(2Px). If Px = N25, which equation is her Engel curve for X?","options":["X = M/50","X = 50M","X = M/25","X = 25/M"],"correctOption":0,"section":"Consumer Behaviour: Ordinal Utility","explanation":"Substituting Px = 25 gives X = M/(2 x 25) = M/50, a straight upward-sloping line through the origin, showing X is a normal good. Option C forgets the 2, option B multiplies instead of dividing, and option D would make X fall as income rises."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 211, $official_bank_source${"itemId":"7808e201-f785-55e5-846f-16c21175864b","questionId":"6a311915-327c-5615-8e68-6a3f2a787eec","sourceKey":"bank:ECO201:E201-0049","payload":{"prompt":"The income effect of a price increase of a normal good is to ______ of that good, and the substitution effect is to ______ of that good.","options":["Increase quantity demanded, reduce quantity demanded","Increase quantity demanded, increase quantity demanded","Reduce quantity demanded, reduce quantity demanded","Reduce quantity demanded, increase quantity demanded"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"For a normal good, a price rise makes the good relatively dearer, so the substitution effect reduces quantity demanded, and it also lowers real income, which reduces purchases of a normal good too. Both effects work in the same direction, which is why a normal good has a downward-sloping demand curve. Option A pairs a falling substitution effect with a rising income effect, which is the inferior-good case, while options B and D wrongly make the substitution effect raise quantity after a price rise."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 212, $official_bank_source${"itemId":"82d0a805-d275-5d31-a25a-95bf2d190056","questionId":"72cd2fce-c749-5b1b-9df8-9ff32bbb2d1e","sourceKey":"bank:ECO201:E201-0052","payload":{"prompt":"Which of the following describes the substitution effect when the price of a commodity falls? ______.","options":["Move up the same curve","Move to a lower curve","Move down the same curve","Move to a higher curve"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The substitution effect is measured along the original indifference curve, holding real income constant. When the price of a good falls it becomes relatively cheaper, so the consumer moves down the same indifference curve towards more of that good. Option D, moving to a higher curve, is what the income effect does, and options A and B describe the wrong direction or a fall in welfare."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 213, $official_bank_source${"itemId":"10222b22-6242-568f-ada4-ac9fcfd231f1","questionId":"452df76d-a481-5f42-bb4b-f998cdb10e6a","sourceKey":"bank:ECO201:E201-0070","payload":{"prompt":"Consumer surplus is the difference between ______ and ______.","options":["Willingness to pay and market price","Market price and cost of production","Supply and demand","Revenue and profit"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"Consumer surplus is the gap between the most a consumer is willing to pay for a good and the price actually paid in the market. If you would pay N500 for a plate of food but the price is N350, your consumer surplus is N150. Option B describes the producer's side, and option D, revenue minus profit, gives total cost, not consumer surplus."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 214, $official_bank_source${"itemId":"f718bf9e-d6f3-56ce-8c9f-f2f9600e49d5","questionId":"5820a09a-bf39-5d1f-a8ae-79e6c49b0484","sourceKey":"bank:ECO201:E201-0080","payload":{"prompt":"Consumer surplus on a demand-supply graph is the area: ______.","options":["Below the demand curve and above the price","Above the demand curve and below the price","Above the supply curve and below the price","Above both curves"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"Consumer surplus is shown as the area below the demand curve and above the market price, up to the quantity bought. The demand curve shows what consumers are willing to pay for each unit, and the price line shows what they actually pay, so the gap between them is their surplus. Option C, the area above the supply curve and below the price, is producer surplus, and option B reverses the correct position."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 215, $official_bank_source${"itemId":"6d1d24d4-58c1-5c8d-af1e-895b82b10710","questionId":"96d173b7-7b3b-5515-b737-73831de2ecf6","sourceKey":"bank:ECO201:E201-0090","payload":{"prompt":"If the market price of a good increases, consumer surplus will: ______.","options":["Increase","Decrease","Remain unchanged","Become zero always"],"correctOption":1,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"Consumer surplus is the gap between what consumers are willing to pay and the market price. When the price rises, that gap shrinks and fewer units are bought, so consumer surplus decreases. Option D is wrong because surplus only disappears if the price rises to the highest amount any consumer would pay, not always."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 216, $official_bank_source${"itemId":"292df4b2-672a-53c6-b399-344dd1a2f51e","questionId":"6530c6a0-5fb5-504f-a670-e95e916561eb","sourceKey":"bank:ECO201:E201-0100","payload":{"prompt":"Consumer surplus is mainly used in microeconomics to measure: ______.","options":["Producer cost","Government revenue","National income","Consumer welfare"],"correctOption":3,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"Consumer surplus measures the benefit consumers get over and above what they pay, so it is used to measure consumer welfare, for example to judge how a tax or price change affects buyers. Options B and C are wrong because government revenue and national income are measured with different tools, and option A concerns producers, not consumers."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 217, $official_bank_source${"itemId":"13dd219c-71b9-5c7b-8938-ed73f54f715c","questionId":"a029210d-6ce8-56b1-8dfd-ba6537fa0c00","sourceKey":"bank:ECO201:E201-0385","payload":{"prompt":"The curve showing the quantity of a good that would be purchased at various income levels:","options":["Income Consumption Curve","Price Consumption Curve","Engel Curve","Indifference Curve"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"An Engel curve plots the quantity of a good bought against the consumer's income. Option A, the income consumption curve, is drawn on an indifference map and joins the equilibrium combinations of two goods as income changes, so it is related but is not a direct plot of quantity against income."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 218, $official_bank_source${"itemId":"5d651dab-f188-5cfb-8e04-de642690c149","questionId":"33fe0966-255d-57ea-9dc9-012225f7d063","sourceKey":"bank:ECO201:E201-0387","payload":{"prompt":"Substitution Effect is:","options":["Always negative","Always positive","Seldom negative","Zero"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The substitution effect always moves quantity demanded in the opposite direction to the price change: a cheaper good is always substituted for others. That is why it is described as always negative. Options B and C are wrong because, unlike the income effect, the substitution effect never changes sign."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 219, $official_bank_source${"itemId":"d1d512cc-f192-5827-a683-d13a7042656b","questionId":"dcd3c8cd-b223-5c01-9c52-cb123d33bd03","sourceKey":"bank:ECO201:E201-0410","payload":{"prompt":"The demand curve for a Giffen good has:","options":["A vertical shape","A horizontal shape","A negative slope","A positive slope"],"correctOption":3,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"A Giffen good is an inferior good whose negative income effect is strong enough to outweigh the substitution effect, so quantity demanded rises when price rises and the demand curve slopes upward. A negative slope (option C) is the normal case under the law of demand, which Giffen goods violate."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 220, $official_bank_source${"itemId":"c6ffd42d-f177-53cb-a6f9-8b8f06f8ba2b","questionId":"7d506d97-a51b-5d1c-b13c-8265f55445b1","sourceKey":"bank:ECO201:E201-0457","payload":{"prompt":"Which of the following correctly distinguishes a normal good from an inferior good?","options":["A normal good is a necessity, while an inferior good is a luxury","Demand for a normal good falls when income rises, while demand for an inferior good rises when income rises","Demand for a normal good rises when income rises, while demand for an inferior good falls when income rises","A normal good obeys the law of demand, while an inferior good always has an upward-sloping demand curve"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The difference lies in how demand responds to income: buyers want more of a normal good as they get richer, but switch away from an inferior good (for example, cheaper staples) as income rises. Option B reverses the two, and option D is wrong because most inferior goods still have downward-sloping demand curves; only Giffen goods slope upward. Option A is wrong because necessities and luxuries are both normal goods."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 221, $official_bank_source${"itemId":"5d6c4411-31da-5784-967c-6278bfaf4c25","questionId":"d1ca5887-bb5d-5e57-91f3-9d03d856cd11","sourceKey":"bank:ECO201:E201-0458","payload":{"prompt":"When the price of a normal good falls, how are its substitution effect and income effect related?","options":["Both effects increase the quantity demanded, so the income effect reinforces the substitution effect","The income effect increases quantity demanded but the substitution effect reduces it","The substitution effect increases quantity demanded but the income effect reduces it","Both effects reduce the quantity demanded"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"A price fall makes the good relatively cheaper, so the substitution effect raises quantity demanded; it also raises real income, and for a normal good higher real income raises demand too, so the two effects work in the same direction. Option C describes an inferior good, where the income effect works against the substitution effect. Option B is wrong because the substitution effect of a price fall always raises quantity demanded, never reduces it."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 222, $official_bank_source${"itemId":"e20578c0-eb81-5817-98ae-d19ac4bac469","questionId":"60a68d6c-7ce9-53f9-816e-17bd860e00c7","sourceKey":"bank:ECO201:ISE-001","payload":{"prompt":"In indifference curve analysis, the total effect of a change in the price of a good on its quantity demanded (the price effect) can be split into","options":["a substitution effect and a scale effect","a substitution effect and an income effect","a price effect and an Engel effect","an income effect and an output effect"],"correctOption":1,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"A price change alters both relative prices and the consumer's real income, so the total change is the substitution effect plus the income effect. Options D and A borrow terms from the theory of the firm, and option C is circular because the price effect is the total being decomposed."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 223, $official_bank_source${"itemId":"cc4cd952-b585-5d8b-8065-8189bcee73f3","questionId":"7edaf1cd-e55d-5209-baa4-65088515fd1e","sourceKey":"bank:ECO201:ISE-002","payload":{"prompt":"The change in quantity demanded of a good that results only from a change in its relative price, with the consumer's real income held constant, is the","options":["price effect","substitution effect","income effect","Giffen effect"],"correctOption":1,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"Holding real income constant means keeping the consumer on her original indifference curve, so the only influence left is the change in relative prices, which is the substitution effect. The income effect (C) holds relative prices constant instead, the price effect (A) is the total change, and option D is not a component of the decomposition."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 224, $official_bank_source${"itemId":"f1a0f91b-2b42-52ce-bf5e-6f6718f10e05","questionId":"53a66b7a-0742-56dc-b995-3c617d0ae40e","sourceKey":"bank:ECO201:ISE-003","payload":{"prompt":"The change in quantity demanded of a good that results from a change in the consumer's real income, with relative prices held constant, is the","options":["compensating variation","endowment effect","substitution effect","income effect"],"correctOption":3,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The income effect captures how a change in purchasing power alone alters consumption, shown by a parallel shift of the budget line. The substitution effect (C) holds real income constant, option B applies only to consumers who sell goods they own, and the compensating variation (A) is a sum of money, not a change in quantity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 225, $official_bank_source${"itemId":"0585dee4-3263-5d46-8eab-f55cf1c4bf7b","questionId":"8730b157-be41-58b5-8792-3467aba90da9","sourceKey":"bank:ECO201:ISE-004","payload":{"prompt":"In the indifference curve diagram of a price fall, the substitution effect is measured as a movement","options":["along the original indifference curve","along the price consumption curve from the old to the new equilibrium","along the new, higher indifference curve","between two parallel budget lines"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The substitution effect rotates the budget line around the original indifference curve to the new price slope, so it is a movement along that curve from E0 to E1. Options C and D point to the higher curve and the parallel shift between budget lines, which belong to the income effect, and option B is the total price effect from E0 to E2."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 226, $official_bank_source${"itemId":"d9da53c1-a3dc-5050-9105-9340ea9357b7","questionId":"7c2d9d78-7995-58e0-9d0d-4c1880c550a2","sourceKey":"bank:ECO201:ISE-005","payload":{"prompt":"In the decomposition of a price change, the income effect is shown by","options":["a movement along the original indifference curve","a parallel shift of the budget line from the compensated line to the actual new line","a change in the slope of the indifference curves","a rotation of the budget line around the original indifference curve"],"correctOption":1,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The income effect keeps relative prices fixed, so it is shown by a parallel shift between the compensated and the actual new budget line, moving the consumer from E1 to E2. Options D and A describe the substitution effect, and option C would mean tastes had changed."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 227, $official_bank_source${"itemId":"94970dfc-06cf-56ee-ab71-f96ec1400c22","questionId":"2a808c05-ca7e-5a04-ac5e-1fd2d94248ed","sourceKey":"bank:ECO201:ISE-006","payload":{"prompt":"After the price of X falls, a hypothetical budget line is drawn parallel to the new budget line but just tangent to the original indifference curve. This line is called the","options":["original budget line","compensated budget line","Engel curve","income consumption curve"],"correctOption":1,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The compensated budget line shows the new relative prices but with enough income taken away to leave the consumer on her original indifference curve, which isolates the substitution effect. The income consumption curve (D) and Engel curve (C) trace income changes, and the original budget line (A) has the old price slope."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 228, $official_bank_source${"itemId":"86c0706d-0827-5a52-a920-5bf0eb451b79","questionId":"a6b03df3-bafc-5ba4-8be4-0cc8061d7f25","sourceKey":"bank:ECO201:ISE-007","payload":{"prompt":"The difference between the Hicks and Slutsky approaches to separating income and substitution effects is that","options":["Hicks applies only to normal goods, while Slutsky applies only to inferior goods","Hicks keeps the consumer on her original indifference curve, while Slutsky lets her just afford her original bundle","Slutsky keeps the consumer on her original indifference curve, while Hicks lets her just afford her original bundle","Hicks holds money income constant, while Slutsky holds the price of the good constant"],"correctOption":1,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"Hicks compensates so that the original level of satisfaction (utility) is kept, while Slutsky compensates so that the original bundle is just affordable at the new prices (constant purchasing power). Option C swaps the two, option D misdescribes both, and option A is false because both methods apply to any good."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 229, $official_bank_source${"itemId":"897725a9-f3f3-5844-b3f5-4e93dfd51229","questionId":"fcd0083b-84ca-5412-8eff-57385efb3d9a","sourceKey":"bank:ECO201:ISE-008","payload":{"prompt":"In the Slutsky approach, the compensated budget line has the new price ratio and passes through","options":["the origin of the diagram","the bundle the consumer bought before the price change","the point where the new indifference curve meets the Y-axis","the bundle the consumer buys after the price change"],"correctOption":1,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"Slutsky removes just enough income for the consumer to be able to buy her original bundle at the new prices, so the compensated line goes through that bundle. Option D is the final equilibrium, while options A and C have no role in the construction."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 230, $official_bank_source${"itemId":"29b02e88-c0f4-5914-8480-e7e78dfc870a","questionId":"936b1c20-0cb1-5d2c-98ed-8343b0b98db3","sourceKey":"bank:ECO201:ISE-009","payload":{"prompt":"After the price of X falls and the Slutsky compensation is made, the consumer generally ends up","options":["on an indifference curve at least as high as the original one","on the new budget line without any compensation","on an indifference curve below the original one","at her original bundle in every case"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"She can still afford her original bundle, but with the new relative prices she usually prefers to substitute towards X, reaching a slightly higher indifference curve; Hicks, by contrast, keeps her exactly on the original curve. Option C is impossible since the old bundle is affordable, option D ignores substitution, and option B ignores the compensation."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 231, $official_bank_source${"itemId":"ca6a366d-c7da-5544-a2c0-de5b90d61028","questionId":"81c7ce95-b522-5eb9-88db-23b9d8604c30","sourceKey":"bank:ECO201:ISE-010","payload":{"prompt":"The substitution effect of a fall in the price of good X, holding real income constant, always","options":["increases the quantity demanded of X","decreases the quantity demanded of X","depends on whether X is normal or inferior","leaves the quantity demanded of X unchanged"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"More is always consumed of the good whose relative price has fallen, so the substitution effect moves quantity in the opposite direction to the price change. Options B and D contradict this, and option C describes the income effect, whose direction does depend on the type of good."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 232, $official_bank_source${"itemId":"cb4e49a8-6980-5cba-ba4a-3559b532e526","questionId":"d0ff9587-efe2-5e4c-90b6-e9fd57a5fb11","sourceKey":"bank:ECO201:ISE-011","payload":{"prompt":"The substitution effect always works in the opposite direction to the price change because","options":["the demand curve always slopes downward","indifference curves are convex to the origin","money income is held constant","the good is always a normal good"],"correctOption":1,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"With convex indifference curves, rotating the budget line around the original curve to a flatter slope (cheaper X) must move the tangency towards more X. Option D is wrong because the result holds for inferior goods too, option C confuses money with real income, and option A is a result to be explained, not a cause."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 233, $official_bank_source${"itemId":"b51b849e-e27e-56e3-a41a-0ff28476af02","questionId":"c1505e61-5040-5e70-92d8-daab72745f70","sourceKey":"bank:ECO201:ISE-012","payload":{"prompt":"A good is a normal good when, for a fall in its price,","options":["the income effect works against the substitution effect but is smaller","the substitution effect is zero","the income effect works against the substitution effect and is larger","the income effect reinforces the substitution effect"],"correctOption":3,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"For a normal good the rise in real income from the price fall raises consumption further, so both effects increase quantity demanded. Option A describes an inferior good that is not Giffen, option C describes a Giffen good, and option B cannot happen with convex indifference curves."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 234, $official_bank_source${"itemId":"ab994759-265c-59e5-9014-141a02e3063a","questionId":"51f37433-ae6b-5083-b3a7-84173c274d4a","sourceKey":"bank:ECO201:ISE-013","payload":{"prompt":"For an inferior good, the income effect of a fall in its price","options":["always outweighs the substitution effect","reinforces the substitution effect, raising quantity demanded","is always zero","works against the substitution effect, reducing quantity demanded"],"correctOption":3,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"An inferior good is bought less as real income rises, so the income effect of a price fall is negative and offsets part of the positive substitution effect. Option B is the normal-good case, option C is false, and option A is only true of the special Giffen case."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 235, $official_bank_source${"itemId":"d94c22cf-1da9-5d77-9e14-06b02dd90b70","questionId":"727ad7d3-fa28-57bf-a2ec-87c29e5c753e","sourceKey":"bank:ECO201:ISE-014","payload":{"prompt":"An inferior good that is not a Giffen good still has a downward-sloping demand curve because","options":["the income effect is zero","the income effect is larger than the substitution effect","the substitution effect is larger than the negative income effect","both effects increase quantity demanded when price falls"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"When the negative income effect is smaller, the substitution effect dominates and a price fall still raises quantity demanded on balance. Option B describes a Giffen good, option D describes a normal good, and option A is not what makes a good inferior."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 236, $official_bank_source${"itemId":"455257cb-1eac-5993-b42f-27d6ed262bdd","questionId":"4f35fe85-c069-5673-a225-2638241d45cf","sourceKey":"bank:ECO201:ISE-015","payload":{"prompt":"A good for which a fall in price leads to a fall in quantity demanded, because a strong negative income effect outweighs the substitution effect, is called","options":["a luxury good","a normal good","a Giffen good","a perfect complement"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"A Giffen good has an upward-sloping demand curve because its negative income effect is bigger than the substitution effect. Normal (B) and luxury (A) goods have positive income effects that reinforce the substitution effect, and option D describes a shape of indifference curve, not a demand response."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 237, $official_bank_source${"itemId":"f977a0cc-2d02-59e5-b737-61ca88ee2f71","questionId":"c5e920df-4a70-51c3-a188-d421e803717f","sourceKey":"bank:ECO201:ISE-016","payload":{"prompt":"Which of the following is NOT a condition usually needed for a good to be a Giffen good?","options":["The good is strongly inferior","The good has few close substitutes, so the substitution effect is small","Spending on the good takes a large share of the consumer's budget","The good is a luxury with a high positive income elasticity"],"correctOption":3,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"A Giffen good needs a large negative income effect and a small substitution effect, so a luxury, which has a large positive income effect, cannot be Giffen. Strong inferiority (A), a large budget share (C) and few substitutes (B) are exactly the conditions that make the negative income effect dominate."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 238, $official_bank_source${"itemId":"f8175315-7f51-598e-981d-6bbad4091668","questionId":"4035a702-9f1d-5fab-842d-f93db4fb6c11","sourceKey":"bank:ECO201:ISE-017","payload":{"prompt":"Which of the following statements about inferior and Giffen goods is correct?","options":["Every inferior good is a Giffen good","Every Giffen good is inferior, but not every inferior good is a Giffen good","Giffen goods are normal goods with a strong income effect","A Giffen good has a substitution effect that raises quantity when price rises"],"correctOption":1,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"A Giffen good must have a negative income effect, so it is inferior, but most inferior goods have income effects too small to outweigh substitution. Option A reverses the relationship, option C contradicts the negative income effect, and option D is wrong because the substitution effect always moves opposite to price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 239, $official_bank_source${"itemId":"20e5deb7-a5f3-5d73-8101-ba16111836cc","questionId":"de0a3803-6a22-55b8-9019-5d1c50f75192","sourceKey":"bank:ECO201:ISE-018","payload":{"prompt":"A very poor household in a Nigerian village spends most of its income on garri. When the price of garri rises, the household cuts out meat altogether and buys more garri to avoid going hungry. For this household, garri is behaving as","options":["a normal good","a luxury good","a perfect substitute for meat","a Giffen good"],"correctOption":3,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"Quantity demanded rises with price because the large fall in real income forces the household to drop dearer foods and rely more on the cheap staple, which is the Giffen case. A normal good (A) or a luxury (B) would be bought less after a price rise, and option C would make the household switch completely towards the now relatively cheaper meat."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 240, $official_bank_source${"itemId":"39acdf59-0786-51c5-85c0-bd0cdb918658","questionId":"140846c2-32ee-5d74-9cc9-1816cf4a5748","sourceKey":"bank:ECO201:ISE-019","payload":{"prompt":"The main reason the demand curve for most goods slopes downward is that","options":["consumers always have unlimited income","the substitution effect is always smaller than the income effect","the substitution effect always raises quantity when price falls, and for normal goods the income effect adds to it","the income effect of a price fall is always negative"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"A price fall always makes the good relatively cheaper, raising quantity through substitution, and for normal goods the rise in real income adds to this; even for most inferior goods substitution still dominates. Option D is only true of inferior goods, option A is unrealistic, and option B would point towards the Giffen case."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 241, $official_bank_source${"itemId":"f24688fb-bc32-5fd3-a821-4a2d097824df","questionId":"e8ffee09-b73f-5a39-9fb6-86109d4cbb0e","sourceKey":"bank:ECO201:ISE-021","payload":{"prompt":"After a fall in the price of X, a consumer moves from E0 (quantity q0) to E1 (quantity q1) by the substitution effect and then to E2 (quantity q2) by the income effect. Which ordering of quantities indicates a Giffen good?","options":["q1 < q0 < q2","q0 < q1 < q2","q2 < q0 < q1","q0 < q2 < q1"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"In the Giffen case the negative income effect pulls quantity back past the starting point, so the final quantity q2 is below q0 even though substitution raised it to q1. Option B shows a normal good, option D shows an inferior but non-Giffen good, and option A would need a substitution effect in the wrong direction."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 242, $official_bank_source${"itemId":"0773d0d3-168b-5812-b882-9066280821d9","questionId":"66e9547c-e808-566b-b46b-2751b306efd1","sourceKey":"bank:ECO201:ISE-022","payload":{"prompt":"After a fall in the price of X, the quantities at E0, E1 and E2 are q0, q1 and q2, with q0 < q2 < q1. Good X is","options":["a good with a zero substitution effect","a Giffen good","a normal good","an inferior good that is not a Giffen good"],"correctOption":3,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The substitution effect raises quantity from q0 to q1, then a negative income effect reduces it to q2, but q2 is still above q0, so demand slopes downward. A normal good (C) would have q2 beyond q1, a Giffen good (B) would have q2 below q0, and option A contradicts the rise from q0 to q1."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 243, $official_bank_source${"itemId":"a34ad031-4520-5e13-8312-ad462fc08294","questionId":"21811727-52ad-5419-87c9-e558d8d5934c","sourceKey":"bank:ECO201:ISE-023","payload":{"prompt":"After a fall in the price of X, the quantities at E0, E1 and E2 are q0, q1 and q2, with q0 < q1 < q2. This shows that X is","options":["a normal good","a Giffen good","a good whose income effect is negative","an inferior good that is not Giffen"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"Both moves increase quantity: substitution from q0 to q1 and income from q1 to q2, so the income effect reinforces the substitution effect, which is a normal good. Options D, B and C all involve a negative income effect, which would put q2 to the left of q1."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 244, $official_bank_source${"itemId":"5c595792-743d-5f3b-b78c-b84667ed8841","questionId":"7f8dba68-f806-5c7f-bfb7-7f4588d7be82","sourceKey":"bank:ECO201:ISE-024","payload":{"prompt":"Hairdressers sell haircuts. If the price of haircuts rises, with all other prices constant, a hairdresser is likely to experience","options":["a negative income effect, because haircuts are now dearer","no income effect at all","a substitution effect towards buying more haircuts","a positive income effect, because her income from selling haircuts rises"],"correctOption":3,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"For someone who sells a good, a rise in its price raises her income, so the endowment income effect is positive and she can buy more of all normal goods. Option A applies to ordinary buyers of haircuts, option B ignores her extra earnings, and option C is wrong because a dearer good is substituted away from."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 245, $official_bank_source${"itemId":"06adb492-bb4c-5b45-8b2a-97ea81d42d75","questionId":"d7244930-5a2a-50a0-bfcc-6edba17e6ba0","sourceKey":"bank:ECO201:ISE-027","payload":{"prompt":"After the price of a good falls, the amount of income that must be taken away from the consumer to return her to her original indifference curve is the","options":["consumer surplus","equivalent variation","compensating variation","substitution effect"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The compensating variation works with the new prices and asks how much money must be removed to leave her just as well off as before the price fall. The equivalent variation (B) works with the original prices, consumer surplus (A) is the area under the demand curve, and the substitution effect (D) is a change in quantity, not a sum of money."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 246, $official_bank_source${"itemId":"01cc5754-c875-5c6c-b897-89acb5b3988d","questionId":"e6fb9651-6fb1-5d8e-a4d4-4fb7ad9da9eb","sourceKey":"bank:ECO201:ISE-028","payload":{"prompt":"The change in income, at the original prices, that would leave a consumer just as well off as a specific fall in the price of a good is the","options":["equivalent variation","compensating variation","Slutsky compensation","income effect"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The equivalent variation asks how much extra income, instead of the price fall, would raise her to the new indifference curve; it is found by shifting the original budget line out parallel. The compensating variation (B) is measured at the new prices back to the old curve, the income effect (D) is a quantity change, and option C is the income adjustment that keeps the old bundle affordable."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 247, $official_bank_source${"itemId":"95d30bf5-1e7a-563d-9555-b0959ada7084","questionId":"67b9b82b-c48b-5535-9c67-120508d08bd5","sourceKey":"bank:ECO201:ISE-029","payload":{"prompt":"For a fall in the price of good X, which statement correctly compares the compensating variation (CV) and the equivalent variation (EV)?","options":["CV uses the original prices and the new indifference curve; EV uses the new prices and the original indifference curve","CV uses the new prices and the original indifference curve; EV uses the original prices and the new indifference curve","Both CV and EV are measured at the original prices along the original indifference curve","CV is a change in quantity demanded, while EV is a change in income"],"correctOption":1,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"CV shifts the new budget line back until it touches the old indifference curve, while EV shifts the old budget line out until it touches the new one. Option A swaps the two, option C would give zero for both, and option D is wrong because both are sums of money."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 248, $official_bank_source${"itemId":"51ecc68f-028b-571b-8a9b-cc61069753d2","questionId":"a909be59-348e-5a10-94c1-33da5ec6bd73","sourceKey":"bank:ECO201:ISE-030","payload":{"prompt":"The demand for suya in a Yaba neighbourhood is P = 100 - 2Q, where P is in naira per stick. If the market price is N40, consumer surplus is","options":["N1,200","N1,800","N900","N600"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"At P = 40, Q = (100 - 40)/2 = 30, and consumer surplus is the triangle 0.5 x 30 x (100 - 40) = N900. Option B forgets the one-half, option A is total spending (30 x 40), and option D uses the price instead of the gap between the intercept and the price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 249, $official_bank_source${"itemId":"d014de37-ebba-5fef-85ce-34ac677c95b3","questionId":"32c360ce-a347-542c-a511-7d1aa3cdcd6b","sourceKey":"bank:ECO201:ISE-031","payload":{"prompt":"Funke is willing to pay N500 for her first plate of amala, N400 for the second, N300 for the third and N200 for the fourth. If a plate costs N250, her consumer surplus is","options":["N450","N1,200","N400","N750"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"She buys 3 plates, since the fourth is worth only N200, and her surplus is (500 - 250) + (400 - 250) + (300 - 250) = N450. Option C wrongly includes the fourth plate (a loss of N50), option B is her total willingness to pay for three plates, and option D is what she spends."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 250, $official_bank_source${"itemId":"a4bf9596-748e-535a-aeab-5afcde3a6b63","questionId":"dfa21c1f-4937-5016-b7e6-0c24c7c23d3f","sourceKey":"bank:ECO201:ISE-032","payload":{"prompt":"Demand is P = 100 - 2Q. If the price falls from N40 to N20, by how much does consumer surplus increase?","options":["N700","N1,600","N900","N600"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"Quantity rises from 30 to 40, and consumer surplus rises from 0.5 x 30 x 60 = N900 to 0.5 x 40 x 80 = N1,600, an increase of N700. Option B is the new surplus, option C is the old surplus, and option D counts only the saving on the first 30 units (30 x 20) and leaves out the gain on the 10 extra units."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 251, $official_bank_source${"itemId":"419fab7a-a97a-585c-9678-d04682dc31d1","questionId":"2ea8cce4-c2ec-5d17-a0ca-834c09d5f0df","sourceKey":"bank:ECO201:ISE-033","payload":{"prompt":"A consumer's demand for sachet water is Q = 200 - 4P. At a price of N30 per sachet, her consumer surplus is","options":["N1,200","N2,400","N1,600","N800"],"correctOption":3,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"At P = 30, Q = 80, and the demand curve meets the price axis at P = 50, so consumer surplus is 0.5 x 80 x (50 - 30) = N800. Option C forgets the one-half, option B is total spending (80 x 30), and option A uses the price 30 instead of the gap 50 - 30."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 252, $official_bank_source${"itemId":"eaadf692-8f17-550e-9665-d8a8cfe0eab3","questionId":"e64139be-2874-582d-a2f7-9e0142037df9","sourceKey":"bank:ECO201:ISE-034","payload":{"prompt":"A consumer has U = XY, income N80 and Py = N1, so her demands are X = M/(2Px) and Y = M/(2Py). The price of X falls from N4 to N1, raising her purchase of X from 10 to 40. Using the Hicks approach (compensating her back to her original utility of 400), the substitution effect on X is","options":["20 units","15 units","30 units","10 units"],"correctOption":3,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"To keep U = 400 at the new prices she needs income M with (M/2)(M/2) = 400, so M = N40 and X = 40/2 = 20; the Hicks substitution effect is 20 - 10 = 10. Option C is the total effect, option A is the income effect, and option B is the Slutsky substitution effect, not the Hicks one."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 253, $official_bank_source${"itemId":"fbe10354-5670-5b17-8bb3-a8a2365e3392","questionId":"c0889663-8e78-5cfc-b984-d7aff4885584","sourceKey":"bank:ECO201:ISE-035","payload":{"prompt":"A consumer has U = XY, income N80 and Py = N1, so her demands are X = M/(2Px) and Y = M/(2Py). The price of X falls from N4 to N1, raising her purchase of X from 10 to 40. Using the Hicks approach (compensating her back to her original utility of 400), the income effect on X is","options":["15 units","20 units","30 units","10 units"],"correctOption":1,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"On the compensated budget line she buys 20 units of X; restoring her full income of N80 raises this to 40, so the income effect is 40 - 20 = 20, which reinforces the substitution effect because X is normal. Option D is the substitution effect, option C is the total effect, and option A is the Slutsky income effect."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 254, $official_bank_source${"itemId":"a4afe35c-b98b-5de6-bccd-5f632b727650","questionId":"c6dc67ed-1673-577f-a640-c4bf3e1a6b71","sourceKey":"bank:ECO201:ISE-036","payload":{"prompt":"A consumer has U = XY, income N80 and Py = N1, so her demands are X = M/(2Px) and Y = M/(2Py). The price of X falls from N4 to N1, raising her purchase of X from 10 to 40. How much income must be taken away from her at the new prices to return her to her original indifference curve (U = 400)?","options":["N40","N30","N50","N80"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"At the new prices she reaches U = 400 with only N40, since (40/2)(40/2) = 400, so N80 - N40 = N40 must be removed; this is the Hicks compensation, equal to the compensating variation. Option B is the Slutsky reduction (10 units x N3), option C is the Slutsky compensated income, and option D is her whole income."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 255, $official_bank_source${"itemId":"620fd63c-33c9-59c5-b8dd-d7b59a01be0e","questionId":"ea9e3ec0-da02-5a85-b8cc-db870d5c665a","sourceKey":"bank:ECO201:ISE-037","payload":{"prompt":"A consumer has U = XY, income N80 and Py = N1, so her demands are X = M/(2Px) and Y = M/(2Py). The price of X falls from N4 to N1, raising her purchase of X from 10 to 40. Under the Slutsky approach, what compensated income would allow her to just buy her original bundle (10 X and 40 Y) at the new prices?","options":["N50","N80","N40","N30"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"At the new prices the original bundle costs 10 x N1 + 40 x N1 = N50, which is the Slutsky compensated income. Option C is the Hicks compensated income, option D is the amount removed (N80 - N50), and option B is her original income."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 256, $official_bank_source${"itemId":"a859974d-673e-5aaf-8394-a67fc76b6a7a","questionId":"da906881-012a-5dd9-abc4-2c5c8dd79809","sourceKey":"bank:ECO201:ISE-038","payload":{"prompt":"The price of a staple food falls. The substitution effect raises a household's weekly purchase by 4 kg, while the income effect reduces it by 6 kg. Which statement is correct?","options":["Quantity falls by 2 kg in total, so the good is a normal good","Quantity rises by 2 kg in total, so the good is an inferior but non-Giffen good","Quantity falls by 2 kg in total, so the good is a Giffen good","Quantity rises by 10 kg in total, so the good is a normal good"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The total effect is +4 - 6 = -2 kg, so a price fall reduces quantity demanded, which happens only when a negative income effect outweighs the substitution effect: a Giffen good. Option D adds the effects as if both were positive, option B gets the sign wrong, and option A is impossible because a normal good has a positive income effect."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 257, $official_bank_source${"itemId":"56d2913e-b55c-562e-a637-40050a29cf17","questionId":"59791c95-739f-55d6-993d-ff1a6a614a8f","sourceKey":"bank:ECO201:ISE-039","payload":{"prompt":"When the price of rice falls, a consumer's total purchase rises by 10 bags. The substitution effect accounts for 6 bags. The income effect and type of good are","options":["+16 bags; rice is a normal good","+4 bags; rice is an inferior good","+4 bags; rice is a normal good","-4 bags; rice is an inferior good"],"correctOption":2,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"Since total effect = substitution effect + income effect, the income effect is 10 - 6 = +4 bags; a positive income effect from a price fall reinforces substitution, so rice is normal. Option D gets the sign wrong, option A adds instead of subtracting, and option B pairs a positive income effect with an inferior good."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 258, $official_bank_source${"itemId":"1adc6a0a-39d9-5bf2-bcf3-ba2b4a2619a1","questionId":"3d137929-b691-5df4-82b5-45fddc3f776b","sourceKey":"bank:ECO201:ISE-040","payload":{"prompt":"When the price of good X falls, the substitution effect raises quantity demanded by 8 units and the income effect reduces it by 3 units. Which statement is correct?","options":["Quantity rises by 5 units, and X is inferior but not a Giffen good","Quantity falls by 5 units, and X is a Giffen good","Quantity rises by 11 units, and X is a normal good","Quantity rises by 5 units, and X is a normal good"],"correctOption":0,"section":"Income and Substitution Effects and Consumer Surplus","explanation":"The total effect is 8 - 3 = +5 units; the income effect is negative, so X is inferior, but the substitution effect dominates, so demand still slopes downward. Option C treats both effects as positive, option B gets the direction wrong, and option D ignores the negative income effect."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 259, $official_bank_source${"itemId":"9735c262-813f-536a-9033-32296f133445","questionId":"40adb8aa-2b87-5f36-84e8-e0b9c018e28b","sourceKey":"bank:ECO201:E201-0004","payload":{"prompt":"When you sum up the quantity demand of a commodity by individual A, individual B, and individual C, the outcome is called ______.","options":["Demand curve","Elastic demand","Aggregate demand","Market demand"],"correctOption":3,"section":"Demand Theory","explanation":"Market demand is the horizontal sum of all individual demands: adding what A, B and C each buy at a given price gives the market demand for that commodity. Option C, aggregate demand, is a macroeconomic idea referring to total spending on all goods and services in the whole economy, not one commodity. A demand curve (option A) is just the graph of demand, and elastic demand (option B) describes responsiveness to price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 260, $official_bank_source${"itemId":"801f3c21-6bc7-5953-935f-36e5798c15d6","questionId":"138533e1-b0e9-5576-8ced-e5a624c3e8d7","sourceKey":"bank:ECO201:E201-0005","payload":{"prompt":"In microeconomics, you are always advised to work with simplistic assumptions that demand is a function of ______.","options":["income","Prices of commodities","Price of a commodity","Taste"],"correctOption":2,"section":"Demand Theory","explanation":"To keep analysis simple, microeconomics usually treats demand for a good as a function of its own price, Qd = f(P), holding income, tastes and other prices constant (ceteris paribus). Option B, the prices of commodities in general, brings in other goods' prices, which are held constant in this simple setup. Income and taste (options A and D) are determinants too, but they are the factors we assume fixed."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 261, $official_bank_source${"itemId":"ec374bf3-1480-5628-b9b5-e9e2b10d1fa1","questionId":"344f6b42-38fe-5b54-ab57-16253f1227d3","sourceKey":"bank:ECO201:E201-0009","payload":{"prompt":"A demand schedule, when plotted on a graph, becomes ______.","options":["A demand graph","A demand curve","A demand coordinate","A market demand"],"correctOption":1,"section":"Demand Theory","explanation":"A demand schedule is a table of prices and the quantities demanded at each price; when those pairs are plotted on a graph and joined, the result is the demand curve. Option A, 'demand graph', is not the standard term. Option D, market demand, is the sum of individual demands, which may or may not be what the schedule shows."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 262, $official_bank_source${"itemId":"803072dd-b2eb-5196-8660-8fcfc24a5577","questionId":"3fa21a39-6dbc-531c-84b2-ea63972d45b4","sourceKey":"bank:ECO201:E201-0010","payload":{"prompt":"Dx = f(Px, Pz, Y, T) is also known as ______.","options":["Demand for commodity x","Demand equation","Demand model","Demand function"],"correctOption":3,"section":"Demand Theory","explanation":"Dx = f(Px, Pz, Y, T) is a demand function: it states that the quantity demanded of x depends on its own price, the price of other goods, income and taste. Option A only names what is being determined, not what the expression is called. Options B and C are loose terms; a demand equation would give the exact numerical form, such as Qd = 100 - 2P, rather than the general f( ) form."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 263, $official_bank_source${"itemId":"a4ebbf9f-6402-5d5e-8adf-63afc72b986c","questionId":"fb6b1787-01a3-5632-8031-7e991981e2a4","sourceKey":"bank:ECO201:E201-0014","payload":{"prompt":"A line that expresses that all things remaining equal, demand varies inversely with price, is called ______.","options":["A demand line","Demand graph","Demand curve","Demand scatter plot"],"correctOption":2,"section":"Demand Theory","explanation":"A demand curve shows the inverse relationship between price and quantity demanded, ceteris paribus: as price falls, quantity demanded rises. Options A and B are not the standard names, and a scatter plot (option D) only shows raw data points rather than the relationship itself."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 264, $official_bank_source${"itemId":"b8d65411-a30c-5e36-95e7-811bc0d719c9","questionId":"c90b5df0-0e8b-5155-80fc-5bb8c5d67cd0","sourceKey":"bank:ECO201:E201-0015","payload":{"prompt":"When we move from point A to point B, and to point C on the same demand curve, the resulting impact is called ______.","options":["A down-sloping demand","Change in quantity demanded","Movement in quantity demanded","Change in demand"],"correctOption":1,"section":"Demand Theory","explanation":"Moving along the same demand curve from A to B to C is a change in quantity demanded, caused only by a change in the good's own price. Option D, a change in demand, describes a shift of the whole curve caused by things like income or tastes. Option C sounds close but is not the standard term, and option A just describes the curve's slope."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 265, $official_bank_source${"itemId":"a29e27fd-f76b-5b9a-af9a-9dbf2e860d9d","questionId":"92ac4aae-562b-500d-9d06-5890c3923268","sourceKey":"bank:ECO201:E201-0020","payload":{"prompt":"What variable is accountable for the movement from point A, to point B, and to point C, on the same demand curve? ______.","options":["change in price of the commodity alone","Change in prices of commodities alone","change in quantity of other commodities","equilibrium price and quantity demanded"],"correctOption":0,"section":"Demand Theory","explanation":"Movement along a single demand curve is caused only by a change in the commodity's own price, with everything else held constant. Option B brings in the prices of other commodities, which would shift the curve instead. Option C is not a determinant of the movement, and option D describes the market outcome, not the cause of the movement."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 266, $official_bank_source${"itemId":"0e8cbdee-d1dc-5adb-8bf8-f1af9fa4457c","questionId":"566755fc-ce80-56c6-831c-0a60d176d353","sourceKey":"bank:ECO201:E201-0029","payload":{"prompt":"Which of the following is not a market demand?","options":["the quantities of commodity that is demanded at different market prices by an individual","the quantities of commodity that is demanded at given market prices by different individuals","the quantities of commodity that is demanded at each alternative prices by different individuals","the quantities of commodity that is demanded at different market prices by different individuals"],"correctOption":0,"section":"Demand Theory","explanation":"Market demand adds up the quantities demanded by all the different individuals in the market at each price, so a schedule for just one individual is individual demand, not market demand. Options B, C and D all describe quantities demanded by different individuals, which is exactly what market demand is."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 267, $official_bank_source${"itemId":"798be902-aeb6-5a70-85c0-d4af2d0e26dd","questionId":"f8818ff9-9dd4-57e6-a51c-c22d96b8ce89","sourceKey":"bank:ECO201:E201-0037","payload":{"prompt":"Effective demand describes all of the following EXCEPT ______.","options":["A consumer's ability to pay with no willingness to buy","A consumer's willingness to buy backed by the ability to pay","A consumer's ability to pay combined with readiness to buy","A consumer's wishes backed by purchasing power"],"correctOption":0,"section":"Demand Theory","explanation":"Effective demand is a desire or willingness to buy that is backed by the ability to pay, so it needs both parts. Option A has the ability to pay but no willingness to buy, so it is not effective demand. Options B, C and D each combine willingness (readiness or wishes) with the ability or purchasing power to pay, which is exactly what effective demand means."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 268, $official_bank_source${"itemId":"75a1dd04-1baf-58c0-be4f-7eae109c471c","questionId":"d0508951-cab3-558d-b65b-720ba4cd9648","sourceKey":"bank:ECO201:E201-0040","payload":{"prompt":"A rightward shift in the demand curve means ______.","options":["More quantity of a commodity demanded at a higher price","Lesser quantity of a commodity demanded at a higher price","More quantity of a commodity demanded at the same price","Lesser quantity of a commodity demanded at a lesser price"],"correctOption":2,"section":"Demand Theory","explanation":"A rightward shift of the demand curve is an increase in demand: consumers buy more of the commodity at the same price, because of factors like higher income or a rise in the price of a substitute. Option A mixes a shift with a price change, which is not what defines the shift. Options B and D describe less being demanded, which would be a leftward shift or a movement."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 269, $official_bank_source${"itemId":"ae3a1dd8-e029-5f9b-9cc2-af9b3b62da3f","questionId":"a282271e-db96-51e1-b0c2-3f730f2cfc91","sourceKey":"bank:ECO201:E201-0067","payload":{"prompt":"When children refer to all noodle brands as \"indomie,\" this is mainly due to: ______.","options":["Price discrimination","Income effect","Substitution effect","Brand dominance"],"correctOption":3,"section":"Demand Theory","explanation":"When one brand becomes so well known that its name is used for the whole product, as with calling every noodle brand Indomie, that reflects brand dominance shaping consumers' tastes and preferences. Options B and C, the income and substitution effects, describe how quantity demanded responds to a price change, not how a brand name becomes the general name for a product. Option A, price discrimination, is about charging different prices to different buyers."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 270, $official_bank_source${"itemId":"e7df8582-7e48-5eb6-89f0-9ede910f9aac","questionId":"9778d9c5-7620-5d1c-b054-c9bf9bce11d4","sourceKey":"bank:ECO201:E201-0074","payload":{"prompt":"When consumer income increases, demand for an inferior good will ______","options":["Increase","Decrease","Remain unchanged","Become perfectly elastic"],"correctOption":1,"section":"Demand Theory","explanation":"An inferior good is one people buy less of as their income rises, because they switch to better-quality alternatives. So an increase in income decreases demand for an inferior good. Option A describes a normal good, and option D confuses income effects with price elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 271, $official_bank_source${"itemId":"93f21095-be5c-53f1-9f16-e54316710099","questionId":"34c54fe8-3a33-5856-8623-a5d6bfd136ff","sourceKey":"bank:ECO201:E201-0077","payload":{"prompt":"Frequent exposure to noodle advertisements influences children's preference mainly through: ______","options":["Income distribution","Production costs","Consumer awareness","Supply constraints"],"correctOption":2,"section":"Demand Theory","explanation":"Advertising works mainly by making consumers aware of a product and shaping their tastes and preferences, which is one of the determinants of demand. Repeated noodle adverts make children familiar with the product and more likely to ask for it. Options A, B and D relate to income or the supply side, which adverts do not directly change."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 272, $official_bank_source${"itemId":"abac3ed0-8faa-5ffb-8b4e-628dfac60c0a","questionId":"e263ba03-e1c0-5984-ace7-99e1a8dd20b2","sourceKey":"bank:ECO201:E201-0084","payload":{"prompt":"An increase in income leads to an increase in demand for: ______","options":["Giffen goods","Veblen goods only","Normal goods","Inferior goods"],"correctOption":2,"section":"Demand Theory","explanation":"A normal good is defined as one whose demand rises when income rises, so an increase in income increases demand for normal goods. Option D, inferior goods, behave the opposite way, and option A, Giffen goods, are a special type of inferior good. Option B is wrong because it is not only Veblen goods whose demand rises with income."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 273, $official_bank_source${"itemId":"bfe9e029-160f-5301-987b-2a37fcefd8ec","questionId":"edba615e-02bf-5995-b895-2b8ed00c0fc2","sourceKey":"bank:ECO201:E201-0096","payload":{"prompt":"When two goods are substitutes, an increase in the price of one good will: ______.","options":["Increase demand for the other","Decrease demand for the other","Leave demand unchanged","Make the other a necessity"],"correctOption":0,"section":"Demand Theory","explanation":"Substitutes can replace each other, so when the price of one rises, consumers switch to the other and demand for it increases. For example, if Dettol soap becomes more expensive, demand for another antiseptic soap rises. Option B describes complementary goods, and option C describes unrelated goods."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 274, $official_bank_source${"itemId":"f33d8f66-3a25-53f7-97de-d5eeb7e3b80c","questionId":"84c447b6-6765-5532-9687-b982a2352229","sourceKey":"bank:ECO201:E201-0359","payload":{"prompt":"Theory of demand examines the behaviour of the--------","options":["Consumer","Producer","Firm","Industry"],"correctOption":0,"section":"Demand Theory","explanation":"The theory of demand studies how consumers decide how much of a good to buy at different prices, incomes and prices of related goods. Options B, C and D (producer, firm and industry) belong to the theory of supply and production."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 275, $official_bank_source${"itemId":"24f3dadc-d13a-5665-94d1-f966f5d1b98a","questionId":"74fd249a-aa53-537b-9cfc-8e51bdf95d06","sourceKey":"bank:ECO201:E201-0369","payload":{"prompt":"Change in demand due to a change in the price of related good :","options":["Cross demand","Price demand","Income demand","None of these"],"correctOption":0,"section":"Demand Theory","explanation":"Cross demand shows how the quantity demanded of one good responds to a change in the price of a related good, such as a substitute or complement. Option B, price demand, is about the good's own price, and option C, income demand, is about changes in consumer income."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 276, $official_bank_source${"itemId":"59380ee4-46d2-5deb-8000-722c6a7c6c9f","questionId":"507eaf00-f574-5ac6-b35a-cb1b54893f36","sourceKey":"bank:ECO201:E201-0371","payload":{"prompt":"In the case of normal goods, the quantity demanded varies inversely with:","options":["Price of good","Income of the consumer","Fashion of the good","Savings"],"correctOption":0,"section":"Demand Theory","explanation":"For normal goods, the law of demand holds: when the price of the good rises, the quantity demanded falls, so quantity varies inversely with its own price. Option B is wrong because for a normal good quantity demanded rises when income rises, which is a direct relationship, not an inverse one."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 277, $official_bank_source${"itemId":"24c00f36-9726-548d-ace0-8a272eed6bd3","questionId":"56c58075-1d64-558f-b50f-b62a15f4f13c","sourceKey":"bank:ECO201:E201-0397","payload":{"prompt":"Which one of the following is an example of close substitutes?","options":["Tea and coffee","Milk and water","Bread and butter","Car and petrol"],"correctOption":0,"section":"Demand Theory","explanation":"Tea and coffee are close substitutes because either one can satisfy the same want, so a rise in the price of one pushes people towards the other. Option C (bread and butter) and option D (car and petrol) are complements that are used together, and milk and water in option B are not normally bought as replacements for each other."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 278, $official_bank_source${"itemId":"79093b93-9e00-5f5c-ab69-4c2bc2b27e97","questionId":"a235d937-93f8-5326-99ea-acce20731ab2","sourceKey":"bank:ECO201:E201-0407","payload":{"prompt":"Other things remaining the same, the quantity of a product demanded increases with a ______ in its price.","options":["Increase","Decrease","Variation","None of the above"],"correctOption":1,"section":"Demand Theory","explanation":"By the law of demand, price and quantity demanded move in opposite directions, so quantity demanded rises when price falls, other things being equal. Option A reverses this inverse relationship, and option C is too vague to describe the law."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 279, $official_bank_source${"itemId":"060d634e-782d-5f00-bfa0-86031fb79269","questionId":"6da072b8-f13e-5c47-817a-65035f1ee5f0","sourceKey":"bank:ECO201:E201-0415","payload":{"prompt":"A change in demand (a shift of the whole demand curve) is NOT caused by a change in:","options":["Income","Own price","Prices of related products","Expectations"],"correctOption":1,"section":"Demand Theory","explanation":"A change in the good's own price causes a movement along the demand curve (a change in quantity demanded), not a shift of the curve. Income (option A), prices of related goods (option C) and expectations (option D) are all non-price factors that shift the whole demand curve."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 280, $official_bank_source${"itemId":"1418ed7e-1bef-5df3-a423-3e7c5da63fe9","questionId":"136c3a4d-5122-5db1-b002-5c83965d1188","sourceKey":"bank:ECO201:E201-0419","payload":{"prompt":"In drawing an individual demand curve for a commodity, all but which of the following are kept constant?","options":["The individual's money income","The prices of related commodities","The price of the commodity under consideration","The tastes of the consumer"],"correctOption":2,"section":"Demand Theory","explanation":"An individual demand curve shows how quantity demanded changes as the commodity's own price changes, so that price is the variable allowed to change. Money income (option A), prices of related goods (option B) and tastes (option D) are held constant, and changes in them would shift the curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 281, $official_bank_source${"itemId":"87902e08-8e81-5b94-a3b2-948d12333311","questionId":"940f50db-6ef7-5a14-a9d6-4d5793c48acc","sourceKey":"bank:ECO201:E201-0420","payload":{"prompt":"A fall in the price of a commodity, holding everything else constant, results in:","options":["Increase in demand","Decrease in demand","Increase in quantity demanded","Decrease in quantity demanded"],"correctOption":2,"section":"Demand Theory","explanation":"A change in the good's own price, with everything else constant, moves the consumer along the same demand curve, so a fall in price raises quantity demanded. An increase in demand (option A) means a shift of the whole curve, which happens only when a non-price factor changes."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 282, $official_bank_source${"itemId":"ba5b5cee-5d9b-5c72-a034-f9b70e432963","questionId":"afe51b08-403c-5220-bf22-c1c75e2ee38d","sourceKey":"bank:ECO201:E201-0421","payload":{"prompt":"When an individual's income rises, everything else remaining the same, his demand for normal goods:","options":["Rises","Falls","Remains the same","Any of the above is possible"],"correctOption":0,"section":"Demand Theory","explanation":"A normal good is one whose demand rises as income rises, so higher income shifts its demand curve to the right. Demand falling with income (option B) describes an inferior good instead."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 283, $official_bank_source${"itemId":"ef505d5e-61d6-573d-a6bb-9e9cb02153dd","questionId":"85f3661f-af5d-515e-be6b-28ec6b427434","sourceKey":"bank:ECO201:E201-0422","payload":{"prompt":"When an individual's income falls, everything else remaining the same, his demand for inferior goods:","options":["Increases","Decreases","Remains unchanged","Cannot say"],"correctOption":0,"section":"Demand Theory","explanation":"For an inferior good, demand moves opposite to income, so when income falls the consumer buys more of it (for example, switching to cheaper staples). A decrease (option B) is what happens to a normal good when income falls."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 284, $official_bank_source${"itemId":"17a262ba-f2a9-5528-b9fe-5767d3f6f541","questionId":"c5f2e2d7-a626-53b9-afb9-0127a90cdd90","sourceKey":"bank:ECO201:E201-0423","payload":{"prompt":"When the price of a substitute for commodity X falls, the demand for X:","options":["Rises","Falls","Remains unchanged","Any of the above is possible"],"correctOption":1,"section":"Demand Theory","explanation":"When a substitute becomes cheaper, consumers switch towards it and away from X, so the demand for X falls. Option A would be true only if the price of the substitute rose."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 285, $official_bank_source${"itemId":"5716e0fd-085e-5d97-ae38-a523fbefb73d","questionId":"63bde9d6-dc7b-5f29-9237-d0d608ce7323","sourceKey":"bank:ECO201:E201-0424","payload":{"prompt":"When both the price of a substitute and the price of a complement of X rise, the demand for X:","options":["Rises","Falls","Remains unchanged","Any of the above is possible"],"correctOption":3,"section":"Demand Theory","explanation":"A rise in the price of a substitute increases the demand for X, while a rise in the price of a complement reduces it. Since the two forces push in opposite directions, the net effect depends on which is stronger, so options A, B and C are each possible."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 286, $official_bank_source${"itemId":"1e4e39ca-b8e0-5969-942f-50896316bda3","questionId":"78d6e417-874a-5dff-9aef-323c358d18c7","sourceKey":"bank:ECO201:E201-0439","payload":{"prompt":"For a normal good, a fall in the income of the consumer, other things being equal, causes:","options":["An increase in demand","A decrease in demand","An increase in quantity demanded","A decrease in quantity demanded"],"correctOption":1,"section":"Demand Theory","explanation":"For a normal good, demand moves in the same direction as income, so a fall in income shifts the whole demand curve to the left, which is a decrease in demand. Option A would apply only to an inferior good, and options C and D describe movements along the curve, which only own-price changes cause."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 287, $official_bank_source${"itemId":"a4523079-07b2-5b0c-ab55-e4cc1699290f","questionId":"e1fa74ad-658d-5d52-b85b-7b32e2159069","sourceKey":"bank:ECO201:E201-0443","payload":{"prompt":"A movement down a given demand curve shows:","options":["An increase in demand","A decrease in demand","An extension of demand","A contraction of demand"],"correctOption":2,"section":"Demand Theory","explanation":"Moving down a given demand curve means price has fallen and quantity demanded has risen, which is called an extension of demand (an increase in quantity demanded). An increase in demand (option A) is a rightward shift of the whole curve, and a contraction (option D) is a movement up the curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 288, $official_bank_source${"itemId":"1f7eb88f-851b-5259-82f4-00c065d818cc","questionId":"b40db1e2-b980-5936-8244-c41e0e190ff0","sourceKey":"bank:ECO201:E201-0444","payload":{"prompt":"Which of the following results in an increase in demand for a normal good?","options":["A fall in the prices of substitutes","An increase in the price of complementary goods","A fall in the consumer's income","None of the above"],"correctOption":3,"section":"Demand Theory","explanation":"Each listed change lowers demand for a normal good: cheaper substitutes pull buyers away (option A), dearer complements make the good less attractive (option B), and lower income reduces what consumers buy of a normal good (option C). None of them raises demand, so D is correct."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 289, $official_bank_source${"itemId":"e89c20aa-799a-57c5-a158-fdd46d8d188b","questionId":"9ba13e3a-63f1-52ae-9423-4504b9baaedc","sourceKey":"bank:ECO201:DEM-001","payload":{"prompt":"In economics, the relationship between the quantity of a good that consumers are willing to buy and the price of the good, other things held constant, is called the","options":["budget line","demand curve","supply curve","indifference curve"],"correctOption":1,"section":"Demand Theory","explanation":"A demand curve links each possible price of a good to the quantity consumers are willing to buy, holding other influences constant. Option C shows what producers are willing to sell, not what consumers want to buy. Options A and D come from consumer theory and describe affordability and equal satisfaction, not the price-quantity relationship."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 290, $official_bank_source${"itemId":"ad235231-f582-5e03-b18c-8772adb86503","questionId":"5841b0fa-b48d-58d9-964c-6eab3a1204dc","sourceKey":"bank:ECO201:DEM-002","payload":{"prompt":"The law of demand states that, other things being equal,","options":["as income rises, the quantity demanded of every good rises","as the price of a good rises, the quantity demanded of it rises","as the price of a good rises, the quantity demanded of it falls","as the price of a good rises, the quantity supplied of it rises"],"correctOption":2,"section":"Demand Theory","explanation":"The law of demand describes an inverse relationship between a good's own price and the quantity demanded, which is why the demand curve slopes downward. Option B reverses the relationship. Option A is about income, not price, and is not true for inferior goods, while option D is the law of supply."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 291, $official_bank_source${"itemId":"59045966-7812-5e97-a3f8-097932ccf3a3","questionId":"5034a60e-eaaf-5935-9f3a-29583bcf4619","sourceKey":"bank:ECO201:DEM-003","payload":{"prompt":"In the demand function QD = D(P, I), the variable I stands for","options":["the interest rate","consumers' income","the price index","the quantity of inputs"],"correctOption":1,"section":"Demand Theory","explanation":"Here QD is quantity demanded, P is the good's own price and I is consumers' income. When the demand curve is drawn against price, I is held fixed. Options A, C and D are other economic variables, but none of them is what I represents in this function."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 292, $official_bank_source${"itemId":"fe9bd0e5-3fd3-529a-b41b-8cceeb6ceccd","questionId":"d22e6501-23d2-5932-bc10-1f521bf51334","sourceKey":"bank:ECO201:DEM-004","payload":{"prompt":"Which of the following is NOT a determinant of the demand for a good?","options":["The income of consumers","The prices of related goods","The cost of producing the good","The tastes of consumers"],"correctOption":2,"section":"Demand Theory","explanation":"Production cost affects how much sellers are willing to offer, so it is a determinant of supply rather than demand. Consumer income (option A), prices of substitutes and complements (option B) and tastes (option D) all change how much buyers want at each price, so they are genuine determinants of demand."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 293, $official_bank_source${"itemId":"51f463fb-41bd-56d0-918d-4f757fbc3e6e","questionId":"a448b97b-324a-5ba4-95a5-e198531eeeb4","sourceKey":"bank:ECO201:DEM-005","payload":{"prompt":"Other things being equal, a fall in the price of bread will cause","options":["a leftward shift of the demand curve for bread","a movement up along the demand curve for bread","a movement down along the demand curve for bread","a rightward shift of the demand curve for bread"],"correctOption":2,"section":"Demand Theory","explanation":"A change in a good's own price changes the quantity demanded and is shown as a movement along its demand curve; a lower price means moving down the curve to a larger quantity. Options D and A are shifts, which happen only when some other factor such as income or tastes changes. Option B would follow a rise in the price of bread, not a fall."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 294, $official_bank_source${"itemId":"be17ee3d-090a-5410-9a05-fd0cb8ecde7c","questionId":"405607a3-ed8e-5857-9e76-fe057e62136d","sourceKey":"bank:ECO201:DEM-006","payload":{"prompt":"A shift of the whole demand curve to the left or right is described in economics as a","options":["change in demand","change in quantity demanded","change in supply","change in quantity supplied"],"correctOption":0,"section":"Demand Theory","explanation":"Economists reserve the phrase 'change in demand' for a shift of the entire demand curve, caused by something other than the good's own price. Option B is the movement along the curve caused by a change in the good's own price. Options D and C refer to the supply side, not to demand."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 295, $official_bank_source${"itemId":"92cc9184-2de3-5314-a533-9cc33f6b9bbf","questionId":"cac30a49-8131-5b56-8bef-85e1f61ee224","sourceKey":"bank:ECO201:DEM-007","payload":{"prompt":"A rightward shift of the demand curve for a good means that","options":["consumers will buy less at each price, or pay a lower price for the same quantity","producers will sell more at each price","the price of the good has fallen, so more is bought","consumers will buy more at each price, or pay a higher price for the same quantity"],"correctOption":3,"section":"Demand Theory","explanation":"When demand shifts right, at the old price a larger quantity is bought, and the old quantity would now be bought even at a higher price. Option A describes a leftward shift. Option B describes an increase in supply, and option C describes a movement along an unchanged demand curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 296, $official_bank_source${"itemId":"bfa578b1-f8b1-5c22-b5ca-26e1c0d22901","questionId":"eac15f2c-caf2-531b-b64a-86652775f2aa","sourceKey":"bank:ECO201:DEM-008","payload":{"prompt":"Salaries of civil servants in Lagos are increased. If fresh fish is a normal good, the demand curve for fresh fish in Lagos will","options":["shift to the right","shift to the left","stay the same, with a movement up along it","become vertical"],"correctOption":0,"section":"Demand Theory","explanation":"For a normal good, higher income makes consumers willing to buy more at every price, so the demand curve shifts to the right. Option B is what happens to a normal good when income falls, or to an inferior good when income rises. Option C is wrong because a change in income shifts the curve; only a change in the fish's own price moves along it."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 297, $official_bank_source${"itemId":"59e4ea23-591c-5e5a-8eb0-26e13b2d319e","questionId":"7b19677c-9bb2-56b0-bc65-80e1c1385d37","sourceKey":"bank:ECO201:DEM-009","payload":{"prompt":"Two goods for which an increase in the price of one leads to an increase in the quantity demanded of the other are called","options":["Giffen goods","complements","inferior goods","substitutes"],"correctOption":3,"section":"Demand Theory","explanation":"Substitutes can replace each other, so when one becomes dearer, buyers switch to the other and its demand rises. Complements (option B) are used together, so a price rise of one reduces demand for the other. Options C and A describe how a good responds to income or to its own price, not the link between two goods."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 298, $official_bank_source${"itemId":"31c0541d-77fe-5f73-b153-1580304d49f4","questionId":"1e510ebb-f550-5004-a3cf-8d440f2505f6","sourceKey":"bank:ECO201:DEM-010","payload":{"prompt":"Two goods for which an increase in the price of one leads to a decrease in the quantity demanded of the other are called","options":["substitutes","complements","independent goods","normal goods"],"correctOption":1,"section":"Demand Theory","explanation":"Complements are consumed together, like cars and petrol, so a higher price for one reduces the demand for the other. Substitutes (option A) move the opposite way: a dearer good raises demand for its substitute. Independent goods (option C) have no such link at all, and normal goods (option D) are defined by their response to income."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 299, $official_bank_source${"itemId":"c709293b-bf35-59dd-bf55-0201e9ae93aa","questionId":"abb5ba25-c019-5ddf-adff-c22431ec0d10","sourceKey":"bank:ECO201:DEM-011","payload":{"prompt":"Which of the following pairs of goods are best described as complements?","options":["Cars and petrol","Butter and margarine","Beef and chicken","Tea and coffee"],"correctOption":0,"section":"Demand Theory","explanation":"Cars and petrol are used together, so a rise in the price of petrol reduces the demand for cars, which is the mark of complements. Beef and chicken (option C), butter and margarine (option B) and tea and coffee (option D) can each replace one another, so they are substitutes."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 300, $official_bank_source${"itemId":"57457ce2-7f75-5a6c-9453-c93e6a937a8a","questionId":"911fc46e-bf79-50bb-af7e-069c4a997186","sourceKey":"bank:ECO201:DEM-012","payload":{"prompt":"Suppose petrol and cars are complements. A sharp rise in the pump price of petrol in Nigeria will, other things equal,","options":["shift the demand curve for cars to the right","shift the supply curve of cars to the right","cause a movement down along the demand curve for cars","shift the demand curve for cars to the left"],"correctOption":3,"section":"Demand Theory","explanation":"Because cars and petrol are used together, dearer petrol makes owning a car more costly, so fewer cars are wanted at each car price and the demand curve for cars shifts left. Option A would be the response of a substitute. Option C is wrong because the price of cars itself has not changed, and option B confuses a demand influence with a supply one."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 301, $official_bank_source${"itemId":"45169a5c-fcb7-5125-9899-bc0015ab746e","questionId":"7d4f7339-6397-55e2-aed5-114e47b5a2b7","sourceKey":"bank:ECO201:DEM-013","payload":{"prompt":"Rice and spaghetti are substitutes for a household. If the price of spaghetti falls, the demand curve for rice will","options":["not move, but the quantity of rice demanded falls","shift to the left","shift to the right","not move, but the quantity of rice demanded rises"],"correctOption":1,"section":"Demand Theory","explanation":"With substitutes, cheaper spaghetti draws buyers away from rice, so less rice is wanted at every rice price and its demand curve shifts left. Option C would follow a rise in the price of spaghetti. Options D and A describe movements along the rice demand curve, which only a change in the price of rice itself can cause."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 302, $official_bank_source${"itemId":"f7af635a-5008-5b5e-810a-c2f17ec95b0c","questionId":"fca2c28e-2800-5500-b025-e5ad9b9c61af","sourceKey":"bank:ECO201:DEM-014","payload":{"prompt":"A good whose demand increases when consumers' income increases, other things equal, is called a","options":["Giffen good","free good","inferior good","normal good"],"correctOption":3,"section":"Demand Theory","explanation":"A normal good is one that people buy more of as they become richer, so its income elasticity is positive. An inferior good (option C) is bought less as income rises. A Giffen good (option A) is a special inferior good defined by its response to its own price, and a free good (option B) is one with no price at all."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 303, $official_bank_source${"itemId":"2b786156-37af-5432-af80-133799ce5f85","questionId":"d79a709a-8a08-5618-9e46-df95e256d03d","sourceKey":"bank:ECO201:DEM-015","payload":{"prompt":"When Tunde's monthly income rose from N50,000 to N80,000, he began taking fewer bus rides and more taxi rides, even though fares did not change. For Tunde, bus rides are","options":["a Giffen good","a normal good","a complement to taxi rides","an inferior good"],"correctOption":3,"section":"Demand Theory","explanation":"An inferior good is one whose demand falls as income rises, which is exactly what happened to Tunde's bus rides with fares unchanged. Option B fits taxi rides, whose demand rose with income. Option A needs quantity to rise when the good's own price rises, which did not happen here, and option C is wrong because Tunde used taxis in place of buses, which makes them substitutes."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 304, $official_bank_source${"itemId":"99c2b57f-b68c-5056-b5e2-5e7cfeff633b","questionId":"42ec6fad-0429-5deb-8847-824de26bc244","sourceKey":"bank:ECO201:DEM-016","payload":{"prompt":"If incomes in a town fall, the demand curve for an inferior good will","options":["remain unchanged","shift to the right","shift to the left","become perfectly inelastic"],"correctOption":1,"section":"Demand Theory","explanation":"Demand for an inferior good moves opposite to income, so when incomes fall people buy more of it at each price and its demand curve shifts right. Option C is what a fall in income does to a normal good. Option A ignores that income is a determinant of demand, and option D has nothing to do with income changes."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 305, $official_bank_source${"itemId":"6e500e82-dcde-5a86-af79-6f01cf56331d","questionId":"b2868de2-7b86-55c9-9069-95370fab9526","sourceKey":"bank:ECO201:DEM-017","payload":{"prompt":"Which of the following is an exception to the law of demand?","options":["A Giffen good","A normal good","A complementary good","A substitute good"],"correctOption":0,"section":"Demand Theory","explanation":"A Giffen good is an inferior good for which a rise in its own price leads to a rise in quantity demanded, so its demand curve slopes upward, breaking the law of demand. Normal goods (option B) obey the law of demand. Substitutes (option D) and complements (option C) describe how two goods are related, not an upward-sloping demand curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 306, $official_bank_source${"itemId":"1a1893b1-e978-5d45-8d0d-167704d8f341","questionId":"65b9680e-0d38-561c-8200-919cf494323b","sourceKey":"bank:ECO201:DEM-018","payload":{"prompt":"Which of the following is NOT usually given as an exception to the law of demand?","options":["Goods that have many close substitutes","Goods whose high price is taken as a sign of high quality","Veblen (conspicuous consumption) goods","Giffen goods"],"correctOption":0,"section":"Demand Theory","explanation":"A good with many close substitutes has very elastic demand, so a rise in its price causes a large fall in quantity demanded, which strongly obeys the law of demand. Giffen goods (option D), Veblen goods bought to show off (option C) and goods where buyers judge quality by price (option B) are the usual cases where more may be bought at a higher price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 307, $official_bank_source${"itemId":"ffcfcc21-3a77-58bf-806b-5af30e5ed085","questionId":"520d122c-9c76-5fc9-8def-d3106f4eefdf","sourceKey":"bank:ECO201:DEM-019","payload":{"prompt":"An inferior good for which a rise in its own price causes the quantity demanded to rise is called a","options":["normal good","luxury good","Veblen good","Giffen good"],"correctOption":3,"section":"Demand Theory","explanation":"A Giffen good is an inferior staple whose negative income effect is so strong that it outweighs the substitution effect, so quantity demanded rises with its price. A Veblen good (option C) also can have an upward-sloping demand, but because it is prized for its high price as a status symbol, not because it is inferior. Normal and luxury goods (options A and B) are bought more as income rises and obey the law of demand."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 308, $official_bank_source${"itemId":"949c2e73-26c0-570f-9a14-097cd3afe551","questionId":"13ca6b3f-d9b3-5c01-a618-3c8a5e6aaa2a","sourceKey":"bank:ECO201:DEM-020","payload":{"prompt":"A wealthy Lagos businessman buys more of a designer wristwatch after its price is raised, because the high price shows off his status. This wristwatch is an example of a","options":["inferior good","Veblen good","complementary good","Giffen good"],"correctOption":1,"section":"Demand Theory","explanation":"A Veblen good is valued partly because it is expensive, so a higher price can increase the quantity demanded by status-seeking buyers. Option D also has an upward-sloping demand, but a Giffen good is a cheap inferior staple, not a luxury item. Option A is wrong because the watch is bought more by the rich, and option C describes a link between two goods."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 309, $official_bank_source${"itemId":"e5d806bd-df14-5f1a-b642-62e620f0102c","questionId":"02019e08-3a36-5f3e-81ae-792275ca7cba","sourceKey":"bank:ECO201:DEM-021","payload":{"prompt":"Which of the following statements about Giffen goods and inferior goods is correct?","options":["Giffen goods are normal goods with an upward-sloping demand curve","Every Giffen good is an inferior good, but not every inferior good is a Giffen good","Giffen goods and inferior goods are exactly the same thing","Every inferior good is a Giffen good, but not every Giffen good is inferior"],"correctOption":1,"section":"Demand Theory","explanation":"A Giffen good must be inferior, because only a negative income effect can outweigh the substitution effect; but most inferior goods have a weak income effect and still obey the law of demand. Option D reverses the relationship and option C wrongly makes them identical. Option A is wrong because a normal good's income effect reinforces the substitution effect, so it cannot be Giffen."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 310, $official_bank_source${"itemId":"b7f46acb-4e49-514d-9262-39377388d912","questionId":"e59b012b-3205-5ece-9828-03e5dccf59ad","sourceKey":"bank:ECO201:DEM-022","payload":{"prompt":"Which of the following helps to explain why the demand curve for most goods slopes downward?","options":["When a good becomes cheaper, firms are willing to produce more of it","When a good becomes cheaper, the prices of all its substitutes rise","When a good becomes cheaper, consumers switch to it from other goods (the substitution effect)","When a good becomes cheaper, consumers' money incomes rise"],"correctOption":2,"section":"Demand Theory","explanation":"A lower price makes a good relatively cheaper than its alternatives, so buyers substitute towards it, which raises the quantity demanded; together with the income effect this gives the downward slope. Option A describes producers and would go with a higher, not a lower, price. Option D confuses real purchasing power with money income, and option B is not something a price fall causes."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 311, $official_bank_source${"itemId":"007c8cec-99f9-559c-804f-3aab5ded7975","questionId":"0c4c5c1d-55f9-51a4-93d5-f8199ce28c38","sourceKey":"bank:ECO201:DEM-023","payload":{"prompt":"A table showing the different quantities of a good that consumers are willing to buy at different prices, other things equal, is called a","options":["demand function","supply schedule","demand schedule","budget schedule"],"correctOption":2,"section":"Demand Theory","explanation":"A demand schedule lists price-quantity pairs for buyers, and plotting it gives the demand curve. A supply schedule (option B) lists what sellers would offer at each price. A demand function (option A) expresses the same relationship as an equation rather than a table, and option D is not a standard demand concept."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 312, $official_bank_source${"itemId":"bac9f75e-1d90-5bf1-b921-f0e80762552b","questionId":"713b1636-bd8d-5213-9a1d-007ea035053a","sourceKey":"bank:ECO201:DEM-024","payload":{"prompt":"The demand for garri in a market is given by Qd = 100 - 4P, where P is in naira per cup. What quantity is demanded when P = N15?","options":["40 cups","25 cups","160 cups","60 cups"],"correctOption":0,"section":"Demand Theory","explanation":"Substituting P = 15 gives Qd = 100 - 4(15) = 100 - 60 = 40 cups. Option D is the amount subtracted (4 x 15), not the quantity left. Option C adds instead of subtracting, and option B is the price at which quantity demanded would be zero (100/4)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 313, $official_bank_source${"itemId":"dca52ae6-371a-5098-9c59-4a591e0f90fd","questionId":"8bcc8c86-80ef-5b78-a4ca-de30fb16cd48","sourceKey":"bank:ECO201:DEM-025","payload":{"prompt":"The demand function for a good is Qd = 120 - 3P. If its price rises from N10 to N15, other things equal, what happens?","options":["Quantity demanded falls by 5 units, a movement along the demand curve","Quantity demanded falls by 15 units, a leftward shift of the demand curve","Quantity demanded falls by 15 units, a movement along the demand curve","Quantity demanded rises by 15 units, a movement along the demand curve"],"correctOption":2,"section":"Demand Theory","explanation":"At P = 10, Qd = 90 and at P = 15, Qd = 75, so quantity demanded falls by 3 x 5 = 15 units; because only the good's own price changed, this is a movement along the curve. Option B gets the number right but wrongly calls it a shift. Option A uses the price change instead of multiplying by the slope of 3, and option D has the wrong direction."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 314, $official_bank_source${"itemId":"06058b6d-4f09-537e-ab6b-867f491deb52","questionId":"868f6019-3684-50ac-813a-d7cd9bfec614","sourceKey":"bank:ECO201:DEM-026","payload":{"prompt":"The market demand curve for a good is obtained from individual demand curves by","options":["multiplying each consumer's quantity demanded by the price","adding the prices each consumer is willing to pay for each quantity (vertical summation)","taking the average of the quantities demanded by consumers at each price","adding the quantities demanded by all consumers at each price (horizontal summation)"],"correctOption":3,"section":"Demand Theory","explanation":"Market demand is the total quantity all buyers want at each price, so the individual quantities are added sideways along the quantity axis. Option B adds prices, which is not how private market demand is formed. Option C gives the average buyer's quantity, not the market total, and option A gives spending, not quantity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 315, $official_bank_source${"itemId":"85a54bc8-8637-59d9-bf33-1fb92305704f","questionId":"3559435a-d69f-5a65-9421-9a05b7818e52","sourceKey":"bank:ECO201:DEM-027","payload":{"prompt":"At a price of N200 per bottle, Ada, Bayo and Chidi are willing to buy 5, 8 and 12 bottles of zobo per week respectively. If they are the only buyers, the market quantity demanded at N200 is","options":["600 bottles","8.33 bottles","12 bottles","25 bottles"],"correctOption":3,"section":"Demand Theory","explanation":"Market quantity demanded at a price is the sum of individual quantities at that price: 5 + 8 + 12 = 25 bottles. Option C takes only the largest buyer. Option B is the average per buyer, and option A multiplies the price by the number of buyers, which is not a quantity."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 316, $official_bank_source${"itemId":"81a8848f-d62e-5cb5-a8cb-833a50c8d79c","questionId":"78ddf988-f302-5c5a-8b27-b47a104736d6","sourceKey":"bank:ECO201:DEM-028","payload":{"prompt":"Two consumers are the only buyers of a good. Their demands are Qa = 20 - 2P and Qb = 30 - 3P (both positive at the prices considered). The market quantity demanded at P = 4 is","options":["12 units","30 units","50 units","18 units"],"correctOption":1,"section":"Demand Theory","explanation":"At P = 4, Qa = 20 - 8 = 12 and Qb = 30 - 12 = 18, so the market quantity is 12 + 18 = 30 units. The market demand can also be written Q = 50 - 5P, which gives the same result. Options A and D are just one consumer's quantity, and option C adds only the intercepts and forgets the price terms."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 317, $official_bank_source${"itemId":"b1e8131f-2907-5974-9e43-3785f54c1e39","questionId":"fb856ea7-985e-5371-b134-c873b06c3a10","sourceKey":"bank:ECO201:DEM-029","payload":{"prompt":"There are 100 identical buyers of a good, each with demand q = 10 - 0.5P. The market quantity demanded at P = 8 is","options":["400 units","600 units","6 units","1,000 units"],"correctOption":1,"section":"Demand Theory","explanation":"Each buyer demands 10 - 0.5(8) = 6 units, and with 100 identical buyers the market quantity is 100 x 6 = 600 units, from market demand Q = 1000 - 50P. Option C is one buyer's quantity only. Option D ignores the price term, and option A is the amount by which the price reduces market demand (50 x 8), not the quantity bought."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 318, $official_bank_source${"itemId":"047d62a2-e977-571f-87d6-27ce81c796f2","questionId":"edc73e38-a5fe-5914-81a0-1986f3f4c3a6","sourceKey":"bank:ECO201:DEM-030","payload":{"prompt":"The only two buyers of a good have demands Qa = 20 - 2P and Qb = 12 - P, where quantity cannot be negative. The market quantity demanded at P = 11 is","options":["3 units","0 units","1 unit","-1 unit"],"correctOption":2,"section":"Demand Theory","explanation":"At P = 11, buyer A would want 20 - 22 = -2, which means A buys nothing, while buyer B wants 12 - 11 = 1 unit, so market demand is 0 + 1 = 1 unit. Option D wrongly adds a negative quantity. Option B assumes neither buyer is in the market, and option A drops the minus sign on A's figure."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 319, $official_bank_source${"itemId":"61736036-470b-55c8-9df2-e14932a735dd","questionId":"c4acff63-6ffb-5584-9adb-6963f4638d21","sourceKey":"bank:ECO201:DEM-031","payload":{"prompt":"A large number of new students arrive on campus at the start of a session. The likely effect on the market for meals at campus canteens is","options":["a rightward shift of the market demand curve","a leftward shift of the market demand curve","a rightward shift of the market supply curve","a movement down along the market demand curve"],"correctOption":0,"section":"Demand Theory","explanation":"Market demand is the sum of all individual demands, so more buyers means more is wanted at each price and the market demand curve shifts right. Option B would follow a fall in the number of buyers. Option D needs a fall in the meal price itself, and option C is about sellers, not buyers."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 320, $official_bank_source${"itemId":"d9fe0e6c-5f66-53d6-b1c6-f9ed867cccb4","questionId":"9c975f20-19d5-549a-a67b-319699fe2b2d","sourceKey":"bank:ECO201:DEM-032","payload":{"prompt":"The demand for a good is Qd = 200 - 5P + 0.01I, where I is income in naira. With P = N20, income rises from N50,000 to N60,000. Quantity demanded rises from","options":["600 to 700 units, so the good is an inferior good","600 to 610 units, so the good is a normal good","100 to 200 units, so the good is a normal good","600 to 700 units, so the good is a normal good"],"correctOption":3,"section":"Demand Theory","explanation":"At P = 20 and I = 50,000, Qd = 200 - 100 + 500 = 600; at I = 60,000 it is 200 - 100 + 600 = 700, and since demand rises with income the good is normal. Option A has the right numbers but the wrong label, as the income coefficient is positive. Option C leaves out the income term entirely at the start, and option B multiplies the income change wrongly."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 321, $official_bank_source${"itemId":"cc011781-cc2e-59ee-8a38-9f124a89295c","questionId":"3d191a62-2d21-5739-b149-43866453dd01","sourceKey":"bank:ECO201:DEM-033","payload":{"prompt":"A demand function is estimated as Qx = 300 - 4Px - 0.002I, where I is income. The negative sign on I shows that good X is","options":["a substitute for income","a normal good","an inferior good","a Giffen good"],"correctOption":2,"section":"Demand Theory","explanation":"A negative income coefficient means that as income rises, less of X is demanded at each price, which is the definition of an inferior good. Option B would need a positive coefficient. Option D is about an upward-sloping response to X's own price, but here the price coefficient is negative, so X obeys the law of demand, and option A is not an economic category."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 322, $official_bank_source${"itemId":"e2420fab-93a4-52e2-8c6d-c16a50073a40","questionId":"e42889fc-a766-5693-8966-1a3247eca823","sourceKey":"bank:ECO201:DEM-034","payload":{"prompt":"The demand for good X is Qx = 50 - 2Px + 3Py, where Py is the price of good Y. If Py rises from N10 to N14, the demand curve for X","options":["shifts right by 12 units, because X and Y are substitutes","shifts right by 4 units, because X and Y are complements","shifts right by 8 units, because X and Y are substitutes","shifts left by 12 units, because X and Y are complements"],"correctOption":0,"section":"Demand Theory","explanation":"The quantity of X demanded at every Px rises by 3 x (14 - 10) = 12 units, and since a dearer Y raises the demand for X, the two goods are substitutes. Option D gets the direction and relationship wrong. Option C uses the coefficient of Px (2) instead of the coefficient of Py (3), and option B ignores the coefficient and mislabels the goods."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 323, $official_bank_source${"itemId":"c7c299cd-17d5-59b3-b49d-e02f3201a2cf","questionId":"f46c8cd9-7845-5842-99dc-e42bbad353a7","sourceKey":"bank:ECO201:DEM-035","payload":{"prompt":"The demand for good A is QA = 80 - 2PA - 4PB, where PB is the price of good B. An increase in PB will","options":["shift the demand curve for A to the left, so A is an inferior good","shift the demand curve for A to the right, so A and B are substitutes","shift the demand curve for A to the left, so A and B are complements","cause a movement up along the demand curve for A"],"correctOption":2,"section":"Demand Theory","explanation":"The negative coefficient on PB means a higher price of B reduces the quantity of A demanded at every PA, a leftward shift, which happens when goods are used together as complements. Option B would need a positive coefficient. Option D needs a change in PA itself, and option A wrongly links a price of another good to the income-based idea of an inferior good."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 324, $official_bank_source${"itemId":"9469af0c-de5f-5853-b717-6b010704a207","questionId":"0bb61821-2ab5-5930-a1e0-274c5d60eb3f","sourceKey":"bank:ECO201:DEM-036","payload":{"prompt":"A successful advertising campaign makes zobo drink more popular among students. Other things equal, the market for zobo will experience","options":["a rightward shift of the demand curve","a leftward shift of the demand curve","a leftward shift of the supply curve","a movement up along the demand curve"],"correctOption":0,"section":"Demand Theory","explanation":"Tastes are a determinant of demand, so when zobo becomes more popular buyers want more at every price and the demand curve shifts right. Option D is caused only by a rise in the price of zobo itself. Option C is a supply-side change, and option B would follow a loss of popularity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 325, $official_bank_source${"itemId":"7dc8166e-a882-5f47-8fd3-b18c0fc98b5d","questionId":"c178743d-e3bb-5f15-9805-9fa7d5597143","sourceKey":"bank:ECO201:DEM-037","payload":{"prompt":"When a demand curve is drawn, economists hold constant factors such as income, tastes and the prices of related goods. This assumption is known as","options":["ceteris paribus","comparative advantage","opportunity cost","laissez faire"],"correctOption":0,"section":"Demand Theory","explanation":"Ceteris paribus means 'other things being equal', and it lets the demand curve show the effect of the good's own price alone. Option D is a policy of non-interference by government. Option C is the value of the next best alternative given up, and option B relates to trade and specialisation."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 326, $official_bank_source${"itemId":"6413755b-82ed-5a61-9dfc-7259f4f0e20c","questionId":"be8e9735-30bb-542b-8cd3-a392315c0e99","sourceKey":"bank:ECO201:E201-0044","payload":{"prompt":"A shift in supply curve is the same as ______","options":["Movement along a supply curve","Change in quantity supplied","Change in supply.","Change in price"],"correctOption":2,"section":"Supply Theory","explanation":"A shift of the supply curve is a change in supply, caused by factors other than the good's own price, such as costs of production or technology. Options A and B describe a movement along the same curve, which happens only when the good's own price changes. Option D, a change in price, causes a movement, not a shift."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 327, $official_bank_source${"itemId":"2b8f7898-7f97-5454-a0f4-d1af383f223f","questionId":"4a79131a-ab80-5877-814d-0cb591e6a7bc","sourceKey":"bank:ECO201:E201-0416","payload":{"prompt":"The supply curve represents a ______ relationship between quantity and price.","options":["Direct","Inverse","Either direct or inverse","None of the above"],"correctOption":0,"section":"Supply Theory","explanation":"By the law of supply, sellers offer more at higher prices, so price and quantity supplied move in the same direction and the relationship is direct. An inverse relationship (option B) describes demand, not supply."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 328, $official_bank_source${"itemId":"b26915e0-6580-54fb-a24b-beb465244d7c","questionId":"b5ad0e65-cfe0-574d-825e-c8b7b1eac918","sourceKey":"bank:ECO201:E201-0425","payload":{"prompt":"If the supply curve of a commodity has a positive slope, a rise in the price of the commodity results in:","options":["Increase in supply","Increase in quantity supplied","Decrease in supply","Decrease in quantity supplied"],"correctOption":1,"section":"Supply Theory","explanation":"With an upward-sloping supply curve, a rise in the commodity's own price moves sellers up along the same curve, so quantity supplied rises. An increase in supply (option A) means a rightward shift of the curve, caused by non-price factors such as cheaper inputs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 329, $official_bank_source${"itemId":"21f90acd-29b1-561d-8af3-91bffa8ca783","questionId":"4794a3da-62c3-5c32-b063-9c1a3c70e394","sourceKey":"bank:ECO201:E201-0440","payload":{"prompt":"Which of the following causes an increase in supply?","options":["A fall in the price of inputs","An increase in the number of producers","A decrease in the price of production substitutes","All of the above"],"correctOption":3,"section":"Supply Theory","explanation":"Each option shifts supply to the right: cheaper inputs lower production costs (option A), more producers add to market supply (option B), and a fall in the price of a production substitute makes it more attractive to switch resources into this good (option C). Since all three raise supply, D is the best answer."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 330, $official_bank_source${"itemId":"db0b2d2f-2ae9-5be5-8dd5-bad4b7ff2051","questionId":"bacf0ed0-6533-5400-a42a-e127376df36a","sourceKey":"bank:ECO201:E201-0446","payload":{"prompt":"An increase in supply means:","options":["A movement down a given supply curve","A movement up a given supply curve","A leftward shift of the supply curve","A rightward shift of the supply curve"],"correctOption":3,"section":"Supply Theory","explanation":"An increase in supply means producers offer more at every price, so the whole supply curve shifts to the right. Options A and B are movements along a given curve caused by own-price changes, and option C is a decrease in supply."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 331, $official_bank_source${"itemId":"29054ee2-8805-5558-aa8b-e5d4453e103c","questionId":"3b8ae2f1-db3a-539b-9a7c-e8c79f1ef415","sourceKey":"bank:ECO201:E201-0464","payload":{"prompt":"Which of the following causes a movement along a given supply curve rather than a shift of the supply curve?","options":["A change in the number of firms in the market","An improvement in production technology","A change in the price of an input used to make the good","A change in the price of the good itself"],"correctOption":3,"section":"Supply Theory","explanation":"A supply curve shows how quantity supplied responds to the good's own price, so a change in that price moves sellers along the curve (a change in quantity supplied). Input prices (option C), technology (option B) and the number of firms (option A) are non-price factors that change the quantity offered at every price, shifting the whole curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 332, $official_bank_source${"itemId":"68c3afe4-a0bc-5972-889e-98ff136fac32","questionId":"ebffd0e7-4153-599e-9630-0475770fc555","sourceKey":"bank:ECO201:E201-0480-b","payload":{"prompt":"Americans bought 15.75 billion packs of cigarettes at an average price of $5.00 per pack. The price elasticity of demand is -0.4 and the price elasticity of supply is 0.5. What linear supply curve, Q = c + dP, is consistent with these figures?","options":["Q = 23.625 + 1.575P","Q = 7.875 + 1.575P","Q = 7.875 + 0.5P","Q = 15.75 + 0.5P"],"correctOption":1,"section":"Supply Theory","explanation":"From elasticity of supply = d(P/Q), we get d = 0.5 x 15.75/5 = 1.575. Then c = Q - dP = 15.75 - 1.575 x 5 = 7.875, so Q = 7.875 + 1.575P. Option A adds dP to Q instead of subtracting it, and options D and C use the elasticity itself as the slope."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 333, $official_bank_source${"itemId":"0fb166bf-2f84-5591-9d2a-ce11408f0167","questionId":"5c6b6ba4-08c6-5048-bc61-cdd270bcd1c9","sourceKey":"bank:ECO201:SUP-001","payload":{"prompt":"The relationship between the quantity of a good that producers are willing to sell and the price of the good, holding other factors constant, is called the","options":["production possibility curve","cost curve","supply curve","demand curve"],"correctOption":2,"section":"Supply Theory","explanation":"A supply curve shows how much sellers are willing to offer at each price, other things held constant. Option D shows buyers' behaviour, not sellers'. Option A shows the combinations an economy can produce with its resources, and option B shows how cost varies with output, not with price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 334, $official_bank_source${"itemId":"baf11aee-8f4f-54e0-b1d3-75ef137250f9","questionId":"a15196f7-f840-5c5e-ac7e-70fb41ce7699","sourceKey":"bank:ECO201:SUP-002","payload":{"prompt":"The law of supply states that, other things being equal,","options":["the higher the price of a good, the smaller the quantity supplied","the higher the cost of production, the greater the quantity supplied","the higher the price of a good, the greater the quantity supplied","the higher the price of a good, the smaller the quantity demanded"],"correctOption":2,"section":"Supply Theory","explanation":"The law of supply describes a direct, positive relationship between price and quantity supplied, which is why the supply curve slopes upward. Option A reverses that relationship. Option D is the law of demand, and option B is wrong because higher costs reduce supply."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 335, $official_bank_source${"itemId":"b7015aeb-5e86-5661-bd62-77a13491ab5c","questionId":"5edfa62c-08be-503d-b904-21ca2fc73bb9","sourceKey":"bank:ECO201:SUP-003","payload":{"prompt":"Which of the following is NOT a reason why a supply curve slopes upward?","options":["At higher prices, firms can expand their plants","At higher prices, firms can profitably hire extra workers or pay for overtime","At higher prices, higher-cost new firms can enter the market","At higher prices, consumers are willing to buy less"],"correctOption":3,"section":"Supply Theory","explanation":"Consumers buying less at higher prices is the law of demand, so it explains the slope of the demand curve, not the supply curve. Overtime and extra workers (option B), bigger plants (option A) and entry of higher-cost firms (option C) are all ways that a higher price makes more output profitable, which gives supply its upward slope."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 336, $official_bank_source${"itemId":"3c4cdad8-85d6-5b1c-9e72-e87311e263eb","questionId":"606748a9-8419-5839-8ad8-a51e7938ef85","sourceKey":"bank:ECO201:SUP-004","payload":{"prompt":"Which of the following is NOT a determinant of the supply of a good?","options":["The cost of raw inputs","The income of consumers","Wage rates paid to workers","The state of technology"],"correctOption":1,"section":"Supply Theory","explanation":"Consumer income affects how much buyers want, so it is a determinant of demand, not supply. Wages (option C) and the cost of inputs (option A) are production costs, and technology (option D) changes how cheaply output can be produced, so all three shift the supply curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 337, $official_bank_source${"itemId":"cda31109-5131-52cd-ab32-c785f6a8d9d9","questionId":"5337f5d4-22ed-5980-bb14-a7025c7f7197","sourceKey":"bank:ECO201:SUP-005","payload":{"prompt":"Other things equal, a fall in the cost of the raw inputs used to make a good will","options":["shift the supply curve to the left","shift the demand curve to the right","cause a movement up along the supply curve","shift the supply curve to the right"],"correctOption":3,"section":"Supply Theory","explanation":"Lower input costs make each unit cheaper to produce, so firms offer more at every price and the supply curve shifts right. Option A follows a rise in costs. Option C needs a change in the good's own price, and option B is wrong because input costs affect sellers, not buyers."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 338, $official_bank_source${"itemId":"79a3626f-02e1-50aa-b5f1-05a1538f62f6","questionId":"263640e7-19ac-5f77-8082-7658d0d2fe09","sourceKey":"bank:ECO201:SUP-006","payload":{"prompt":"A rightward shift of a supply curve means that","options":["more is offered at each price, or the same quantity is offered at a lower price","less is offered at each price, or the same quantity is offered only at a higher price","the price of the good has risen, so more is offered","more is bought by consumers at each price"],"correctOption":0,"section":"Supply Theory","explanation":"After a rightward shift, at the old price producers offer a larger quantity, and they would offer the old quantity even at a lower price. Option B describes a leftward shift. Option D describes an increase in demand, and option C describes a movement along an unchanged supply curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 339, $official_bank_source${"itemId":"1b9299d1-54e5-5271-b314-176d0e08b45f","questionId":"37e43301-2f00-54e1-982b-25aa72c167fb","sourceKey":"bank:ECO201:SUP-007","payload":{"prompt":"A rise in the market price of cement, other things equal, leads to","options":["a decrease in the supply of cement, shown as a leftward shift of the supply curve","a decrease in the quantity of cement supplied, shown as a movement along the supply curve","an increase in the quantity of cement supplied, shown as a movement along the supply curve","an increase in the supply of cement, shown as a rightward shift of the supply curve"],"correctOption":2,"section":"Supply Theory","explanation":"A change in the good's own price changes the quantity supplied and is a movement along the supply curve, upward to a larger quantity when price rises. Option D is wrong because a shift (a change in supply) needs some other factor such as costs to change. Option A is also a shift, and option B has the wrong direction."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 340, $official_bank_source${"itemId":"f6caede5-f8c9-50e3-a869-14cb8bd689db","questionId":"d1774fa9-4eab-5f9d-8c5e-d62c2239b3aa","sourceKey":"bank:ECO201:SUP-009","payload":{"prompt":"Bakeries in Ibadan have to pay their workers higher wages. Other things equal, the supply curve of bread in Ibadan will","options":["become perfectly elastic","shift to the left","not move, but quantity supplied falls along it","shift to the right"],"correctOption":1,"section":"Supply Theory","explanation":"Higher wages raise the cost of producing each loaf, so bakers offer less bread at every price and the supply curve shifts left. Option D would follow a fall in costs. Option C is wrong because wages are not the price of bread, so they shift the curve rather than move along it, and option A has no basis in the scenario."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 341, $official_bank_source${"itemId":"3daa0edc-b732-5a3d-9660-1c1d7fa99265","questionId":"2738ae6f-53b8-5877-a6b7-3116f95cc499","sourceKey":"bank:ECO201:SUP-010","payload":{"prompt":"A new machine that cuts the time needed to process cassava into garri is widely adopted. The likely effect is","options":["a rightward shift of the demand curve for garri","a movement down along the supply curve of garri","a leftward shift of the supply curve of garri","a rightward shift of the supply curve of garri"],"correctOption":3,"section":"Supply Theory","explanation":"Better technology lowers the cost of producing each unit, so producers supply more at each price and the supply curve shifts right. Option C would follow higher costs. Option A is about buyers, and option B needs a fall in the price of garri itself."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 342, $official_bank_source${"itemId":"405a119b-ed9a-5668-a5ea-57f11c4d0ab5","questionId":"071f3549-beff-56bb-9967-de66d42a8527","sourceKey":"bank:ECO201:SUP-011","payload":{"prompt":"Several new firms enter the market for sachet water in Abuja. Other things equal, the market supply curve will","options":["shift the market demand curve to the left","shift to the right","shift to the left","not change, since each firm's supply is unchanged"],"correctOption":1,"section":"Supply Theory","explanation":"Market supply is the sum of all firms' supplies, so more firms means more is offered at each price and the market supply curve shifts right. Option C would follow firms leaving. Option D forgets that adding firms adds to the horizontal sum, and option A confuses supply with demand."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 343, $official_bank_source${"itemId":"27fe2b9c-b580-5a85-8c85-7001b2c82e79","questionId":"00be7e26-8268-518f-ad9f-fef0ef845325","sourceKey":"bank:ECO201:SUP-012","payload":{"prompt":"A severe drought destroys much of the maize crop in northern Nigeria. Other things equal, the effect on the maize market is","options":["a leftward shift of the supply curve","a rightward shift of the demand curve","a rightward shift of the supply curve","a movement up along the supply curve"],"correctOption":0,"section":"Supply Theory","explanation":"Bad weather reduces the amount farmers can bring to market at any price, so supply shifts left. Option C would follow a good harvest. Option D is a movement caused by a rise in the maize price, not by the drought itself, and option B is a change in buyers' behaviour."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 344, $official_bank_source${"itemId":"065f4288-14f1-5e47-926f-db9dfc7abd14","questionId":"e65d5b04-e55e-5c05-850e-ea86dcc52a8b","sourceKey":"bank:ECO201:SUP-013","payload":{"prompt":"The market supply curve is derived from individual firms' supply curves by","options":["adding the quantities supplied by all firms at each price","taking the average quantity supplied by firms at each price","choosing the supply curve of the largest firm","adding the prices charged by all firms at each quantity"],"correctOption":0,"section":"Supply Theory","explanation":"Market supply at any price is the total output all firms are willing to sell at that price, so individual supply curves are added horizontally. Option D adds prices, which is not how market supply is formed. Option B gives the average firm's output, and option C ignores all the other firms."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 345, $official_bank_source${"itemId":"229553cb-ae28-5d7b-85ef-478ce01c0d1a","questionId":"db88e2c5-8191-5f5f-82b4-b5af77222438","sourceKey":"bank:ECO201:SUP-014","payload":{"prompt":"At a price of N500 per crate, three poultry farms are willing to supply 40, 55 and 25 crates of eggs per week. If they are the only sellers, the market quantity supplied at N500 is","options":["60,000 crates","55 crates","40 crates","120 crates"],"correctOption":3,"section":"Supply Theory","explanation":"Market quantity supplied is the horizontal sum of the firms' quantities at that price: 40 + 55 + 25 = 120 crates. Option B is the largest farm only. Option C is the average per farm, and option A multiplies price by quantity, which gives revenue in naira, not crates."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 346, $official_bank_source${"itemId":"0a2438d9-927d-59c2-b934-a0753aa975ff","questionId":"0894f925-271d-54e3-8183-d11fba7d4554","sourceKey":"bank:ECO201:SUP-015","payload":{"prompt":"There are 50 identical firms in a market, each with supply qs = -10 + 2P. The market quantity supplied at P = N20 is","options":["1,500 units","2,000 units","1,000 units","30 units"],"correctOption":0,"section":"Supply Theory","explanation":"Each firm supplies -10 + 2(20) = 30 units, so 50 firms supply 50 x 30 = 1,500 units, from market supply Qs = -500 + 100P. Option D is one firm's output only. Option B ignores the negative intercept (100 x 20), and option C just multiplies the number of firms by the price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 347, $official_bank_source${"itemId":"ee563311-360f-5df3-9781-b9a7af1f8065","questionId":"96516fed-abd1-5a43-9cf1-49c9fe4cb252","sourceKey":"bank:ECO201:SUP-016","payload":{"prompt":"Firm A's supply is qA = 2P and firm B's supply is qB = -20 + 4P for P >= 5 (B produces nothing below N5). The market quantity supplied at P = N4 is","options":["4 units","24 units","8 units","-4 units"],"correctOption":2,"section":"Supply Theory","explanation":"At P = 4, firm A supplies 2 x 4 = 8 units, while firm B's formula gives -4, which means B supplies nothing, so the market total is 8 + 0 = 8 units. Option A wrongly adds B's negative figure. Option D is B's negative figure alone, and option B forgets B's intercept and adds 8 + 16."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 348, $official_bank_source${"itemId":"b3ffbe6d-b55f-5b17-a122-86647218aad7","questionId":"9d2208c7-b19c-5c1c-b101-402037a8f65a","sourceKey":"bank:ECO201:SUP-017","payload":{"prompt":"The supply of a good is Qs = -40 + 5P. If the price rises from N20 to N30, quantity supplied","options":["rises from 60 to 70 units","rises from 60 to 110 units","falls from 110 to 60 units","rises from 100 to 150 units"],"correctOption":1,"section":"Supply Theory","explanation":"At P = 20, Qs = -40 + 100 = 60 and at P = 30, Qs = -40 + 150 = 110, an increase of 50 units along the supply curve. Option D forgets the intercept of -40. Option C reverses the direction, and option A adds the price change of 10 rather than multiplying it by the slope of 5."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 349, $official_bank_source${"itemId":"9dc2e2eb-6847-5c79-9fcc-e1c0ac331c13","questionId":"64caac16-cad8-5e95-a5db-21527daed61e","sourceKey":"bank:ECO201:SUP-018","payload":{"prompt":"A perfectly inelastic supply curve is","options":["horizontal, with an elasticity of supply equal to infinity","vertical, with an elasticity of supply equal to zero","a straight line through the origin, with elasticity equal to one","vertical, with an elasticity of supply equal to infinity"],"correctOption":1,"section":"Supply Theory","explanation":"Perfectly inelastic supply means the quantity offered does not change at all when price changes, so the curve is vertical and the elasticity is zero. Option A describes perfectly elastic supply. Option D pairs the vertical shape with the wrong value, and option C describes unit-elastic supply."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 350, $official_bank_source${"itemId":"f5729c17-12a2-5128-8296-250e348a7008","questionId":"df46d44c-4b1c-5ed0-843c-b4f70af68915","sourceKey":"bank:ECO201:SUP-019","payload":{"prompt":"A football stadium has exactly 20,000 seats for a particular match, and no more can be added whatever the ticket price. The supply of seats for that match is","options":["unitary elastic","perfectly inelastic","elastic but not perfectly so","perfectly elastic"],"correctOption":1,"section":"Supply Theory","explanation":"Because the number of seats is fixed at 20,000 regardless of price, quantity supplied does not respond to price, which is perfectly inelastic supply with a vertical curve. Option D would mean any quantity is supplied at one price. Options A and C both require quantity supplied to respond to price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 351, $official_bank_source${"itemId":"a9378021-4ba6-5263-ab40-a5dcee45a310","questionId":"fabe94d7-3f04-5272-b96f-f5e8e7c90103","sourceKey":"bank:ECO201:SUP-020","payload":{"prompt":"A perfectly elastic supply curve is","options":["horizontal, with an elasticity of supply equal to zero","upward sloping, with an elasticity of supply equal to one","vertical, with an elasticity of supply equal to zero","horizontal, with an elasticity of supply equal to infinity"],"correctOption":3,"section":"Supply Theory","explanation":"With perfectly elastic supply, sellers will supply any quantity at one price but nothing below it, so the curve is horizontal and elasticity is infinite. Option C describes perfectly inelastic supply. Option A pairs the horizontal shape with the wrong value, and option B does not describe a perfectly elastic curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 352, $official_bank_source${"itemId":"905bf13f-60c4-53b8-8725-b0c78c1ee1e5","questionId":"727717ff-6d33-5a43-8058-4f25ee9d27e6","sourceKey":"bank:ECO201:SUP-021","payload":{"prompt":"Any straight-line supply curve that passes through the origin has a price elasticity of supply that is","options":["greater than one at every point","equal to zero at every point","equal to one at every point","less than one at every point"],"correctOption":2,"section":"Supply Theory","explanation":"For a supply line through the origin, Q = dP, so elasticity = d(P/Q) = d(P/dP) = 1 at every point, whatever the slope. Option B describes a vertical supply curve. Option A fits a line that cuts the price axis, and option D fits a line that cuts the quantity axis."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 353, $official_bank_source${"itemId":"557c0173-1d98-5e91-88a3-c0899e70b5c3","questionId":"246112cc-eaf0-54a4-be86-8b54f3538a72","sourceKey":"bank:ECO201:SUP-022","payload":{"prompt":"The supply of a good is Qs = -20 + 4P, a straight line that cuts the price axis. Using Es = (P/Q)(change in Q / change in P), the price elasticity of supply at P = N10 is","options":["0.5, so supply is inelastic","2.0, so supply is elastic","4.0, so supply is elastic","1.0, so supply is unit elastic"],"correctOption":1,"section":"Supply Theory","explanation":"At P = 10, Qs = -20 + 40 = 20 and the slope term is 4, so Es = (10/20) x 4 = 2.0, which is elastic; any straight-line supply curve that cuts the price axis is elastic. Option A uses P/Q = 0.5 but forgets to multiply by the slope of 4. Option C uses the slope alone without multiplying by P/Q, and option D would hold only for a line through the origin."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 354, $official_bank_source${"itemId":"abe86842-c0b5-5cf2-a8e9-a8095febc8af","questionId":"d2938e7f-1d11-5e89-ae90-c4a45cc3a256","sourceKey":"bank:ECO201:SUP-023","payload":{"prompt":"The supply of a good is Qs = 20 + 2P, a straight line that cuts the quantity axis. Using Es = (P/Q)(change in Q / change in P), the price elasticity of supply at P = N10 is","options":["2.0, so supply is elastic","1.0, so supply is unit elastic","0.25, so supply is inelastic","0.5, so supply is inelastic"],"correctOption":3,"section":"Supply Theory","explanation":"At P = 10, Qs = 20 + 20 = 40 and the slope term is 2, so Es = (10/40) x 2 = 0.5, which is inelastic; any straight-line supply curve that cuts the quantity axis is inelastic. Option A uses the slope of 2 alone without multiplying by P/Q. Option C is P/Q = 0.25 without the slope, and option B would hold only for a line through the origin."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 355, $official_bank_source${"itemId":"4fd36ff5-ca27-5e2e-8881-b1871aaf26c0","questionId":"e9848e35-a485-568a-b65b-8a33f4d918cd","sourceKey":"bank:ECO201:SUP-024","payload":{"prompt":"A firm's supply function is Qs = 100 + 6P - 2W, where W is the wage rate. If W rises from N20 to N30, the supply curve","options":["shifts left by 20 units at every price","shifts right by 20 units at every price","does not shift; quantity supplied moves along the curve","shifts left by 60 units at every price"],"correctOption":0,"section":"Supply Theory","explanation":"The quantity supplied at each price changes by -2 x (30 - 20) = -20 units, so the whole supply curve shifts 20 units to the left. Option B has the wrong direction, since the wage coefficient is negative. Option D uses the price coefficient of 6 instead of the wage coefficient, and option C is wrong because the wage is a determinant other than the good's own price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 356, $official_bank_source${"itemId":"e0f44569-6140-5e5e-9cfb-ad2935a1eb00","questionId":"bcfca1e0-34e3-583e-97a6-3347dc0a48be","sourceKey":"bank:ECO201:SUP-025","payload":{"prompt":"Which of the following statements about supply elasticities is correct?","options":["The price elasticity of supply is usually positive, while the elasticity of supply with respect to raw-input prices is usually negative","Both the price elasticity of supply and the elasticity with respect to input prices are usually negative","The price elasticity of supply is usually negative, while the elasticity of supply with respect to raw-input prices is usually positive","Both the price elasticity of supply and the elasticity with respect to input prices are usually positive"],"correctOption":0,"section":"Supply Theory","explanation":"A higher price of the good encourages more output, so price elasticity of supply is positive, whereas a higher price of inputs raises costs and reduces output, so that elasticity is negative. Option C swaps the two signs. Options D and B wrongly give both elasticities the same sign."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 357, $official_bank_source${"itemId":"dfcb6ab2-047e-5cd0-bd4c-d1eff9364931","questionId":"9b29a575-607b-5077-99ee-9e67e84189e9","sourceKey":"bank:ECO201:SUP-026","payload":{"prompt":"For most manufactured products, the price elasticity of supply is","options":["larger in the long run than in the short run, because firms need time to expand capacity","larger in the short run than in the long run, because firms run down stocks","the same in the short run and the long run","always zero in the long run"],"correctOption":0,"section":"Supply Theory","explanation":"In the short run firms face capacity limits, but with time they can build new plants and new firms can enter, so supply responds more to price in the long run. Option B reverses the usual pattern. Option C ignores capacity constraints, and option D describes perfectly inelastic supply, which is the opposite of what happens over time."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 358, $official_bank_source${"itemId":"cce77441-aed8-50f8-a64e-d218e2c3c913","questionId":"17830bba-4890-5009-a07d-fb593fa9281d","sourceKey":"bank:ECO201:E201N1-001","payload":{"prompt":"Estimated price elasticities of total copper supply are 0.25 in the short run and 1.50 in the long run. If the price of copper rises by 10% and stays at the new level, the long-run increase in the quantity of copper supplied is about","options":["2.5%","1.5%","15%","6.7%"],"correctOption":2,"section":"Supply Theory","explanation":"Price elasticity of supply is the % change in quantity supplied divided by the % change in price, so the long-run change is 1.50 x 10% = 15%. The figure 2.5% uses the short-run elasticity of 0.25, which describes the response before firms have time to expand capacity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 359, $official_bank_source${"itemId":"74339651-71c5-5f6a-9eb7-0b449e288682","questionId":"ac34752f-7393-510e-8eee-4b6d8d2eb862","sourceKey":"bank:ECO201:E201N1-002","payload":{"prompt":"For which of the following is the price elasticity of supply generally smaller in the long run than in the short run?","options":["Secondary supply of a durable good, such as scrap metal","Supply of most manufactured goods","Total market supply of copper","Primary supply of copper from mines"],"correctOption":0,"section":"Supply Theory","explanation":"Long-run supply is usually more elastic because firms can expand capacity, but secondary supply of a durable good like scrap metal is the exception: for secondary copper the elasticity falls from 0.43 in the short run to 0.31 in the long run. Primary copper from mines follows the normal pattern, with its elasticity rising from 0.20 to 1.60."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 360, $official_bank_source${"itemId":"7cb211fb-bdd4-5886-8bb4-3ed37c929842","questionId":"79afeb51-b544-5f95-9a67-4a1cb491f2bc","sourceKey":"bank:ECO201:E201N1-003","payload":{"prompt":"Before any subsidy, sachet water producers in Lagos need a price of at least N60 per bag to supply 500 bags a day. The government then pays them a subsidy of N4 per bag. Other things equal, the lowest price buyers must now pay for producers to supply 500 bags a day is","options":["N15","N56","N60","N64"],"correctOption":1,"section":"Supply Theory","explanation":"A per-unit subsidy shifts the supply curve down by the amount of the subsidy, so producers who still need N60 in total per bag now need only N60 - N4 = N56 from buyers. The figure N64 adds the subsidy instead of subtracting it, which is how a N4 per-unit tax would shift supply up."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 361, $official_bank_source${"itemId":"c444bd57-de54-5c41-b6cb-f94ae9bc208b","questionId":"8fb2d0bd-db23-5596-aceb-76083756614c","sourceKey":"bank:ECO201:E201N1-004","payload":{"prompt":"The supply of a good is Qs = -20 + 4P, where P is in naira. The government imposes a tax of N5 per unit, paid by sellers. Written in terms of the price buyers pay, the new supply equation is","options":["Qs = -40 + 4P","Qs = -25 + 4P","Qs = 4P","Qs = -15 + 4P"],"correctOption":0,"section":"Supply Theory","explanation":"A per-unit tax shifts supply up by the tax, so sellers now receive only P - 5 of each price P that buyers pay: Qs = -20 + 4(P - 5) = -40 + 4P. The equation Qs = 4P comes from adding the tax to the price instead of subtracting it, which would wrongly make sellers more willing to supply."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 362, $official_bank_source${"itemId":"877874bb-d2a9-55c1-8f6e-3e29c469a3c8","questionId":"4fda3894-d849-5b86-99e6-a5ced9097568","sourceKey":"bank:ECO201:E201N1-005","payload":{"prompt":"The elasticity of supply of bread with respect to the price of flour is -0.4 for bakeries in Surulere. If the price of flour rises by 10%, other things equal, the quantity of bread supplied will","options":["fall by about 0.4%","fall by about 4%","fall by about 25%","rise by about 4%"],"correctOption":1,"section":"Supply Theory","explanation":"This elasticity is the % change in bread supplied divided by the % change in the flour price, so the change is -0.4 x 10% = -4%, a fall of about 4%. The negative sign is normal here, because dearer raw materials raise costs and reduce supply, so an answer of a 4% rise ignores the sign."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 363, $official_bank_source${"itemId":"f3f666e3-ec82-50e1-93d3-52c6c235430d","questionId":"6bb2e512-ae3d-51bd-a855-c27d0bd4cb4d","sourceKey":"bank:ECO201:E201N1-006","payload":{"prompt":"The price elasticity of supply is best defined as the","options":["percentage change in quantity supplied resulting from a 1 percent rise in input prices","change in quantity supplied resulting from a N1 increase in the price","percentage change in quantity demanded resulting from a 1 percent increase in price","percentage change in quantity supplied resulting from a 1 percent increase in price"],"correctOption":3,"section":"Supply Theory","explanation":"Elasticity of supply compares percentage changes, telling us by what percent quantity supplied changes when price rises by 1 percent. The change in quantity per N1 rise in price is the slope of the supply curve, which depends on the units used and is not the same thing as elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 364, $official_bank_source${"itemId":"d7e70a0c-eede-51d4-b894-86bb6a76d6c1","questionId":"e08d4a3b-a23d-5fe3-bfae-58c5a8be57b0","sourceKey":"bank:ECO201:E201N1-007","payload":{"prompt":"A manufacturing firm in Ikeja finances its machines with bank loans. If the interest rate it pays on these loans rises sharply, other things equal, the firm's supply curve will","options":["stay put, with a movement up along it","shift to the right","shift to the left","become perfectly elastic"],"correctOption":2,"section":"Supply Theory","explanation":"Interest is part of a firm's cost of production, alongside wages and raw materials, so a higher interest rate raises costs and the firm offers less at each price, a leftward shift. A movement along the curve happens only when the good's own price changes, not when a cost changes."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 365, $official_bank_source${"itemId":"89455e06-166f-5670-ade7-16965d936de7","questionId":"ca0f1116-7695-5531-b0db-1a65fbf9dfd8","sourceKey":"bank:ECO201:E201N1-008","payload":{"prompt":"When the price of tomatoes at Mile 12 market rises sharply, the total quantity of tomatoes offered for sale rises. One reason the market supply curve slopes upward in this way is that","options":["the cost of fertiliser to existing growers falls","consumers' incomes rise, so buyers want more tomatoes","the supply curve of tomatoes shifts to the right","higher-cost growers now find it worthwhile to enter the market"],"correctOption":3,"section":"Supply Theory","explanation":"At a higher price, existing growers can cover the extra cost of overtime or more workers, and growers whose costs were too high at the old price now find it profitable to sell, so quantity supplied rises along the curve. A fall in fertiliser costs is a different event: it is a non-price determinant that shifts the whole supply curve rather than explaining its upward slope."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 366, $official_bank_source${"itemId":"daed3ddd-fe5b-5076-b100-cfdcc5a7b116","questionId":"e4405792-3939-5592-838f-1dcf0079001d","sourceKey":"bank:ECO201:E201-0033","payload":{"prompt":"A decrease in supply when demand remains the same will cause equilibrium ______.","options":["P and Q to both fall","P and Q to both rise","P to rise while Q falls","P to fall while Q rises"],"correctOption":2,"section":"Market Equilibrium","explanation":"A decrease in supply shifts the supply curve to the left; with demand unchanged, a shortage appears at the old price, so price rises and the quantity bought and sold falls. Option A (both fall) is what happens when demand decreases, and option B (both rise) is the result of an increase in demand. Option D describes an increase in supply."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 367, $official_bank_source${"itemId":"0be65971-629a-5595-8a7a-8aa93b6b73d8","questionId":"438d65eb-303f-5c9b-a46b-68551f68ce01","sourceKey":"bank:ECO201:E201-0034","payload":{"prompt":"Any price below the equilibrium price will lead to ______ which is also referred to as ______.","options":["Excess demand, surplus","Excess demand, shortage","Excess supply, shortage","Excess supply, surplus"],"correctOption":1,"section":"Market Equilibrium","explanation":"Below the equilibrium price, quantity demanded is greater than quantity supplied, giving excess demand, which is also called a shortage. Options C and D refer to excess supply, which occurs above the equilibrium price and is called a surplus. Option A wrongly pairs excess demand with surplus."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 368, $official_bank_source${"itemId":"828d629b-2566-5ae7-a031-583ef62ed2e4","questionId":"7d5be4ff-715d-55f1-aeca-f183e9632e2c","sourceKey":"bank:ECO201:E201-0045","payload":{"prompt":"Given Qd = 300 - 2.5P and Qs = 200 + 1.5P, the equilibrium price and quantity are ______ and ______ respectively.","options":["Ep = 20 and Eq = 300.5","Ep = 24 and Eq = 250.5","Ep = 45 and Eq = 285.0","Ep = 25 and Eq = 237.5"],"correctOption":3,"section":"Market Equilibrium","explanation":"At equilibrium Qd = Qs, so 300 - 2.5P = 200 + 1.5P, which gives 100 = 4P and P = 25. Substituting, Q = 300 - 2.5(25) = 237.5, and the supply side gives the same: 200 + 1.5(25) = 237.5. The other options do not make quantity demanded equal to quantity supplied; for example, at P = 20 demand is 250 but supply is only 230."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 369, $official_bank_source${"itemId":"7cd3b3ae-2a8b-5088-b407-6fd4f7798680","questionId":"bd23be73-6066-5f5d-b035-96d34c871275","sourceKey":"bank:ECO201:E201-0279","payload":{"prompt":"The market equilibrium for a commodity is determined by","options":["The market demand for the commodity","The market supply of the commodity","The balancing of the forces of demand and supply for the commodity","Any of these"],"correctOption":2,"section":"Market Equilibrium","explanation":"Market equilibrium is reached at the price where quantity demanded equals quantity supplied, so it is set by the balancing of demand and supply together. Demand alone (option A) or supply alone (option B) cannot fix the price, which is like asking which blade of a pair of scissors does the cutting."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 370, $official_bank_source${"itemId":"7fe73217-2255-5f77-9e2b-af5be7b34a0f","questionId":"665295d8-7c2e-5e8b-bf3c-822ad152e718","sourceKey":"bank:ECO201:E201-0447","payload":{"prompt":"At prices above the equilibrium price:","options":["Quantity supplied exceeds quantity demanded","Quantity demanded exceeds quantity supplied","There is a shortage","Any of the above is possible"],"correctOption":0,"section":"Market Equilibrium","explanation":"Above the equilibrium price, sellers want to sell more and buyers want to buy less, so quantity supplied exceeds quantity demanded and there is a surplus. Options B and C describe a shortage, which happens below the equilibrium price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 371, $official_bank_source${"itemId":"5d764f7e-7c6b-53f1-ae9e-c7eb2675f049","questionId":"eb4226b2-da32-5728-805c-2771fd4ab2b7","sourceKey":"bank:ECO201:E201-0448","payload":{"prompt":"An increase in market supply, with demand remaining the same, causes:","options":["Increase in equilibrium price","Decrease in equilibrium quantity","Decrease in equilibrium price and increase in equilibrium quantity","Both equilibrium price and quantity rises"],"correctOption":2,"section":"Market Equilibrium","explanation":"A rightward shift of supply with demand unchanged creates a surplus at the old price, so price falls and buyers move down their demand curve to buy more. Option A has price moving the wrong way, and option D is what happens when demand, not supply, increases."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 372, $official_bank_source${"itemId":"da29aec3-e9e0-5ffa-85c4-566d864c84f2","questionId":"72010df8-f065-5972-94b3-9a0f0ae2368d","sourceKey":"bank:ECO201:E201-0449","payload":{"prompt":"An increase in market demand, with supply remaining the same, results in:","options":["A decrease in equilibrium price","A decrease in equilibrium quantity","A decrease in equilibrium price and an increase in equilibrium quantity","A rise in both equilibrium price and quantity"],"correctOption":3,"section":"Market Equilibrium","explanation":"A rightward shift of demand with supply unchanged creates a shortage at the old price, so price is bid up and sellers move up their supply curve, raising quantity too. Option C pairs a fall in price with a rise in quantity, which happens when supply increases."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 373, $official_bank_source${"itemId":"a9e657b9-ac63-5622-94dd-0473aad2c414","questionId":"c5b26b94-65de-53df-acbd-33d67824940f","sourceKey":"bank:ECO201:E201-0450","payload":{"prompt":"A fall in market demand, with supply remaining the same, results in:","options":["An increase in equilibrium price","An increase in equilibrium quantity","An increase in equilibrium price and a decrease in equilibrium quantity","A fall in both equilibrium price and quantity"],"correctOption":3,"section":"Market Equilibrium","explanation":"A leftward shift of demand with supply unchanged leaves a surplus at the old price, so price falls and sellers cut the quantity they supply, lowering both. Option C is the result of a decrease in supply, not of a fall in demand."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 374, $official_bank_source${"itemId":"1cfad9c4-bbac-5920-a566-f2ed93a349bf","questionId":"ffc3169a-0bbe-537c-9baf-6477cd8f869e","sourceKey":"bank:ECO201:E201-0461","payload":{"prompt":"Unusually hot weather shifts the demand curve for ice cream to the right. Why does the price of ice cream rise to a new market-clearing level?","options":["The supply curve shifts to the left because sellers expect hot weather","Sellers raise the price, but the quantity sold must stay the same as before","At the old price quantity demanded now exceeds quantity supplied, and the shortage bids the price up until the two are equal again","At the old price quantity supplied now exceeds quantity demanded, and the surplus pushes the price up"],"correctOption":2,"section":"Market Equilibrium","explanation":"After demand shifts right, buyers want more ice cream than sellers offer at the old price, so there is a shortage. Competition among buyers pushes the price up, which raises quantity supplied along the supply curve and reduces quantity demanded until the market clears again at a higher price and a larger quantity. Option D describes a surplus, which would push price down, and option B is wrong because the new equilibrium quantity is larger."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 375, $official_bank_source${"itemId":"45c83ccf-8a9c-52de-9160-8bc717971bda","questionId":"99c13bc4-9d68-5596-a8cb-cd75eb022ba6","sourceKey":"bank:ECO201:E201-0462","payload":{"prompt":"Margarine is a substitute for butter. Using supply and demand, how would an increase in the price of margarine affect the market for butter?","options":["The price of butter rises and the quantity of butter bought and sold rises","The price of butter rises and the quantity of butter bought and sold falls","The price of butter falls and the quantity of butter bought and sold rises","The price of butter falls and the quantity of butter bought and sold falls"],"correctOption":0,"section":"Market Equilibrium","explanation":"Dearer margarine makes consumers switch to butter, so the demand curve for butter shifts to the right along an unchanged supply curve. A rightward demand shift raises both equilibrium price and equilibrium quantity. Option B is the result of a fall in supply, and option D is the result of a fall in demand."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 376, $official_bank_source${"itemId":"49df0f4d-e62d-5b40-8560-dcb2c6dd2e60","questionId":"b486c4d4-6a20-52df-8c16-9ddfb73773d7","sourceKey":"bank:ECO201:E201-0462-b","payload":{"prompt":"Milk is the main input used in producing butter. Using supply and demand, how would an increase in the price of milk affect the market for butter?","options":["The price of butter rises and the quantity of butter bought and sold rises","The price of butter falls and the quantity of butter bought and sold falls","The price of butter falls and the quantity of butter bought and sold rises","The price of butter rises and the quantity of butter bought and sold falls"],"correctOption":3,"section":"Market Equilibrium","explanation":"A rise in the price of milk raises the cost of making butter, so the supply curve of butter shifts to the left while demand stays the same. At the old price there is now a shortage, so price rises and the quantity traded falls. Option A is what happens when demand increases, not when supply decreases."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 377, $official_bank_source${"itemId":"6f56d662-94ce-5bbf-b754-b88d2980ca19","questionId":"1b2438eb-1dc5-5409-afb1-31f45a6bdec3","sourceKey":"bank:ECO201:E201-0472","payload":{"prompt":"The copper market has supply Q = -9 + 9P and demand Q = 27 - 3P (Q in million metric tons per year, P in dollars per pound). A fall in production costs shifts the supply curve to the right by 40 percent, to Q = 1.4(-9 + 9P). What happens to the price of copper?","options":["It falls from $3.00 to about $2.54 per pound","It falls from $3.00 to about $2.75 per pound","It rises from $3.00 to about $3.46 per pound","It falls from $3.00 to about $1.80 per pound"],"correctOption":0,"section":"Market Equilibrium","explanation":"Initially 27 - 3P = -9 + 9P gives 12P = 36, so P = $3.00. The new supply is Q = -12.6 + 12.6P, so 27 - 3P = -12.6 + 12.6P gives 15.6P = 39.6 and P = about $2.54 per pound. Option D wrongly cuts the price itself by 40 percent, and option C has price moving the wrong way, since more supply lowers price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 378, $official_bank_source${"itemId":"26c22f56-8f76-5ffb-a228-5402a09c110a","questionId":"601cd8a1-263f-55ba-8125-706b7abc0d6a","sourceKey":"bank:ECO201:E201-0474","payload":{"prompt":"The demand curve for a product is Q = 300 - 2P + 4I, where I is average income in thousands of dollars, and the supply curve is Q = 3P - 50. If I = 25, what are the market-clearing price and quantity?","options":["P = 90, Q = 220","P = 80, Q = 190","P = 70, Q = 160","P = 110, Q = 280"],"correctOption":0,"section":"Market Equilibrium","explanation":"With I = 25, demand is Q = 300 - 2P + 100 = 400 - 2P. Setting 400 - 2P = 3P - 50 gives 5P = 450, so P = 90 and Q = 3(90) - 50 = 220. Option C leaves out the income term (350 = 5P), and option D is the answer for I = 50."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 379, $official_bank_source${"itemId":"334ae16d-8d96-5f0c-8235-3bdac40a3bf3","questionId":"01c89208-bd58-531e-8f1d-47e9fd0f3d9f","sourceKey":"bank:ECO201:E201-0474-b","payload":{"prompt":"The demand curve for a product is Q = 300 - 2P + 4I, where I is average income in thousands of dollars, and the supply curve is Q = 3P - 50. If I = 50, what are the market-clearing price and quantity?","options":["P = 70, Q = 160","P = 110, Q = 280","P = 90, Q = 220","P = 130, Q = 340"],"correctOption":1,"section":"Market Equilibrium","explanation":"With I = 50, demand is Q = 300 - 2P + 200 = 500 - 2P. Setting 500 - 2P = 3P - 50 gives 5P = 550, so P = 110 and Q = 3(110) - 50 = 280. Option C is the equilibrium when I = 25, so it ignores the income rise that shifts demand to the right."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 380, $official_bank_source${"itemId":"2586ff91-fc20-5987-96bb-59d03dce4049","questionId":"cdef800a-adf7-5f70-85d9-490a3d19e8e6","sourceKey":"bank:ECO201:E201-0476","payload":{"prompt":"The total demand for U.S. wheat is Q = 3244 - 283P and domestic supply is QS = 1944 + 207P (Q in million bushels, P in dollars per bushel). New export markets add 200 million bushels to demand at every price. What are the new free-market price and quantity?","options":["P = about $3.06, Q = about 2578 million bushels","P = about $3.06, Q = about 2778 million bushels","P = about $2.24, Q = about 2409 million bushels","P = about $2.65, Q = about 2493 million bushels"],"correctOption":0,"section":"Market Equilibrium","explanation":"New demand is Q = 3444 - 283P. Setting 3444 - 283P = 1944 + 207P gives 490P = 1500, so P = about $3.06 and Q = 1944 + 207(3.06) = about 2578 million bushels. Option D is the old equilibrium before the extra demand, and option C subtracts the 200 instead of adding it."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 381, $official_bank_source${"itemId":"2c04e477-7871-5206-a54c-82a38c92f43a","questionId":"7464c25d-8679-55bf-ba06-6324a57471f7","sourceKey":"bank:ECO201:E201-0477-b","payload":{"prompt":"A vegetable fiber has a world price of $9 per pound, and unlimited imports are available at that price. U.S. supply and demand (million pounds) are: price $3, supply 2, demand 34; $6, supply 4, demand 28; $9, supply 6, demand 22; $12, supply 8, demand 16; $15, supply 10, demand 10; $18, supply 12, demand 4. In a free market, what will be the level of U.S. fiber imports?","options":["16 million pounds","6 million pounds","Zero","22 million pounds"],"correctOption":0,"section":"Market Equilibrium","explanation":"With unlimited imports at $9, the U.S. price is $9. At that price U.S. demand is 22 million pounds and U.S. supply is 6 million pounds, so imports fill the gap of 22 - 6 = 16 million pounds. Option B is domestic supply, option D is total demand, and option C would be correct only at the domestic equilibrium price of $15."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 382, $official_bank_source${"itemId":"5145940d-7747-5693-ba91-e469b3214dde","questionId":"87486a8a-0b47-5dc5-a108-8ffe38396f35","sourceKey":"bank:ECO201:E201-0478","payload":{"prompt":"Total demand for U.S. wheat is Q = 3244 - 283P, of which domestic demand is QD = 1700 - 107P; domestic supply is QS = 1944 + 207P (Q in million bushels, P in dollars per bushel). Export demand then falls by 40 percent at every price. What happens to the free-market price of wheat?","options":["It falls from about $2.65 to about $1.63 per bushel","It stays at about $2.65 per bushel","It falls from about $2.65 to about $0.98 per bushel","It falls from about $2.65 to about $2.24 per bushel"],"correctOption":0,"section":"Market Equilibrium","explanation":"Export demand is total minus domestic: (3244 - 283P) - (1700 - 107P) = 1544 - 176P, and 60 percent of it is 926.4 - 105.6P. New total demand is 2626.4 - 212.6P, so 2626.4 - 212.6P = 1944 + 207P gives P = 682.4/419.6 = about $1.63, down from 1300/490 = about $2.65. Option B ignores the fall in export demand, which shifts total demand to the left and must lower the price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 383, $official_bank_source${"itemId":"16cdfbcf-5da0-5908-aa39-fc22fe240151","questionId":"6a8ce8df-09bb-5407-b93e-f183e315639a","sourceKey":"bank:ECO201:E201-0479","payload":{"prompt":"Rental demand in a city is QD = 160 - 8P and supply is QS = 70 + 7P, where Q is in tens of thousands of apartments and P is the average monthly rent in hundreds of dollars. What are the free-market rent and number of apartments?","options":["$900 per month and 880,000 apartments","$300 per month and 1,360,000 apartments","$600 per month and 112 apartments","$600 per month and 1,120,000 apartments"],"correctOption":3,"section":"Market Equilibrium","explanation":"Setting 160 - 8P = 70 + 7P gives 15P = 90, so P = 6, which is $600 per month. Then Q = 160 - 8(6) = 112 tens of thousands, or 1,120,000 apartments. Option C forgets to convert the units, and option B uses the demand at a rent of $300 instead of the equilibrium."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 384, $official_bank_source${"itemId":"121a8c96-b5b4-5486-b5d2-93e166a7c446","questionId":"ea01b061-3a63-50df-a469-a6fe87a810b0","sourceKey":"bank:ECO201:E201-0482","payload":{"prompt":"The copper market is in equilibrium at P = $3 per pound and Q = 18 million metric tons per year, with supply elasticity 1.5 and demand elasticity -0.5, giving supply Q = -9 + 9P and demand Q = 27 - 3P. If copper demand increases by 20 percent at every price, what is the new equilibrium price?","options":["About $3.29 per pound","About $3.67 per pound","About $2.71 per pound","About $3.60 per pound"],"correctOption":0,"section":"Market Equilibrium","explanation":"New demand is 1.2(27 - 3P) = 32.4 - 3.6P. Setting 32.4 - 3.6P = -9 + 9P gives 12.6P = 41.4, so P = about $3.29, with Q = -9 + 9(3.29) = about 20.6 million tons. Option D raises the price itself by 20 percent, and option B is the price when supply also falls by 20 percent."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 385, $official_bank_source${"itemId":"6345c8d1-05a0-54a9-a4d0-2c04fb093afc","questionId":"a82886fd-646c-59b7-a1d2-e4a92e63002b","sourceKey":"bank:ECO201:E201-0482-b","payload":{"prompt":"The copper market is in equilibrium at P = $3 per pound and Q = 18 million metric tons per year, with supply elasticity 1.5 and demand elasticity -0.5, giving supply Q = -9 + 9P and demand Q = 27 - 3P. If copper demand increases by 20 percent and copper supply decreases by 20 percent at every price, what are the new equilibrium price and quantity?","options":["P = about $3.67, Q = about 19.2 million tons","P = about $3.67, Q = about 24.0 million tons","P = about $3.29, Q = about 20.6 million tons","P = $3.00, Q = 18.0 million tons"],"correctOption":0,"section":"Market Equilibrium","explanation":"New demand is 32.4 - 3.6P and new supply is 0.8(-9 + 9P) = -7.2 + 7.2P. Setting them equal gives 10.8P = 39.6, so P = about $3.67 and Q = -7.2 + 7.2(3.67) = about 19.2 million tons. Option C ignores the fall in supply, and option B works out quantity from the old supply curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 386, $official_bank_source${"itemId":"a6077490-0fd8-592d-8e9e-b1cf6a314383","questionId":"694f9bc5-63ce-540d-aac7-ec0cd10b2c18","sourceKey":"bank:ECO201:E201-0483","payload":{"prompt":"The world oil market is at P = $50 per barrel, with world demand of 35 billion barrels per year (bb/yr), competitive (non-OPEC) supply of 23 bb/yr and OPEC supply of 12 bb/yr. Short-run demand is D = 36.75 - 0.035P and short-run competitive supply is SC = 21.85 + 0.023P; long-run demand is D = 45.5 - 0.210P and long-run competitive supply is SC = 16.1 + 0.138P. OPEC then raises output by 2 bb/yr to 14 bb/yr. What is the new short-run price of oil?","options":["About $44.25 per barrel","About $15.52 per barrel","About $48.00 per barrel","About $34.48 per barrel"],"correctOption":1,"section":"Market Equilibrium","explanation":"In the short run total supply is 21.85 + 0.023P + 14. Setting 36.75 - 0.035P = 35.85 + 0.023P gives 0.058P = 0.90, so P = about $15.52. Because short-run demand and supply are very inelastic, a small rise in output causes a big price fall. Option A is the long-run price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 387, $official_bank_source${"itemId":"aabe95f5-ff67-588b-9df6-6a9093d5e252","questionId":"3a4b14b4-bb7e-52c7-a981-5e7870d0524a","sourceKey":"bank:ECO201:E201-0483-b","payload":{"prompt":"The world oil market is at P = $50 per barrel, with world demand of 35 billion barrels per year (bb/yr), competitive (non-OPEC) supply of 23 bb/yr and OPEC supply of 12 bb/yr. Short-run demand is D = 36.75 - 0.035P and short-run competitive supply is SC = 21.85 + 0.023P; long-run demand is D = 45.5 - 0.210P and long-run competitive supply is SC = 16.1 + 0.138P. OPEC then raises output by 2 bb/yr to 14 bb/yr. What is the new long-run price of oil?","options":["About $55.75 per barrel","About $44.25 per barrel","About $15.52 per barrel","About $48.00 per barrel"],"correctOption":1,"section":"Market Equilibrium","explanation":"In the long run total supply is 16.1 + 0.138P + 14. Setting 45.5 - 0.210P = 30.1 + 0.138P gives 0.348P = 15.4, so P = about $44.25. Long-run demand and supply are more elastic, so the price falls far less than in the short run. Option C is the short-run price, and option A has price rising when supply has increased."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 388, $official_bank_source${"itemId":"4ed0412b-af86-51c1-b2f8-17caaff6f3cd","questionId":"fe88ca07-e9bc-565f-bb53-0bea1f6b0cac","sourceKey":"bank:ECO201:E201-0484-b","payload":{"prompt":"The natural gas market (Q in trillion cubic feet, Tcf) has supply Q = 15.90 + 0.72PG + 0.05PO and demand Q = 0.02 - 1.8PG + 0.69PO, where PG is the price of gas ($ per thousand cubic feet) and PO is the price of oil ($ per barrel). If the gas market is unregulated and the price of oil rises from $50 to $100, what happens to the free-market price of gas?","options":["It stays at about $6.40","It rises from about $6.40 to about $12.80","It rises from about $6.40 to about $19.10","It falls from about $6.40 to about $3.20"],"correctOption":2,"section":"Market Equilibrium","explanation":"With PO = 100, supply is 15.90 + 5.00 + 0.72PG = 20.90 + 0.72PG and demand is 0.02 + 69.00 - 1.8PG = 69.02 - 1.8PG. Setting them equal gives 2.52PG = 48.12, so PG = about $19.10. Oil is a substitute for gas, so dearer oil raises gas demand much more than gas supply; option B simply doubles the gas price, which the equations do not support."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 389, $official_bank_source${"itemId":"1fb43540-507e-5546-a6d4-37c6f2aa4cb1","questionId":"c07c0fed-c048-5710-8f18-8cdcb0540426","sourceKey":"bank:ECO201:MEQ-001","payload":{"prompt":"The price that equates the quantity supplied to the quantity demanded in a market is called the","options":["reservation price","support price","ceiling price","equilibrium (market-clearing) price"],"correctOption":3,"section":"Market Equilibrium","explanation":"At the equilibrium or market-clearing price, the amount buyers want equals the amount sellers offer, so there is neither shortage nor surplus. A ceiling price (option C) and a support price (option B) are prices set by government, usually away from equilibrium. A reservation price (option A) is the most a buyer will pay or the least a seller will accept, not the price that clears the market."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 390, $official_bank_source${"itemId":"3fc922de-079d-588d-a4a4-79428c8e2ec2","questionId":"5f40eac9-6e2e-52ec-b225-e4d583282818","sourceKey":"bank:ECO201:MEQ-002","payload":{"prompt":"The tendency in a free market for price to change until the market clears is called the","options":["invisible tax","market mechanism","law of supply","price control"],"correctOption":1,"section":"Market Equilibrium","explanation":"The market mechanism is the process by which shortages push prices up and surpluses push them down until quantity demanded equals quantity supplied. Option D is government interference with that process. Option C describes only how sellers respond to price, and option A is not the name of this process."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 391, $official_bank_source${"itemId":"fcd82234-16a1-52a0-91bd-637bf38cc42a","questionId":"bee40b2d-509d-5586-924a-52ec62da9636","sourceKey":"bank:ECO201:MEQ-003","payload":{"prompt":"A situation in which the quantity supplied exceeds the quantity demanded at the current price is called a","options":["surplus (excess supply)","shortage (excess demand)","market-clearing position","equilibrium"],"correctOption":0,"section":"Market Equilibrium","explanation":"A surplus or excess supply exists when sellers offer more than buyers want at the going price, which happens when price is above equilibrium. Option B is the opposite situation. Options D and C describe the point where the two quantities are equal."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 392, $official_bank_source${"itemId":"0cdaad83-46a6-53f5-a559-2d8c76ded267","questionId":"c5e6216f-8828-5bf2-b60e-1514f9b0a6db","sourceKey":"bank:ECO201:MEQ-004","payload":{"prompt":"In a market, a shortage (excess demand) means that at the current price","options":["quantity supplied is greater than quantity demanded","both quantity demanded and quantity supplied are zero","quantity demanded equals quantity supplied","quantity demanded is greater than quantity supplied"],"correctOption":3,"section":"Market Equilibrium","explanation":"A shortage occurs when buyers want more than sellers are offering, which happens when price is below equilibrium. Option A describes a surplus. Option C describes equilibrium, and option B is not what a shortage means."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 393, $official_bank_source${"itemId":"77e156c4-a1fd-585c-8fc3-1200786bf72a","questionId":"5ca3541e-49db-5c11-a1d9-eea151913b94","sourceKey":"bank:ECO201:MEQ-005","payload":{"prompt":"If the current price in a competitive market is above the equilibrium price, what will happen?","options":["A surplus exists, and the price will tend to fall towards equilibrium","A shortage exists, and the price will tend to fall towards equilibrium","A shortage exists, and the price will tend to rise further","A surplus exists, and the price will tend to rise further"],"correctOption":0,"section":"Market Equilibrium","explanation":"Above equilibrium, sellers offer more than buyers want, so unsold stock builds up and sellers cut prices until the market clears. Option C wrongly names the situation as a shortage. Option D has the right situation but the wrong direction, and option B gets the situation wrong."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 394, $official_bank_source${"itemId":"af1e27a0-0254-5b67-af6f-64cb62d8c788","questionId":"524d0c3f-702a-54c2-9df1-749e3f4a1f8d","sourceKey":"bank:ECO201:MEQ-006","payload":{"prompt":"At a price below equilibrium in a competitive market, buyers who cannot get the good will","options":["bid the price up, which reduces quantity demanded and raises quantity supplied until the market clears","force sellers to cut output, which removes the shortage","accept the shortage permanently, since price cannot change","push the price down, which raises quantity demanded further"],"correctOption":0,"section":"Market Equilibrium","explanation":"When there is a shortage, unsatisfied buyers offer more, so the price rises; along the way quantity demanded falls and quantity supplied rises until they are equal. Option C ignores the market mechanism in a free market. Option D moves price the wrong way and would widen the shortage, and option B would make the shortage worse, not remove it."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 395, $official_bank_source${"itemId":"83e4aea6-cd5c-5e26-93fe-94a5aa142f5a","questionId":"642438f7-276c-5b8d-b2eb-edff0296545c","sourceKey":"bank:ECO201:MEQ-007","payload":{"prompt":"Other things equal, an increase in demand with supply unchanged will cause equilibrium price and quantity to","options":["rise and fall respectively","both fall","both rise","fall and rise respectively"],"correctOption":2,"section":"Market Equilibrium","explanation":"A rightward demand shift creates a shortage at the old price, so price is bid up and sellers move up their supply curve to a larger quantity; both price and quantity rise. Option B follows a fall in demand. Option A is the result of a fall in supply, and option D is the result of a rise in supply."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 396, $official_bank_source${"itemId":"759ab3c2-e3cf-5189-b2e1-d880cd53bd30","questionId":"0e831356-c1b2-5753-adc2-f44b3116728b","sourceKey":"bank:ECO201:MEQ-008","payload":{"prompt":"Other things equal, an increase in supply with demand unchanged will cause the equilibrium price to","options":["rise and the equilibrium quantity to fall","rise and the equilibrium quantity to rise","fall and the equilibrium quantity to fall","fall and the equilibrium quantity to rise"],"correctOption":3,"section":"Market Equilibrium","explanation":"A rightward supply shift creates a surplus at the old price, so price falls and buyers move down their demand curve to a larger quantity. Option B is the effect of a rise in demand. Option C follows a fall in demand, and option A follows a fall in supply."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 397, $official_bank_source${"itemId":"a5aa5281-cb59-5292-ab45-5ae8832f1f7f","questionId":"ac11009b-a0b6-53a7-bab1-4a87c4ac0251","sourceKey":"bank:ECO201:MEQ-009","payload":{"prompt":"A pest destroys a large part of the tomato harvest in Kano, while demand for tomatoes is unchanged. The equilibrium price and quantity of tomatoes will","options":["fall and rise respectively","both fall","rise and fall respectively","both rise"],"correctOption":2,"section":"Market Equilibrium","explanation":"The pest shifts supply left, so at the old price there is a shortage; price rises and buyers move up their demand curve to a smaller quantity. Option D is the result of a rise in demand. Option B follows a fall in demand, and option A follows a rise in supply."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 398, $official_bank_source${"itemId":"07399015-7f02-53eb-beaf-4be509734d56","questionId":"7df58c67-1b15-55e8-bedb-60bf97edce77","sourceKey":"bank:ECO201:MEQ-010","payload":{"prompt":"If demand and supply both increase at the same time, then","options":["equilibrium price falls, but the change in equilibrium quantity is indeterminate","equilibrium quantity rises, but the change in equilibrium price is indeterminate","equilibrium price and quantity both definitely rise","equilibrium price rises, but the change in equilibrium quantity is indeterminate"],"correctOption":1,"section":"Market Equilibrium","explanation":"Both shifts push quantity up, so quantity certainly rises; but more demand pushes price up while more supply pushes it down, so the price change depends on which shift is bigger. Option D swaps which variable is certain. Option C wrongly treats the price rise as certain, and option A wrongly treats a price fall as certain."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 399, $official_bank_source${"itemId":"9567aced-fe00-5de0-bb30-22bf7637d097","questionId":"81e56c48-ce76-59f6-9f56-c15839847095","sourceKey":"bank:ECO201:MEQ-011","payload":{"prompt":"If demand increases while supply decreases, then","options":["equilibrium quantity rises, but the change in equilibrium price is indeterminate","equilibrium price falls, but the change in equilibrium quantity is indeterminate","equilibrium price and quantity both definitely rise","equilibrium price rises, but the change in equilibrium quantity is indeterminate"],"correctOption":3,"section":"Market Equilibrium","explanation":"Both changes push price up, so price certainly rises; but more demand raises quantity while less supply lowers it, so the quantity change depends on the relative sizes of the shifts. Option A swaps which variable is certain. Option C wrongly treats the quantity rise as certain, and option B has price moving the wrong way."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 400, $official_bank_source${"itemId":"3214fbef-2bd6-5657-a8d3-e8b1b9782bc0","questionId":"9ffe5dd4-3bfb-575b-a09e-616e9f4d1336","sourceKey":"bank:ECO201:MEQ-012","payload":{"prompt":"If demand decreases while supply increases, then","options":["equilibrium price and quantity both definitely fall","equilibrium price falls, but the change in equilibrium quantity is indeterminate","equilibrium price rises, but the change in equilibrium quantity is indeterminate","equilibrium quantity falls, but the change in equilibrium price is indeterminate"],"correctOption":1,"section":"Market Equilibrium","explanation":"Both changes push price down, so price certainly falls; but lower demand reduces quantity while higher supply raises it, so the net effect on quantity is uncertain. Option D swaps which variable is certain. Option A wrongly treats the quantity fall as certain, and option C has price moving the wrong way."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 401, $official_bank_source${"itemId":"2c66751a-65eb-53f1-aa1b-d827dfec0194","questionId":"12b76d6c-7c0f-5933-a1ae-8965e1e76e7b","sourceKey":"bank:ECO201:MEQ-013","payload":{"prompt":"Which combination of changes will DEFINITELY reduce the equilibrium quantity, whatever the sizes of the shifts?","options":["An increase in demand together with an increase in supply","An increase in demand together with a decrease in supply","A decrease in demand together with an increase in supply","A decrease in demand together with a decrease in supply"],"correctOption":3,"section":"Market Equilibrium","explanation":"When both demand and supply fall, each shift on its own lowers quantity, so quantity definitely falls, while the price change is uncertain. In options B and C the two shifts pull quantity in opposite directions, so the result depends on their sizes. Option A definitely raises quantity rather than reducing it."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 402, $official_bank_source${"itemId":"8cf8261d-54d7-5a43-b96b-033f216eb087","questionId":"34656446-775f-5e34-95b1-ef0f553de226","sourceKey":"bank:ECO201:MEQ-014","payload":{"prompt":"After a disaster, office space in a city was destroyed (supply fell), but many firms also moved away (demand fell). Rents actually fell. This shows that when demand and supply both fall,","options":["price must always fall","the change in price depends on which shift is larger","quantity must always rise","price must always rise"],"correctOption":1,"section":"Market Equilibrium","explanation":"With both curves shifting left, quantity definitely falls but price can go either way; here the demand fall was larger than the supply fall, so rents dropped. Options D and A wrongly treat the price change as certain in one direction. Option C is wrong because two leftward shifts both reduce quantity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 403, $official_bank_source${"itemId":"5c3d5b25-5e13-5bcb-8ed5-863050209b4f","questionId":"6ff43d6b-3bc7-5c20-a3ba-1f78c9f92da1","sourceKey":"bank:ECO201:MEQ-015","payload":{"prompt":"The simple supply-demand model of price determination assumes that the market is","options":["controlled by government price ceilings","an oligopoly in which a few firms agree on prices","roughly competitive, with buyers and sellers having little market power","a monopoly, with one seller setting the price"],"correctOption":2,"section":"Market Equilibrium","explanation":"The model works because each buyer and seller is a price taker, so price is set by the interaction of total demand and supply. Option D is excluded because a monopolist has no simple one-to-one relation between price and quantity supplied. Option A describes intervention, not a free market, and option B also involves market power."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 404, $official_bank_source${"itemId":"d8036f31-410f-50d7-b76a-a5e286788c8c","questionId":"a7e1c806-2857-5ba6-8b92-481c2e912454","sourceKey":"bank:ECO201:MEQ-016","payload":{"prompt":"When the government imposes a specific (per-unit) tax of N10 on sellers of a good, the supply curve","options":["shifts upward (to the left) by N10 at every quantity","does not move, but the demand curve shifts up by N10","becomes vertical at the old equilibrium quantity","shifts downward (to the right) by N10 at every quantity"],"correctOption":0,"section":"Market Equilibrium","explanation":"Sellers now need N10 more per unit to be willing to supply each quantity, so the supply curve moves up by exactly the tax at every quantity. Option D describes a per-unit subsidy. Option B is wrong for a tax collected from sellers, and option C has no basis."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 405, $official_bank_source${"itemId":"3f9aec6c-65fd-5788-97b0-fc47c69684af","questionId":"f3cf3a49-3669-5a54-ad80-87de0a122a50","sourceKey":"bank:ECO201:MEQ-017","payload":{"prompt":"With a normal downward-sloping demand curve and upward-sloping supply curve, a per-unit tax on sellers will usually cause the price paid by buyers to","options":["rise by exactly the amount of the tax, so buyers bear all of it","fall, because quantity sold falls","rise by less than the tax, so buyers and sellers share the burden","stay the same, so sellers bear all of the tax"],"correctOption":2,"section":"Market Equilibrium","explanation":"When neither curve is vertical or horizontal, the buyers' price rises by part of the tax and the sellers' net price falls by the rest, so the burden is shared. Option A happens only when demand is perfectly inelastic or supply perfectly elastic. Option D happens only when demand is perfectly elastic or supply perfectly inelastic, and option B has price moving the wrong way."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 406, $official_bank_source${"itemId":"b8b9acb8-cedf-5ac1-8a17-daa07e99419d","questionId":"a0b08217-4410-5aa7-b77f-9939bdc85b45","sourceKey":"bank:ECO201:MEQ-018","payload":{"prompt":"The burden (incidence) of a per-unit tax falls more heavily on buyers when","options":["supply is perfectly inelastic","demand is more elastic than supply","demand is more inelastic than supply","demand is perfectly elastic"],"correctOption":2,"section":"Market Equilibrium","explanation":"The side of the market that is less able to respond to price changes bears more of a tax, so when demand is relatively inelastic, buyers pay most of it through a higher price. Option B puts more of the burden on sellers. Options A and D are cases where sellers bear the whole tax."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 407, $official_bank_source${"itemId":"2a2b3ca4-0b81-5f0e-a8a0-647f341509cd","questionId":"dd292e9e-6be6-5812-90bd-1f32bae9372c","sourceKey":"bank:ECO201:MEQ-019","payload":{"prompt":"If the demand for a good is perfectly inelastic and a per-unit tax is placed on sellers, then","options":["buyers bear the whole tax, and the equilibrium quantity does not change","buyers and sellers share the tax equally, and quantity falls","sellers bear the whole tax, and the equilibrium quantity does not change","buyers bear the whole tax, and the equilibrium quantity falls sharply"],"correctOption":0,"section":"Market Equilibrium","explanation":"With a vertical demand curve, buyers keep buying the same quantity whatever the price, so price rises by the full tax and quantity stays the same. Option C is what happens when supply, not demand, is perfectly inelastic. Option B assumes equal slopes, and option D is wrong because a vertical demand fixes quantity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 408, $official_bank_source${"itemId":"e1f34904-7ffd-5724-b419-470e4d00babf","questionId":"1c54a8e9-30a4-5e3a-bace-1c845fee0585","sourceKey":"bank:ECO201:MEQ-020","payload":{"prompt":"A per-unit subsidy paid to producers of a good will, other things equal,","options":["shift the demand curve to the right, raising both price and quantity","shift the supply curve down (to the right), lowering the buyers' price and raising quantity","shift the supply curve up (to the left), raising the buyers' price and lowering quantity","leave price and quantity unchanged, since it only transfers money"],"correctOption":1,"section":"Market Equilibrium","explanation":"A subsidy lowers producers' effective cost per unit, so they will supply each quantity at a lower price; the supply curve moves down, buyers pay less and more is traded. Option C describes a per-unit tax. Option A confuses a producer subsidy with a demand change, and option D ignores the effect on supply."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 409, $official_bank_source${"itemId":"5638ca5b-cb7e-5674-90f4-21343de541ef","questionId":"ac31cea2-0086-53cd-b027-bfda47b91dce","sourceKey":"bank:ECO201:MEQ-021","payload":{"prompt":"In a market, Qd = 100 - 2P and Qs = 20 + 2P. The equilibrium price is","options":["N20","N30","N25","N40"],"correctOption":0,"section":"Market Equilibrium","explanation":"Setting Qd = Qs gives 100 - 2P = 20 + 2P, so 4P = 80 and P = N20 (and Q = 60). Option B adds the intercepts (120/4) instead of subtracting them. Option D divides 80 by 2 instead of by the combined slope of 4, and option C divides 100 by 4, ignoring the supply intercept."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 410, $official_bank_source${"itemId":"cf09c3cd-fc10-53b9-a415-a66ed068a240","questionId":"6e38328f-07b9-54a6-9432-6d29ccdb40a1","sourceKey":"bank:ECO201:MEQ-022","payload":{"prompt":"The market for a good has Qd = 240 - 4P and Qs = -60 + 6P. The equilibrium quantity is","options":["180 units","300 units","120 units","30 units"],"correctOption":2,"section":"Market Equilibrium","explanation":"Solving 240 - 4P = -60 + 6P gives 10P = 300, so P = 30, and then Q = 240 - 4(30) = 120 units (check: -60 + 180 = 120). Option D is the equilibrium price, not the quantity. Option A uses only 6 x 30 and ignores the supply intercept, and option B is the value of 10P, the step before dividing by 10."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 411, $official_bank_source${"itemId":"5deae68f-9be6-534f-89f7-4f630e150264","questionId":"3e8aa570-4f78-510f-a8c4-694bedb73c81","sourceKey":"bank:ECO201:MEQ-024","payload":{"prompt":"For a good, Qd = 500 - 10P and Qs = -100 + 20P (equilibrium price N20). If the price is N25, the market has","options":["a surplus (excess supply) of 150 units","a surplus (excess supply) of 50 units","a shortage (excess demand) of 150 units","a surplus (excess supply) of 250 units"],"correctOption":0,"section":"Market Equilibrium","explanation":"At P = 25, Qd = 500 - 250 = 250 and Qs = -100 + 500 = 400, so sellers offer 150 more than buyers want, a surplus. Option C gets the type wrong, since price is above equilibrium. Option D reports quantity demanded instead of the gap, and option B simply multiplies the 5-naira price gap by 10."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 412, $official_bank_source${"itemId":"bbd1710f-5150-5afa-b940-849c7f6d33d1","questionId":"0604511c-ec69-56ea-8cd7-1ac87ff0e146","sourceKey":"bank:ECO201:MEQ-025","payload":{"prompt":"With Qd = 240 - 4P and Qs = -60 + 6P, how large is the excess demand when the price is held at N15?","options":["180 units","150 units","30 units","210 units"],"correctOption":1,"section":"Market Equilibrium","explanation":"At P = 15, Qd = 240 - 60 = 180 and Qs = -60 + 90 = 30, so excess demand is 180 - 30 = 150 units. Option A is quantity demanded alone and option C is quantity supplied alone. Option D adds the two quantities instead of subtracting them."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 413, $official_bank_source${"itemId":"39e267ca-5b62-53b6-ae7b-7fec4b6afcd1","questionId":"8c2ebfe7-51d3-5ae0-9285-b10049cd7aa9","sourceKey":"bank:ECO201:MEQ-026","payload":{"prompt":"The market for wheat in a year has supply QS = 1800 + 240P and demand QD = 3550 - 266P (quantities in millions of bushels, P in dollars per bushel). The equilibrium price, to two decimal places, is","options":["$7.29","$6.58","$3.46","$10.57"],"correctOption":2,"section":"Market Equilibrium","explanation":"Setting supply equal to demand gives 1800 + 240P = 3550 - 266P, so 506P = 1750 and P = $3.46. Option B divides 1750 by the demand slope only and option A by the supply slope only. Option D adds the two intercepts instead of subtracting them."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 414, $official_bank_source${"itemId":"32c4622a-9e92-5a03-a9ea-cf346b27d791","questionId":"7ac9eedc-2cca-5f47-bf80-de10e3f62626","sourceKey":"bank:ECO201:MEQ-027","payload":{"prompt":"In a later year the wheat market has demand QD = 2900 - 125P and supply QS = 1460 + 115P (millions of bushels, P in dollars). The equilibrium quantity is","options":["6 million bushels","2,150 million bushels","2,900 million bushels","2,210 million bushels"],"correctOption":1,"section":"Market Equilibrium","explanation":"Solving 1460 + 115P = 2900 - 125P gives 240P = 1440, so P = $6, and Q = 1460 + 115(6) = 2,150 million bushels. Option C is the demand intercept, the quantity at a zero price. Option A is the equilibrium price, and option D comes from wrongly using 125 instead of 115 when substituting into supply."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 415, $official_bank_source${"itemId":"9b33df6c-87da-5547-a424-1c9276feaa9a","questionId":"02cd0e0d-95e2-574c-b210-fb22c38b0418","sourceKey":"bank:ECO201:MEQ-028","payload":{"prompt":"A market starts with Qd = 100 - 2P and Qs = 20 + 2P, so P = N20 and Q = 60. Higher incomes shift demand to Qd = 120 - 2P. The new equilibrium is","options":["P = N25 and Q = 70","P = N30 and Q = 60","P = N25 and Q = 80","P = N20 and Q = 80"],"correctOption":0,"section":"Market Equilibrium","explanation":"Solving 120 - 2P = 20 + 2P gives 4P = 100, so P = 25, and Q = 20 + 2(25) = 70; price and quantity both rise, as expected for an increase in demand. Option D keeps the old price, which would leave a shortage. Option B keeps the old quantity, and option C gets the price right but substitutes it wrongly."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 416, $official_bank_source${"itemId":"53453476-56ec-5209-8ef9-cacade20dd4b","questionId":"1dd771f9-a911-57a0-a84c-041bf80768c2","sourceKey":"bank:ECO201:MEQ-029","payload":{"prompt":"A market has Qd = 100 - 2P and Qs = 20 + 2P. A rise in input costs changes supply to Qs = 2P. The new equilibrium price and quantity are","options":["P = N50 and Q = 0","P = N15 and Q = 70","P = N20 and Q = 40","P = N25 and Q = 50"],"correctOption":3,"section":"Market Equilibrium","explanation":"With Qs = 2P, setting 100 - 2P = 2P gives P = 25 and Q = 50, so price rises and quantity falls, as expected when supply decreases. Option B is what a supply increase would give. Option C keeps the old price, which would leave a shortage, and option A is the price at which nothing would be demanded."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 417, $official_bank_source${"itemId":"3920ed35-fbb9-5a12-8fff-1bb5abe1a290","questionId":"6a2ba678-aad6-58e6-b840-2025281ead45","sourceKey":"bank:ECO201:MEQ-030","payload":{"prompt":"A market starts with Qd = 100 - 2P and Qs = 20 + 2P (P = N20, Q = 60). Demand then shifts to Qd = 130 - 2P and supply to Qs = 50 + 2P. The new equilibrium is","options":["P = N20 and Q = 60","P = N27.50 and Q = 75","P = N12.50 and Q = 75","P = N20 and Q = 90"],"correctOption":3,"section":"Market Equilibrium","explanation":"Solving 130 - 2P = 50 + 2P gives 4P = 80, so P = 20, and Q = 50 + 40 = 90: quantity rises while price is unchanged because both curves shifted out by the same 30 units. Option B is the result of the demand shift alone, and option C the supply shift alone. Option A wrongly assumes nothing changes."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 418, $official_bank_source${"itemId":"f4998a1b-fbb0-53ef-8578-c754f6b801ca","questionId":"c3695981-ba28-58e4-9de0-b1e0eee9431e","sourceKey":"bank:ECO201:MEQ-031","payload":{"prompt":"In a market, Qd = a - 3P and Qs = 10 + 2P. If the equilibrium price is N8, the value of a is","options":["50","34","26","24"],"correctOption":0,"section":"Market Equilibrium","explanation":"At P = 8 the quantity supplied is 10 + 2(8) = 26, and in equilibrium demand must equal 26, so a - 3(8) = 26 and a = 26 + 24 = 50. Option C is the equilibrium quantity, not the intercept. Option B adds only 8 instead of 3 x 8, and option D is just the slope term 3 x 8."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 419, $official_bank_source${"itemId":"3c8be20a-edeb-54ce-b443-c5ee55890209","questionId":"2026495c-8b4d-51ce-8c25-64a24e921727","sourceKey":"bank:ECO201:MEQ-032","payload":{"prompt":"A market has inverse demand P = 40 - 0.5Q and inverse supply P = 10 + Q. The equilibrium price and quantity are","options":["P = N25 and Q = 15","P = N20 and Q = 30","P = N30 and Q = 20","P = N30 and Q = 60"],"correctOption":2,"section":"Market Equilibrium","explanation":"Setting 40 - 0.5Q = 10 + Q gives 1.5Q = 30, so Q = 20, and P = 10 + 20 = 30. Option B swaps price and quantity. Option A divides 30 by 2 instead of 1.5, and option D divides 30 by 0.5, ignoring the supply slope."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 420, $official_bank_source${"itemId":"a9c63097-720f-5c08-8527-5c28620220da","questionId":"90f51f77-0c2c-54bb-b8bb-bf1fea53738d","sourceKey":"bank:ECO201:MEQ-033","payload":{"prompt":"Demand is Qd = 60 - 3P + 0.5I, where I is an income index, and supply is Qs = 4P. When I = 20, the equilibrium price and quantity are","options":["P = N11.43 and Q = 45.7","P = N8.57 and Q = 34.3","P = N10 and Q = 40","P = N14 and Q = 56"],"correctOption":2,"section":"Market Equilibrium","explanation":"With I = 20, demand becomes Qd = 60 - 3P + 10 = 70 - 3P; setting 70 - 3P = 4P gives 7P = 70, so P = 10 and Q = 40. Option B leaves out the income term (60/7). Option A adds the full value of I (20) instead of 0.5I, and option D divides 70 by 5 using a wrong slope."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 421, $official_bank_source${"itemId":"6d70edef-3f01-5e21-9538-2d38d68b5c33","questionId":"f4a9d5a2-da0b-5c35-aa64-16c0d32c0a45","sourceKey":"bank:ECO201:MEQ-034","payload":{"prompt":"Demand for a life-saving drug is fixed at Qd = 100 units whatever the price, and supply is Qs = -20 + 4P, so the equilibrium price is N30. A per-unit tax of N5 is imposed on sellers. The new price paid by buyers is","options":["N35","N25","N30","N32.50"],"correctOption":0,"section":"Market Equilibrium","explanation":"The tax shifts supply to Qs = -20 + 4(P - 5); setting this equal to 100 gives 4P = 140, so P = N35 and buyers pay the whole N5 because demand is perfectly inelastic. Option C assumes sellers absorb the tax. Option D assumes the tax is split equally, and option B subtracts the tax instead of adding it."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 422, $official_bank_source${"itemId":"5504baed-7ad3-5707-b03c-f26b4f225d34","questionId":"e8688e1a-7c39-513f-9044-abec4aac9c84","sourceKey":"bank:ECO201:MEQ-035","payload":{"prompt":"In a market, Qd = 100 - 2P and Qs = 20 + 2P (equilibrium P = N20, Q = 60). A per-unit tax of N6 is imposed on sellers, so supply becomes Qs = 20 + 2(P - 6). The new price paid by buyers is","options":["N20","N17","N26","N23"],"correctOption":3,"section":"Market Equilibrium","explanation":"Setting 100 - 2P = 20 + 2(P - 6) gives 100 - 2P = 8 + 2P, so 4P = 92 and buyers pay N23; sellers keep 23 - 6 = N17 and the equal slopes split the tax N3 each. Option C assumes buyers pay the whole tax. Option A ignores the tax, and option B is the sellers' net price, not the buyers' price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 423, $official_bank_source${"itemId":"438ac834-1ec3-5ff4-ac3a-0ab82f092d59","questionId":"8ee19f54-e718-51ef-a089-553bf7e3d005","sourceKey":"bank:ECO201:MEQ-036","payload":{"prompt":"A market has Qd = 120 - 2P and Qs = -30 + 3P, so the equilibrium price is N30. A per-unit tax of N5 is placed on sellers. After the tax, the net price received by sellers is","options":["N28","N33","N30","N25"],"correctOption":0,"section":"Market Equilibrium","explanation":"With the tax, -30 + 3(P - 5) = 120 - 2P gives 5P = 165, so buyers pay N33 and sellers keep 33 - 5 = N28; buyers bear N3 and sellers N2 of the tax because demand is steeper relative to supply here. Option B is the buyers' price. Option D assumes sellers bear the whole tax, and option C ignores the tax."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 424, $official_bank_source${"itemId":"de58c62e-90ea-5e89-87b5-71e03fc6629b","questionId":"49d16703-428f-5bb8-879c-630ea0f75de4","sourceKey":"bank:ECO201:MEQ-037","payload":{"prompt":"In a market with Qd = 120 - 2P and Qs = -30 + 3P, a per-unit tax of N5 on sellers raises the buyers' price to N33. What is the total tax revenue collected by the government?","options":["N165","N270","N300","N1,782"],"correctOption":1,"section":"Market Equilibrium","explanation":"After the tax, quantity is Qd = 120 - 2(33) = 54 units, so revenue = tax per unit x quantity = 5 x 54 = N270. Option C uses the old quantity of 60. Option A multiplies the buyers' price by 5, and option D is buyers' spending (33 x 54), not tax revenue."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 425, $official_bank_source${"itemId":"ebb87255-b9e3-5d2f-8004-1ede2f748418","questionId":"1c92d97d-166f-552f-b61e-0345b918356f","sourceKey":"bank:ECO201:MEQ-038","payload":{"prompt":"A market has Qd = 120 - 2P and Qs = -30 + 3P (equilibrium P = N30). The government pays producers a subsidy of N5 per unit, so supply becomes Qs = -30 + 3(P + 5). The new price paid by buyers is","options":["N30","N27","N32","N25"],"correctOption":1,"section":"Market Equilibrium","explanation":"Setting 120 - 2P = -30 + 3(P + 5) gives 120 - 2P = -15 + 3P, so 5P = 135 and buyers pay N27, while sellers receive 27 + 5 = N32. Option D assumes buyers get the whole subsidy. Option C is the sellers' price including the subsidy, and option A ignores the subsidy."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 426, $official_bank_source${"itemId":"6c7161a4-6eea-5e02-a82d-c090b14ad10e","questionId":"2535654a-08a6-511d-9884-8ab18406b220","sourceKey":"bank:ECO201:MEQ-039","payload":{"prompt":"In a market with Qd = 120 - 2P and Qs = -30 + 3P, a producer subsidy of N5 per unit lowers the buyers' price to N27. What is the total cost of the subsidy to the government?","options":["N1,782","N135","N300","N330"],"correctOption":3,"section":"Market Equilibrium","explanation":"After the subsidy, quantity is 120 - 2(27) = 66 units, so the cost = subsidy per unit x quantity = 5 x 66 = N330. Option C uses the old quantity of 60. Option B multiplies the buyers' price by 5, and option A is buyers' spending (27 x 66), not the subsidy bill."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 427, $official_bank_source${"itemId":"63f384af-0a2f-585d-bab3-367bf6663fb1","questionId":"b78489a9-400a-5050-95a2-f25999da4d92","sourceKey":"bank:ECO201:MEQ-040","payload":{"prompt":"Copper supply is Q = -9 + 9P and, after a fall in demand, copper demand is Q = 12.15 - 1.35P (Q in million metric tons, P in dollars per pound). The new equilibrium price, to two decimal places, is","options":["$0.30","$3.00","$2.04","$2.35"],"correctOption":2,"section":"Market Equilibrium","explanation":"Setting -9 + 9P = 12.15 - 1.35P gives 10.35P = 21.15, so P = $2.04. Option B was the price before demand fell. Option A subtracts 9 from 12.15 instead of adding it, and option D divides 21.15 by the supply slope of 9 alone."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 428, $official_bank_source${"itemId":"1d10c9a3-6a7b-58ba-849c-21e9cffd916b","questionId":"5e54f25c-d57f-5898-adee-e4545f6bf7a2","sourceKey":"bank:ECO201:MEQ-023","payload":{"prompt":"In a market with Qd = 100 - 2P and Qs = 20 + 2P, the government fixes the price at N10. At this price there is","options":["a surplus (excess supply) of 40 units","a surplus (excess supply) of 20 units","a shortage (excess demand) of 80 units","a shortage (excess demand) of 40 units"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"At P = 10, Qd = 100 - 20 = 80 and Qs = 20 + 20 = 40, so buyers want 40 more units than are offered, a shortage of 40. Option A gets the size right but the type wrong, since price is below equilibrium. Option C reports quantity demanded instead of the gap, and option B has neither the type nor the size right."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 429, $official_bank_source${"itemId":"e9732d89-c746-5497-b9de-a22f12b78ecc","questionId":"301d992e-96bc-5ae1-b142-cb1042b25fc8","sourceKey":"bank:ECO201:MEQ-041","payload":{"prompt":"Natural-gas supply is Q = 15.90 + 0.72PG + 0.05PO and demand is Q = 0.02 - 1.8PG + 0.69PO, where PG is the gas price and PO = $50 is the oil price. If PG is held at a ceiling of $3.00, excess demand is approximately","options":["About 20.56 Tcf","About 8.56 Tcf","About 29.12 Tcf","About 11.06 Tcf"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"At PG = 3 and PO = 50, quantity supplied is 15.90 + 2.16 + 2.50 = 20.56 Tcf and quantity demanded is 0.02 - 5.40 + 34.50 = 29.12 Tcf, so excess demand is 29.12 - 20.56 = 8.56 Tcf. Options A and C are quantity supplied and quantity demanded on their own, not the gap. Option D leaves out the oil-price term in the supply equation."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 430, $official_bank_source${"itemId":"e574a345-2ff2-552b-975e-a7a44cd306a9","questionId":"fb27a128-b8bc-5cc9-ae4c-206de12b7a5f","sourceKey":"bank:ECO201:E201-0068","payload":{"prompt":"If government imposes a rent ceiling below equilibrium rent, it will lead to: ______.","options":["Surplus of housing","Shortage of housing","No change in market","Increase in supply"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"A rent ceiling below equilibrium holds rent at a level where more people want housing than landlords are willing to supply. Quantity demanded rises while quantity supplied falls, creating a shortage of housing. Option A, a surplus, happens with a price floor above equilibrium, and option D is wrong because a lower rent reduces landlords' willingness to supply."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 431, $official_bank_source${"itemId":"96192b4d-4b07-5f54-bd02-57f48aabc167","questionId":"9cae16cf-17a5-5ac1-a33d-034f63f55752","sourceKey":"bank:ECO201:E201-0078","payload":{"prompt":"When rent is artificially lowered below equilibrium, quantity demanded of hostel accommodation will: ______.","options":["Decrease","Increase","Remain unchanged","Become zero"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"When rent is held below equilibrium, accommodation becomes cheaper, so by the law of demand more students want hostel space and quantity demanded increases. At the same time landlords supply less, which creates a shortage. Option A describes what happens to quantity supplied, not quantity demanded."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 432, $official_bank_source${"itemId":"11d80e12-4b6c-5092-b7eb-01b4df003497","questionId":"d158105f-2e96-517a-8233-090425d15696","sourceKey":"bank:ECO201:E201-0088","payload":{"prompt":"If the Lagos State Government were to impose rent control on students' housing around university vicinities, landlords are likely to: ______.","options":["Increase supply","Maintain supply","Reduce supply","Double supply"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"Rent control holds rent below the market level, so renting out rooms becomes less profitable and landlords offer fewer rooms or convert them to other uses. Quantity supplied therefore falls, which worsens the housing shortage. Options A and D are wrong because a lower controlled rent gives landlords less reason to supply more, and option B ignores how supply responds to price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 433, $official_bank_source${"itemId":"60e65d99-14ca-5d5f-85a1-acfd381c4b0e","questionId":"0066f557-1c14-5f0f-8c8f-4f39c0b2a22d","sourceKey":"bank:ECO201:E201-0468","payload":{"prompt":"The government fixes the prices of beef and chicken below their market-clearing levels, creating shortages. What will happen to the price of pork, a substitute that is not regulated?","options":["It will fall, because pork producers move into beef and chicken production","It will rise, because consumers who cannot buy enough beef and chicken increase their demand for pork","It will not change, because pork is not regulated","It will fall, because the price controls lower meat prices generally"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"With ceilings below equilibrium, quantity demanded of beef and chicken exceeds quantity supplied, and the size of each shortage depends on how far the ceiling is below equilibrium and on the elasticities of demand and supply. Consumers who are rationed out switch to pork, a substitute, so the demand for pork shifts right and its price rises. Option C is wrong because a change in the market for substitutes shifts pork demand even though pork itself is not controlled."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 434, $official_bank_source${"itemId":"75d58c29-e69f-587c-b5b6-50026cfe1e7f","questionId":"fed25f33-80ac-5f08-87d5-e05dd66b957a","sourceKey":"bank:ECO201:E201-0469","payload":{"prompt":"Market rents for two-bedroom apartments in a college town are $700 per month and are expected to rise to $900 within a year. The city council caps rents at $700. Will this policy benefit all students?","options":["No; every student must now pay more than the market rent","Yes; every student pays less rent than the market rate","Yes; the cap increases the number of apartments available","No; students who obtain apartments at $700 gain, but others cannot find apartments because the cap creates a shortage"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"Once demand rises so that the market rent would be $900, the $700 cap acts as a price ceiling below equilibrium, so quantity demanded exceeds quantity supplied. Students who secure an apartment pay less and gain, but those left out are worse off. Option B ignores the shortage, and option C is wrong because a lower rent reduces, not increases, the quantity of apartments landlords supply."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 435, $official_bank_source${"itemId":"fc5ed58a-631a-5327-bae2-036f0b547047","questionId":"58c2cf31-2f05-5172-a292-8537c3391e33","sourceKey":"bank:ECO201:E201-0473","payload":{"prompt":"Suppose the demand for natural gas is perfectly inelastic. If the government sets a ceiling on the price of natural gas below the market-clearing price, what is the effect?","options":["Quantity demanded is unchanged, quantity supplied falls, and the shortage equals the fall in quantity supplied","Quantity demanded falls and the market ends up in surplus","Quantity demanded rises and quantity supplied falls, so the shortage is larger than with normal demand","There is no effect, because buyers do not respond to price"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"With perfectly inelastic (vertical) demand, buyers want the same quantity whatever the price, so the ceiling does not change quantity demanded. Producers, however, supply less at the lower price, so the shortage is exactly the cut in quantity supplied. Option C is wrong because quantity demanded cannot rise when demand is perfectly inelastic, and option D ignores the response of sellers."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 436, $official_bank_source${"itemId":"0efe6d82-abf0-5df7-9e7a-d6b8d9924e27","questionId":"e764474d-12c8-5d7e-8154-da3568bd1d74","sourceKey":"bank:ECO201:E201-0475-b","payload":{"prompt":"In a competitive market, the quantities demanded and supplied (millions per year) are: at $60, demand 22 and supply 14; at $80, demand 20 and supply 16; at $100, demand 18 and supply 18; at $120, demand 16 and supply 20. If the government sets a price ceiling of $80, will there be a shortage, and how large?","options":["Yes, a shortage of 2 million units","Yes, a shortage of 6 million units","Yes, a shortage of 4 million units","No, there will be no shortage"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"Equilibrium is at $100, where 18 million are demanded and supplied, so a $80 ceiling is binding. At $80, quantity demanded is 20 million but quantity supplied is only 16 million, giving a shortage of 20 - 16 = 4 million. Option A compares demand at $80 with the old equilibrium quantity, and option D wrongly treats the ceiling as non-binding."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 437, $official_bank_source${"itemId":"b74dc843-bcf4-58bc-8e39-7976dc77321a","questionId":"86e54aa0-cf65-5724-bd1c-e9f16992062f","sourceKey":"bank:ECO201:E201-0478-b","payload":{"prompt":"Total demand for U.S. wheat is Q = 3244 - 283P, of which domestic demand is QD = 1700 - 107P; domestic supply is QS = 1944 + 207P (Q in million bushels, P in dollars per bushel). Export demand then falls by 40 percent at every price. How much wheat must the government buy to raise the price to $3.50 per bushel, and what will this cost?","options":["About 786 million bushels, costing about $2.75 billion","About 415 million bushels, costing about $1.45 billion","About 786 million bushels, costing about $1.28 billion","About 2669 million bushels, costing about $9.34 billion"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"After the drop, demand is 2626.4 - 212.6P. At $3.50, supply is 1944 + 207(3.5) = 2668.5 and private demand is 2626.4 - 212.6(3.5) = 1882.3, so the government must buy 2668.5 - 1882.3 = about 786 million bushels at $3.50, costing about $2.75 billion. Option B uses the demand before export demand fell, and option C values the purchase at the free-market price of $1.63 instead of $3.50."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 438, $official_bank_source${"itemId":"5b2e55b2-5892-51da-9b6a-f62fd208caf9","questionId":"235742b0-8e7a-55b9-8857-f586477433a8","sourceKey":"bank:ECO201:E201-0484","payload":{"prompt":"The natural gas market (Q in trillion cubic feet, Tcf) has supply Q = 15.90 + 0.72PG + 0.05PO and demand Q = 0.02 - 1.8PG + 0.69PO, where PG is the price of gas ($ per thousand cubic feet) and PO is the price of oil ($ per barrel). With PO = $50, how much excess demand would there be if the price of gas were regulated at $4.50?","options":["About 26.42 Tcf","About 4.78 Tcf","Zero, because $4.50 is above the free-market price","About 8.56 Tcf"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"With PO = 50, supply is 18.40 + 0.72PG and demand is 34.52 - 1.8PG (free-market PG = 16.12/2.52 = about $6.40). At $4.50, supply is 18.40 + 3.24 = 21.64 and demand is 34.52 - 8.10 = 26.42, so excess demand is 26.42 - 21.64 = 4.78 Tcf. Option D is the excess demand at a regulated price of $3.00, and option C is wrong because $4.50 is below the free-market price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 439, $official_bank_source${"itemId":"6a8fdfe1-f048-5d8e-8d6c-e07f39e3e869","questionId":"b977419a-4ffe-59be-846e-9002f0006eb7","sourceKey":"bank:ECO201:MDG-001","payload":{"prompt":"In economics, the model that explains recurring fluctuations of price and output in markets where producers decide current output on the basis of the previous period's price is called the","options":["cobweb model","accelerator model","kinked demand curve model","multiplier model"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"The cobweb model shows how a lag between the production decision and the sale of output can make price and quantity swing around equilibrium, tracing a cobweb-like pattern on the supply and demand diagram. Option B and option D are macroeconomic models of investment and income, while option C explains price rigidity in oligopoly."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 440, $official_bank_source${"itemId":"94b15fbd-1bd4-5583-9119-c7b849071044","questionId":"ef8377e2-801a-5bd1-9f0c-825b99c77dea","sourceKey":"bank:ECO201:MDG-002","payload":{"prompt":"In the basic cobweb model, the quantity supplied in period t depends on the","options":["price in period t","price in period t-1","price expected in period t+1 under perfect foresight","quantity demanded in period t-1"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"Producers in the cobweb model base this period's output on last period's price, because output must be planned before the current price is known. Option A is what determines quantity demanded, not quantity supplied, and option C contradicts the model, which assumes producers simply expect last period's price to continue."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 441, $official_bank_source${"itemId":"6c53e2e5-065d-505c-9eba-65f46d7c2f93","questionId":"0a0f8fe8-1dce-5702-9d13-221c038a02d9","sourceKey":"bank:ECO201:MDG-003","payload":{"prompt":"The main reason the cobweb model uses a lagged supply function is that","options":["production takes time, so output must be decided before the selling price is known","consumers respond to price changes only after a delay","government fixes the price at the start of every season","producers hold large stocks that they release slowly"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"In many agricultural markets there is a gestation period between planting and harvest, so the amount offered for sale this season was fixed by decisions made earlier at an earlier price. Option B is wrong because demand responds to the current price in the model, and option D is wrong because the model assumes output is perishable and sold in the period it is produced."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 442, $official_bank_source${"itemId":"db7f75f9-0921-5573-8b6e-03ae7bc322cb","questionId":"07d5ea1a-fb78-5b70-b644-05bc445cdfb1","sourceKey":"bank:ECO201:MDG-004","payload":{"prompt":"Tomato prices were very high in one season, so many farmers in Kano planted more tomatoes. The next season there was a glut and prices crashed, so farmers planted less, and prices rose sharply again the season after. This pattern is best explained by the","options":["law of diminishing marginal utility","backward-bending supply curve","theory of price ceilings","cobweb model"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"The alternating high and low prices come from farmers reacting to last season's price, which is exactly the lagged-supply mechanism of the cobweb model. Option C involves a government-imposed maximum price, which is absent here, and option B relates to labour supply at high wages, not crop cycles."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 443, $official_bank_source${"itemId":"5a7a9a15-72f1-5786-93d4-e71d555e5c8d","questionId":"d389a635-7a6c-532f-b506-2fe68b36d5d7","sourceKey":"bank:ECO201:MDG-005","payload":{"prompt":"In the cobweb model, with price on the vertical axis and quantity on the horizontal axis, the fluctuations in price and output become smaller each period (convergent cobweb) when","options":["the supply curve is flatter than the demand curve","the demand curve slopes upward","the supply curve is steeper than the demand curve","the supply and demand curves have the same absolute slope"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"When supply is steeper than demand, producers respond only weakly to last period's price, so each overshoot is smaller than the one before and price converges to equilibrium. Option A gives an explosive (divergent) cobweb, and option D gives a continuous oscillation of constant size."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 444, $official_bank_source${"itemId":"1919b6ee-4a76-5bd1-9884-5c427bb1e001","questionId":"4ae3063e-7d4d-5a60-a1a2-7899309d795c","sourceKey":"bank:ECO201:MDG-006","payload":{"prompt":"In the cobweb model, the oscillations of price and output become larger and larger (divergent or explosive cobweb) when, at equilibrium,","options":["supply and demand are equally elastic (in absolute value)","supply is more elastic than demand (in absolute value)","demand is more elastic than supply (in absolute value)","demand is perfectly elastic and supply is perfectly inelastic"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"If supply is more responsive than demand, a small price change triggers a large output response, which then needs an even bigger price change to clear the market, so the swings grow. Option C is the condition for a convergent cobweb, and option A is the condition for a continuous (constant-amplitude) cobweb."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 445, $official_bank_source${"itemId":"ab54a255-0358-5af8-8434-c467dff39a3d","questionId":"8993bc6e-ec55-5681-9733-1910b8dc309e","sourceKey":"bank:ECO201:MDG-007","payload":{"prompt":"In the cobweb model, price and output oscillate around equilibrium with a constant amplitude, neither growing nor dying out, when","options":["the supply and demand curves have equal slopes in absolute value","the supply curve is steeper than the demand curve","the demand curve is perfectly elastic","the supply curve is flatter than the demand curve"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"With equal absolute slopes, every overshoot is exactly as large as the previous one, so the cycle repeats forever around equilibrium. Option B gives a convergent (damped) cobweb, while option D gives a divergent (explosive) one."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 446, $official_bank_source${"itemId":"ece12124-63db-5329-b375-fd11953ac0e7","questionId":"1bb3da29-5ac7-567f-80a4-71ad38786382","sourceKey":"bank:ECO201:MDG-008","payload":{"prompt":"In the cobweb model, a situation in which price and output move further away from equilibrium in each successive period is described as","options":["a continuous (constant) cobweb","a stable equilibrium","a divergent (explosive) cobweb","a convergent (damped) cobweb"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"A divergent cobweb is one where the deviations from equilibrium grow each period, so the market never settles. Option D describes deviations that shrink over time, option A describes deviations of constant size, and option B is the opposite of what is happening."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 447, $official_bank_source${"itemId":"2ba04969-70cb-5744-b3d6-2005f73c5074","questionId":"4d47e2a7-d995-5633-aede-f81feccf1317","sourceKey":"bank:ECO201:MDG-009","payload":{"prompt":"In the cobweb model with demand Qd(t) = a - bP(t) and supply Qs(t) = c + dP(t-1), where a, b, c and d are positive constants, the price path converges to equilibrium if","options":["c < a","d < b","d > b","d = b"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"Each period's price deviation equals -(d/b) times the previous one, so deviations shrink only when d/b is less than 1, that is d < b. Option C makes the deviations grow (divergent), option D makes them constant (continuous oscillation), and option A only ensures a positive equilibrium, not stability."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 448, $official_bank_source${"itemId":"ad5c954f-995b-5d11-b9cd-90aa92d38315","questionId":"f67aff64-ffd7-5e0e-8dbb-7cc78d268b26","sourceKey":"bank:ECO201:MDG-010","payload":{"prompt":"In a cobweb market, demand is Qd(t) = 100 - 2P(t) and supply is Qs(t) = 10 + P(t-1), with P in naira. The long-run equilibrium price, where P(t) = P(t-1), is","options":["N36.67","N90","N30","N33.33"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"At equilibrium the price is the same in every period, so 100 - 2P = 10 + P, giving 3P = 90 and P = N30. Option B comes from dividing 90 by (2 - 1) instead of (2 + 1), and option A comes from adding 10 to 100 instead of subtracting it."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 449, $official_bank_source${"itemId":"36ec44c2-a434-56d2-974d-edeb81a70c92","questionId":"4b58b9b2-9797-5948-b7d6-44d8cebf8266","sourceKey":"bank:ECO201:MDG-011","payload":{"prompt":"In a cobweb market, demand is Qd(t) = 100 - 2P(t) and supply is Qs(t) = 10 + P(t-1). If the price in period 0 is N36, what is the market-clearing price in period 1?","options":["N18","N46","N27","N54"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"Farmers supply 10 + 36 = 46 units in period 1, and price must fall until buyers take all 46 units: 100 - 2P = 46, so P = 54/2 = N27. Option B is the quantity supplied, not the price, and option D forgets to divide by 2."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 450, $official_bank_source${"itemId":"76b2ed96-bdf5-5175-adfb-7e5173618cf3","questionId":"0345aefb-6b9e-5640-8446-a6095ba5ac1a","sourceKey":"bank:ECO201:MDG-012","payload":{"prompt":"In a cobweb market, demand is Qd(t) = 100 - 2P(t) and supply is Qs(t) = 10 + P(t-1). The price in period 0 is N36 and the price in period 1 is N27. What is the market-clearing price in period 2?","options":["N27","N36","N31.50","N37"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"In period 2 farmers supply 10 + 27 = 37 units, and buyers absorb them when 100 - 2P = 37, so P = 63/2 = N31.50. Option D is the quantity supplied rather than the price, and option A simply repeats the period 1 price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 451, $official_bank_source${"itemId":"36c23678-1f7e-5081-ac42-739b4faf3ec8","questionId":"1dc0ba50-f178-51ed-b8f9-00b4dc621450","sourceKey":"bank:ECO201:MDG-013","payload":{"prompt":"In a cobweb market, demand is Qd(t) = 60 - P(t) and supply is Qs(t) = 2P(t-1). Starting away from equilibrium, the price path will be","options":["a smooth movement to equilibrium without any oscillation","divergent, because supply responds more strongly to price than demand does","a continuous oscillation, because both curves have the same slope","convergent, because demand responds more strongly to price than supply does"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"Here d = 2 and b = 1, so each price deviation is -(2/1) = -2 times the previous one, and the swings double in size every period. Option D would need d < b, option C would need d = b, and option A never happens in the cobweb because the factor -(d/b) is negative, so price always alternates above and below equilibrium."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 452, $official_bank_source${"itemId":"f236a04e-5416-5a7e-96c6-3a52eeccfd4b","questionId":"1685816f-f792-5e88-939f-3191e4e94a21","sourceKey":"bank:ECO201:MDG-014","payload":{"prompt":"In a cobweb market, demand is Qd(t) = 90 - 3P(t) and supply is Qs(t) = 3P(t-1) - 30. The equilibrium price is N20. If the market starts at a price different from N20, price will","options":["oscillate around N20 with a constant amplitude","stay at the starting price forever","converge gradually to N20","move further and further away from N20"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"Demand and supply have the same price coefficient (3), so the ratio d/b equals 1 and each deviation is exactly reversed in the next period, giving a continuous cycle of constant size. Option C would require d < b and option D would require d > b."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 453, $official_bank_source${"itemId":"7687a1a8-0e35-5ac0-b5d6-ad85282f1efc","questionId":"49fd5821-ccf1-524b-94a9-6f78f17d2ef7","sourceKey":"bank:ECO201:MDG-015","payload":{"prompt":"Which of the following markets is most likely to show cobweb-type price fluctuations?","options":["Electricity sold at a tariff fixed by a regulator","Recharge cards, whose supply can be increased within hours","Bread from a bakery that adjusts output every morning","Yam, where planting decisions are made many months before harvest"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"Cobweb cycles need a production lag, which is typical of crops and livestock like yam, where output is fixed long before the selling price is known. Options B and C can adjust supply almost immediately to current price, and option A has a regulated price that does not respond to market conditions."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 454, $official_bank_source${"itemId":"82b7eca8-2539-5aef-84ed-b1541260226a","questionId":"0a8bf4b4-37b1-5594-869b-c66577a3dff1","sourceKey":"bank:ECO201:MDG-016","payload":{"prompt":"Which of the following is NOT an assumption of the basic cobweb model?","options":["Output produced in a period is sold in that period at whatever price clears the market","Quantity demanded depends on the current period's price","Quantity supplied depends on the previous period's price","Producers correctly forecast next period's market price"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"The cobweb model assumes producers naively expect last period's price to continue, so they do not correctly forecast the next price; that is why they keep overshooting. Options C, B and A are genuine assumptions of the model: lagged supply, current-price demand and no storage of output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 455, $official_bank_source${"itemId":"f0b4e8ce-eff8-5649-bcc8-6f531388bc11","questionId":"9d008233-d596-54de-84fd-f50526705fd7","sourceKey":"bank:ECO201:MDG-017","payload":{"prompt":"A legal maximum price, set by government below the market-clearing price, is called a","options":["price floor","price ceiling","equilibrium price","support price"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"A price ceiling is the highest price sellers are legally allowed to charge, and it only has an effect when it is set below equilibrium. Option A and option D are minimum prices set above equilibrium, while option C is the market-clearing price itself."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 456, $official_bank_source${"itemId":"4037f54c-1e89-5260-abe0-c49d5b0fb6b7","questionId":"1960234c-9f0a-5a2f-8819-92d3e92b5c0a","sourceKey":"bank:ECO201:MDG-018","payload":{"prompt":"When government imposes a price ceiling below the equilibrium price, the market will experience","options":["a shortage, because quantity demanded exceeds quantity supplied","no change in quantity, only a lower price","a surplus, because quantity supplied exceeds quantity demanded","an increase in the quantity supplied"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"At a price below equilibrium buyers want more than before while sellers offer less, so excess demand appears. Option C is the effect of a binding price floor, and option D is wrong because a lower price moves sellers down their supply curve, reducing the quantity supplied."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 457, $official_bank_source${"itemId":"9a40debd-f830-5d2e-924d-28cba6717bd4","questionId":"0968bcea-31e7-5c94-9a11-351cd45bd41c","sourceKey":"bank:ECO201:MDG-019","payload":{"prompt":"Government sets a maximum price of N900 for a bag of cement whose equilibrium price is N800. The most likely effect is that","options":["a black market for cement develops","the ceiling has no effect and the market stays at equilibrium","a surplus of cement develops","a shortage of cement develops"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"A ceiling above the equilibrium price is non-binding: sellers can still charge the market price of N800, which is legal, so nothing changes. Options D and A only arise when the ceiling is set below equilibrium, and option C is the effect of a binding floor."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 458, $official_bank_source${"itemId":"37c19738-3f0d-5028-a743-556909d9e717","questionId":"f3817d2d-08c8-5ace-8ac1-557c8cf701e3","sourceKey":"bank:ECO201:MDG-020","payload":{"prompt":"After a maximum pump price for petrol is set below the market-clearing level, long queues form at filling stations and some people resell petrol in jerrycans at far higher prices by the roadside. The roadside trade is an example of","options":["a cobweb cycle","a price floor","a black market","market clearing"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"A black market is illegal trading at prices above the legal ceiling, which arises because some buyers are willing to pay more than the controlled price for the scarce good. Option B is a minimum price, and option D is wrong because the controlled market does not clear: there are queues."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 459, $official_bank_source${"itemId":"11386c3b-ae75-5cda-b0d6-0c0d9dbd6289","questionId":"bfb899b0-3936-5777-bf96-0745d8b49009","sourceKey":"bank:ECO201:MDG-021","payload":{"prompt":"When a binding price ceiling creates a shortage, which of the following is NOT a way the limited quantity may be allocated?","options":["Ration coupons issued by government","Sellers' preferences for favoured customers","Queuing on a first-come, first-served basis","Letting the price rise until quantity demanded equals quantity supplied"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"Under a binding ceiling the price cannot legally rise to clear the market, so the price mechanism is exactly what is NOT available. Options C, A and B are genuine non-price rationing methods that replace the price mechanism when there is a shortage."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 460, $official_bank_source${"itemId":"be3863f4-39e4-5f30-be29-9a4752956562","questionId":"5944cea7-22f3-5335-901b-0e6fce35fb4a","sourceKey":"bank:ECO201:MDG-022","payload":{"prompt":"The demand for a good is Qd = 200 - 4P and the supply is Qs = -40 + 2P, with P in naira. If government sets a price ceiling of N30, the resulting shortage is","options":["40 units","20 units","80 units","60 units"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"At N30, quantity demanded is 200 - 4(30) = 80 and quantity supplied is -40 + 2(30) = 20, so the shortage is 80 - 20 = 60 units. Option C is only the quantity demanded, option B is only the quantity supplied, and option A is the equilibrium quantity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 461, $official_bank_source${"itemId":"d2fbc01c-283a-5aae-8f95-cbfc143d4f1f","questionId":"e121cb2c-555a-5c33-84b1-876f25c132cb","sourceKey":"bank:ECO201:MDG-023","payload":{"prompt":"The demand for a good is Qd = 200 - 4P and the supply is Qs = -40 + 2P. If government sets a price ceiling of N30, the quantity actually bought and sold in the legal market is","options":["80 units","20 units","60 units","40 units"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"Trade cannot exceed what sellers are willing to offer, so with a ceiling the quantity traded is the quantity supplied, -40 + 2(30) = 20 units. Option A is what buyers want but cannot get, option D is the equilibrium quantity that would be traded without the ceiling, and option C is the shortage."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 462, $official_bank_source${"itemId":"d093d60c-54d6-561f-b6bf-b9c5a0358d20","questionId":"fbfe295e-200d-5eb8-b792-e92196145844","sourceKey":"bank:ECO201:MDG-024","payload":{"prompt":"The demand for a good is Qd = 200 - 4P and the supply is Qs = -40 + 2P. A ceiling of N30 limits supply to 20 units. The highest price buyers would be willing to pay for those 20 units on a black market is","options":["N40","N45","N50","N30"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"Buyers' willingness to pay for the 20th unit is found from the demand curve: 20 = 200 - 4P, so P = 180/4 = N45. Option D is the legal ceiling, option A is the free-market equilibrium price, and option C is the price at which quantity demanded falls to zero."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 463, $official_bank_source${"itemId":"e69ba47f-a869-578b-bf54-db19b1c44193","questionId":"4b26382d-848e-595d-ba68-daf30593ba49","sourceKey":"bank:ECO201:MDG-025","payload":{"prompt":"In a market, demand is Qd = 120 - 2P and supply is Qs = 3P - 30, with P in naira. The equilibrium price is N30. If government imposes a price ceiling of N25, the shortage is","options":["60 units","45 units","70 units","25 units"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"At N25, quantity demanded is 120 - 50 = 70 and quantity supplied is 75 - 30 = 45, so excess demand is 70 - 45 = 25 units. Option C and option B are just the quantities demanded and supplied, and option A is the equilibrium quantity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 464, $official_bank_source${"itemId":"2faf30a4-4328-5a84-af56-30b35f942b35","questionId":"92434f2a-4c1f-5c66-8962-b6ef1e3117b7","sourceKey":"bank:ECO201:MDG-026","payload":{"prompt":"Which statement about a binding price ceiling is correct?","options":["All consumers gain and producers are unaffected","Nobody gains, because quantity traded stays the same","Producers gain because they sell more at the controlled price","Consumers who can still buy the good gain, producers lose, and consumers who are rationed out lose"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"Buyers who obtain the good pay less, but sellers receive a lower price on fewer units, and buyers who cannot obtain it are worse off. Option A ignores the rationed-out consumers and the producers, option C is wrong because sellers actually sell less, and option B is wrong because the quantity traded falls."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 465, $official_bank_source${"itemId":"a6ede883-b1cb-5642-932a-59d93002294d","questionId":"a754aac9-7dc0-5f29-922e-b62b8978da64","sourceKey":"bank:ECO201:MDG-027","payload":{"prompt":"A state government fixes maximum rents in Lagos well below the market level. Which outcome is most likely over time?","options":["A surplus of empty apartments as landlords build more","A shortage of rental apartments, with long searches and some landlords collecting illegal extra payments","No change, since housing demand is fixed","Rents and the number of apartments both rise"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"A rent ceiling below equilibrium lowers the quantity of housing supplied and raises the quantity demanded, so tenants face a shortage, and side payments act as a hidden black market. Option A is the effect of a price floor, option D contradicts the legal maximum, and option C is wrong because demand still responds to price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 466, $official_bank_source${"itemId":"38502c7a-e231-53f1-a8a8-dad7fcff9465","questionId":"4774736e-11cf-5d56-ab48-8dbbdc2bc693","sourceKey":"bank:ECO201:MDG-028","payload":{"prompt":"A legal minimum price, set by government above the market-clearing price, is called a","options":["equilibrium price","black-market price","price ceiling","price floor"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"A price floor is the lowest price at which a good may legally be sold, and it is effective only when it is set above equilibrium. Option C is a maximum price set below equilibrium, option A is the market-clearing price, and option B is the illegal price that arises under a ceiling."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 467, $official_bank_source${"itemId":"6eeb50fc-fecd-54a5-a79e-9649f0c471ff","questionId":"9f157214-5b88-51bc-b26e-64a5a9d4ff41","sourceKey":"bank:ECO201:MDG-029","payload":{"prompt":"A binding price floor set above the equilibrium price leads to","options":["a surplus, because quantity supplied exceeds quantity demanded","the market clearing at a higher quantity","a rise in the quantity demanded","a shortage, because quantity demanded exceeds quantity supplied"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"At a price above equilibrium sellers want to sell more and buyers want to buy less, so unsold output (excess supply) appears. Option D is the effect of a binding ceiling, and options C and B are wrong because a higher price reduces the quantity demanded."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 468, $official_bank_source${"itemId":"4321305b-212e-5cbf-b6b8-ad441f6e13b8","questionId":"d613e49a-07da-5b8b-b16d-30197c1b6045","sourceKey":"bank:ECO201:MDG-030","payload":{"prompt":"For a price control to change the market outcome, a price ceiling must be set ___ the equilibrium price and a price floor must be set ___ the equilibrium price.","options":["below; below","above; above","above; below","below; above"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"A maximum price only binds if it stops the price reaching equilibrium from above, so it must lie below equilibrium, while a minimum price binds only if it lies above equilibrium. Option C reverses the two, and those controls would simply be ignored by the market."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 469, $official_bank_source${"itemId":"997b90f3-8d83-5196-b6a7-3e7b85742a1c","questionId":"43f72ecd-3280-576f-ab95-50247c1686b5","sourceKey":"bank:ECO201:MDG-031","payload":{"prompt":"A national minimum wage set above the equilibrium wage in a competitive labour market will most likely cause","options":["higher employment, because workers earn more","no change in employment","a shortage of workers, because firms want to hire more","unemployment, because more people want to work than firms want to hire"],"correctOption":3,"section":"Market Dynamics and Government Intervention","explanation":"A minimum wage is a price floor in the labour market, so at a wage above equilibrium the quantity of labour supplied exceeds the quantity demanded, which is unemployment. Option C would follow from a wage set below equilibrium, and option A is wrong because firms hire fewer workers at a higher wage."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 470, $official_bank_source${"itemId":"af61c645-f8ec-5999-9153-5da0ab19863e","questionId":"87c79121-6cea-5080-b57a-7a2c6a5a295b","sourceKey":"bank:ECO201:MDG-032","payload":{"prompt":"Government guarantees cocoa farmers a price above the market-clearing price and promises to keep the market price at that level. To do this, government must","options":["buy and store the surplus that private buyers will not take","tax cocoa farmers to reduce their output","impose a maximum price on cocoa","sell cocoa from its own stocks to raise supply"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"At a guaranteed price above equilibrium farmers produce more than private buyers want, so the price can only be held up if government buys the excess supply. Option D would push the price down, option C is a ceiling, which is the opposite policy, and option B would hurt rather than support farmers."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 471, $official_bank_source${"itemId":"660d6fad-373a-516f-a5e4-94b6ee9b783b","questionId":"9a30c6af-9da0-5706-95a6-0fafec6bca8a","sourceKey":"bank:ECO201:MDG-033","payload":{"prompt":"The demand for a good is Qd = 200 - 4P and the supply is Qs = -40 + 2P, with P in naira. If government sets a price floor of N45, the surplus is","options":["70 units","30 units","50 units","20 units"],"correctOption":1,"section":"Market Dynamics and Government Intervention","explanation":"At N45, quantity supplied is -40 + 2(45) = 50 and quantity demanded is 200 - 4(45) = 20, so excess supply is 50 - 20 = 30 units. Option C is just the quantity supplied, option D is the quantity demanded, and option A adds them instead of subtracting."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 472, $official_bank_source${"itemId":"11b545f1-dc93-5792-afa2-4782adaa4217","questionId":"fe78a721-93d7-5b8a-937b-b1253dda046f","sourceKey":"bank:ECO201:MDG-034","payload":{"prompt":"Demand is Qd = 200 - 4P and supply is Qs = -40 + 2P. Government sets a guaranteed price of N45 and buys all the unsold output at that price. How much does government spend?","options":["N1,200","N900","N1,350","N2,250"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"The surplus at N45 is 50 - 20 = 30 units, and buying them at N45 each costs 30 x 45 = N1,350. Option D values all 50 units supplied, option B values only the 20 units bought by consumers, and option A wrongly uses the equilibrium price of N40."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 473, $official_bank_source${"itemId":"e63b14a1-87d9-5eb2-88e9-67b3c8b065e5","questionId":"467859e6-aa4b-54e3-b5bc-36c5cb3bffee","sourceKey":"bank:ECO201:MDG-035","payload":{"prompt":"In a market, demand is Qd = 120 - 2P and supply is Qs = 3P - 30, with P in naira. If government imposes a price floor of N40, the surplus is","options":["60 units","40 units","50 units","90 units"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"At N40, quantity supplied is 3(40) - 30 = 90 and quantity demanded is 120 - 2(40) = 40, giving a surplus of 90 - 40 = 50 units. Options D and B are only one side of the market, and option A is the equilibrium quantity at N30."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 474, $official_bank_source${"itemId":"cfb60687-1581-54ca-ba07-f330428c8604","questionId":"53551440-988a-56ad-976d-a7270a70ae3b","sourceKey":"bank:ECO201:MDG-036","payload":{"prompt":"In a labour market, labour demand is Ld = 500 - 10W and labour supply is Ls = 20W - 100, where W is the daily wage in naira. If a minimum wage of N25 is imposed, the resulting unemployment is","options":["250 workers","400 workers","150 workers","300 workers"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"At W = 25, firms want 500 - 250 = 250 workers while 20(25) - 100 = 400 people want jobs, so 400 - 250 = 150 are unemployed. Option B is the number willing to work, option A is the number hired, and option D is the equilibrium employment at a wage of N20."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 475, $official_bank_source${"itemId":"1e41dd85-b31a-5939-bb39-10a398feb1c6","questionId":"1135b775-08b4-53d5-af26-2182145d7f35","sourceKey":"bank:ECO201:MDG-037","payload":{"prompt":"In a labour market, labour demand is Ld = 500 - 10W and labour supply is Ls = 20W - 100. The equilibrium wage is N20. If a minimum wage of N25 is imposed, how many workers are actually employed?","options":["250 workers","150 workers","300 workers","400 workers"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"Employment is set by the short side of the market, which is labour demand: 500 - 10(25) = 250 workers. Option C is employment at the old equilibrium, option D is the number of people who want work, and option B is the unemployment created."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 476, $official_bank_source${"itemId":"f701749e-6a4a-59f8-8c03-76c0262ea8eb","questionId":"1dab19ef-4524-5406-867d-686be3cb7572","sourceKey":"bank:ECO201:MDG-038","payload":{"prompt":"The net loss of total (consumer plus producer) surplus that results when a market is prevented from reaching its competitive equilibrium is called","options":["excess demand","producer surplus","deadweight loss","consumer surplus"],"correctOption":2,"section":"Market Dynamics and Government Intervention","explanation":"Deadweight loss is surplus that disappears altogether because some mutually beneficial trades no longer take place; nobody receives it. Options D and B are the gains that buyers and sellers do receive from trade, and option A is a shortage of quantity, not a loss of welfare."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 477, $official_bank_source${"itemId":"ab0c65db-ca08-5f7d-b748-79e1284594ae","questionId":"c986b648-9767-5a34-a83b-eb5d15eb811a","sourceKey":"bank:ECO201:MDG-039","payload":{"prompt":"A binding price ceiling creates a deadweight loss mainly because","options":["some units that buyers value above their cost of production are no longer produced and traded","quantity demanded rises above its equilibrium level","consumers pay a lower price than before","producers transfer part of their surplus to consumers"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"The ceiling cuts the quantity traded below equilibrium, so trades that would have created value for both sides are lost, and that lost value is the deadweight loss. Options C and D describe a transfer from producers to consumers, which is a redistribution rather than a loss to society, and option B is a shortage effect, not the reason surplus is lost."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 478, $official_bank_source${"itemId":"6a9e4888-9389-505a-aae8-b56b13fb4e18","questionId":"a728983c-2395-54aa-b86a-264a913860e8","sourceKey":"bank:ECO201:MDG-040","payload":{"prompt":"Which of the following does NOT create a deadweight loss?","options":["A competitive market left free to reach its equilibrium","A binding minimum wage","A binding price ceiling on rented housing","A binding minimum price for maize"],"correctOption":0,"section":"Market Dynamics and Government Intervention","explanation":"A free competitive equilibrium already exploits all mutually beneficial trades, so total surplus is maximised and there is no deadweight loss. Options C, D and B are all binding price controls that change the quantity traded away from equilibrium and so cause market distortions."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 479, $official_bank_source${"itemId":"7bd0df9b-f29e-59cb-9503-f68e2922a295","questionId":"2ee38613-3474-5313-997b-107f6aac7ddd","sourceKey":"bank:ECO201:E201-0039","payload":{"prompt":"Zero price elasticity means ______.","options":["Demand is perfectly elastic","Demand is inelastic","Demand is perfectly inelastic","Demand is elastic"],"correctOption":2,"section":"Elasticity","explanation":"A price elasticity of zero means quantity demanded does not change at all when price changes, so demand is perfectly inelastic and the demand curve is vertical. Option B, inelastic demand, means elasticity is between 0 and 1, so quantity still responds a little. Option A, perfectly elastic, is the opposite extreme with an infinite elasticity and a horizontal curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 480, $official_bank_source${"itemId":"c45ccf69-ea4e-5f4a-9a1c-58c784fb05be","questionId":"33ded670-162b-5a5f-9719-dfacb0628aae","sourceKey":"bank:ECO201:E201-0064","payload":{"prompt":"When goods have income elasticity between 0 and 1, they are better described as: ______","options":["Necessities","Giffen goods","Luxury goods","Inferior goods"],"correctOption":0,"section":"Elasticity","explanation":"An income elasticity between 0 and 1 means demand rises with income but by a smaller percentage than income, which is the mark of a necessity such as basic food items. Option C, luxury goods, have income elasticity greater than 1, and option D, inferior goods, have negative income elasticity. Option B, Giffen goods, are a special type of inferior good."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 481, $official_bank_source${"itemId":"30080079-b691-5c6a-a67f-e4fa9840d858","questionId":"eff013ae-9183-5824-adec-a77d00d1b22a","sourceKey":"bank:ECO201:E201-0066","payload":{"prompt":"Closeup and Pepsodent are two common brands of toothpaste on the campus of University of Lagos. Using the elasticity construct, these products are best described as: ______.","options":["Complementary goods","Substitute goods","Inferior goods","Independent goods"],"correctOption":1,"section":"Elasticity","explanation":"Closeup and Pepsodent serve the same purpose, so if the price of one rises, many students will switch to the other, giving a positive cross-price elasticity of demand. Goods with a positive cross elasticity are substitutes. Option A, complementary goods, are used together and have a negative cross elasticity, like toothpaste and toothbrushes, and option D, independent goods, have a cross elasticity of zero."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 482, $official_bank_source${"itemId":"7cb6e221-e782-5983-b3d2-494166c94d32","questionId":"d8eb20c8-bd50-5a1a-b48f-75762cbbfa6c","sourceKey":"bank:ECO201:E201-0073","payload":{"prompt":"For normal goods, income elasticity of demand is: ______","options":["Positive","Infinite","Zero","Negative"],"correctOption":0,"section":"Elasticity","explanation":"For a normal good, demand rises when income rises, so income and quantity demanded move in the same direction and income elasticity is positive. Option D, negative income elasticity, is the mark of an inferior good, and option C, zero, means demand does not respond to income at all."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 483, $official_bank_source${"itemId":"e76a273f-1a0f-5df4-96c0-febf640362ef","questionId":"9e814553-dc67-566c-a0c9-e09edaffedeb","sourceKey":"bank:ECO201:E201-0075","payload":{"prompt":"When crude oil prices increase due to restricted supply routes, the percentage decrease in quantity demanded is: ______.","options":["Greater than the percentage increase in price","Equal to the percentage increase in price","Unrelated to price changes","Less than the percentage increase in price"],"correctOption":3,"section":"Elasticity","explanation":"Crude oil has inelastic demand because it is essential and has few quick substitutes, and inelastic demand means the percentage fall in quantity demanded is smaller than the percentage rise in price. Option A describes elastic demand, and option B describes unit elastic demand. Option C is wrong because quantity demanded still responds to price, only weakly."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 484, $official_bank_source${"itemId":"ce1d02a2-0f89-53b0-b91c-97219a533a86","questionId":"84b468ec-e9a4-59c3-9c82-c78280c312e9","sourceKey":"bank:ECO201:E201-0076","payload":{"prompt":"An increase in the price of Dettol Antiseptic Soap leads consumers to switch to Dudu Osun. This indicates: ______","options":["Negative income elasticity","Unit income elasticity","Positive cross-price elasticity","Perfect complementarity"],"correctOption":2,"section":"Elasticity","explanation":"When a rise in the price of Dettol soap causes consumers to buy more Dudu Osun, the price of one good and the quantity demanded of the other move in the same direction. That gives a positive cross-price elasticity, which shows the two soaps are substitutes. Option D, perfect complementarity, would give a negative cross elasticity, and options A and B are about income changes, not price changes of another good."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 485, $official_bank_source${"itemId":"9da7b7ca-fee8-533e-9bbe-652b23e68f18","questionId":"9f9a4fad-f37b-5254-b90c-65836b87aab2","sourceKey":"bank:ECO201:E201-0083","payload":{"prompt":"Inferior goods are characterized by: ______","options":["Positive income elasticity","Zero income elasticity","Unit income elasticity","Negative income elasticity"],"correctOption":3,"section":"Elasticity","explanation":"An inferior good is one whose demand falls when income rises, so income and quantity demanded move in opposite directions and income elasticity is negative. Option A, positive income elasticity, belongs to normal goods, and option B, zero, means demand does not respond to income at all."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 486, $official_bank_source${"itemId":"34108626-2589-5367-8f65-d1a59c63e892","questionId":"550328dd-778e-5b21-b335-0deae372872a","sourceKey":"bank:ECO201:E201-0085","payload":{"prompt":"Crude oil remains essential for transport and industry despite price hikes caused by geopolitical disruptions. This indicates that crude oil is: ______","options":["A luxury good","A necessity with inelastic demand","A Giffen good with elastic demand","A perfect substitute good"],"correctOption":1,"section":"Elasticity","explanation":"Crude oil is essential for transport and industry, so people keep buying it even when the price rises sharply. A good that is needed regardless of price is a necessity with inelastic demand. Option A is wrong because luxuries are things people cut back on easily, and option C is wrong because a Giffen good is a rare inferior good and does not have elastic demand."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 487, $official_bank_source${"itemId":"32375870-6172-5931-98fb-25bf13b64d04","questionId":"fa2f818c-ded0-5359-8f13-fa506d7d92e6","sourceKey":"bank:ECO201:E201-0086","payload":{"prompt":"If the price of Indomie increases and the demand for Chikki Noodles rises, the cross-price elasticity of demand is: ______.","options":["Negative","Zero","Perfectly inelastic","Positive"],"correctOption":3,"section":"Elasticity","explanation":"Cross-price elasticity compares the change in demand for one good with the change in price of another. Here the price of Indomie rises and demand for Chikki Noodles also rises, so both move in the same direction and the cross elasticity is positive, showing they are substitutes. Option A, negative, would mean the goods are complements, and option B, zero, would mean they are unrelated."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 488, $official_bank_source${"itemId":"0c461cc3-56d7-52ce-8951-1c3ff067e772","questionId":"698457dd-e60f-5f99-9ec8-e721f6251d1d","sourceKey":"bank:ECO201:E201-0093","payload":{"prompt":"A good with income elasticity greater than 1 is classified as ______.","options":["Inferior good","Luxury good","Necessity good","Complementary good"],"correctOption":1,"section":"Elasticity","explanation":"An income elasticity greater than 1 means demand rises by a bigger percentage than income, which is the mark of a luxury good. Option C, necessity goods, have income elasticity between 0 and 1, and option A, inferior goods, have negative income elasticity. Option D, complementary goods, are defined by cross-price elasticity, not income elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 489, $official_bank_source${"itemId":"ffc7ddec-f1d8-543b-b93d-15f8a75d3e17","questionId":"b60bad68-c396-509a-99cf-81f6ff13e366","sourceKey":"bank:ECO201:E201-0094","payload":{"prompt":"If the income elasticity of a commodity is negative, the commodity is:","options":["A normal good","A luxury good","A substitute good","An inferior good"],"correctOption":3,"section":"Elasticity","explanation":"A negative income elasticity means demand falls as income rises, which defines an inferior good. Options A and B, normal and luxury goods, both have positive income elasticity. Option C, a substitute good, is defined by a positive cross-price elasticity, not by income elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 490, $official_bank_source${"itemId":"57ac4955-c302-5676-bee4-dd0b79b6681a","questionId":"3d93316b-2270-5893-9c5b-446837519a6c","sourceKey":"bank:ECO201:E201-0095","payload":{"prompt":"In the short run after a major supply disruption like the Strait of Hormuz closure, the demand for crude oil is: ______.","options":["Inelastic due to lack of immediate substitutes","More elastic due to availability of substitutes","Perfectly elastic","Unit elastic due to proportional adjustments"],"correctOption":0,"section":"Elasticity","explanation":"Immediately after a major supply disruption, users of crude oil cannot quickly switch to other fuels or change their vehicles and machines, so quantity demanded falls very little even as the price jumps. Demand is therefore inelastic due to the lack of immediate substitutes. Option B describes the longer run, when substitutes become available, and option C, perfectly elastic, would mean consumers stop buying completely after any price rise."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 491, $official_bank_source${"itemId":"9dbe2ae2-240f-5b7c-be07-7816e6f24fe5","questionId":"a273bd05-4037-5d4f-9c1a-2067f9bdaed8","sourceKey":"bank:ECO201:E201-0408","payload":{"prompt":"For complementary goods, the cross elasticity of demand is:","options":["Positive","Negative","Zero","Infinite"],"correctOption":1,"section":"Elasticity","explanation":"Complements are used together, so a rise in the price of one reduces the quantity demanded of the other, giving a negative cross elasticity. A positive cross elasticity (option A) belongs to substitutes, while zero (option C) means the goods are unrelated."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 492, $official_bank_source${"itemId":"515339f5-9d98-5baa-8192-892fea875ee3","questionId":"b171c7eb-6d05-5f75-939c-2ed7ae6ca60b","sourceKey":"bank:ECO201:E201-0409","payload":{"prompt":"The relationship between the price of one commodity and the demand for another commodity is measured by:","options":["Price elasticity","Income elasticity","Cross elasticity","Elasticity of substitution"],"correctOption":2,"section":"Elasticity","explanation":"Cross elasticity of demand measures how the quantity demanded of one good responds to a change in the price of another good. Price elasticity (option A) looks at a good's own price, and income elasticity (option B) looks at changes in income."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 493, $official_bank_source${"itemId":"a69e5e3a-0cb7-5557-a0ae-1e7e4e90397e","questionId":"02939f31-38a6-543b-ab53-0925f6aa2c85","sourceKey":"bank:ECO201:E201-0413","payload":{"prompt":"For luxury goods, the income elasticity of demand will be:","options":["Less than unity","Unity","More than unity","All the above"],"correctOption":2,"section":"Elasticity","explanation":"For a luxury, quantity demanded rises proportionately more than income, so the income elasticity is greater than one. A value between zero and one (option A) describes a necessity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 494, $official_bank_source${"itemId":"5780193e-3d4f-5231-8a7a-80c560fc447c","questionId":"59059bba-7167-5faf-ab4f-0310430d5066","sourceKey":"bank:ECO201:E201-0427","payload":{"prompt":"If the percentage increase in the quantity demanded of a commodity is smaller than the percentage fall in its price, the coefficient of price elasticity is:","options":["Greater than one","Equal to one","Smaller than one","Zero"],"correctOption":2,"section":"Elasticity","explanation":"Price elasticity equals the percentage change in quantity demanded divided by the percentage change in price, so a smaller percentage change in quantity than in price gives a coefficient below one (inelastic demand). A coefficient greater than one (option A) would need the quantity response to be the larger of the two."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 495, $official_bank_source${"itemId":"86d3fa94-9098-5761-971b-2d4d83793bf2","questionId":"97756ca9-a633-57d4-bef4-7831ca02ccb8","sourceKey":"bank:ECO201:E201-0428","payload":{"prompt":"A fall in the price of a commodity whose demand curve is a rectangular hyperbola causes total expenditure on the commodity to:","options":["Increase","Decrease","Remain unchanged","None of the above"],"correctOption":2,"section":"Elasticity","explanation":"A demand curve shaped like a rectangular hyperbola has P x Q constant at every point, which means elasticity is one throughout. Because spending equals P x Q, a fall in price leaves total expenditure unchanged, so options A and B are wrong."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 496, $official_bank_source${"itemId":"2b6603d4-3ffd-5679-a058-e09624437c80","questionId":"16bebd3e-be3a-57e6-a0ef-94896ffa0abf","sourceKey":"bank:ECO201:E201-0429","payload":{"prompt":"If the quantity demanded remains unchanged as the price of a commodity falls, the coefficient of price elasticity of demand is:","options":["Greater than One","Equal to one","Smaller than one","Zero"],"correctOption":3,"section":"Elasticity","explanation":"If quantity demanded does not respond at all when price changes, the percentage change in quantity is zero, so the elasticity coefficient is zero (perfectly inelastic demand). Option C, smaller than one, fits inelastic demand where quantity still responds a little."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 497, $official_bank_source${"itemId":"9bfbdf67-6e19-5268-982a-ef6e2533788b","questionId":"1d4a7a58-ebc8-56af-bb38-4b702cd94da9","sourceKey":"bank:ECO201:E201-0430","payload":{"prompt":"An increase in the price of a commodity whose demand is inelastic causes consumers' total expenditure on the commodity to:","options":["Increase","Decrease","Remain unchanged","Any of the above"],"correctOption":0,"section":"Elasticity","explanation":"When demand is inelastic, quantity falls by a smaller percentage than price rises, so the higher price outweighs the lower quantity and total expenditure (P x Q) increases. Option C holds only for unit elastic demand, and option B holds when demand is elastic."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 498, $official_bank_source${"itemId":"856b2c2e-2f96-5a1c-bf07-ae049e5ff3dd","questionId":"34f6e818-8b6a-56ea-b861-c0bc25b9c392","sourceKey":"bank:ECO201:E201-0431","payload":{"prompt":"A negative income elasticity of demand for a commodity indicates that, as income falls, the amount of the commodity purchased:","options":["Rises","Falls","Remains unchanged","None of the above"],"correctOption":0,"section":"Elasticity","explanation":"A negative income elasticity means income and quantity bought move in opposite directions, so when income falls the amount purchased rises, as with an inferior good. Option B would be the case for a positive income elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 499, $official_bank_source${"itemId":"2277c144-df46-5400-b0c6-84e63364dc10","questionId":"c6c19130-a2fd-5d5e-9f4d-f7573b0b9a0c","sourceKey":"bank:ECO201:E201-0433","payload":{"prompt":"If the amount of the commodity purchased remains unchanged when the price of another commodity changes, the cross elasticity of demand between them will be:","options":["Positive","Negative","Zero","One"],"correctOption":2,"section":"Elasticity","explanation":"If the purchase of one good does not change at all when another good's price changes, the numerator of the cross elasticity is zero, so the cross elasticity is zero and the goods are unrelated. Positive (option A) would indicate substitutes and negative (option B) complements."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 500, $official_bank_source${"itemId":"74c680df-6cf9-58a7-872c-18a3084d7529","questionId":"10da4a15-49bc-53de-a954-8fd782ccd8b1","sourceKey":"bank:ECO201:E201-0434","payload":{"prompt":"If the income elasticity of demand for a commodity is found to be 0.4, the commodity is a:","options":["Luxury","Necessity","Giffen good","Independent good"],"correctOption":1,"section":"Elasticity","explanation":"An income elasticity of 0.4 is positive but less than one, so demand rises with income but more slowly, which is the definition of a necessity. A luxury (option A) needs an income elasticity above one, and a Giffen good (option C) is an inferior good with negative income elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 501, $official_bank_source${"itemId":"b91ee9fc-3766-5094-8f86-594557ae9910","questionId":"7030e825-5020-5184-ac9a-31bc9646c05e","sourceKey":"bank:ECO201:E201-0435","payload":{"prompt":"The elasticity of supply for a positively sloped straight-line supply curve that intersects the price axis is:","options":["Equal to zero","Equal to one","Greater than one","Constant"],"correctOption":2,"section":"Elasticity","explanation":"Write the line as Q = k + mP; if it cuts the price axis, k is negative, so elasticity = mP/(k + mP) is greater than one at every point. In other words, quantity supplied always changes by a bigger percentage than price, so supply is elastic. Unit elasticity (option B) applies only to a line through the origin, and option D is wrong because elasticity changes along such a line."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 502, $official_bank_source${"itemId":"d4576a07-469c-5314-aa63-c94b7ab88926","questionId":"67b31652-cf81-58bc-95b6-8a4a86a6d533","sourceKey":"bank:ECO201:E201-0436","payload":{"prompt":"If a positively sloped linear supply curve crosses the quantity axis, the elasticity of supply is:","options":["Inelastic","Elastic","Unitary elastic","Perfectly elastic"],"correctOption":0,"section":"Elasticity","explanation":"When a straight-line supply curve starts on the quantity axis, some quantity is supplied even at a zero price, so the percentage change in quantity is always smaller than the percentage change in price and supply is inelastic. Option B describes a line cutting the price axis, and option C a line through the origin."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 503, $official_bank_source${"itemId":"681bf9ba-5926-585a-bcea-ca793d7686f8","questionId":"e496a0ec-5252-5807-bab2-5cf1f1c724ec","sourceKey":"bank:ECO201:E201-0437","payload":{"prompt":"If a positively sloped linear supply curve passes through the origin, the elasticity of supply is:","options":["Inelastic","Elastic","Unitary elastic","Perfectly elastic"],"correctOption":2,"section":"Elasticity","explanation":"Any straight-line supply curve through the origin has Q proportional to P, so a given percentage change in price causes the same percentage change in quantity and elasticity equals one at every point, whatever the slope. Options A and B describe lines that cut the quantity and price axes respectively."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 504, $official_bank_source${"itemId":"f0f68207-4d2f-5154-b2cf-27266aa4ba0e","questionId":"8aa8c40d-f75d-5cb2-871e-95f7341b2ff2","sourceKey":"bank:ECO201:E201-0438","payload":{"prompt":"A horizontal supply curve, parallel to the quantity axis, represents:","options":["Elastic supply","Inelastic supply","Perfectly elastic supply","Perfectly inelastic supply"],"correctOption":2,"section":"Elasticity","explanation":"A horizontal supply curve means sellers will supply any quantity at that single price but nothing below it, so elasticity of supply is infinite (perfectly elastic). A vertical supply curve would be perfectly inelastic (option D)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 505, $official_bank_source${"itemId":"6ad5721b-1da4-5c95-b195-da9746f2313a","questionId":"3a3b22bf-6dc4-5b92-967b-c028411c75c7","sourceKey":"bank:ECO201:E201-0441","payload":{"prompt":"Which of the following elasticities measures a movement along a demand curve rather than a shift of the curve?","options":["Price elasticity of demand","Income elasticity of demand","Cross elasticity of demand","None of the above"],"correctOption":0,"section":"Elasticity","explanation":"Price elasticity of demand measures the response of quantity demanded to the good's own price, which is a movement along a given demand curve. Income elasticity (option B) and cross elasticity (option C) measure responses to income and to other goods' prices, which shift the demand curve."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 506, $official_bank_source${"itemId":"c495a3ee-683f-5908-864e-e6ef4dd9b504","questionId":"d01b3345-0f55-5f56-b0bc-2de181791795","sourceKey":"bank:ECO201:E201-0442","payload":{"prompt":"In the case of substitutes, the cross elasticity of demand is:","options":["Zero","Negative","Positive","Infinity"],"correctOption":2,"section":"Elasticity","explanation":"Substitutes replace each other, so a rise in the price of one raises demand for the other, which makes the cross elasticity positive. A negative cross elasticity (option B) is the sign for complements, and zero (option A) means the goods are unrelated."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 507, $official_bank_source${"itemId":"1c615500-3d35-533a-976c-9eaffe01fde5","questionId":"6fa3cf6e-871b-59aa-a73f-84ab8b4f6686","sourceKey":"bank:ECO201:E201-0452","payload":{"prompt":"If a fall in the price of a commodity causes total expenditure on it to decrease, the coefficient of price elasticity of demand is:","options":["Equal to one","Greater than one","Less than one","Cannot say"],"correctOption":2,"section":"Elasticity","explanation":"If total expenditure falls when price falls, quantity rose by a smaller percentage than price fell, which means demand is inelastic with a coefficient less than one. A coefficient greater than one (option B) would make spending rise after a price cut, and one (option A) would leave it unchanged."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 508, $official_bank_source${"itemId":"c2da10c8-f501-54bc-8b26-4456c0abbbc0","questionId":"23921c6b-ddd0-5b2f-8f54-b2c1079572d7","sourceKey":"bank:ECO201:E201-0453","payload":{"prompt":"If a small change in price leads to an infinitely large change in quantity demanded, demand is:","options":["Perfectly elastic","Perfectly inelastic","Elastic","Inelastic"],"correctOption":0,"section":"Elasticity","explanation":"When even a tiny price change causes an infinitely large change in quantity demanded, elasticity is infinite and demand is perfectly elastic, shown by a horizontal demand curve. Perfectly inelastic demand (option B) is the opposite case, where quantity does not respond at all and the curve is vertical."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 509, $official_bank_source${"itemId":"1ec4fb3b-acee-5b70-8d44-c5ecd0afb49d","questionId":"0e006085-f528-51c1-8723-425fb9c17066","sourceKey":"bank:ECO201:E201-0454","payload":{"prompt":"When the demand curve is a rectangular hyperbola, the price elasticity of demand is:","options":["Zero","One","Greater than one","Infinity"],"correctOption":1,"section":"Elasticity","explanation":"On a rectangular hyperbola P x Q is constant, so every percentage fall in price is matched by an equal percentage rise in quantity, giving price elasticity equal to one at every point. Zero (option A) and infinity (option D) are the vertical and horizontal demand curve cases."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 510, $official_bank_source${"itemId":"3474db54-a157-5b5a-b595-872facacf868","questionId":"1f425285-0ca0-5ce6-960d-8fbd9f1aa6ac","sourceKey":"bank:ECO201:E201-0463","payload":{"prompt":"If a 3-percent increase in the price of corn flakes causes a 6-percent decline in the quantity demanded, what is the price elasticity of demand?","options":["-0.5","-3.0","-2.0","-18.0"],"correctOption":2,"section":"Elasticity","explanation":"Price elasticity of demand = percentage change in quantity demanded / percentage change in price = -6% / 3% = -2.0, so demand is elastic. Option A divides the figures the wrong way round (3/6), option B subtracts them, and option D multiplies them."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 511, $official_bank_source${"itemId":"925a4cfc-21d3-5493-86a4-9fd0b36d2fea","questionId":"2a02d5c5-3600-572e-bc00-78c6d3c94ed1","sourceKey":"bank:ECO201:E201-0465","payload":{"prompt":"Why is the long-run price elasticity of supply of many goods larger than the short-run elasticity?","options":["Production costs are always fixed in the long run","In the long run consumers become more sensitive to price","In the short run firms can easily build new plants, but in the long run they cannot","In the short run firms are limited by existing capacity, while in the long run they can expand capacity and new firms can enter"],"correctOption":3,"section":"Elasticity","explanation":"In the short run a firm can raise output only by using its existing plant more intensively, so quantity supplied responds little to price. Given time, firms can build new capacity and new producers can enter, so the supply response to a price change becomes larger. Option B is about demand, not supply, and option A is wrong because in the long run all costs are variable."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 512, $official_bank_source${"itemId":"07f70073-315b-5339-8019-b68ba0593bd2","questionId":"3015a2d1-b904-5ed6-ab52-80ddd67d93b2","sourceKey":"bank:ECO201:E201-0466","payload":{"prompt":"Televisions are durable goods. How does the price elasticity of demand for televisions in the short run compare with that in the long run?","options":["It is the same in the short run and the long run, because televisions are durable","It is larger in the short run, because consumers can delay or bring forward replacing their existing sets","It is larger in the long run, because consumers take time to change their habits","It is zero in the short run, because people never change their purchase plans quickly"],"correctOption":1,"section":"Elasticity","explanation":"For a durable good, a price rise mainly makes people postpone replacing the set they already own, so purchases drop sharply at first. Over time old sets wear out and must be replaced, so the long-run response is smaller than the short-run one. Option C is the pattern for non-durable goods such as paper towels, where habits adjust slowly."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 513, $official_bank_source${"itemId":"5a5bf526-010b-5f1d-b4f9-d80d40ae296c","questionId":"997c0f5e-df61-50d8-9cea-6acb7d3895e5","sourceKey":"bank:ECO201:E201-0466-b","payload":{"prompt":"Paper towels are a non-durable good. Would you expect the price elasticity of demand for paper towels to be larger in the short run or in the long run?","options":["Larger in the short run, because paper towels are a necessity","The same in both periods, because paper towels are cheap","Larger in the short run, because consumers can postpone replacing their stock","Larger in the long run, because consumers need time to change habits and find substitutes"],"correctOption":3,"section":"Elasticity","explanation":"For most non-durable goods, people adjust slowly to a price change: it takes time to change habits and switch to alternatives such as cloth towels, so the quantity response grows over time and demand is more elastic in the long run. Option C describes durable goods, where postponing replacement creates a large short-run response."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 514, $official_bank_source${"itemId":"b527b06e-19d5-5462-94f8-a594e458b674","questionId":"ad98266b-5ce6-5908-9b2e-faa4ef5d89ab","sourceKey":"bank:ECO201:E201-0467","payload":{"prompt":"Which of the following statements is correct?","options":["The supply of apartments is more elastic in the short run than in the long run","The supply of apartments is more inelastic in the short run than in the long run","The cross-price elasticity of demand is always positive","The elasticity of demand is the same as the slope of the demand curve"],"correctOption":1,"section":"Elasticity","explanation":"In the short run the stock of apartments is fixed by what has already been built, so quantity supplied hardly responds to rent, while in the long run new apartments can be built. Option D is false because elasticity is the slope multiplied by P/Q, so it changes along a straight-line demand curve even though the slope does not. Option C is false because cross-price elasticity is negative for complements."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 515, $official_bank_source${"itemId":"eef37b0c-0d7c-5981-a495-bde121508ffc","questionId":"d747489b-c691-507f-aa20-a4d9978fa041","sourceKey":"bank:ECO201:E201-0470","payload":{"prompt":"A university doubled its real tuition over 15 years, yet the number and quality of applicants did not fall. An official concludes that demand for admission is completely price inelastic. What is the best response?","options":["Accept the argument: tuition is a necessity, so its demand must be perfectly inelastic","Reject the argument: rising tuition proves that demand is perfectly elastic","Reject the argument: the observed points are different equilibria, and the demand curve itself has probably shifted rightward over time","Accept the argument: unchanged applications at a higher price prove a vertical demand curve"],"correctOption":2,"section":"Elasticity","explanation":"The official sees only price-quantity points from different years, not a single demand curve. If demand rose over the period (for example, because the value of a degree grew), price could double without applications falling, even if demand at any moment is quite price sensitive. Option D assumes the demand curve stayed fixed, and option B draws an equally unsupported conclusion."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 516, $official_bank_source${"itemId":"a4124ef4-e54e-5cfd-9e49-803ae32da1c5","questionId":"13a57e87-6f99-5933-a027-4480d5e7b99c","sourceKey":"bank:ECO201:E201-0471","payload":{"prompt":"The demand curve for a product is Q = 10 - 2P + PS, where P is the price of the product and PS is the price of a substitute good. PS = $2.00 and P = $1.00. What are the price elasticity of demand and the cross-price elasticity of demand?","options":["Price elasticity -2.0; cross-price elasticity 1.0","Price elasticity -0.2; cross-price elasticity 0.2","Price elasticity -5.0; cross-price elasticity 5.0","Price elasticity -0.25; cross-price elasticity 0.25"],"correctOption":1,"section":"Elasticity","explanation":"First find quantity: Q = 10 - 2(1) + 2 = 10. Price elasticity = (dQ/dP)(P/Q) = -2 x 1/10 = -0.2, and cross-price elasticity = (dQ/dPS)(PS/Q) = 1 x 2/10 = 0.2. Option A reports the slopes without multiplying by price over quantity, and option D wrongly uses Q = 8 by leaving out the substitute's price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 517, $official_bank_source${"itemId":"5d1528e4-2301-57d1-9271-374cec7bc718","questionId":"20f32816-48b1-55de-9ec1-c3a0815d4e58","sourceKey":"bank:ECO201:E201-0471-b","payload":{"prompt":"The demand curve for a product is Q = 10 - 2P + PS, where P is the price of the product and PS is the price of a substitute good. PS = $2.00 and P = $2.00. What are the price elasticity of demand and the cross-price elasticity of demand?","options":["Price elasticity -0.5; cross-price elasticity 0.25","Price elasticity -0.4; cross-price elasticity 0.2","Price elasticity -0.5; cross-price elasticity 0.5","Price elasticity -2.0; cross-price elasticity 1.0"],"correctOption":0,"section":"Elasticity","explanation":"Quantity is now Q = 10 - 2(2) + 2 = 8. Price elasticity = -2 x 2/8 = -0.5, and cross-price elasticity = 1 x 2/8 = 0.25. Option B wrongly keeps the old quantity of 10, and option D gives only the slopes of the demand equation."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 518, $official_bank_source${"itemId":"4fb033a1-98e6-54b0-971a-62198727b626","questionId":"79241766-66ef-5804-b503-a3d4573d4ff1","sourceKey":"bank:ECO201:E201-0475","payload":{"prompt":"In a competitive market, the quantities demanded and supplied (millions per year) are: at $60, demand 22 and supply 14; at $80, demand 20 and supply 16; at $100, demand 18 and supply 18; at $120, demand 16 and supply 20. What is the price elasticity of demand at a price of $80?","options":["-0.56","-0.40","-2.50","-0.10"],"correctOption":1,"section":"Elasticity","explanation":"Demand falls by 2 million for every $20 rise in price, so DeltaQ/DeltaP = -2/20 = -0.1. At $80, elasticity = (DeltaQ/DeltaP)(P/Q) = -0.1 x 80/20 = -0.40. Option D gives only the slope, option C inverts the ratio, and option A is the elasticity at $100 (-0.1 x 100/18)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 519, $official_bank_source${"itemId":"c36ac6e4-7e11-5f23-a584-5520f5dd97aa","questionId":"4e4d1266-26a4-5af0-bece-ff5d674a4f07","sourceKey":"bank:ECO201:E201-0477","payload":{"prompt":"A vegetable fiber has a world price of $9 per pound, and unlimited imports are available at that price. U.S. supply and demand (million pounds) are: price $3, supply 2, demand 34; $6, supply 4, demand 28; $9, supply 6, demand 22; $12, supply 8, demand 16; $15, supply 10, demand 10; $18, supply 12, demand 4. What is the price elasticity of demand at a price of $9?","options":["-2.00","About -1.50","About -0.82","About -1.22"],"correctOption":2,"section":"Elasticity","explanation":"The table gives the straight-line demand Q = 40 - 2P, so DeltaQ/DeltaP = -2. At $9, Q = 22, so elasticity = -2 x 9/22 = about -0.82. Option D inverts the ratio (22/18), option B is the elasticity at $12 (-2 x 12/16), and option A is just the slope."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 520, $official_bank_source${"itemId":"9dacd058-cdf4-56e4-b56d-ca664033135b","questionId":"b2f8416d-8833-532f-89ec-58ec12d3acbf","sourceKey":"bank:ECO201:E201-0480","payload":{"prompt":"Americans bought 15.75 billion packs of cigarettes at an average price of $5.00 per pack. The price elasticity of demand is -0.4 and the price elasticity of supply is 0.5. What linear demand curve, Q = a - bP, is consistent with these figures?","options":["Q = 9.45 - 1.26P","Q = 22.05 - 1.26P","Q = 22.05 - 0.4P","Q = 15.75 - 0.4P"],"correctOption":1,"section":"Elasticity","explanation":"From elasticity = -b(P/Q), we get b = 0.4 x 15.75/5 = 1.26. Then a = Q + bP = 15.75 + 1.26 x 5 = 22.05, so Q = 22.05 - 1.26P. Option D uses the elasticity itself as the slope, and option A subtracts bP from Q instead of adding it."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 521, $official_bank_source${"itemId":"303a067a-0b91-5079-8d9e-69f21a3bea7c","questionId":"9e4b241d-dc2c-5944-972a-c841f527f218","sourceKey":"bank:ECO201:E201-0481","payload":{"prompt":"In the copper market the equilibrium price is $3 per pound and the equilibrium quantity is 18 million metric tons per year. If the price elasticity of demand is -0.75, what linear demand curve, Q = a - bP, is consistent with these figures?","options":["Q = 31.5 - 4.5P","Q = 4.5 - 31.5P","Q = 18 - 0.75P","Q = 27 - 3P"],"correctOption":0,"section":"Elasticity","explanation":"From elasticity = -b(P/Q), b = 0.75 x 18/3 = 4.5. Then a = 18 + 4.5 x 3 = 31.5, so Q = 31.5 - 4.5P. Option D is the demand curve for an elasticity of -0.5, and option C uses the elasticity itself as the slope."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 522, $official_bank_source${"itemId":"d6d44781-6df8-5d9d-b1d0-1cca6e7c0c28","questionId":"f0bf0a6f-a3b1-5d03-b67c-339bb98774b8","sourceKey":"bank:ECO201:E201-0485","payload":{"prompt":"Instant coffee: Year 1 price $10.35/lb with sales 75 million lbs; Year 2 price $10.48/lb with sales 70 million lbs. Roasted coffee: Year 1 price $4.11/lb with sales 820 million lbs; Year 2 price $3.76/lb with sales 850 million lbs. Using the arc (midpoint) formula, what is the short-run price elasticity of demand for roasted coffee?","options":["About -85.7","About -5.53","About -2.48","About -0.40"],"correctOption":3,"section":"Elasticity","explanation":"Arc elasticity = (DeltaQ / average Q) / (DeltaP / average P) = (30/835) / (-0.35/3.935) = 0.0359 / -0.0889 = about -0.40, so demand for roasted coffee is inelastic. Option C turns the ratio upside down, option A is just DeltaQ/DeltaP (30/-0.35), and option B is the elasticity for instant coffee."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 523, $official_bank_source${"itemId":"32dd7feb-4fa6-591d-9a71-ab63250e6d05","questionId":"5ed6c5f3-a680-5c51-8dd1-64fc23e329ba","sourceKey":"bank:ECO201:E201-0485-b","payload":{"prompt":"Instant coffee: Year 1 price $10.35/lb with sales 75 million lbs; Year 2 price $10.48/lb with sales 70 million lbs. Roasted coffee: Year 1 price $4.11/lb with sales 820 million lbs; Year 2 price $3.76/lb with sales 850 million lbs. Using the arc (midpoint) formula, what is the short-run price elasticity of demand for instant coffee?","options":["About -0.18","About -5.53","About -38.5","About -0.40"],"correctOption":1,"section":"Elasticity","explanation":"Arc elasticity = (DeltaQ / average Q) / (DeltaP / average P) = (-5/72.5) / (0.13/10.415) = -0.0690 / 0.0125 = about -5.53, so instant coffee has much more elastic demand than roasted coffee. Option A turns the ratio upside down, option C is just DeltaQ/DeltaP (-5/0.13), and option D is the elasticity for roasted coffee."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 524, $official_bank_source${"itemId":"e6b2f0fd-0268-5f32-afca-d8a22455dcf0","questionId":"84fb5185-3e33-5ccf-a533-611ac5bb0cc4","sourceKey":"bank:ECO201:ELS-001","payload":{"prompt":"In economics, the percentage change in one variable that results from a 1 percent increase in another variable is called","options":["slope","elasticity","marginal propensity","marginal rate of substitution"],"correctOption":1,"section":"Elasticity","explanation":"Elasticity measures responsiveness in percentage terms, so it does not depend on the units in which quantities and prices are measured. Option A is the absolute change in one variable per unit change in another, which does depend on units, and option D relates to indifference curves, not responsiveness."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 525, $official_bank_source${"itemId":"68de1efe-2c62-5c0f-9754-3fcf8689f18f","questionId":"1ac787ba-2e89-5852-b22b-0cd93350f3d5","sourceKey":"bank:ECO201:ELS-002","payload":{"prompt":"The percentage change in the quantity demanded of a good resulting from a 1 percent increase in its own price is the","options":["price elasticity of supply","price elasticity of demand","income elasticity of demand","cross-price elasticity of demand"],"correctOption":1,"section":"Elasticity","explanation":"Price elasticity of demand links the quantity demanded of a good to its own price. Option C uses income instead of price, option D uses the price of another good, and option A concerns quantity supplied rather than quantity demanded."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 526, $official_bank_source${"itemId":"bf872afb-e9c4-5cb9-842d-0948665dbddd","questionId":"48dd84de-a16c-5e82-b1a4-2946883eba7b","sourceKey":"bank:ECO201:ELS-003","payload":{"prompt":"Which of the following is the point formula for the price elasticity of demand, Ep?","options":["Ep = (Q/P) x (dQ/dP)","Ep = dQ/dP","Ep = (P/Q) x (dP/dQ)","Ep = (P/Q) x (dQ/dP)"],"correctOption":3,"section":"Elasticity","explanation":"Elasticity is (dQ/Q) divided by (dP/P), which rearranges to (P/Q) times dQ/dP. Option A inverts the ratio of price to quantity, option C uses the slope of the demand curve drawn with price on the vertical axis instead of dQ/dP, and option B is just the slope term without converting to percentages."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 527, $official_bank_source${"itemId":"87b97c8e-e7b0-5a03-9719-cae11c3bb9d7","questionId":"6c58bcfb-6678-5afe-b423-b736b7f782d6","sourceKey":"bank:ECO201:ELS-004","payload":{"prompt":"Demand for a good is described as price elastic when the absolute value of its price elasticity is","options":["equal to 0","greater than 1","equal to 1","less than 1"],"correctOption":1,"section":"Elasticity","explanation":"Elastic demand means quantity changes by a larger percentage than price, so the magnitude of the elasticity exceeds 1. Option D describes inelastic demand, option C unitary elasticity, and option A perfectly inelastic demand."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 528, $official_bank_source${"itemId":"fd9dcf93-c4d1-5e0c-8e29-a26bac61be26","questionId":"a0da756b-5d15-5d98-9af1-754c3239a2ff","sourceKey":"bank:ECO201:ELS-005","payload":{"prompt":"If the price elasticity of demand for salt is -0.1, demand for salt is","options":["price elastic","price inelastic","perfectly elastic","unitary elastic"],"correctOption":1,"section":"Elasticity","explanation":"An elasticity of magnitude 0.1 is less than 1, so a 1 percent price rise reduces quantity demanded by only 0.1 percent, which is inelastic. Option A needs a magnitude above 1, option D needs exactly 1, and option C would require an infinite elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 529, $official_bank_source${"itemId":"c250bfa1-8e1e-5f73-aa66-a851b9d5c637","questionId":"d70d0f7b-9ea6-5e90-a1bb-05452b5ea162","sourceKey":"bank:ECO201:ELS-006","payload":{"prompt":"A horizontal demand curve at a single price represents demand that is","options":["relatively inelastic","perfectly (infinitely) elastic","perfectly inelastic","unitary elastic"],"correctOption":1,"section":"Elasticity","explanation":"With a horizontal demand curve, consumers buy as much as they can get at that price but nothing at any higher price, so the elasticity is infinite. Option C is shown by a vertical demand curve, and options D and A have finite elasticities on a downward-sloping curve."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 530, $official_bank_source${"itemId":"d6cfafc4-f2e1-5042-8fc6-b8eb5e59b655","questionId":"14a61b63-6aef-5c55-9de0-9845f0b1fa25","sourceKey":"bank:ECO201:ELS-007","payload":{"prompt":"When consumers buy a fixed quantity of a good regardless of its price, the demand curve is","options":["upward sloping, and demand is elastic","horizontal, and demand is infinitely elastic","downward sloping, and demand is unitary elastic","vertical, and demand is completely inelastic"],"correctOption":3,"section":"Elasticity","explanation":"A fixed quantity at every price gives a vertical demand curve with an elasticity of zero, called completely inelastic demand. Option B describes infinitely elastic demand, and option A is impossible for a normal demand curve, which slopes downward."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 531, $official_bank_source${"itemId":"7a3a6930-920f-5468-b7c6-eea4806de2f7","questionId":"28c980d4-4eec-55bb-9506-d83f74234957","sourceKey":"bank:ECO201:ELS-008","payload":{"prompt":"If the demand for a good is price elastic, a reduction in its price will","options":["leave total revenue unchanged","reduce total revenue","increase total revenue","reduce the quantity demanded"],"correctOption":2,"section":"Elasticity","explanation":"With elastic demand, quantity rises by a larger percentage than price falls, so price times quantity goes up. Option B is what happens when demand is inelastic, option A applies to unitary elasticity, and option D contradicts the law of demand."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 532, $official_bank_source${"itemId":"9e279c53-fe16-53d5-8f88-029963784c9d","questionId":"334f48fc-c32b-5da0-b2f6-9fbffa83f76b","sourceKey":"bank:ECO201:ELS-010","payload":{"prompt":"When the price elasticity of demand is exactly -1, a small change in price will","options":["increase total revenue","reduce total revenue","leave total revenue unchanged","reduce quantity demanded by more than the price change"],"correctOption":2,"section":"Elasticity","explanation":"At unitary elasticity the percentage change in quantity exactly offsets the percentage change in price, so total revenue stays the same. Options A and B require inelastic or elastic demand depending on the direction of the price change, and option D describes elastic demand."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 533, $official_bank_source${"itemId":"ba647c79-f1cc-53f5-bf13-3bb4b7e50f32","questionId":"0c2a36b4-7fc4-5ec4-91bc-c0f38442afd0","sourceKey":"bank:ECO201:ELS-011","payload":{"prompt":"The price elasticity of demand for a good is likely to be high when","options":["the good has many close substitutes","the good has no close substitutes","consumers are given very little time to adjust","the good takes a tiny share of the consumer's income"],"correctOption":0,"section":"Elasticity","explanation":"When close substitutes exist, buyers can easily switch away after a price rise, so quantity demanded falls a lot. Options B, D and C all make demand less elastic, because buyers either cannot switch, hardly notice the price change, or have not had time to change their habits."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 534, $official_bank_source${"itemId":"e1d27f25-bde1-5820-bcdb-e3f56059323c","questionId":"145ffbc0-d1e5-5102-9e09-5c3367818d26","sourceKey":"bank:ECO201:ELS-012","payload":{"prompt":"Which of the following is NOT a determinant of the price elasticity of demand for a good?","options":["The proportion of income spent on the good","The production technology used by firms making the good","The length of time allowed for adjustment","The availability of close substitutes"],"correctOption":1,"section":"Elasticity","explanation":"Production technology affects how easily firms can supply the good, which belongs to the elasticity of supply, not demand. Options D, A and C are genuine determinants of the price elasticity of demand: substitutes, budget share and time."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 535, $official_bank_source${"itemId":"f8cd147c-590c-5b66-a729-dafd05b772b9","questionId":"b73cdc7b-5363-53b7-a82c-f263462eef8d","sourceKey":"bank:ECO201:ELS-013","payload":{"prompt":"For a non-durable good such as petrol, the price elasticity of demand is usually","options":["larger in magnitude in the short run than in the long run","the same in the short run and long run","larger in magnitude in the long run than in the short run","zero in the long run"],"correctOption":2,"section":"Elasticity","explanation":"Over a longer period consumers can change habits and replace the cars and equipment that use petrol, so the quantity demanded responds more strongly. Option A applies to durable goods such as cars, and option D contradicts the fact that demand becomes more responsive over time."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 536, $official_bank_source${"itemId":"5f59ebde-5b0b-5356-91d6-58b3b3f6b9f4","questionId":"24f583e3-5217-5862-90c7-75406ce70925","sourceKey":"bank:ECO201:ELS-014","payload":{"prompt":"For durable goods such as cars and refrigerators, demand is typically more price elastic in the short run than in the long run because","options":["the existing stock is large relative to annual purchases, so buyers can postpone replacement","firms cannot change the supply of durables in the long run","durable goods have no substitutes","consumers spend only a small share of income on durables"],"correctOption":0,"section":"Elasticity","explanation":"A price rise lets owners keep their old cars longer, causing a big short-run drop in new purchases, though in the long run the stock must still be replaced. Option C is false and would make demand less elastic, option D is also false, and option B is about supply, not demand."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 537, $official_bank_source${"itemId":"162f3b87-d0f9-5398-983f-fe5b55b2c3c0","questionId":"18d6e0ad-4442-5de7-9659-267ac2fbbff5","sourceKey":"bank:ECO201:ELS-015","payload":{"prompt":"Along a straight-line demand curve Q = a - bP, which statement is correct?","options":["The price elasticity equals the slope at every point","The price elasticity is constant but the slope changes","The slope and the price elasticity are both constant","The slope is constant but the price elasticity changes from point to point"],"correctOption":3,"section":"Elasticity","explanation":"The term dQ/dP = -b is fixed, but elasticity also depends on P/Q, which rises as we move up the curve, so elasticity varies. Option C confuses slope with elasticity, option B reverses them, and option A ignores the P/Q factor."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 538, $official_bank_source${"itemId":"2bfb2160-28e6-5f22-834a-da1d3158f581","questionId":"40e38718-056c-5219-a2e1-6c5b3ac2bedb","sourceKey":"bank:ECO201:ELS-016","payload":{"prompt":"On a straight-line demand curve, demand is price elastic","options":["above the midpoint, towards the price axis","only at the midpoint","at every point, because the slope is constant","below the midpoint, towards the quantity axis"],"correctOption":0,"section":"Elasticity","explanation":"Near the price axis quantity is small and price is high, so P/Q is large and the elasticity exceeds 1 in magnitude; it equals 1 at the midpoint and falls towards 0 at the quantity axis. Option D is the inelastic section, option B is where elasticity is exactly unitary, and option C confuses constant slope with constant elasticity."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 539, $official_bank_source${"itemId":"60629352-b0c0-56b8-a592-6b6a05555af2","questionId":"b620837f-ef91-5a30-8942-c6241ae4ad67","sourceKey":"bank:ECO201:ELS-017","payload":{"prompt":"Two demand curves pass through the same price-quantity point. At that point, the steeper curve (price on the vertical axis) is","options":["less elastic than the flatter curve","more elastic than the flatter curve","equally elastic as the flatter curve","perfectly elastic"],"correctOption":0,"section":"Elasticity","explanation":"At a common point P/Q is the same, so elasticity depends only on dQ/dP, which is smaller in magnitude for the steeper curve. Option B reverses the relationship, and option D describes a horizontal, not a steep, curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 540, $official_bank_source${"itemId":"f7b77af6-3167-5634-8326-d08db8530cb6","questionId":"13d08cc2-d0b2-599f-bf8f-470fd39f7564","sourceKey":"bank:ECO201:ELS-018","payload":{"prompt":"The price elasticity of demand calculated over a range of prices, using average price and average quantity, is called the","options":["point elasticity of demand","cross-price elasticity of demand","arc elasticity of demand","income elasticity of demand"],"correctOption":2,"section":"Elasticity","explanation":"Arc elasticity measures responsiveness between two points on the demand curve, using the averages so the answer is the same whether price rises or falls. Option A is the elasticity at one particular point, and options B and D involve another good's price and income respectively."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 541, $official_bank_source${"itemId":"a64666e3-a8eb-5e82-8f7c-cc3fd556b71f","questionId":"0b4f0a8f-2943-5b59-8ac0-0d06301dcad1","sourceKey":"bank:ECO201:ELS-019","payload":{"prompt":"For a straight-line demand curve, which statement about the arc (midpoint) elasticity of demand between two prices is correct?","options":["It depends on whether price rises or falls between the two points","It lies somewhere between the point elasticities at the lower and higher prices","It is always larger in magnitude than both point elasticities","It is always exactly halfway between the two point elasticities"],"correctOption":1,"section":"Elasticity","explanation":"Using average price and quantity gives a value between the two point elasticities, but not necessarily exactly halfway. Option D is too strong, option C is false, and option A is exactly the problem the midpoint formula is designed to avoid."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 542, $official_bank_source${"itemId":"72687c8d-c8de-5a9c-be02-c6b596e61467","questionId":"b7b4fbf3-0b47-55b9-a35e-862416773fb1","sourceKey":"bank:ECO201:ELS-022","payload":{"prompt":"As workers in Ibadan get pay rises, many buy less garri and more rice and meat. In this case, garri is","options":["a normal good with positive income elasticity","a luxury good with income elasticity above 1","a complement of rice with negative cross-price elasticity","an inferior good with negative income elasticity"],"correctOption":3,"section":"Elasticity","explanation":"Buying less of a good as income rises means its income elasticity is negative, so garri is an inferior good here. Options A and B would require demand to rise with income, and option C confuses income elasticity with the response to another good's price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 543, $official_bank_source${"itemId":"6e857c71-3289-5e82-91d2-49f6e38eb909","questionId":"e4645f70-e069-5dba-8d33-e187ed8a634e","sourceKey":"bank:ECO201:ELS-023","payload":{"prompt":"If the cross-price elasticity of demand between two goods is positive, the goods are","options":["substitutes","independent goods","complements","inferior goods"],"correctOption":0,"section":"Elasticity","explanation":"A positive cross elasticity means a rise in the price of one good increases demand for the other, as buyers switch, which defines substitutes. Option C has a negative cross elasticity, option B has a cross elasticity of zero, and option D is about income, not other prices."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 544, $official_bank_source${"itemId":"b614d74d-fc4f-52df-b9ae-f43b54168312","questionId":"5adae820-7c91-5753-8583-b4b5deae66c4","sourceKey":"bank:ECO201:ELS-024","payload":{"prompt":"Cars and petrol are used together. The cross-price elasticity of demand for cars with respect to the price of petrol is expected to be","options":["zero, because they are independent","negative, because they are complements","positive, because they are substitutes","greater than 1, because cars are luxuries"],"correctOption":1,"section":"Elasticity","explanation":"A rise in the price of petrol makes running a car more expensive, so fewer cars are demanded, giving a negative cross elasticity, the mark of complements. Option C would apply to goods that replace each other, and option D mixes up cross elasticity with income elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 545, $official_bank_source${"itemId":"2fe9d3a3-a725-5be0-aee5-38a1e0f13b04","questionId":"f6094ea4-483e-5591-9687-1883816a6380","sourceKey":"bank:ECO201:ELS-025","payload":{"prompt":"The price elasticity of supply measures the percentage change in quantity supplied resulting from a 1 percent increase in price, and it is usually","options":["negative, because higher prices reduce output","positive, because higher prices encourage firms to produce more","zero, because supply never responds to price","equal to the price elasticity of demand"],"correctOption":1,"section":"Elasticity","explanation":"Supply curves usually slope upward, so price and quantity supplied move in the same direction and the elasticity is positive. Option A describes the sign of price elasticity of demand, and option D has no basis since supply and demand elasticities are generally different."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 546, $official_bank_source${"itemId":"a56ac7f2-bec4-59ff-9263-041a723e0de0","questionId":"91a55d93-1ea8-5d2a-b0b1-ce76100085c2","sourceKey":"bank:ECO201:ELS-026","payload":{"prompt":"For most manufactured goods, the price elasticity of supply is","options":["negative in the long run","the same in the short run and long run","greater in the long run than in the short run","greater in the short run than in the long run"],"correctOption":2,"section":"Elasticity","explanation":"In the short run firms face capacity limits, but in the long run they can build new plants and new firms can enter, so supply responds more to price. Option D is true only for special cases like recycled scrap metal, and option A contradicts the upward-sloping supply curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 547, $official_bank_source${"itemId":"f1a50261-dd6c-5b1c-bcc8-76628cd75676","questionId":"4ad1854c-b3e6-5c0e-b635-473781166c84","sourceKey":"bank:ECO201:ELS-027","payload":{"prompt":"In the short run, the number of rental flats in a city cannot change quickly whatever happens to rent. The short-run supply of rental flats is therefore","options":["unitary elastic","more elastic than in the long run","completely inelastic","perfectly elastic"],"correctOption":2,"section":"Elasticity","explanation":"If quantity supplied cannot change at all in response to rent, the supply curve is vertical and the elasticity is zero. Option D is a horizontal supply curve, and option B is wrong because building new flats over time makes long-run supply more elastic."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 548, $official_bank_source${"itemId":"dfa65c2d-d5a6-5d3a-860c-bf650e2966fc","questionId":"fa0e9add-873f-5c03-bac7-699f03548987","sourceKey":"bank:ECO201:ELS-028","payload":{"prompt":"The price of a crate of eggs rises from N100 to N110 and the quantity demanded falls from 500 to 450 crates. Using the point formula E = (dQ/Q)/(dP/P) with the initial price and quantity, the price elasticity of demand is","options":["-0.50","-10.00","-0.10","-1.00"],"correctOption":3,"section":"Elasticity","explanation":"The percentage change in quantity is -50/500 = -10 percent and the percentage change in price is 10/100 = 10 percent, so E = -10/10 = -1.00, which is unit elastic. Option C, -0.10, is only the proportional change in quantity and has not been divided by the change in price. Option B, -10.00, is the percentage change in quantity left undivided as well."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 549, $official_bank_source${"itemId":"03ab457f-a32d-5ecd-8451-b9c12910cd29","questionId":"1afee7c6-d901-53c5-9565-5b45b16f124e","sourceKey":"bank:ECO201:ELS-029","payload":{"prompt":"The price of a loaf of bread rises from N200 to N250 and the quantity demanded falls from 100 to 80 loaves. Using the arc (midpoint) formula E = (dQ/dP) x (average P / average Q), the price elasticity of demand is","options":["-0.80","-1.25","-1.00","-0.40"],"correctOption":2,"section":"Elasticity","explanation":"The change in quantity is -20 and the change in price is 50, with average price 225 and average quantity 90, so E = (-20/50)(225/90) = -0.4 x 2.5 = -1.00. Option A uses the initial values (-20 percent / 25 percent) and option B uses the new values (-25 percent / 20 percent), which is why the midpoint formula is preferred."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 550, $official_bank_source${"itemId":"df837632-14c8-5fdb-b4da-bff0f757fdc3","questionId":"734f0265-454d-56a2-913e-0483b7f1406f","sourceKey":"bank:ECO201:ELS-030","payload":{"prompt":"When the price of a bag of sachet water rises from N40 to N60, the quantity demanded falls from 1,000 to 600 bags. Using the arc (midpoint) formula E = (dQ/dP) x (average P / average Q), the price elasticity of demand is","options":["-20.00","-1.25","-0.80","-2.00"],"correctOption":1,"section":"Elasticity","explanation":"The changes are dQ = -400 and dP = 20, with averages 800 and 50, so E = (-400/20)(50/800) = -20 x 0.0625 = -1.25. Option C uses initial values (-40 percent / 50 percent), option D uses new values, and option A is just dQ/dP without the price-quantity ratio."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 551, $official_bank_source${"itemId":"e3a2932a-eb2d-5a15-90ab-0eaa0cf9b1e8","questionId":"5c9a44f5-80a2-5261-a794-1f1f6a9bf006","sourceKey":"bank:ECO201:ELS-031","payload":{"prompt":"The demand for a good is Q = 100 - 4P. Using the point formula E = (dQ/dP)(P/Q), the price elasticity of demand at P = N10 is","options":["-0.67","-0.25","-1.50","-4.00"],"correctOption":0,"section":"Elasticity","explanation":"At P = 10, Q = 100 - 40 = 60, and dQ/dP = -4, so E = -4 x (10/60) = -0.67, which is inelastic. Option D is only the slope term dQ/dP, option C inverts the ratio, and option B is simply 1/(-4), the slope of the curve with price on the vertical axis."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 552, $official_bank_source${"itemId":"4cfba2bc-24be-5983-81e5-29ede382479f","questionId":"e04670ea-1572-5354-a668-0c1580d975a7","sourceKey":"bank:ECO201:ELS-032","payload":{"prompt":"The demand for a good is Q = 100 - 4P. Using the point formula E = (dQ/dP)(P/Q), at P = N20 demand is","options":["unitary elastic, with E = -1.00","perfectly elastic","inelastic, with E = -0.25","elastic, with E = -4.00"],"correctOption":3,"section":"Elasticity","explanation":"At P = 20, Q = 100 - 80 = 20, so E = -4 x (20/20) = -4.00, whose magnitude exceeds 1. Option C inverts the calculation, and option A applies only at the midpoint of the curve, where P = 12.50."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 553, $official_bank_source${"itemId":"6fac3d0c-d8ee-5d35-a6fb-ec6092ab8649","questionId":"2db7a3ca-ac36-59dc-bdc8-d37cc11a7406","sourceKey":"bank:ECO201:ELS-033","payload":{"prompt":"The demand for a good is Q = 100 - 4P. Using the point formula E = (dQ/dP)(P/Q), at what price is demand unitary elastic?","options":["N50.00","N25.00","N6.25","N12.50"],"correctOption":3,"section":"Elasticity","explanation":"Set -4P/(100 - 4P) = -1, so 4P = 100 - 4P and P = 12.50, which is the midpoint of the linear demand curve. Option B is the price intercept where Q = 0 and elasticity is infinite, option A is the quantity at the midpoint, and option C is half the correct price."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 554, $official_bank_source${"itemId":"36f26439-136b-54c1-a4f2-9d87fc71f84e","questionId":"44ac025a-b238-5acd-a528-79ce3b018374","sourceKey":"bank:ECO201:ELS-034","payload":{"prompt":"The demand for a good is Q = 60 - 3P. Using the point formula E = (dQ/dP)(P/Q), the price elasticity of demand at P = N5 is","options":["-3.33","-3.00","-0.33","-0.11"],"correctOption":2,"section":"Elasticity","explanation":"At P = 5, Q = 60 - 15 = 45, so E = -3 x (5/45) = -0.33, which is inelastic. Option B is only the slope term dQ/dP and option D is only the ratio P/Q (5/45); the elasticity needs the two multiplied together. Option A is far too large for a point this close to the quantity axis, where demand is inelastic."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 555, $official_bank_source${"itemId":"43a6888f-9c03-51b7-85e1-796d8108c21c","questionId":"4287f882-509d-5f0a-9730-b69b38d14e00","sourceKey":"bank:ECO201:ELS-035","payload":{"prompt":"The inverse demand curve for a good is P = 50 - 0.5Q. Using the point formula E = (dQ/dP)(P/Q), the price elasticity of demand at P = N30 is","options":["-0.67","-2.00","-1.50","-0.38"],"correctOption":2,"section":"Elasticity","explanation":"Rewriting gives Q = 100 - 2P, so dQ/dP = -2; at P = 30, Q = 40 and E = -2 x (30/40) = -1.50. Option D wrongly uses dP/dQ = -0.5 in place of dQ/dP, option A inverts the answer, and option B is just dQ/dP."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 556, $official_bank_source${"itemId":"4f5c961e-698a-56ac-9f36-2801e2552516","questionId":"07ec053b-bd06-59b3-a1e7-0ffb99f5a09b","sourceKey":"bank:ECO201:ELS-036","payload":{"prompt":"A seller faces demand Q = 200 - 5P. Using the point formula E = (dQ/dP)(P/Q) and the rule that total revenue is maximised where demand is unitary elastic, the revenue-maximising price is","options":["N20","N40","N10","N100"],"correctOption":0,"section":"Elasticity","explanation":"Unitary elasticity requires 5P = 200 - 5P, so P = 20 and Q = 100, giving revenue of N2,000. Option B is the price intercept where nothing is sold, option D is the quantity at the revenue-maximising point, and option C is half the correct price."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 557, $official_bank_source${"itemId":"c0ed81e1-a5c2-591f-ac97-61f450958629","questionId":"7ad1a52e-a727-5878-b263-1152a39d6f4a","sourceKey":"bank:ECO201:ELS-037","payload":{"prompt":"A trader cuts the price of a phone case from N100 to N80, and sales rise from 50 to 70 cases. Using the arc (midpoint) formula E = (dQ/dP) x (average P / average Q), which statement is correct?","options":["E = -1.50, demand is elastic and total revenue falls by N600","E = -1.00, demand is unitary elastic and total revenue is unchanged","E = -0.67, demand is inelastic and total revenue falls by N600","E = -1.50, demand is elastic and total revenue rises by N600"],"correctOption":3,"section":"Elasticity","explanation":"With dQ = 20, dP = -20, average P = 90 and average Q = 60, E = (20/-20)(90/60) = -1.50, and revenue rises from N5,000 to N5,600. Option C inverts the elasticity and gets the revenue direction wrong, and option A forgets that a price cut raises revenue when demand is elastic."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 558, $official_bank_source${"itemId":"8697c2e1-437f-5b8e-9e8d-56c2b223659a","questionId":"a8f96661-bc39-571e-80f4-8e29172f3baf","sourceKey":"bank:ECO201:ELS-038","payload":{"prompt":"The price of a paint bucket of garri rises from N500 to N600 and the quantity demanded falls from 200 to 180 buckets. Using the point formula E = (dQ/Q)/(dP/P), using the initial price and quantity, the price elasticity of demand is","options":["-0.10","-0.20","-2.00","-0.50"],"correctOption":3,"section":"Elasticity","explanation":"Quantity falls by 20/200 = 10 percent while price rises by 100/500 = 20 percent, so E = -10/20 = -0.50, which is inelastic; total revenue rises from N100,000 to N108,000. Option C inverts the ratio, and options A and B report only one of the percentage changes as a decimal."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 559, $official_bank_source${"itemId":"496a0bf4-6e5e-592d-9bda-f938a883d973","questionId":"62d8fd53-31ca-5f35-a25a-b6291c4aaf3d","sourceKey":"bank:ECO201:ELS-039","payload":{"prompt":"The price elasticity of demand for kerosene is -0.4. Using E = (percentage change in Q)/(percentage change in P), a 10 percent rise in the price of kerosene will change the quantity demanded by","options":["-40 percent","-25 percent","-4 percent","-0.4 percent"],"correctOption":2,"section":"Elasticity","explanation":"Rearranging gives percentage change in Q = E x percentage change in P = -0.4 x 10 = -4 percent. Option B divides 10 by 0.4 instead of multiplying, and options D and A misplace the decimal point."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 560, $official_bank_source${"itemId":"b674effe-306a-56a3-b831-440c7020e040","questionId":"e49e703e-b198-5545-8e37-de01901b54fc","sourceKey":"bank:ECO201:ELS-040","payload":{"prompt":"The price of a life-saving drug rises by 30 percent but the quantity demanded does not change at all. Using E = (percentage change in Q)/(percentage change in P), the price elasticity of demand is","options":["0","infinite","-1","-30"],"correctOption":0,"section":"Elasticity","explanation":"With no change in quantity, the numerator is 0 and E = 0/30 = 0, which is completely inelastic demand shown by a vertical demand curve. Option C is unitary elasticity, and option B belongs to a horizontal, perfectly elastic demand curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 561, $official_bank_source${"itemId":"bc35dd6a-5125-5f2c-ad44-7338e2179c18","questionId":"eb65d85f-256b-5d4f-a3c0-b6af9d57a7c1","sourceKey":"bank:ECO201:ELS-041","payload":{"prompt":"In a market, demand is Qd = 120 - 2P and supply is Qs = 3P - 30. Using the point formula E = (dQ/dP)(P/Q) at the equilibrium point, the price elasticity of demand is","options":["-2.00","-1.00","-0.50","-4.00"],"correctOption":1,"section":"Elasticity","explanation":"Equilibrium is where 120 - 2P = 3P - 30, so P = 30 and Q = 60; then ED = -2 x (30/60) = -1.00, which is unit elastic. Option A is only the slope dQ/dP = -2, option D uses Q/P = 2 instead of P/Q = 0.5, and option C is just the reciprocal of the slope (1/-2)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 562, $official_bank_source${"itemId":"620e07aa-b935-524a-8d76-1fa497bf9564","questionId":"5964143e-5f05-5e64-b88e-efebf16271d5","sourceKey":"bank:ECO201:ELS-042","payload":{"prompt":"In a market, demand is Qd = 120 - 2P and supply is Qs = 3P - 30. Using the point formula E = (dQ/dP)(P/Q) at the equilibrium point, the price elasticity of supply is","options":["3.00","6.00","1.50","0.67"],"correctOption":2,"section":"Elasticity","explanation":"At equilibrium P = 30 and Q = 60, and dQs/dP = 3, so ES = 3 x (30/60) = 1.50. Option A is just the supply coefficient, option D inverts the answer, and option B uses Q/P instead of P/Q."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 563, $official_bank_source${"itemId":"8b319521-127e-5d29-9098-202691ec6628","questionId":"50bdc9ca-1fd0-5f0f-be9e-7b11e4a1ef53","sourceKey":"bank:ECO201:ELS-043","payload":{"prompt":"At the equilibrium price of N20 per unit, 100 units of a good are sold, and the point price elasticity of demand there is -0.5. If demand is linear, Q = a - bP, and the point formula ED = -b(P/Q) holds, the value of b is","options":["0.1","5","10","2.5"],"correctOption":3,"section":"Elasticity","explanation":"From -0.5 = -b(20/100) we get b = 0.5 x 5 = 2.5, and then a = 100 + 2.5 x 20 = 150, so demand is Q = 150 - 2.5P. Option C multiplies 0.5 by 20, option A is 0.5 x (20/100), which forgets to divide, and option B ignores the 0.5."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 564, $official_bank_source${"itemId":"5a4026f1-eafd-5345-8f73-75f9eac01710","questionId":"cec14686-2c11-5214-a2cd-2d56c7ef445c","sourceKey":"bank:ECO201:ELS-044","payload":{"prompt":"When a household's monthly income rises from N100,000 to N120,000, its monthly purchases of restaurant meals rise from 50 to 65. Using the point formula EI = (dQ/Q)/(dI/I) with initial values, the income elasticity and type of good are","options":["1.50; a normal good and a luxury","0.67; a normal good and a necessity","1.50; an inferior good","0.30; a normal good and a necessity"],"correctOption":0,"section":"Elasticity","explanation":"Quantity rises 15/50 = 30 percent and income rises 20,000/100,000 = 20 percent, so EI = 30/20 = 1.50, which is positive and above 1, so a luxury. Option B inverts the ratio, option C gets the right number but wrongly treats a positive value as inferior, and option D reports only the quantity change."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 565, $official_bank_source${"itemId":"c598fc5d-e686-579d-895d-15c1e7910c0d","questionId":"c986782e-d97a-503a-95dd-41c8fdf43693","sourceKey":"bank:ECO201:ELS-045","payload":{"prompt":"When a family's income rises from N200,000 to N250,000 a month, its purchases of a cheap brand of rice fall from 40 to 38 bags a year. Using the point formula EI = (dQ/Q)/(dI/I) with initial values, the income elasticity is","options":["-5.00","0.20","-0.05","-0.20"],"correctOption":3,"section":"Elasticity","explanation":"Quantity falls by 2/40 = 5 percent and income rises by 50,000/200,000 = 25 percent, so EI = -5/25 = -0.20, a negative value that marks an inferior good. Option B drops the minus sign, option A inverts the ratio, and option C reports only the quantity change."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 566, $official_bank_source${"itemId":"b79c862a-1714-5c5a-ac77-fe282fc0047e","questionId":"b5ebd52e-0159-5fcb-bc97-632e75689621","sourceKey":"bank:ECO201:ELS-046","payload":{"prompt":"When average income in a town rises from N100,000 to N140,000, the quantity of bread bought per household rises from 20 to 24 loaves a month. Using the arc (midpoint) formula EI = (dQ/dI) x (average I / average Q), the income elasticity is","options":["1.83","0.18","0.50","0.55"],"correctOption":3,"section":"Elasticity","explanation":"With dQ = 4, dI = 40,000, average Q = 22 and average I = 120,000, EI = (4/22)/(40,000/120,000) = 0.18/0.33 = 0.55, so bread is a necessity. Option C uses initial values (20 percent / 40 percent), option A inverts the answer, and option B is only the percentage change in quantity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 567, $official_bank_source${"itemId":"59c5222d-e801-5b20-8abe-01a2213231cd","questionId":"ad668104-9be2-5a6d-bdb1-c6eab4363bec","sourceKey":"bank:ECO201:ELS-047","payload":{"prompt":"The income elasticity of demand for air travel is 1.2. Using EI = (percentage change in Q)/(percentage change in income), a 5 percent rise in income will increase the quantity of air travel demanded by","options":["4.17 percent","6 percent","0.24 percent","1.2 percent"],"correctOption":1,"section":"Elasticity","explanation":"Rearranging gives percentage change in Q = 1.2 x 5 = 6 percent. Option A divides 5 by 1.2 instead of multiplying, option D just repeats the elasticity, and option C divides 1.2 by 5."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 568, $official_bank_source${"itemId":"b0459f11-925c-52f1-b6d2-bcf96352f875","questionId":"5944f85a-befb-5cde-8fdc-91b4c26527a6","sourceKey":"bank:ECO201:ELS-048","payload":{"prompt":"When the price of a bottle of Coke rises from N200 to N240, the quantity of Pepsi demanded rises from 500 to 550 bottles. Using the point formula Exy = (dQx/Qx)/(dPy/Py) with initial values, the cross-price elasticity and relationship are","options":["+2.00; complements","-0.50; complements","+0.50; complements","+0.50; substitutes"],"correctOption":3,"section":"Elasticity","explanation":"Pepsi quantity rises 50/500 = 10 percent while Coke price rises 40/200 = 20 percent, so Exy = 10/20 = +0.50, and a positive sign means substitutes. Option B gets the sign wrong, option A inverts the ratio and misreads the sign, and option C has the right number but the wrong relationship."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 569, $official_bank_source${"itemId":"69cf9537-b7af-51ad-8062-9ef53bfc0e9d","questionId":"3cac0fe9-6aa5-58e1-9d8f-d679f8113acc","sourceKey":"bank:ECO201:ELS-049","payload":{"prompt":"When the price of petrol rises from N600 to N720 per litre, the number of cars bought in a city falls from 1,000 to 900. Using the point formula Exy = (dQx/Qx)/(dPy/Py) with initial values, the cross-price elasticity of demand for cars with respect to the petrol price is","options":["-2.00","-0.50","-0.10","0.50"],"correctOption":1,"section":"Elasticity","explanation":"Car purchases fall 100/1,000 = 10 percent while petrol price rises 120/600 = 20 percent, so Exy = -10/20 = -0.50, showing the goods are complements. Option D drops the negative sign, option A inverts the ratio, and option C reports only the change in quantity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 570, $official_bank_source${"itemId":"09c78e7c-e551-5749-a2a4-e0c2467f3ee8","questionId":"759c6818-5316-5a16-ad2a-e1e1ca88328b","sourceKey":"bank:ECO201:ELS-050","payload":{"prompt":"When the price of printers rises from N50,000 to N70,000, the quantity of ink cartridges demanded falls from 300 to 240. Using the arc (midpoint) formula Exy = (dQx/dPy) x (average Py / average Qx), the cross-price elasticity is","options":["-0.67","0.67","-1.50","-0.50"],"correctOption":0,"section":"Elasticity","explanation":"With dQx = -60, dPy = 20,000, average Qx = 270 and average Py = 60,000, Exy = (-60/270)/(20,000/60,000) = -0.22/0.33 = -0.67, so printers and cartridges are complements. Option D uses initial values, option B drops the sign, and option C inverts the ratio."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 571, $official_bank_source${"itemId":"3d0b03b3-5703-5159-8d10-77ab33b0e5f0","questionId":"46e8a2e4-e534-562b-b41f-57b58bb22ae4","sourceKey":"bank:ECO201:ELS-051","payload":{"prompt":"The cross-price elasticity of demand for chicken with respect to the price of beef is 0.8. Using Exy = (percentage change in Qx)/(percentage change in Py), a 15 percent rise in the price of beef will change the quantity of chicken demanded by","options":["+0.8 percent","-12 percent","+12 percent","+18.75 percent"],"correctOption":2,"section":"Elasticity","explanation":"Percentage change in chicken demanded = 0.8 x 15 = +12 percent, and the positive cross elasticity means beef and chicken are substitutes. Option B has the wrong sign, option D divides 15 by 0.8, and option A just repeats the elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 572, $official_bank_source${"itemId":"9e578479-e3b6-5c6d-9c55-6375e569efe0","questionId":"21b5370e-da9a-5c8e-b78b-859c06f9a565","sourceKey":"bank:ECO201:ELS-052","payload":{"prompt":"When the price of tomatoes rises from N50 to N60 per kg, the quantity supplied rises from 200 kg to 260 kg. Using the point formula Es = (dQ/Q)/(dP/P) with initial values, the price elasticity of supply is","options":["0.67","6.00","1.50","0.30"],"correctOption":2,"section":"Elasticity","explanation":"Quantity supplied rises 60/200 = 30 percent while price rises 10/50 = 20 percent, so Es = 30/20 = 1.50, which is elastic supply. Option A inverts the ratio, option B uses absolute changes 60/10 without converting to percentages, and option D reports only the quantity change."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 573, $official_bank_source${"itemId":"a0b71160-9592-5709-8fc3-891f4c0be456","questionId":"9059fcac-8484-5fe7-98f8-4d1ad3edf4a3","sourceKey":"bank:ECO201:ELS-053","payload":{"prompt":"When the price of a carton of fish rises from N10,000 to N14,000, the quantity supplied rises from 100 to 120 cartons. Using the arc (midpoint) formula Es = (dQ/dP) x (average P / average Q), the price elasticity of supply is","options":["0.50","0.55","1.83","0.18"],"correctOption":1,"section":"Elasticity","explanation":"With dQ = 20, dP = 4,000, average Q = 110 and average P = 12,000, Es = (20/110)/(4,000/12,000) = 0.18/0.33 = 0.55, so supply is inelastic. Option A uses initial values (20 percent / 40 percent), option C inverts the answer, and option D is only the percentage change in quantity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 574, $official_bank_source${"itemId":"de067762-2a9f-552a-bbec-f8cbd4f2376e","questionId":"5c3f2d3e-67d1-5d5c-ac88-5dd4f07aba77","sourceKey":"bank:ECO201:ELS-054","payload":{"prompt":"The supply of a good is Qs = -20 + 4P. Using the point formula Es = (dQ/dP)(P/Q), the price elasticity of supply at P = N10 is","options":["2.00","4.00","1.00","0.50"],"correctOption":0,"section":"Elasticity","explanation":"At P = 10, Qs = -20 + 40 = 20 and dQ/dP = 4, so Es = 4 x (10/20) = 2.00. Option B is only the slope term, option D inverts the answer, and option C would hold only for a straight-line supply curve through the origin."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 575, $official_bank_source${"itemId":"d989ad3e-174d-553d-9c8e-765f5ad60121","questionId":"e4b4cf04-acdf-5c60-89e0-bc783d289134","sourceKey":"bank:ECO201:ELS-055","payload":{"prompt":"The price elasticity of supply of maize is 0.5. Using Es = (percentage change in Qs)/(percentage change in P), a 20 percent rise in the price of maize will raise the quantity supplied by","options":["10 percent","40 percent","0.5 percent","20 percent"],"correctOption":0,"section":"Elasticity","explanation":"Percentage change in quantity supplied = 0.5 x 20 = 10 percent, so supply is inelastic. Option B divides 20 by 0.5 instead of multiplying, option D assumes unit elasticity, and option C simply repeats the elasticity."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 576, $official_bank_source${"itemId":"ea33666f-6b68-5b55-bcc8-4c6f868a61c5","questionId":"dd23e4db-bdd8-5860-9121-b26d49708aaa","sourceKey":"bank:ECO201:E201-0104","payload":{"prompt":"The marginal product of labor is equal to","options":["the additional labor required to produce one more unit of output.","average product when average product is at a minimum.","the additional output produced by hiring one more unit of labor.","the slope of a ray drawn from the origin to a point on the total product curve."],"correctOption":2,"section":"Short-run Production","explanation":"The marginal product of labour is the extra output produced when one more unit of labour is employed, holding other inputs fixed: MPL = change in TP / change in L. Option A turns the ratio upside down (labour per unit of output), and option D describes the average product, which is the slope of a ray from the origin to the TP curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 577, $official_bank_source${"itemId":"269e2cee-0478-5f3e-8e00-9f9f90a55202","questionId":"26a7a2ea-8ea4-55f9-af42-9cf09a49ab21","sourceKey":"bank:ECO201:E201-0105","payload":{"prompt":"The average product of labor is equal to","options":["the additional labor required to produce one more unit of output.","marginal product when average product is at a minimum.","the additional output produced by hiring one more unit of labor.","the slope of a ray drawn from the origin to a point on the total product curve."],"correctOption":3,"section":"Short-run Production","explanation":"Average product of labour is TP/L, and that is exactly the slope of a straight line (ray) drawn from the origin to a point on the TP curve. Option C is the definition of marginal product, and option B is wrong because MP equals AP where AP is at its maximum, not its minimum."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 578, $official_bank_source${"itemId":"54760426-471a-5976-a676-f0bbd93b1b1c","questionId":"c55e8123-46f0-5ff1-a874-21948fe21e07","sourceKey":"bank:ECO201:E201-0106","payload":{"prompt":"The output elasticity of labor is","options":["equal to one at the level of output where average product is at a maximum.","the percentage change in labor required to produce one more unit of output.","equal to the ratio of total product to the quantity of labor employed.","a measure of the percentage change in output that can result when the quantity of labor is held constant."],"correctOption":0,"section":"Short-run Production","explanation":"Output elasticity of labour is the percentage change in output divided by the percentage change in labour, which simplifies to MP/AP. Where AP is at its maximum, MP = AP, so the elasticity equals one. Option C describes average product itself, and option D is impossible because output cannot be changed by labour if labour is held constant."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 579, $official_bank_source${"itemId":"5f79c649-2825-51ac-af7c-ad25cd8b4f2f","questionId":"6373e27a-5446-5f60-8138-73b9fef7c93a","sourceKey":"bank:ECO201:E201-0107","payload":{"prompt":"The point of inflection on the total product curve corresponds to the level of output where","options":["Stage II of production begins.","average product is at a maximum.","marginal product is at a maximum.","All of the above are correct."],"correctOption":2,"section":"Short-run Production","explanation":"At the point of inflection the TP curve stops rising at an increasing rate and starts rising at a decreasing rate, so its slope, the marginal product, is at its maximum there. Options A and B are wrong because AP reaches its maximum, and Stage II begins, at a larger output where MP falls to meet AP, so D is also wrong."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 580, $official_bank_source${"itemId":"9ae3b53e-7092-54c7-bd66-184df99061a4","questionId":"22f76ee9-b59a-5c74-96e6-9ad4899d5854","sourceKey":"bank:ECO201:E201-0108","payload":{"prompt":"The law of diminishing returns","options":["is reflected in the negatively sloped portion of the marginal product curve.","is the result of specialization and division of labor.","applies in both the short run and the long run.","All of the above are correct."],"correctOption":0,"section":"Short-run Production","explanation":"The law of diminishing returns says that as more of a variable input is added to fixed inputs, marginal product eventually falls, which is the downward-sloping part of the MP curve. Option B is wrong because specialisation and division of labour explain rising returns, not diminishing ones, and option C is wrong because the law needs at least one fixed input, so it is a short-run law only."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 581, $official_bank_source${"itemId":"0f7d87de-a0ad-54d5-bd43-49ecb6bdaaa8","questionId":"56c3724b-8c34-56e8-ba30-fe5ed0fc5a19","sourceKey":"bank:ECO201:E201-0126","payload":{"prompt":"Which of the following best describes a production function?","options":["An equation, table or graph showing the maximum output that can be produced from different combinations of inputs, given technology","A graph showing all combinations of two inputs that cost the same amount","A list of the prices the firm pays for each of its inputs","A schedule showing the total cost of producing each level of output"],"correctOption":0,"section":"Short-run Production","explanation":"A production function is a purely technical relationship: it shows the maximum output obtainable from each combination of inputs with the existing technology. Options D and C bring in costs and prices, which belong to cost analysis, and option B describes an isocost line, not a production function."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 582, $official_bank_source${"itemId":"9698785d-7e5c-5001-8604-fa13e1eed5ef","questionId":"bbe515a1-f351-51eb-bafb-6673611698cb","sourceKey":"bank:ECO201:E201-0128","payload":{"prompt":"Which of the following correctly describes a fixed input?","options":["An input whose price never changes","An input whose quantity cannot be changed within the period under consideration (the short run)","An input that can never be changed, even in the long run","An input whose quantity rises and falls directly with output"],"correctOption":1,"section":"Short-run Production","explanation":"A fixed input, such as factory buildings, cannot be varied within the short run, but it can be changed in the long run. Option C is wrong because in the long run all inputs become variable, option D describes a variable input, and option A confuses a fixed quantity with a fixed price."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 583, $official_bank_source${"itemId":"1147713b-4d54-58cb-9f82-c15e714e8448","questionId":"9812117b-abf6-5062-a3a8-44d4cbd71a71","sourceKey":"bank:ECO201:E201-0134","payload":{"prompt":"The output elasticity of an input is equal to","options":["the marginal product of the input multiplied by its price","the average product of the input divided by its marginal product","the marginal product of the input divided by its average product","the change in output divided by the change in the input"],"correctOption":2,"section":"Short-run Production","explanation":"Output elasticity is (% change in Q)/(% change in L) = (change in Q / change in L) x (L/Q), which is MP x 1/AP = MP/AP. Option B is the inverse, and option D is just the marginal product, which ignores the percentage form."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 584, $official_bank_source${"itemId":"5f46ce85-3df6-55bb-9174-bc253a618f1e","questionId":"6fed5f41-cd72-5961-aa94-cd90ec1780f9","sourceKey":"bank:ECO201:E201-0135","payload":{"prompt":"The law of diminishing returns is","options":["the same thing as decreasing returns to scale","a short-run concept, because it requires at least one input to be fixed","a long-run concept, because all inputs are varied together","a law that applies only when all inputs are increased in the same proportion"],"correctOption":1,"section":"Short-run Production","explanation":"Diminishing returns arise because more and more of a variable input is combined with a fixed input, so the law belongs to the short run. Options C and D describe changing all inputs together, which is about returns to scale, and option A confuses diminishing returns to a factor with decreasing returns to scale."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 585, $official_bank_source${"itemId":"420bcc15-da48-5f12-9624-3beb2f7d4426","questionId":"204da369-7062-5f44-a793-4a0df8c77afb","sourceKey":"bank:ECO201:E201-0138","payload":{"prompt":"When the marginal product of a variable input is less than its average product, the average product is","options":["equal to zero","falling","at its maximum","rising"],"correctOption":1,"section":"Short-run Production","explanation":"Whenever the marginal unit adds less than the current average, it pulls the average down, so AP is falling when MP < AP. Option D applies when MP > AP, and option C applies only at the single point where MP = AP."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 586, $official_bank_source${"itemId":"99357a0c-be1b-5759-a993-8987a80714a8","questionId":"8b925787-d75e-561d-bd40-e5f2b9657be0","sourceKey":"bank:ECO201:E201-0140","payload":{"prompt":"Stage II of production begins and ends, respectively, where","options":["total product is at a maximum, and marginal product is at a maximum","average product equals zero, and total product is at a maximum","average product is at a maximum, and marginal product equals zero","marginal product is at a maximum, and average product equals zero"],"correctOption":2,"section":"Short-run Production","explanation":"Stage II starts where AP reaches its peak (where MP = AP) and ends where MP falls to zero, which is also where TP is at its maximum. Option D is wrong because MP peaks earlier, inside Stage I, and option A gets the end of the stage confused with its start."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 587, $official_bank_source${"itemId":"c53f4c95-8a42-58ec-9599-beecb1e05058","questionId":"2305a2ac-f81b-5382-9dfc-0a4102055a02","sourceKey":"bank:ECO201:E201-0317","payload":{"prompt":"The marginal product of labour curve shows the change in total product resulting from a:","options":["One-unit increase in the quantity of a particular resource used, letting other resources vary.","One-unit increase in the quantity of a particular resource used, holding constant other resources.","Change in the cost of a variable resource.","Change in the cost of a fixed resource."],"correctOption":1,"section":"Short-run Production","explanation":"Marginal product measures the extra output from adding one more unit of an input while all other inputs are held constant. Option A is wrong because letting other inputs vary would mix in their contribution. Options C and D are about costs, not physical output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 588, $official_bank_source${"itemId":"11deebef-278c-548f-8318-97e690968586","questionId":"65872156-f587-5d94-9251-c88df101bf9d","sourceKey":"bank:ECO201:E201-0318","payload":{"prompt":"When the total product curve is falling, the:","options":["Marginal product of labor is zero.","Marginal product of labor is negative.","Average product of labor is increasing.","Average product of labor must be negative ."],"correctOption":1,"section":"Short-run Production","explanation":"Marginal product is the change in total product from one more unit of labour. If total product is falling, each extra worker reduces output, so marginal product is negative. Option A is true only at the very top of the total product curve, and option D is wrong because average product stays positive as long as total product is positive."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 589, $official_bank_source${"itemId":"cbf5ec1d-efdb-5ef8-861f-023dc1435118","questionId":"3f08b231-449e-5241-a5e4-c4f1a9487572","sourceKey":"bank:ECO201:E201-0319","payload":{"prompt":"When marginal product reaches its maximum, what can be said of total product?","options":["Total product must be at its maximum","Total product starts to decline even if marginal product is positive","Total product is increasing if marginal product is still positive","Total product levels off"],"correctOption":2,"section":"Short-run Production","explanation":"When marginal product reaches its maximum, it is still positive, so total product is still rising, and in fact rising at its fastest rate (the inflection point of the TP curve). Option A is wrong because TP is at its maximum only when MP falls to zero, and option D is wrong for the same reason."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 590, $official_bank_source${"itemId":"3f5eff6f-3172-5760-9bcc-c73b4db3220b","questionId":"2bb58397-9fff-5e0c-b49b-f2004284ea68","sourceKey":"bank:ECO201:E201-0334","payload":{"prompt":"Which of the following statements best describes the general form of a production function: (i) It is a purely technological relationship between quantities of input and quantities of output. (ii) It represents the technology of an organisation, sector of an economy. iii) Prices of inputs or of the output do not enter into the production function. (iv) It is a flow concept describing the transformation of inputs into output per unit of time.","options":["(i),(ii) and (iv)","(i) and (ii)","(i) and (iv)","All of the above"],"correctOption":3,"section":"Short-run Production","explanation":"A production function is a purely technical relationship showing the maximum output obtainable from given inputs with a given state of technology. It can describe a firm, an industry or a whole economy, it contains no prices, and it is a flow measured per period of time. All four statements are therefore correct, so options A, B and C each leave out a true statement."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 591, $official_bank_source${"itemId":"ba813474-446d-5609-90d4-bdc3d70c0ff5","questionId":"230668fe-bd0a-57ab-8c30-77880ebffa94","sourceKey":"bank:ECO201:E201-0335","payload":{"prompt":"Which of the following statements describes the presence of diminishing returns. Holding at least one factor constant .......","options":["The marginal product of a factor is positive and rising.","The marginal product of a factor is positive but falling.","The marginal product of a factor is falling and negative.","The marginal product of a factor is constant."],"correctOption":1,"section":"Short-run Production","explanation":"Diminishing returns describes the stage where each extra unit of the variable factor still adds to output, but by less and less, so marginal product is positive but falling. Option A describes increasing returns, and option D constant returns. Option C goes beyond diminishing returns to negative returns, where adding the factor actually reduces total output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 592, $official_bank_source${"itemId":"da377922-50b1-5aa9-9749-5c72cb367780","questionId":"2b4b4b41-fe24-5380-b0b4-c541d31129a6","sourceKey":"bank:ECO201:E201-0338","payload":{"prompt":"A basic distinction between the long run and the short run is that","options":["If a firm produces no output in the long run it still incurs a cost, while in the short run a firm incurs a cost only if it produces output.","The opportunity costs of production are constant in the short run, while the opportunity costs of production are variable in the long run.","In the long run some inputs are fixed, while in the short run all inputs are variable.","In the short run complete adjustment of all inputs is impossible, while in the long run all inputs can be adjusted."],"correctOption":3,"section":"Short-run Production","explanation":"The short run is a period in which at least one input cannot be changed, while in the long run the firm has enough time to adjust every input. Option C has this backwards, and option A is also reversed, since fixed costs that must be paid even at zero output exist only in the short run."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 593, $official_bank_source${"itemId":"2bf53ff2-0e32-549c-8fb5-0978e4e08e23","questionId":"4c1014c1-79e1-5eba-8288-b0b85e60be51","sourceKey":"bank:ECO201:E201-0339","payload":{"prompt":"Whenever marginal product is positive but declining with increasing use of an input,","options":["Total product is declining as input increases.","Average product is declining as input use increases","Marginal product is greater than average product","Total product is increasing at a decreasing rate as input use increases."],"correctOption":3,"section":"Short-run Production","explanation":"As long as marginal product is positive, each extra unit of input still adds to total product, so TP keeps rising; if MP is falling, each addition is smaller, so TP rises at a decreasing rate. Option B is not always true, because average product keeps rising while MP is still above AP, and option C is not guaranteed either."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 594, $official_bank_source${"itemId":"d3897833-b604-5a22-ba0a-eb36733ecf25","questionId":"2ad2b993-a607-5096-b8d9-8ba5df87274a","sourceKey":"bank:ECO201:E201-0341","payload":{"prompt":"When average product is at a maximum, marginal product is","options":["Zero","Increasing","Equal to average product","Greater than average product"],"correctOption":2,"section":"Short-run Production","explanation":"Marginal product cuts average product at the highest point of the AP curve. While MP is above AP it pulls AP up, and once MP falls below AP it pulls AP down, so at the peak MP = AP. Option A is wrong because MP is zero where total product, not average product, is at a maximum, and option B is wrong because MP is already falling at that point."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 595, $official_bank_source${"itemId":"fd78583e-5903-5a72-bcc5-d8f267317cbf","questionId":"eb1311a6-58e0-5f8e-8868-f40c35f6bb80","sourceKey":"bank:ECO201:E201-0342","payload":{"prompt":"Whenever average product is declining, with increases in input usage,","options":["Marginal product is less than average product","Total product is declining with increases in input","Total product is increasing with increases in input","Marginal product is greater than average product"],"correctOption":0,"section":"Short-run Production","explanation":"An average falls only when the marginal addition is below it, so whenever average product is declining, marginal product must be less than average product. Option B is not necessarily true: total product keeps rising after AP starts falling, as long as MP is still positive. Option D describes the stage when AP is rising."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 596, $official_bank_source${"itemId":"9edd4716-a136-5cab-af1e-191c11e6f51a","questionId":"0aac85af-d456-550d-9297-205f344eb933","sourceKey":"bank:ECO201:E201-0343","payload":{"prompt":"The total product curve may initially show output increasing at an increasing rate as more labour is hired because of the:","options":["Declining quality of the labor force.","Principle of comparative advantage.","Law of diminishing marginal returns.","Increase in marginal physical product."],"correctOption":3,"section":"Short-run Production","explanation":"In the early stage of production, adding workers allows better division of labour and fuller use of the fixed input, so each extra worker adds more than the previous one. This rising marginal physical product makes total product grow at an increasing rate. Option C, diminishing marginal returns, explains the later stage when TP grows at a decreasing rate."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 597, $official_bank_source${"itemId":"3f802889-c346-5eb2-b1dd-0cd3671e2cd2","questionId":"f328578d-b0f6-526b-8d7b-f0f252b80412","sourceKey":"bank:ECO201:E201-0345","payload":{"prompt":"When both average and total product are greater than zero, and marginal product equals average product, then total product:","options":["Is at a maximum.","Is positive and rising.","Is falling.","Is negative but rising."],"correctOption":1,"section":"Short-run Production","explanation":"Marginal product equals average product at the maximum point of the AP curve. At that point MP is still positive (because AP is positive), so total product is positive and still rising. Option A is wrong because TP is at its maximum only where MP = 0, which comes later."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 598, $official_bank_source${"itemId":"5196bbed-7c6e-5554-a82b-1b10455118db","questionId":"926ed153-ae48-5e66-8850-9ebb9c552097","sourceKey":"bank:ECO201:E201-0347","payload":{"prompt":"The law of diminishing marginal returns is encountered as increasing amounts of labour are hired because:","options":["As production rises, the additional labor hired is less and less skilled.","Experienced workers are hired before the less skilled.","Each extra worker hired decreases the amounts of land and capital per worker, so the work place becomes more congested and managerial control becomes more difficult.","As more and more is produced, selling it requires cutting prices."],"correctOption":2,"section":"Short-run Production","explanation":"Diminishing returns arise because the other inputs are fixed: each extra worker has less land and capital to work with, so the work place becomes crowded and harder to manage, and each addition to output gets smaller. Options A and B are wrong because the law assumes all units of labour are equally skilled, and option D is about selling prices, not physical output."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 599, $official_bank_source${"itemId":"80110412-427f-5cf6-b202-476386603dac","questionId":"0598a43f-3a43-551b-9538-ffb2b96dc941","sourceKey":"bank:ECO201:SRP-002","payload":{"prompt":"In production theory, the short run is best defined as a period in which","options":["the firm operates for less than one calendar year","technology changes while all inputs stay fixed","at least one factor of production is fixed in quantity","all factors of production can be varied"],"correctOption":2,"section":"Short-run Production","explanation":"The short run is defined by how flexible inputs are, not by calendar time: it is any period in which at least one input, such as plant or machinery, cannot be changed. Option D describes the long run, and Option A is wrong because the short run is not a set number of months; its length depends on how quickly the firm can change its fixed inputs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 600, $official_bank_source${"itemId":"f54b6799-ce16-57c7-8d9e-07737897d9ca","questionId":"7c1fd936-6848-5448-a69a-0628fa71233e","sourceKey":"bank:ECO201:SRP-003","payload":{"prompt":"A bakery in Yaba can hire extra bakers within a week, but it would take more than a year to build and equip a new bakery hall. In the short run, the bakery hall is an example of a","options":["intermediate input","variable input","fixed input","substitute input"],"correctOption":2,"section":"Short-run Production","explanation":"An input whose quantity cannot be changed within the period being considered is a fixed input, and the bakery hall fits this because it takes over a year to change, so C is right. Option B describes the bakers, who can be added quickly, and Option A refers to goods such as flour that are used up in making the bread."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 601, $official_bank_source${"itemId":"7f00f9f7-4715-5563-b34b-08e36503a76d","questionId":"445ece1c-34e1-5ff9-afd9-e75c0bb63a61","sourceKey":"bank:ECO201:SRP-004","payload":{"prompt":"Which of the following is most likely to be a variable input in the short run for a garri-processing factory in Ogun State?","options":["The installed grating machine","The land on which the factory stands","The factory building","Cassava tubers bought each day"],"correctOption":3,"section":"Short-run Production","explanation":"A variable input is one the firm can increase or reduce quickly as it changes output, and the daily purchase of cassava tubers fits this, so D is correct. Options C, A and B are buildings, installed machinery and land, which cannot be changed quickly and are therefore fixed inputs in the short run."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 602, $official_bank_source${"itemId":"3d4fbcbe-6877-5f46-8814-4ecff2e210ae","questionId":"454ccfd3-7498-5246-8cba-9cc3a1835d0b","sourceKey":"bank:ECO201:SRP-005","payload":{"prompt":"The change in total product resulting from employing one additional unit of a variable input, with all other inputs held constant, is called the","options":["total product","average product","marginal rate of technical substitution","marginal product"],"correctOption":3,"section":"Short-run Production","explanation":"Marginal product measures the extra output from one more unit of the variable input, MP = change in TP / change in L, so D is right. Option B is output per unit of input (TP/L), and Option C is the rate at which one input can replace another while output stays the same, which is an isoquant idea, not a single-input one."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 603, $official_bank_source${"itemId":"b5da1c69-5531-5884-b792-603f9a75f1bc","questionId":"28d105e6-7e90-5e58-b1a8-2edd671532e1","sourceKey":"bank:ECO201:SRP-006","payload":{"prompt":"The average product of labour (APL) is calculated as","options":["total product divided by the number of units of labour","change in total product divided by change in labour","number of units of labour divided by total product","total product multiplied by the number of units of labour"],"correctOption":0,"section":"Short-run Production","explanation":"Average product is output per unit of the variable input, APL = TP/L, so A is correct. Option B is the formula for marginal product, and Option C turns the ratio upside down, giving labour per unit of output instead of output per worker."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 604, $official_bank_source${"itemId":"af45444f-f54d-5057-af45-fd3126641fa4","questionId":"b99c9224-af4c-5bdf-8236-d0a112f6b2f8","sourceKey":"bank:ECO201:SRP-007","payload":{"prompt":"When the marginal product of labour is greater than the average product of labour, the average product of labour is","options":["at its maximum","rising","falling","equal to zero"],"correctOption":1,"section":"Short-run Production","explanation":"If the extra output from the next worker is above the current average, adding that worker pulls the average up, so AP is rising and B is right. Option C happens when MP is below AP, and Option A happens only at the point where MP exactly equals AP."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 605, $official_bank_source${"itemId":"745343c9-f6ee-53d4-a76d-9f63a811287c","questionId":"7c01f59c-2106-5f88-a424-02ad5fa9ad52","sourceKey":"bank:ECO201:SRP-009","payload":{"prompt":"Total product of a variable input reaches its maximum when the marginal product of that input is","options":["equal to the average product","zero","equal to one","at its maximum"],"correctOption":1,"section":"Short-run Production","explanation":"TP keeps rising as long as MP is positive and starts falling once MP turns negative, so TP peaks exactly where MP = 0 and B is right. Option D marks the point of inflection of TP, where diminishing marginal returns begin, and Option A marks the maximum of AP, not of TP."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 606, $official_bank_source${"itemId":"6967fc71-3c15-54c6-b351-8d3d550dd070","questionId":"12143cad-d739-5887-9059-38bcf2266e03","sourceKey":"bank:ECO201:SRP-010","payload":{"prompt":"A cocoa farmer in Ondo keeps adding workers to the same plot until an extra worker actually causes total output to fall. The marginal product of that extra worker is","options":["equal to the average product","zero","positive but falling","negative"],"correctOption":3,"section":"Short-run Production","explanation":"Marginal product is the change in total output from one more worker, so if output falls the change is below zero and MP is negative, making D correct. Option B would mean output stayed exactly the same, and Option C would mean output still rose, only by less than before."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 607, $official_bank_source${"itemId":"cfe15fa9-a1c5-5771-8637-cd967206cada","questionId":"fe964ca4-12f9-515e-8611-17eb732bf1ba","sourceKey":"bank:ECO201:SRP-011","payload":{"prompt":"The law of diminishing marginal returns states that as more units of a variable input are added to a fixed input, with technology unchanged,","options":["total product eventually becomes zero","the marginal product of the variable input eventually declines","the average cost of production always falls","output increases in the same proportion as the input"],"correctOption":1,"section":"Short-run Production","explanation":"The law says that beyond some point each extra unit of the variable input adds less to output than the one before, because it has less of the fixed input to work with, so B is right. Option A is wrong because TP falls only if MP becomes negative and need not reach zero, and Option D describes a constant marginal product, which is the opposite of what the law predicts."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 608, $official_bank_source${"itemId":"eda648dc-b1a2-59ef-a62c-6d5c3458f27f","questionId":"f9d58ebf-720c-546a-80a1-128f65786b75","sourceKey":"bank:ECO201:SRP-012","payload":{"prompt":"Which of the following is NOT an assumption of the law of variable proportions?","options":["At least one input is held fixed","Units of the variable input are homogeneous","The state of technology is given","All inputs are increased in the same proportion"],"correctOption":3,"section":"Short-run Production","explanation":"The law of variable proportions is a short-run law in which only one input changes while others stay fixed, so increasing all inputs in the same proportion is not one of its assumptions; that is returns to scale, and D is the answer. Options C, A and B are genuine assumptions: given technology, at least one fixed factor and identical units of the variable factor."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 609, $official_bank_source${"itemId":"42ddb7cd-599f-5258-a7ac-9759a248ee6a","questionId":"65a851ca-5727-58af-86e0-14c38fc3ccf2","sourceKey":"bank:ECO201:SRP-013","payload":{"prompt":"In the three stages of production, Stage I extends from the origin to the point where","options":["the average product of the variable input is at its maximum","total product is at its maximum","the marginal product of the variable input becomes zero","the marginal product of the variable input is at its maximum"],"correctOption":0,"section":"Short-run Production","explanation":"Stage I is the range over which average product is rising, so it ends where AP reaches its peak and MP = AP, making A correct. Option D is a point inside Stage I where diminishing marginal returns begin, while Options B and C mark the end of Stage II, where MP = 0 and TP is at its maximum."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 610, $official_bank_source${"itemId":"c61f5457-04c4-5dfa-9ae4-6ab577acc17a","questionId":"4f9c4786-38e9-5f4f-bc55-2f9395be7a71","sourceKey":"bank:ECO201:SRP-014","payload":{"prompt":"Stage III of production is the range in which","options":["the marginal product exceeds the average product","the average product of the variable input is rising","total product is rising at an increasing rate","the marginal product of the variable input is negative"],"correctOption":3,"section":"Short-run Production","explanation":"Stage III begins once MP falls below zero, so each extra unit of the variable input reduces total output; D is correct. Options B and A describe Stage I, where AP is still rising because MP is above it, and Option C describes the early part of Stage I where MP is rising."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 611, $official_bank_source${"itemId":"3ee67dba-02f5-58bc-a345-613270ce0355","questionId":"8b1a096b-d886-55d0-8b45-e22de1b1fe93","sourceKey":"bank:ECO201:SRP-015","payload":{"prompt":"A rational producer will choose to operate in which stage of production?","options":["Stage I, where AP is rising","Stage III, where MP is negative","Stage II, between maximum AP and zero MP","At the point where MP is at its maximum"],"correctOption":2,"section":"Short-run Production","explanation":"Stage II is the economic region: AP is falling but MP is still positive, so extra units still add to output, and C is correct. Option A is irrational because output per unit of input can still be raised by using more of the variable input, Option B is irrational because extra units cut output, and Option D lies inside Stage I."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 612, $official_bank_source${"itemId":"713aa44d-7cfb-5d3b-ba11-99d0f4514664","questionId":"78d8afe1-e478-50fb-a443-51d28ccfc1b0","sourceKey":"bank:ECO201:SRP-016","payload":{"prompt":"A firm would never knowingly operate in Stage III because in that stage","options":["the marginal product of the variable input is at its maximum","the average product of the variable input is still rising","adding more of the variable input reduces total output","the fixed input is being under-used"],"correctOption":2,"section":"Short-run Production","explanation":"In Stage III the marginal product of the variable input is negative, so the firm would pay for extra units that actually lower output; C is correct. Option B describes Stage I, Option A is a point inside Stage I, and Option D is also a Stage I feature, since in Stage III the fixed input is overcrowded rather than under-used."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 613, $official_bank_source${"itemId":"135c8d2d-7b67-5b08-a885-f9153b07498a","questionId":"5493afd3-b7c9-5b74-be15-10435325878b","sourceKey":"bank:ECO201:SRP-017","payload":{"prompt":"Stage I of production is considered irrational for a producer mainly because","options":["average product of the variable input is still rising, so using more of it raises output per unit","the marginal product of the variable input is negative","total product is falling","the variable input is used too intensively relative to the fixed input"],"correctOption":0,"section":"Short-run Production","explanation":"In Stage I the average product of the variable input is still rising, so the firm can raise output per unit of that input by using more of it, and stopping there wastes the fixed input; A is right. Options B and C describe Stage III, and Option D is the problem of Stage III too, where the fixed input is overcrowded."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 614, $official_bank_source${"itemId":"63b0952b-e265-50a1-8ef5-d0c9ecf6d94c","questionId":"89550353-dbaf-597b-9c34-13b5ac8ed11b","sourceKey":"bank:ECO201:SRP-018","payload":{"prompt":"Over the range where the marginal product of labour is rising, the total product curve is","options":["decreasing","horizontal","increasing at an increasing rate","increasing at a decreasing rate"],"correctOption":2,"section":"Short-run Production","explanation":"Rising MP means each extra worker adds more output than the last, so TP climbs more and more steeply, which is C. Option D applies once MP is falling but still positive, Option A applies only when MP is negative, and Option B applies only where MP is zero."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 615, $official_bank_source${"itemId":"b568648b-34b4-535d-a85d-340746932c86","questionId":"3c872a85-c5f7-5a5a-b087-34ae7845bcaa","sourceKey":"bank:ECO201:SRP-019","payload":{"prompt":"On a total product curve, the marginal product at any point is measured by","options":["the slope of a straight line from the origin to that point","the slope of the TP curve at that point","the area under the TP curve up to that point","the height of the TP curve at that point"],"correctOption":1,"section":"Short-run Production","explanation":"MP is the change in TP per unit change in input, which is the slope of the TP curve at that point, so B is correct. Option A measures average product, because the slope of a ray from the origin equals TP/L, and Option D is simply total product itself."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 616, $official_bank_source${"itemId":"553845b1-d06c-5128-adec-7ff42f18622c","questionId":"98037804-8262-53bd-9b26-94ad82c9c922","sourceKey":"bank:ECO201:SRP-020","payload":{"prompt":"The main difference between the law of variable proportions and returns to scale is that","options":["the former applies to the long run, while the latter applies to the short run","the former assumes changing technology, while the latter assumes fixed technology","the former varies one input with others fixed, while the latter varies all inputs in the same proportion","the former concerns costs, while the latter concerns revenue"],"correctOption":2,"section":"Short-run Production","explanation":"The law of variable proportions is a short-run law about changing one input while others stay fixed, whereas returns to scale is a long-run idea about changing all inputs together in the same proportion, so C is right. Option A reverses the time periods, and Option B is wrong because both concepts assume a given technology."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 617, $official_bank_source${"itemId":"7824a96e-d4fe-515a-9f3d-9f0427342d3a","questionId":"30d13baa-c6ac-5c72-9d41-365c1482e45b","sourceKey":"bank:ECO201:SRP-021","payload":{"prompt":"Diminishing marginal returns to a variable input set in at the point where","options":["the total product curve reaches its maximum","the marginal product curve reaches its maximum","the marginal product becomes zero","the average product curve reaches its maximum"],"correctOption":1,"section":"Short-run Production","explanation":"Marginal returns start to diminish as soon as MP stops rising, which is at the peak of the MP curve and the point of inflection of the TP curve, so B is correct. Option D comes later and marks the start of Stage II, while Options A and C both mark the end of Stage II."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 618, $official_bank_source${"itemId":"0997c822-e056-51c9-af55-dfad6aebeaee","questionId":"9127881d-02b0-51da-8e1b-b6226e69c3dc","sourceKey":"bank:ECO201:SRP-022","payload":{"prompt":"Which of the following is NOT true of Stage II of production?","options":["The average product of the variable input is rising","The marginal product of the variable input is below its average product","Total product is still increasing","The marginal product of the variable input is positive"],"correctOption":0,"section":"Short-run Production","explanation":"In Stage II average product is falling, because it begins at the peak of AP, so the statement that AP is rising is false and A is the answer. Options D, B and C are all true of Stage II: MP is positive but below AP, so TP is still increasing, only at a decreasing rate."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 619, $official_bank_source${"itemId":"6f5546dc-ae12-5ce0-85da-98150baa55d2","questionId":"bb45f2bd-abeb-5ea1-a25f-d9de0ed1bb60","sourceKey":"bank:ECO201:SRP-023","payload":{"prompt":"A poultry farm in Abeokuta has a fixed number of pens and records the following total product (TP, crates of eggs per week) as it hires more workers (L): L = 1, 2, 3, 4, 5, 6, 7, 8; TP = 10, 24, 42, 57, 66, 72, 72, 68. What is the marginal product of the 3rd worker?","options":["42","18","24","14"],"correctOption":1,"section":"Short-run Production","explanation":"Marginal product is the change in TP when one more worker is hired: MP of the 3rd worker = 42 - 24 = 18 crates, so B is correct. Option D is the average product of 3 workers (42/3), Option A is the total product of 3 workers, and Option C is the total product of 2 workers."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 620, $official_bank_source${"itemId":"1f401177-0c0a-5e43-8287-960b00456e40","questionId":"dee3b7ac-d147-57a9-b3c2-17a624318175","sourceKey":"bank:ECO201:SRP-024","payload":{"prompt":"A poultry farm in Abeokuta has a fixed number of pens and records the following total product (TP, crates of eggs per week) as it hires more workers (L): L = 1, 2, 3, 4, 5, 6, 7, 8; TP = 10, 24, 42, 57, 66, 72, 72, 68. What is the average product of labour when 5 workers are employed?","options":["66","13.20","14.25","9"],"correctOption":1,"section":"Short-run Production","explanation":"Average product is TP divided by the number of workers: 66 / 5 = 13.20 crates per worker, so B is right. Option D is the marginal product of the 5th worker (66 - 57), Option A is total product, and Option C is the average product of 4 workers."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 621, $official_bank_source${"itemId":"a3a262f8-ac93-53a6-97c3-2f5c3344d03d","questionId":"e6391f01-cfac-56f1-b2a9-2eec4c3fbc42","sourceKey":"bank:ECO201:SRP-025","payload":{"prompt":"A poultry farm in Abeokuta has a fixed number of pens and records the following total product (TP, crates of eggs per week) as it hires more workers (L): L = 1, 2, 3, 4, 5, 6, 7, 8; TP = 10, 24, 42, 57, 66, 72, 72, 68. Diminishing marginal returns to labour begin with the hiring of which worker?","options":["The 4th worker","The 7th worker","The 3rd worker","The 5th worker"],"correctOption":0,"section":"Short-run Production","explanation":"The marginal products are 10, 14, 18, 15, 9, 6, 0 and -4, so MP rises up to the 3rd worker and first falls with the 4th worker (from 18 to 15), making A correct. Option C is the worker with the highest MP, not the first with a lower MP, and Option B is where MP reaches zero, which is much later."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 622, $official_bank_source${"itemId":"55767f8a-cb22-59cf-849a-2754f3e66530","questionId":"63d44c07-9633-598e-999d-731714cfd391","sourceKey":"bank:ECO201:SRP-026","payload":{"prompt":"A poultry farm in Abeokuta has a fixed number of pens and records the following total product (TP, crates of eggs per week) as it hires more workers (L): L = 1, 2, 3, 4, 5, 6, 7, 8; TP = 10, 24, 42, 57, 66, 72, 72, 68. At what level of employment is the average product of labour at its maximum?","options":["4 workers","3 workers","7 workers","6 workers"],"correctOption":0,"section":"Short-run Production","explanation":"The average products are 10, 12, 14, 14.25, 13.2, 12, about 10.29 and 8.5, so AP peaks at 14.25 with 4 workers, and A is right. Option B is where MP peaks (18), and Options D and C are where TP reaches its maximum of 72, not where output per worker is highest."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 623, $official_bank_source${"itemId":"d0c3f0d9-ae79-5a61-b7cc-f91d26ecad0d","questionId":"7b52ca11-a87e-54fe-a3d2-a4436ecf8d44","sourceKey":"bank:ECO201:SRP-027","payload":{"prompt":"A poultry farm in Abeokuta has a fixed number of pens and records the following total product (TP, crates of eggs per week) as it hires more workers (L): L = 1, 2, 3, 4, 5, 6, 7, 8; TP = 10, 24, 42, 57, 66, 72, 72, 68. What is the marginal product of the 8th worker?","options":["8.50","68","-4","0"],"correctOption":2,"section":"Short-run Production","explanation":"MP of the 8th worker = 68 - 72 = -4 crates: hiring this worker actually lowers output, so C is correct and the farm is in Stage III. Option D is the MP of the 7th worker, Option A is the average product of 8 workers (68/8), and Option B is total product."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 624, $official_bank_source${"itemId":"04de4a7d-99b2-5d49-ad47-febaa396efa1","questionId":"13251531-6e76-519c-8425-ee6db766db9f","sourceKey":"bank:ECO201:SRP-028","payload":{"prompt":"A poultry farm in Abeokuta has a fixed number of pens and records the following total product (TP, crates of eggs per week) as it hires more workers (L): L = 1, 2, 3, 4, 5, 6, 7, 8; TP = 10, 24, 42, 57, 66, 72, 72, 68. Within what range of employment is the farm in Stage II, the rational stage of production?","options":["From 7 to 8 workers","From 4 to 7 workers","From 3 to 6 workers","From 1 to 4 workers"],"correctOption":1,"section":"Short-run Production","explanation":"Stage II runs from the point of maximum AP (4 workers, AP = 14.25) to the point where MP becomes zero (the 7th worker, MP = 0), so B is right. Option D is Stage I, where AP is still rising, Option A covers the move into Stage III, where the 8th worker has a negative MP, and Option C starts too early, at the peak of MP."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 625, $official_bank_source${"itemId":"5e477189-aad3-5abc-a133-cee727df34be","questionId":"f95da8b3-bc4a-5ab0-9ccf-a760a3a92a73","sourceKey":"bank:ECO201:SRP-029","payload":{"prompt":"A tailoring shop in Aba finds that the average product of 5 tailors is 20 shirts per day and the average product of 6 tailors is 19 shirts per day. What is the marginal product of the 6th tailor?","options":["14","114","19","-1"],"correctOption":0,"section":"Short-run Production","explanation":"First find total products: TP(5) = 5 x 20 = 100 and TP(6) = 6 x 19 = 114, so MP of the 6th tailor = 114 - 100 = 14 shirts, and A is correct. Option D wrongly subtracts the two averages, Option C is the average product of 6 tailors, and Option B is the total product of 6 tailors."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 626, $official_bank_source${"itemId":"9c3392df-6a27-5bce-b0f1-3a4b515646e0","questionId":"f7aef4d6-84b3-5067-b9bf-fe4c22aa753a","sourceKey":"bank:ECO201:SRP-030","payload":{"prompt":"On a rice farm in Ebonyi the average product of 4 workers is 25 bags. If the 5th worker has a marginal product of 15 bags, what is the total product of 5 workers?","options":["115 bags","40 bags","23 bags","125 bags"],"correctOption":0,"section":"Short-run Production","explanation":"TP of 4 workers = 4 x 25 = 100 bags; adding the 5th worker's MP gives 100 + 15 = 115 bags, so A is right. Option B simply adds AP and MP, Option D wrongly multiplies AP of 25 by 5 workers, and Option C is the new average product (115/5)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 627, $official_bank_source${"itemId":"e3d71bea-4cc4-5d83-b263-6723158f0fdf","questionId":"18d606a4-fd71-53d7-a2be-3774203c6d42","sourceKey":"bank:ECO201:SRP-031","payload":{"prompt":"A firm's short-run production function is Q = 10L - L^2, where L is labour. At what level of labour is total product at its maximum?","options":["L = 10","L = 5","L = 2.5","L = 25"],"correctOption":1,"section":"Short-run Production","explanation":"MP = dQ/dL = 10 - 2L, and TP is maximised where MP = 0, giving 10 - 2L = 0 and L = 5, so B is correct. Option A is where output falls back to zero (10L = L^2), and Option D is the maximum output itself (25), not the labour input."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 628, $official_bank_source${"itemId":"d7ffc40b-2442-56b7-b4c5-16edb2fbcced","questionId":"156e0ed7-bf0f-5e7a-9f37-a92bec51dce4","sourceKey":"bank:ECO201:SRP-032","payload":{"prompt":"A firm's short-run production function is Q = 10L - L^2. What is the maximum output the firm can produce?","options":["24","50","5","25"],"correctOption":3,"section":"Short-run Production","explanation":"MP = 10 - 2L equals zero at L = 5, so maximum output is Q = 10(5) - 5^2 = 50 - 25 = 25, and D is right. Option B forgets to subtract L^2, Option A is output at L = 4 (or L = 6), and Option C is the labour input at the maximum rather than the output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 629, $official_bank_source${"itemId":"d8c0a689-c3d4-5927-958e-937d021eeb59","questionId":"e56eba73-a4f3-57f0-a22e-c433e2c0cbdd","sourceKey":"bank:ECO201:SRP-033","payload":{"prompt":"For the production function Q = 10L - L^2, what is the marginal product of labour when L = 3?","options":["7","21","6","4"],"correctOption":3,"section":"Short-run Production","explanation":"MP = dQ/dL = 10 - 2L, so at L = 3, MP = 10 - 6 = 4, and D is correct. Option A is the average product (Q/L = 10 - L = 7), Option B is total output at L = 3 (30 - 9 = 21), and Option C is MP at L = 2."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 630, $official_bank_source${"itemId":"9aec64c4-7fe8-5e6d-8e68-dba8637f7e82","questionId":"292e811c-7d2c-57c2-925d-bff6dc7de99a","sourceKey":"bank:ECO201:SRP-034","payload":{"prompt":"For the production function Q = 10L - L^2, what is the average product of labour when L = 4?","options":["8","2","6","24"],"correctOption":2,"section":"Short-run Production","explanation":"AP = Q/L = (10L - L^2)/L = 10 - L, so at L = 4, AP = 6, and C is right. Option B is the marginal product at L = 4 (10 - 2L = 2), Option D is total output at L = 4 (40 - 16 = 24), and Option A would follow from wrongly using AP = 10 - L/2."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 631, $official_bank_source${"itemId":"bebf859b-10ae-57cb-8a14-a61ece64fd37","questionId":"707dcd59-7166-57f5-a970-a941986ada69","sourceKey":"bank:ECO201:SRP-035","payload":{"prompt":"A firm's short-run production function is Q = 6L^2 - 0.2L^3, where L is labour. At what level of labour is the marginal product of labour at its maximum?","options":["L = 20","L = 15","L = 10","L = 30"],"correctOption":2,"section":"Short-run Production","explanation":"MP = dQ/dL = 12L - 0.6L^2, and MP is at its peak where dMP/dL = 12 - 1.2L = 0, giving L = 10, so C is correct. Option B is where AP is maximised, Option A is where MP = 0 and TP is maximised, and Option D is where output falls back to zero."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 632, $official_bank_source${"itemId":"b1a50ffa-a416-5cd6-bbce-69074647e72e","questionId":"42ae039b-85f2-5e17-8025-e666a906a2c3","sourceKey":"bank:ECO201:SRP-036","payload":{"prompt":"A firm's short-run production function is Q = 6L^2 - 0.2L^3, where L is labour. At what level of labour is the average product of labour at its maximum?","options":["L = 30","L = 15","L = 20","L = 10"],"correctOption":1,"section":"Short-run Production","explanation":"AP = Q/L = 6L - 0.2L^2, which peaks where dAP/dL = 6 - 0.4L = 0, giving L = 15; at that point AP = MP = 45, as the theory predicts, so B is right. Option D is where MP is maximised, and Option C is where MP becomes zero."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 633, $official_bank_source${"itemId":"11c78715-b9a5-5ba7-8ddb-a94fecf6f435","questionId":"887c3231-0169-5acc-be2e-4b0c4d3b0e96","sourceKey":"bank:ECO201:SRP-037","payload":{"prompt":"A firm's short-run production function is Q = 6L^2 - 0.2L^3, where L is labour. At what level of labour is total product at its maximum?","options":["L = 20","L = 10","L = 15","L = 30"],"correctOption":0,"section":"Short-run Production","explanation":"TP is maximised where MP = 12L - 0.6L^2 = 0, that is L(12 - 0.6L) = 0, giving L = 20, so A is correct. Option B is the peak of MP and Option C is the peak of AP, both of which come before the peak of TP, while Option D is where output has fallen back to zero."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 634, $official_bank_source${"itemId":"3d472c0d-c1a5-529a-b2c8-26ca98394676","questionId":"c1929e5a-d45d-5bfb-bf76-58084aa6d699","sourceKey":"bank:ECO201:SRP-038","payload":{"prompt":"A firm's short-run production function is Q = 6L^2 - 0.2L^3, where L is labour. What is the maximum total product the firm can obtain?","options":["2,400","800","1,600","675"],"correctOption":1,"section":"Short-run Production","explanation":"TP peaks where MP = 12L - 0.6L^2 = 0, at L = 20, so Q = 6(400) - 0.2(8,000) = 2,400 - 1,600 = 800, and B is right. Option D is output at L = 15, where AP (not TP) is maximised, while Options C and A are just the separate terms 0.2L^3 and 6L^2 at L = 20."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 635, $official_bank_source${"itemId":"e394944e-55d2-5614-ad91-aef75ae30c5f","questionId":"97840741-c204-55ee-a7f6-c7aaefd184ad","sourceKey":"bank:ECO201:SRP-039","payload":{"prompt":"A firm's short-run production function is Q = 6L^2 - 0.2L^3, where L is labour. What is the maximum value of the average product of labour?","options":["40","60","675","45"],"correctOption":3,"section":"Short-run Production","explanation":"AP = 6L - 0.2L^2 is maximised at L = 15, giving AP = 90 - 45 = 45, so D is correct. Option B is the maximum marginal product (at L = 10), Option A is AP at L = 10, and Option C is total product at L = 15 rather than output per worker."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 636, $official_bank_source${"itemId":"af305fc2-4c3f-52c7-86b6-28cb2fd6e291","questionId":"9d5cc8ba-5b9b-5353-acda-e2d284fcb270","sourceKey":"bank:ECO201:SRP-040","payload":{"prompt":"A firm's short-run production function is Q = 6L^2 - 0.2L^3, where L is labour. Over what range of labour input is the firm in Stage II of production?","options":["From L = 10 to L = 20","From L = 10 to L = 15","From L = 20 to L = 30","From L = 15 to L = 20"],"correctOption":3,"section":"Short-run Production","explanation":"Stage II begins at the maximum of AP (L = 15) and ends where MP = 0 (L = 20), so D is right. Options B and A wrongly start the stage at the peak of MP (L = 10), which is inside Stage I, and Option C is Stage III, where MP is negative."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 637, $official_bank_source${"itemId":"d01f34a3-8540-5780-ab2b-23a0f83ff088","questionId":"e0fb6d66-f092-5792-be30-665e5ef301ef","sourceKey":"bank:ECO201:SRP-041","payload":{"prompt":"A firm's short-run production function is Q = 6L^2 - 0.2L^3, where L is labour. What is the marginal product of labour when L = 5?","options":["125","25","45","60"],"correctOption":2,"section":"Short-run Production","explanation":"MP = dQ/dL = 12L - 0.6L^2, so at L = 5, MP = 60 - 15 = 45, and C is correct. Option B is the average product (6L - 0.2L^2 = 25), Option A is total output (150 - 25 = 125), and Option D forgets the second term of the MP function."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 638, $official_bank_source${"itemId":"9bb73214-b39d-5709-8ad5-12b64383ae91","questionId":"c6e1b337-5265-5f43-8683-c1960ae149cb","sourceKey":"bank:ECO201:SRP-042","payload":{"prompt":"A block-making yard in Ibadan produces 40 blocks per hour with 4 workers and 52 blocks per hour with 5 workers. What is the marginal product of the 5th worker?","options":["52 blocks","10 blocks","12 blocks","10.4 blocks"],"correctOption":2,"section":"Short-run Production","explanation":"MP is the change in total product from the extra worker: 52 - 40 = 12 blocks, so C is right. Option D is the average product of 5 workers (52/5), Option B is the average product of 4 workers (40/4), and Option A is total product, not the addition to it."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 639, $official_bank_source${"itemId":"b975db04-972c-5266-b523-54071f49d0e8","questionId":"23e7070c-369e-5478-b2d7-0f00a10ac85d","sourceKey":"bank:ECO201:SRP-043","payload":{"prompt":"A palm-oil mill increases its workers from 5 to 7 and daily output rises from 100 to 130 litres. What is the marginal product per additional worker over this range?","options":["20 litres","18.57 litres","30 litres","15 litres"],"correctOption":3,"section":"Short-run Production","explanation":"MP = change in TP / change in L = (130 - 100) / (7 - 5) = 30/2 = 15 litres per worker, so D is correct. Option C forgets to divide by the 2 extra workers, Option B is the average product of 7 workers (130/7), and Option A is the average product of 5 workers."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 640, $official_bank_source${"itemId":"4a3a4781-1b6d-568a-bef2-833de3e9f4e1","questionId":"72daf0a2-4974-5fe3-9d1a-3b699f19a5a7","sourceKey":"bank:ECO201:SRP-044","payload":{"prompt":"Eight labourers on a tomato farm in Kano harvest 96 baskets in a day. What is the average product of labour?","options":["768 baskets","0.08 baskets","13.71 baskets","12 baskets"],"correctOption":3,"section":"Short-run Production","explanation":"Average product = TP / L = 96 / 8 = 12 baskets per labourer, so D is right. Option A multiplies instead of dividing, Option B divides labour by output, and Option C wrongly divides by 7 instead of 8."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 641, $official_bank_source${"itemId":"bbe64a8b-752c-5a58-8a40-8c485fb3b0e9","questionId":"20ce5a8b-b7d1-5378-ada4-2be6a7dfd90d","sourceKey":"bank:ECO201:SRP-045","payload":{"prompt":"A firm's production function is Q = 30L - 1.5L^2. What is the maximum output the firm can produce?","options":["150","300","10","112.5"],"correctOption":0,"section":"Short-run Production","explanation":"MP = 30 - 3L equals zero at L = 10, so maximum output is 30(10) - 1.5(100) = 300 - 150 = 150, and A is correct. Option B forgets to subtract 1.5L^2, Option D is output at L = 5, and Option C is the labour input at which output is maximised."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 642, $official_bank_source${"itemId":"78d716ea-0acd-5fee-a939-4081438105e3","questionId":"a238e9b6-7fc7-52fc-87d5-7d1409a129a3","sourceKey":"bank:ECO201:SRP-046","payload":{"prompt":"In a cassava mill the average product of labour is currently 30 kg per worker. The next worker hired has a marginal product of 24 kg. When that worker is hired, the average product of labour will","options":["become zero","rise","fall","remain at 30 kg"],"correctOption":2,"section":"Short-run Production","explanation":"When marginal product is below average product, adding that unit pulls the average down, just as a low score lowers a class average, so with MP = 24 below AP = 30 the AP falls and C is right. Option B would require MP above 30, and Option D would require MP exactly equal to 30."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 643, $official_bank_source${"itemId":"940b0b10-7a3e-5553-8a83-802e99477e3e","questionId":"0122f860-b6f6-5396-9ae6-c8792a913a20","sourceKey":"bank:ECO201:SRP-047","payload":{"prompt":"A bakery's 3 workers produce 45 loaves per hour. A 4th worker adds 9 loaves. What is the average product of labour with 4 workers?","options":["9","13.50","15","54"],"correctOption":1,"section":"Short-run Production","explanation":"TP with 4 workers = 45 + 9 = 54 loaves, so AP = 54/4 = 13.50 loaves per worker, and B is correct. Option A is the marginal product of the 4th worker, Option C is the average product of 3 workers (45/3), and Option D is total product rather than output per worker."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 644, $official_bank_source${"itemId":"d6bc54b6-56e8-598f-bb6d-be1cbc20564e","questionId":"fb8e60b4-f62e-587f-83e8-ae7904ca4d60","sourceKey":"bank:ECO201:E201-0111","payload":{"prompt":"An isoquant that is","options":["further from the origin represents greater output.","flatter represents the trade-offs between inputs that are poor substitutes.","negatively sloped represents input combinations associated with Stage I of production.","All of the above are correct."],"correctOption":0,"section":"Long-run Production","explanation":"Each isoquant shows one level of output, and an isoquant further from the origin contains more of at least one input, so it represents a higher output. Option B is wrong because poor substitutes give a sharply curved, nearly L-shaped isoquant, not one that simply looks flatter, and option C is wrong because the negatively sloped part of an isoquant is the economic region (Stage II), not Stage I. Since B and C are false, D is false too."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 645, $official_bank_source${"itemId":"c5862b33-36e4-58d3-bb58-f408bb6ad184","questionId":"9b1f8ef7-74c7-530a-a1da-75bc6330df4f","sourceKey":"bank:ECO201:E201-0112","payload":{"prompt":"The absolute value of the slope of a convex isoquant","options":["is equal to the marginal rate of technical substitution.","is equal to the ratio of the marginal products of the two inputs.","decreases from left to right.","All of the above are correct."],"correctOption":3,"section":"Long-run Production","explanation":"The absolute slope of an isoquant is the marginal rate of technical substitution, and MRTS of L for K = MPL/MPK. Because isoquants are convex, this MRTS falls as we move down the curve from left to right (diminishing MRTS). All three statements are true, so D is correct."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 646, $official_bank_source${"itemId":"07279b6a-5829-5b39-a37e-aa794e268593","questionId":"9a6add99-86bc-51fc-a1a0-2c8d28423645","sourceKey":"bank:ECO201:E201-0113","payload":{"prompt":"The combination of inputs is optimal","options":["at points of tangency between isoquants and isocosts.","if the marginal revenue product is equal to the marginal resource cost for all inputs.","if the marginal rate of technical substitution between every pair of inputs is equal to the ratio of the prices of those inputs.","All of the above are correct."],"correctOption":3,"section":"Long-run Production","explanation":"The least-cost (optimal) input combination is where an isoquant is tangent to an isocost line, which means MRTS = w/r, the ratio of input prices. Hiring each input until its marginal revenue product equals its price also gives MPL/MPK = w/r, so it satisfies the same condition. Because A, B and C all describe the optimum, D is correct."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 647, $official_bank_source${"itemId":"f1e21297-cf49-5104-b68d-eaf6f3bb2140","questionId":"89718ed4-b7ac-5493-94c0-382ef3e8d7e4","sourceKey":"bank:ECO201:E201-0114","payload":{"prompt":"An isocost line will be shifted further away from the origin","options":["if the prices of both inputs increase.","if total cost increases.","if there is an advance in technology.","All of the above are correct."],"correctOption":1,"section":"Long-run Production","explanation":"The isocost line is C = wL + rK, so a higher total cost outlay at the same input prices moves it parallel and further from the origin. Option A does the opposite: higher input prices let the same money buy less, so the line shifts toward the origin. Option C is wrong because better technology shifts the isoquants, not the isocost line, so D is also wrong."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 648, $official_bank_source${"itemId":"7548635d-6bc8-5efd-8a89-a0b486b5366b","questionId":"a4a085e4-188a-5f4e-8728-22ca7cdf8eab","sourceKey":"bank:ECO201:E201-0115","payload":{"prompt":"If isoquants are plotted on a graph with capital measured on the vertical axis and labor on the horizontal axis, then an increase in the wage rate will cause the isocost line","options":["to become steeper and the optimal quantity of labor will decrease.","to become steeper and the optimal quantity of labor will increase.","to become flatter and the optimal quantity of labor will decrease.","to become flatter and the optimal quantity of labor will increase."],"correctOption":0,"section":"Long-run Production","explanation":"With capital on the vertical axis and labour on the horizontal axis, the isocost slope is -w/r, so a higher wage makes the line steeper. Labour has become relatively dearer, so the cost-minimising firm substitutes capital for labour and uses less labour. Options C and D get the slope wrong, and option B gets the direction of substitution wrong."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 649, $official_bank_source${"itemId":"45c5b1dc-6059-5604-82c5-00ef3a12a704","questionId":"c8b36cc4-a8bc-5310-85f3-fa6f12075e45","sourceKey":"bank:ECO201:E201-0116","payload":{"prompt":"A line that connects all points where the marginal rate of technical substitution is equal to the ratio of input prices is called the","options":["input demand curve.","total product curve.","expansion path.","isocost line."],"correctOption":2,"section":"Long-run Production","explanation":"The expansion path joins the tangency points between isoquants and isocost lines as output or outlay grows, and at each of those points MRTS = w/r. Option D, the isocost line, shows combinations with the same total cost, and option B, the TP curve, relates output to one variable input, so neither links all the tangency points."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 650, $official_bank_source${"itemId":"6ee9db15-f451-5839-9489-f74b1b266627","questionId":"a4ce9ea9-e681-5240-b0df-291789a1bfb9","sourceKey":"bank:ECO201:E201-0117","payload":{"prompt":"Suppose that three isoquants that represent 10, 20, and 30 units of output are plotted on a graph and a straight line is drawn from the origin through the isoquants. If the portion of the line between the isoquants that represent 10 and 20 units of output is longer than the portion of the line between the isoquants that represent 20 and 30 units of output, then the firm represented by these isoquants","options":["has engaged in product innovation.","is experiencing increasing returns to scale.","is experiencing decreasing returns to scale.","will maximize profits by producing 10 units of output."],"correctOption":1,"section":"Long-run Production","explanation":"Each step from 10 to 20 and from 20 to 30 units adds the same 10 units of output. If the second step needs a shorter distance along the ray, it needs a smaller increase in inputs, so output is growing faster than inputs, which is increasing returns to scale. Option C would apply if the isoquants were getting further apart, and options A and D are not shown by isoquant spacing at all."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 651, $official_bank_source${"itemId":"4f5fe994-abf7-5423-a599-10671c5bc400","questionId":"22d1f072-3e91-5668-b8c6-b0e6e76e13a6","sourceKey":"bank:ECO201:E201-0118","payload":{"prompt":"If the output elasticities of all inputs used by a firm are summed together, then the total","options":["will be greater than one if returns to scale are decreasing.","will be equal to one if returns to scale are constant.","will be less than one if returns to scale are increasing.","All of the above are correct."],"correctOption":1,"section":"Long-run Production","explanation":"When the output elasticities of all inputs are added, the sum tells us returns to scale: greater than one means increasing, equal to one means constant, and less than one means decreasing returns. Options A and C reverse the signs of the inequalities, so they are false, which also rules out D."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 652, $official_bank_source${"itemId":"4c79fa32-6b2f-5111-b8cd-9e149f1e24ac","questionId":"c328f73d-005e-559a-9963-8dc16d9ad523","sourceKey":"bank:ECO201:E201-0119","payload":{"prompt":"Which of the following is not a characteristic of production technologies that can be described by the Cobb-Douglas production function?","options":["The marginal product of an input divided by the average product of that input is constant.","The exponents will sum to one if returns to scale are constant.","Linear regression can be used to estimate the parameters of the function.","All of the above are characteristics of the Cobb-Douglas production function."],"correctOption":3,"section":"Long-run Production","explanation":"In a Cobb-Douglas function Q = A L^a K^b, MP/AP for each input equals its exponent, which is a constant; the exponents sum to one under constant returns to scale; and taking logs gives log Q = log A + a log L + b log K, which can be estimated by linear regression. Since A, B and C are all genuine characteristics, D is correct."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 653, $official_bank_source${"itemId":"eecf436e-87b1-5afd-b58e-b193fe2d11df","questionId":"6e349824-2d5c-5457-b5f7-076954bbab51","sourceKey":"bank:ECO201:E201-0120","payload":{"prompt":"If the marginal product of labor is 2, the marginal product of capital is 4, the wage rate is $3, the rental price of capital is $6, and the price of output is $1.50, then the firm should","options":["Increase output by hiring more labor, more capital, or both.","Hold output constant, but hire more labor and less capital.","Decrease output by reducing the quantity of capital, reducing the number of units of labor, or both.","None of the above is correct."],"correctOption":3,"section":"Long-run Production","explanation":"Check the cost-minimising rule first: MPL/w = 2/3 = 0.667 and MPK/r = 4/6 = 0.667, so the input mix is already correct and option B is wrong. Then check output: the value of each extra unit is MPL x P = 2 x 1.50 = 3 = w and MPK x P = 4 x 1.50 = 6 = r, so expanding or cutting output would not raise profit, which rules out A and C. The firm is already at its best position, so D is correct."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 654, $official_bank_source${"itemId":"f35d2da3-9827-5ae0-838d-56ace185376a","questionId":"f0c2fbee-57d8-549f-846d-02e685802819","sourceKey":"bank:ECO201:E201-0129","payload":{"prompt":"Which of the following statements about the long run in production is correct?","options":["All inputs are fixed","Only labour can be varied","At least one input is fixed","All inputs are variable"],"correctOption":3,"section":"Long-run Production","explanation":"The long run is a period long enough for the firm to change the quantities of all its inputs, including plant and machinery. Option C describes the short run, where at least one input is fixed, and options A and B are even more restrictive, so they cannot describe the long run."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 655, $official_bank_source${"itemId":"72d19abe-8247-5003-b018-57d3fbb6c8f1","questionId":"5ddf6aeb-3d94-5a06-9861-5010f38486ac","sourceKey":"bank:ECO201:E201-0131","payload":{"prompt":"Returns to scale describe how output responds when","options":["one input is varied while the others are held fixed in the short run","output is held constant and one input is substituted for another","the price of one input changes","all inputs are changed in the same proportion in the long run"],"correctOption":3,"section":"Long-run Production","explanation":"Scale refers to the size of the whole operation, so returns to scale are a long-run idea measured by changing all inputs in the same proportion. Option A describes returns to a variable factor (the law of variable proportions), which is a short-run idea, and option B describes substitution along an isoquant."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 656, $official_bank_source${"itemId":"c9a4cfe1-9e22-5bef-99af-9a9435beda6c","questionId":"84de3113-3c15-5f77-a2c1-d16e56aabc7b","sourceKey":"bank:ECO201:E201-0132","payload":{"prompt":"Which of the following statements about short-run and long-run decisions of a firm is correct?","options":["The firm plans in the long run and operates in the short run","The firm both plans and operates only in the long run","The firm plans in the short run and operates in the long run","The firm's planning horizon is unrelated to the long run"],"correctOption":0,"section":"Long-run Production","explanation":"When a firm plans, it can still choose any plant size, so planning takes place in the long run; once a plant is built, day-to-day production happens with that fixed plant, which is the short run. Option C reverses this, and option B ignores that actual production always takes place with some inputs fixed."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 657, $official_bank_source${"itemId":"fdfd2164-574a-5370-be38-f0e0b2a65321","questionId":"dcb6e641-7ac6-5970-a35e-229b25dc54c3","sourceKey":"bank:ECO201:E201-0146","payload":{"prompt":"An isoquant shows","options":["all combinations of two goods that give the consumer the same satisfaction","the maximum output obtainable from one variable input","all combinations of two inputs that produce the same level of output","all combinations of two inputs that have the same total cost"],"correctOption":2,"section":"Long-run Production","explanation":"Iso means equal and quant means quantity, so an isoquant joins all input combinations that yield the same output. Option D is an isocost line, option A is an indifference curve from consumer theory, and option B describes the short-run total product curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 658, $official_bank_source${"itemId":"235427de-45ff-589d-9535-b69d3786291c","questionId":"7e8837e0-74f2-5cb9-8038-e019a68a1b95","sourceKey":"bank:ECO201:E201-0147","payload":{"prompt":"Ridge lines drawn on an isoquant map","options":["join points of equal total cost","separate the economic region of production (Stage II) from the uneconomic regions (Stages I and III)","join all points where isoquants are tangent to isocost lines","show the maximum output the firm can produce"],"correctOption":1,"section":"Long-run Production","explanation":"Ridge lines pass through the points where isoquants turn backward (where an input's MP becomes zero), so outside them the isoquants slope upward and one input has negative MP. A rational firm only operates between the ridge lines, in Stage II. Option C describes the expansion path and option A an isocost line."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 659, $official_bank_source${"itemId":"df1a38d9-c926-5d39-8c58-69e101a63536","questionId":"f936c229-9193-5270-93d0-54efe1211eb7","sourceKey":"bank:ECO201:E201-0150","payload":{"prompt":"The marginal rate of technical substitution of labour for capital measures","options":["the extra output obtained from one more unit of labour","the number of units of labour needed to produce one more unit of output","the number of units of capital that can be given up when one more unit of labour is added, with output held constant","the ratio of the price of labour to the price of capital"],"correctOption":2,"section":"Long-run Production","explanation":"MRTS is the rate at which one input can be swapped for another while staying on the same isoquant, so output does not change. Option A is the marginal product of labour, and option D is the slope of the isocost line, which equals the MRTS only at the least-cost point."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 660, $official_bank_source${"itemId":"f7721bf0-3628-5697-82b7-18355e0bbf6b","questionId":"d89264d6-e87c-5807-acdf-0a20b97b3c9b","sourceKey":"bank:ECO201:E201-0151","payload":{"prompt":"The closer an isoquant is to a straight line, the closer the two inputs are to being","options":["perfect substitutes","inferior inputs","fixed inputs","perfect complements"],"correctOption":0,"section":"Long-run Production","explanation":"A straight-line isoquant has a constant MRTS, meaning one input can always replace the other at the same rate, which is the case of perfect substitutes. Option D is wrong because perfect complements give L-shaped (right-angled) isoquants, the opposite of a straight line."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 661, $official_bank_source${"itemId":"061e7d06-dcc4-55b3-ad30-e77bda869d90","questionId":"fec73df8-f449-57a0-9f9a-11a29baa3b20","sourceKey":"bank:ECO201:E201-0153","payload":{"prompt":"An isocost line shows","options":["the combination of inputs that maximises output","the total cost of producing each level of output","all combinations of inputs that produce the same output","all combinations of inputs that have the same total cost"],"correctOption":3,"section":"Long-run Production","explanation":"An isocost line, C = wL + rK, gives every combination of labour and capital the firm can buy with a given outlay at given input prices. Option C describes an isoquant, and option A is only the single tangency point between an isocost line and the highest isoquant."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 662, $official_bank_source${"itemId":"d985d766-eac6-560f-8263-d4f9d405ec7e","questionId":"28f5b8f0-44f3-52c8-a2d5-14b90bd9ade3","sourceKey":"bank:ECO201:E201-0154","payload":{"prompt":"With capital on the vertical axis and labour on the horizontal axis, the absolute value of the slope of the isocost line equals","options":["the ratio of the marginal product of labour to the marginal product of capital at every point","the ratio of the price of capital to the wage rate (r/w)","the total cost divided by the wage rate","the ratio of the wage rate to the price of capital (w/r)"],"correctOption":3,"section":"Long-run Production","explanation":"From C = wL + rK, K = C/r - (w/r)L, so the slope is -w/r. Option B inverts the ratio, option A is the slope of an isoquant, which equals w/r only at the tangency point, and option C is the horizontal intercept, not the slope."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 663, $official_bank_source${"itemId":"78a4dcca-a816-52cd-80b9-e99aa562ada9","questionId":"61abe5d2-64da-5a01-9e8b-900b6195e75d","sourceKey":"bank:ECO201:E201-0155","payload":{"prompt":"If two isocost lines are parallel, then","options":["the one closer to the origin represents a higher total cost","they represent the same level of output","they have the same total cost but different input prices","they have the same input price ratio, and the one further from the origin represents a higher total cost"],"correctOption":3,"section":"Long-run Production","explanation":"Parallel lines have equal slopes, and the slope of an isocost is w/r, so the input price ratio is the same; the outer line lets the firm buy more of both inputs, so it reflects a bigger outlay. Option A reverses this, and option B confuses isocosts with isoquants."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 664, $official_bank_source${"itemId":"0495db5d-5f0e-5eb7-aeb3-e3ff1e4472f6","questionId":"79b41afe-fd6d-539e-8673-f8311e64b102","sourceKey":"bank:ECO201:E201-0156","payload":{"prompt":"If a firm is minimising the total cost of producing a given level of output, then it is also","options":["producing where MRTS is greater than the input price ratio","operating outside the ridge lines","maximising its total cost","maximising the output that can be produced at that level of total cost"],"correctOption":3,"section":"Long-run Production","explanation":"Both problems lead to the same tangency of an isoquant with an isocost line, where MRTS = w/r, so the least-cost point for an output is also the maximum-output point for that cost. Option A is wrong because at the optimum MRTS equals, not exceeds, the price ratio, and option B is wrong because a rational firm operates between the ridge lines."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 665, $official_bank_source${"itemId":"80e29fbc-3ed6-5b01-b4d2-26c3687b08c1","questionId":"b74e17d6-f3de-5d84-903d-511b4d28eacb","sourceKey":"bank:ECO201:E201-0158","payload":{"prompt":"Which of the following is true of every point on a firm's expansion path?","options":["It lies on a straight line through the origin for every production function","It is an input combination that minimises the cost of producing that level of output","It is a point where the marginal products of both inputs are zero","It is an input combination that maximises the firm's profit"],"correctOption":1,"section":"Long-run Production","explanation":"The expansion path joins the tangency points of isoquants and isocosts, so every point on it is the least-cost way to produce its output. Option D is wrong because only one point on the path gives maximum profit, and option A is wrong because the path is a straight line through the origin only for special production functions, not for all."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 666, $official_bank_source${"itemId":"db6efff3-55b8-5140-8659-e62bfc1a45a9","questionId":"aafb3131-e17e-55ce-b2ba-4638b4086773","sourceKey":"bank:ECO201:E201-0160","payload":{"prompt":"Which of the following statements about a firm's expansion path is correct?","options":["A profit-maximising firm may operate anywhere off its expansion path","A profit-maximising firm must be on its expansion path, but being on the path does not by itself guarantee maximum profit","The expansion path shows combinations of output and price","Any point on the expansion path gives the firm maximum profit"],"correctOption":1,"section":"Long-run Production","explanation":"To maximise profit a firm must produce its chosen output at least cost, so it must be on the expansion path. But the path has a least-cost point for every output, and only one of those outputs maximises profit. Option D wrongly treats all least-cost points as profit-maximising, and option A ignores that any point off the path wastes money."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 667, $official_bank_source${"itemId":"eb7a8b91-a123-5a89-aad3-06d92631a7d1","questionId":"1de0f4e4-5e22-5405-8a1c-cedf632fac0a","sourceKey":"bank:ECO201:E201-0163","payload":{"prompt":"If a firm is experiencing increasing returns to scale, then doubling output will require","options":["less than a doubling of all inputs","no increase in inputs","more than a doubling of all inputs","exactly a doubling of all inputs"],"correctOption":0,"section":"Long-run Production","explanation":"Under increasing returns to scale, output rises proportionately more than inputs, so less than double the inputs is enough to double output. Option C describes decreasing returns to scale, and option D describes constant returns to scale."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 668, $official_bank_source${"itemId":"0ba19e6a-5835-5e75-9112-540ad2a01e01","questionId":"4e764ad5-a55d-5413-b8e8-a3b81dc75fc1","sourceKey":"bank:ECO201:E201-0164","payload":{"prompt":"Decreasing returns to scale are mainly attributed to","options":["the use of more specialised machinery","increased specialisation and division of labour","the indivisibility of some inputs at low output","managerial difficulties in coordinating and controlling a very large operation"],"correctOption":3,"section":"Long-run Production","explanation":"As a firm becomes very large, management finds it harder to coordinate, communicate and control, so output grows less than proportionately with inputs. Options B, A and C are the classic causes of increasing returns to scale, not decreasing returns."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 669, $official_bank_source${"itemId":"fdf7ef26-c30c-52e4-8c34-0eb0dd8f2f54","questionId":"446ca24e-d54a-5bbf-8aed-7ab22bec843c","sourceKey":"bank:ECO201:E201-0198","payload":{"prompt":"One reason that a firm may experience decreasing returns to scale is that greater levels of output can result in","options":["a greater division of labor.","an increase in meetings and paperwork.","smaller inventories per unit of output.","All of the above are correct."],"correctOption":1,"section":"Long-run Production","explanation":"Decreasing returns to scale happen when output grows by a smaller proportion than inputs, and a common cause is that a very large firm becomes hard to manage, with more meetings, paperwork and layers of coordination. Option A, greater division of labour, is actually a source of increasing returns to scale, and option C, smaller inventories per unit, lowers cost per unit rather than raising it. So D cannot be correct either."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 670, $official_bank_source${"itemId":"0c4aa7ea-62e0-54df-986b-ff8265744583","questionId":"96957599-3b08-55c7-b602-d80ae85fb479","sourceKey":"bank:ECO201:E201-0331","payload":{"prompt":"If all resources used in the production of a product are increased by 20 percent and output increases by 20 percent, then there must be:","options":["Economies of scale.","Diseconomies of scale.","Constant returns to scale.","Increasing average total costs."],"correctOption":2,"section":"Long-run Production","explanation":"Constant returns to scale means output changes in exactly the same proportion as all inputs. A 20 percent rise in every input giving a 20 percent rise in output fits that exactly. Option A would need output to rise by more than 20 percent, and option B by less than 20 percent."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 671, $official_bank_source${"itemId":"fa8566b9-767c-5b22-96f3-a74b04dc7df3","questionId":"45ae9aa8-684a-5bd9-bb7e-7b60f17438ab","sourceKey":"bank:ECO201:E201-0336","payload":{"prompt":"Which of the following statements describes increasing returns to scale:","options":["Doubling the inputs used leads to double the output.","Increasing the inputs by 50% leads to a 25% increase in output.","Increasing inputs by 1/4 leads to an increase in output of 1/3.","None of the above."],"correctOption":2,"section":"Long-run Production","explanation":"Increasing returns to scale means output rises by a larger proportion than inputs. In option C, inputs rise by 1/4 (25 percent) and output by 1/3 (about 33.3 percent), so output grows faster than inputs. Option A shows constant returns to scale, and option B (25 percent output for 50 percent more inputs) shows decreasing returns to scale."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 672, $official_bank_source${"itemId":"113b9f18-d608-597c-9bfe-6bfeb42c08be","questionId":"d995baf6-3a60-55ec-8bb4-fe4e41d4080a","sourceKey":"bank:ECO201:LRP-001","payload":{"prompt":"In production theory, a curve showing all the combinations of two inputs that produce the same level of output is called","options":["an indifference curve","an isoquant","an expansion path","an isocost line"],"correctOption":1,"section":"Long-run Production","explanation":"An isoquant (meaning 'equal quantity') joins all input combinations that yield the same output, so B is correct. Option D joins input combinations with the same total cost, and Option A is the consumer-theory curve joining bundles of goods that give equal satisfaction."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 673, $official_bank_source${"itemId":"d4a2f58b-5b8a-5260-b08c-fb8c44b71fdc","questionId":"98025010-0b59-5b3e-855e-f177471dad06","sourceKey":"bank:ECO201:LRP-003","payload":{"prompt":"Which of the following is NOT a property of normal isoquants in the economic region?","options":["They are concave to the origin","Two isoquants never intersect","They slope downward from left to right","Higher isoquants represent higher levels of output"],"correctOption":0,"section":"Long-run Production","explanation":"Normal isoquants are convex, not concave, to the origin because the MRTS diminishes as one input replaces another, so A is the answer. Options C, B and D are genuine properties: isoquants slope downward, never cross, and lie further from the origin for larger outputs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 674, $official_bank_source${"itemId":"94e6736f-ee48-51ea-bf7e-f738aec98b6f","questionId":"4c463972-9dcc-5950-9b3e-623f7abc99ba","sourceKey":"bank:ECO201:LRP-004","payload":{"prompt":"Normal isoquants are convex to the origin because of","options":["decreasing returns to scale","the straight-line shape of the isocost line","constant factor prices","a diminishing marginal rate of technical substitution"],"correctOption":3,"section":"Long-run Production","explanation":"As a firm substitutes labour for capital along an isoquant, it can give up less and less capital for each extra unit of labour, and this diminishing MRTS makes the curve bow in toward the origin; D is correct. Option A concerns what happens when all inputs are scaled up and so moves between isoquants, while Options C and B describe the isocost line, not the isoquant."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 675, $official_bank_source${"itemId":"2fb3496e-4c70-5a58-8895-87ecf866f241","questionId":"53e136a8-1c7a-5d47-a28f-dc99346b5d2e","sourceKey":"bank:ECO201:LRP-005","payload":{"prompt":"Two isoquants of the same firm cannot intersect because","options":["the inputs would then be perfect complements","the input combination at the crossing point would be producing two different levels of output","the isocost line would become vertical","returns to scale would then be constant"],"correctOption":1,"section":"Long-run Production","explanation":"Each isoquant stands for one output level, so a crossing point would mean the same quantities of labour and capital give two different maximum outputs, which is a contradiction; B is right. Option A concerns the shape of an isoquant (L-shaped), not whether two can cross, and Options C and D have nothing to do with intersection."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 676, $official_bank_source${"itemId":"2547b9d0-ce7f-55ef-aa0f-4a874b49e60e","questionId":"3cebdf1b-f3af-582b-8869-6efbff1aa92e","sourceKey":"bank:ECO201:LRP-007","payload":{"prompt":"The marginal rate of technical substitution of labour for capital (MRTS of L for K) is equal to","options":["MPL x MPK","APL / APK","MPK / MPL","MPL / MPK"],"correctOption":3,"section":"Long-run Production","explanation":"Along an isoquant the output lost from giving up capital equals the output gained from extra labour, so -dK/dL = MPL/MPK, making D correct. Option C is the inverse, which is the MRTS of capital for labour, and Option B uses average products, which do not measure the trade-off at the margin."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 677, $official_bank_source${"itemId":"fa9603d9-6d4c-581d-a221-c3e074bdb8cf","questionId":"416b715a-8ecf-5071-86c4-9a936e91586b","sourceKey":"bank:ECO201:LRP-008","payload":{"prompt":"Diminishing MRTS means that as a firm substitutes labour for capital along an isoquant,","options":["it gives up successively larger amounts of capital for each extra unit of labour","the cost of production falls continuously","it gives up successively smaller amounts of capital for each extra unit of labour","output falls by smaller and smaller amounts"],"correctOption":2,"section":"Long-run Production","explanation":"As labour becomes plentiful and capital scarce, each extra worker can replace less and less capital, so the firm gives up ever smaller amounts of capital per unit of labour; C is right. Option A would be an increasing MRTS, which would make the isoquant concave, and Option D is wrong because output is constant along an isoquant."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 678, $official_bank_source${"itemId":"f8a5c225-9514-556f-bb98-adcb66b1ef9e","questionId":"3c65bcc7-6eaa-520e-8662-f1cd0eb4ba12","sourceKey":"bank:ECO201:LRP-009","payload":{"prompt":"If labour and capital are perfect substitutes in production, the isoquants are","options":["downward-sloping straight lines","L-shaped","smooth curves convex to the origin","vertical lines"],"correctOption":0,"section":"Long-run Production","explanation":"With perfect substitutes one input can always replace the other at a constant rate, so the MRTS is constant and the isoquant is a straight downward-sloping line, making A correct. Option B is the case of perfect complements (fixed proportions), and Option C is the normal case where substitution is possible but imperfect."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 679, $official_bank_source${"itemId":"980d1fff-c0d8-562f-9c84-0ba398c50695","questionId":"bfc798fc-34bd-510f-b431-a1daf4545498","sourceKey":"bank:ECO201:LRP-010","payload":{"prompt":"A transport company in Lagos needs exactly one driver for each bus, and extra drivers without buses (or extra buses without drivers) add nothing to output. Its isoquants are","options":["smooth curves convex to the origin","downward-sloping straight lines","L-shaped (right-angled)","upward-sloping lines"],"correctOption":2,"section":"Long-run Production","explanation":"When inputs must be combined in fixed proportions there is no substitution between them, so each isoquant has a right-angle corner at the required ratio, making C right. Option B is the perfect-substitutes case, and Option A is the normal case where labour and capital can partly replace each other."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 680, $official_bank_source${"itemId":"c290e0fa-0eaf-59c3-90dd-ca7d07698541","questionId":"51f25224-59e2-5e9f-ad0b-950da2ba9ff3","sourceKey":"bank:ECO201:LRP-012","payload":{"prompt":"If a firm's total outlay on inputs rises while the wage rate and the rental rate of capital stay the same, its isocost line","options":["shifts outward parallel to the original line","pivots inward on the labour axis","becomes steeper","becomes flatter"],"correctOption":0,"section":"Long-run Production","explanation":"The slope -w/r is unchanged because input prices have not changed, but both intercepts (C/w and C/r) increase, so the line shifts out parallel to itself and A is right. Options C and D would require a change in the relative price of labour, and Option B would follow from a rise in the wage rate."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 681, $official_bank_source${"itemId":"cbe53a59-bd91-572b-b6f3-cad627c3a1d8","questionId":"82c4aa75-a550-5872-a3fa-e84d319fa1cf","sourceKey":"bank:ECO201:LRP-013","payload":{"prompt":"Labour is on the horizontal axis. If the wage rate rises while the rental rate of capital and the total outlay stay the same, the isocost line","options":["pivots inward on the labour axis and becomes flatter","pivots outward on the capital axis","shifts outward parallel to itself","pivots inward on the labour axis and becomes steeper"],"correctOption":3,"section":"Long-run Production","explanation":"The capital intercept C/r is unchanged, but the labour intercept C/w falls, so the line swings inward along the labour axis; since the slope w/r has risen in size, it becomes steeper, which is D. Option A gets the direction of the slope wrong, Option C describes an increase in outlay, and Option B would need a fall in the price of capital."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 682, $official_bank_source${"itemId":"d40131fa-62e2-5052-a002-ae74dfedcab3","questionId":"cc0d7465-03f9-501d-876e-b97351351f48","sourceKey":"bank:ECO201:LRP-014","payload":{"prompt":"A firm using labour and capital is at its least-cost combination (producer equilibrium) where","options":["w = r","MRTS of L for K = r/w","MPL = MPK","MRTS of L for K = w/r"],"correctOption":3,"section":"Long-run Production","explanation":"At equilibrium the rate at which the firm can technically swap capital for labour (MRTS = MPL/MPK) equals the rate at which the market lets it swap them (w/r), so D is correct. Option B inverts the price ratio, and Option C would hold only in the special case where the two inputs have equal prices."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 683, $official_bank_source${"itemId":"dec0ca1a-1696-5e63-a7a2-52234a25ade2","questionId":"d735a111-c4d3-5e4c-b81f-ac458e26493f","sourceKey":"bank:ECO201:LRP-015","payload":{"prompt":"The least-cost condition for a firm using labour (L) and capital (K) can also be written as","options":["MPL/w = MPK/r","APL/w = APK/r","MPL/r = MPK/w","MPL x w = MPK x r"],"correctOption":0,"section":"Long-run Production","explanation":"Rearranging MPL/MPK = w/r gives MPL/w = MPK/r: the last naira spent on each input must add the same amount of output, so A is right. Option C puts each input's marginal product over the wrong price, and Option B uses average rather than marginal products."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 684, $official_bank_source${"itemId":"a43398a0-477d-591c-8058-6adbd60e81ab","questionId":"ef674d23-f6e5-5142-ae79-6775e1b847ea","sourceKey":"bank:ECO201:LRP-016","payload":{"prompt":"On an isoquant-isocost diagram, the producer's equilibrium occurs where","options":["the isoquant is tangent to the isocost line","the isoquant cuts the isocost line at two points","the isoquant meets a ridge line","the isocost line meets the capital axis"],"correctOption":0,"section":"Long-run Production","explanation":"At the tangency point the slope of the isoquant (MRTS) equals the slope of the isocost line (w/r), so the firm gets the highest output for its outlay or the lowest cost for its output, and A is correct. Option B means the firm could reach a higher isoquant at the same cost, and Option C marks the edge of the economic region, not equilibrium."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 685, $official_bank_source${"itemId":"450a15c6-4c24-54d9-91b4-ae19e536ccd9","questionId":"a90296e6-84dd-58dc-9b40-ddc21225eec5","sourceKey":"bank:ECO201:LRP-018","payload":{"prompt":"A cement plant in Ewekoro doubles all of its inputs and its output more than doubles. The plant is experiencing","options":["diminishing marginal returns","constant returns to scale","decreasing returns to scale","increasing returns to scale"],"correctOption":3,"section":"Long-run Production","explanation":"When output rises by a larger proportion than all inputs, the firm has increasing returns to scale, so D is correct. Option B would mean output exactly doubles, Option C would mean it rises by less than double, and Option A is a short-run idea about adding one input to fixed inputs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 686, $official_bank_source${"itemId":"02c16d2b-2164-5f24-ab44-a3e3877126b7","questionId":"144957b9-cf2d-5db8-b68e-295c98ce02c4","sourceKey":"bank:ECO201:LRP-019","payload":{"prompt":"Which of the following is a common reason for increasing returns to scale?","options":["The fixity of one input in the short run","Greater specialisation and division of labour","Difficulties of coordinating a very large organisation","A rise in the wage rate"],"correctOption":1,"section":"Long-run Production","explanation":"As a firm grows it can split work into specialised tasks and use large, indivisible machines efficiently, which raises output more than proportionately, so B is right. Option C is a cause of decreasing returns to scale, and Option A is the basis of diminishing returns in the short run, not a scale effect."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 687, $official_bank_source${"itemId":"a88ec352-4e8b-5670-92b8-b7f69bc82a3b","questionId":"7ae6d719-3dc3-5943-9eca-94a1cc52a15f","sourceKey":"bank:ECO201:LRP-021","payload":{"prompt":"The expansion path of a firm is","options":["the path of output as one input is increased with others fixed","the line joining points where isoquants become positively sloped","the line joining least-cost input combinations as outlay rises, with input prices constant","a curve joining input combinations that give equal output"],"correctOption":2,"section":"Long-run Production","explanation":"As the firm's budget rises with w and r unchanged, each new isocost line touches a higher isoquant, and the expansion path joins these tangency points, so C is right. Option B describes a ridge line, Option D is an isoquant, and Option A is the short-run total product curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 688, $official_bank_source${"itemId":"ed366cf1-7255-5663-92e8-03de816aede8","questionId":"10bbb8fb-ac8c-5f3f-a152-e5b22f654558","sourceKey":"bank:ECO201:LRP-022","payload":{"prompt":"Wages in a Kano textile factory rise sharply while the rental cost of machines stays the same. To produce the same output at least cost, the factory will","options":["cut both inputs in the same proportion","keep the same mix of labour and capital","use more capital and less labour","use more labour and less capital"],"correctOption":2,"section":"Long-run Production","explanation":"A higher w/r makes the isocost line steeper, so the new tangency on the same isoquant is at a point with more capital and less labour: the firm substitutes the relatively cheaper input for the dearer one, and C is correct. Option D is the opposite of what happens, and Option B ignores that the least-cost mix depends on relative input prices."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 689, $official_bank_source${"itemId":"7d52c6bb-bc3c-52a4-b064-e3d59f3312ec","questionId":"d6a7c232-196a-5e6d-a9e7-c5f97c892ff2","sourceKey":"bank:ECO201:LRP-023","payload":{"prompt":"On an isoquant map, ridge lines join the points where","options":["the MRTS equals the input price ratio","isoquants are tangent to isocost lines","the marginal product of one of the inputs is zero","output doubles when all inputs double"],"correctOption":2,"section":"Long-run Production","explanation":"Ridge lines pass through the points where an isoquant turns vertical or horizontal, that is where the MP of capital or of labour falls to zero, so C is right. Options B and A describe the points of producer equilibrium that make up the expansion path, and Option D describes constant returns to scale."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 690, $official_bank_source${"itemId":"24dfba8c-4cdd-516d-a8c6-03f8b132cfca","questionId":"f5d6a1a4-cb6e-5d19-ba78-06560b695293","sourceKey":"bank:ECO201:LRP-024","payload":{"prompt":"A rational firm will operate only in the region between the ridge lines because outside them","options":["returns to scale are always increasing","the marginal product of one input is negative, so the isoquants slope upward","the MRTS is constant","the isocost line slopes upward"],"correctOption":1,"section":"Long-run Production","explanation":"Beyond a ridge line, adding more of one input lowers output, so more of both inputs would be needed to keep output constant and the isoquant slopes upward; no cost-minimising firm would pay for such inputs, so B is correct. Option D is wrong because the isocost line always slopes downward, and Option A has no connection to the ridge lines."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 691, $official_bank_source${"itemId":"5225f98a-8365-519f-b38d-1e191421b93e","questionId":"63b83851-18c1-5a59-a5ad-4908b2451786","sourceKey":"bank:ECO201:LRP-025","payload":{"prompt":"If the last naira spent on labour adds more to output than the last naira spent on capital, a cost-minimising firm should","options":["employ more capital and less labour","employ more labour and less capital","reduce both inputs equally","keep its input combination unchanged"],"correctOption":1,"section":"Long-run Production","explanation":"Here MPL/w is greater than MPK/r, so shifting spending from capital to labour raises output at the same cost; the firm should keep doing this until the two ratios are equal, making B right. Option A moves in the wrong direction, and Option D is correct only when MPL/w = MPK/r."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 692, $official_bank_source${"itemId":"69f33de4-a7ca-5fec-b782-f75ff4411f4b","questionId":"3a03a2fa-3e89-5d26-b63a-7d64485f46bc","sourceKey":"bank:ECO201:LRP-026","payload":{"prompt":"Returns to scale is a long-run concept because","options":["it concerns only the fixed input","it requires all inputs to be variable","it applies only when technology changes","it is measured over a period of more than five years"],"correctOption":1,"section":"Long-run Production","explanation":"To change the scale of production, every input, including plant and machinery, must be variable, and that is possible only in the long run, so B is correct. Option C is wrong because returns to scale assume a given technology, and Option D is wrong because the long run is defined by input flexibility, not a fixed number of years."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 693, $official_bank_source${"itemId":"9d4d60f9-48d4-50be-9cc0-3ea9f4dc6dd9","questionId":"2f696aa2-a3c3-5bff-98ec-dfb12279420a","sourceKey":"bank:ECO201:LRP-027","payload":{"prompt":"A poultry farm in Ogun has a budget of N12,000 per day to spend on labour and capital. The wage rate is N400 per worker-day and the rental rate of capital is N600 per machine-day. What is the maximum quantity of labour it can hire if it uses no capital?","options":["12 worker-days","30 worker-days","20 worker-days","50 worker-days"],"correctOption":1,"section":"Long-run Production","explanation":"With K = 0 the whole budget goes on labour, so L = C/w = 12,000/400 = 30 worker-days, which is the labour intercept of the isocost line; B is correct. Option C divides by the price of capital and is the capital intercept, and Option A wrongly divides by the sum of the two prices."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 694, $official_bank_source${"itemId":"73afcd2d-1217-536e-8d5e-d002c5cbc5fb","questionId":"21e9c92c-43bf-542f-a700-fccd13a70911","sourceKey":"bank:ECO201:LRP-028","payload":{"prompt":"A firm's isocost line is drawn with capital (K) on the vertical axis and labour (L) on the horizontal axis. The wage rate is N400 and the rental rate of capital is N600. What is the slope of the isocost line?","options":["-3/2","-200","2/3","-2/3"],"correctOption":3,"section":"Long-run Production","explanation":"The isocost line K = C/r - (w/r)L has slope -w/r = -400/600 = -2/3, so D is right. Option A inverts the ratio (-r/w), option B subtracts the prices instead of dividing them, and option C has the wrong sign, since an isocost line always slopes downward."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 695, $official_bank_source${"itemId":"e2d11875-0cd2-5d1f-8149-87c129cf8552","questionId":"504fe1fa-ddbc-502e-8dfe-72f0a75819a5","sourceKey":"bank:ECO201:LRP-029","payload":{"prompt":"A firm spends N20,000 on labour (L) and capital (K). The wage rate is N500 and the rental rate of capital is N1,000. Which equation gives its isocost line with K on the vertical axis?","options":["K = 20 - 2L","K = 40 - 2L","K = 40 - 0.5L","K = 20 - 0.5L"],"correctOption":3,"section":"Long-run Production","explanation":"From 20,000 = 500L + 1,000K, dividing by 1,000 gives K = 20 - 0.5L: the intercept is C/r = 20 and the slope is -w/r = -0.5, so D is correct. Option B uses the labour intercept (C/w = 40) and the inverted slope, while Options A and C each get one of the two parts wrong."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 696, $official_bank_source${"itemId":"c597a3ec-867a-5d21-bcbc-86d98db7a7f0","questionId":"00eaa227-aa60-5845-98e5-7e38cc4b1253","sourceKey":"bank:ECO201:LRP-030","payload":{"prompt":"At a firm's current input mix, the marginal product of labour is 12 units and the marginal product of capital is 4 units. What is the MRTS of labour for capital?","options":["48","3","8","1/3"],"correctOption":1,"section":"Long-run Production","explanation":"MRTS of L for K = MPL/MPK = 12/4 = 3, meaning one extra unit of labour can replace 3 units of capital with output unchanged, so B is right. Option D is MPK/MPL, Option A multiplies the marginal products, and Option C subtracts them."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 697, $official_bank_source${"itemId":"cf01b763-a043-5974-bc9c-1846a883f6ce","questionId":"b0cf4c16-492a-5b0b-bf8d-4ebf2f30dc4d","sourceKey":"bank:ECO201:LRP-031","payload":{"prompt":"A printing firm in Surulere has MPL = 10 copies and MPK = 40 copies. The wage is N200 per hour and the rental rate of a machine is N400 per hour. To minimise cost for its current output, the firm should","options":["use more capital and less labour","keep its current input mix, as it is already in equilibrium","use more labour and less capital","use less of both inputs"],"correctOption":0,"section":"Long-run Production","explanation":"Compare output per naira: MPL/w = 10/200 = 0.05 while MPK/r = 40/400 = 0.1, so a naira spent on capital adds twice as much output as a naira on labour; the firm should switch towards capital, making A correct. Option C moves the wrong way, and Option B is wrong because the two ratios are not equal."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 698, $official_bank_source${"itemId":"b5d5ae2e-d502-5d62-906f-bc7744e99798","questionId":"24a00edc-628c-5886-815b-0e75edefa4b0","sourceKey":"bank:ECO201:LRP-032","payload":{"prompt":"A firm has the production function Q = K^0.5 L^0.5. The wage rate is N20, the rental rate of capital is N80 and the firm's budget is N1,600. How many units of labour will it employ at the least-cost (output-maximising) combination?","options":["80","20","40","10"],"correctOption":2,"section":"Long-run Production","explanation":"Here MRTS = MPL/MPK = K/L; setting it equal to w/r = 20/80 gives K = L/4. Substituting into 20L + 80K = 1,600 gives 20L + 20L = 1,600, so L = 40 and C is correct. Option D is the capital used, Option A spends the whole budget on labour (1,600/20), and Option B is the output produced."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 699, $official_bank_source${"itemId":"a7cf5231-d8ba-5d62-bef5-615a88a5b060","questionId":"573f13b7-111e-5d01-81c7-52a9171c1fda","sourceKey":"bank:ECO201:LRP-033","payload":{"prompt":"A firm has the production function Q = K^0.5 L^0.5. The wage rate is N20, the rental rate of capital is N80 and the firm's budget is N1,600. How many units of capital will it employ at the least-cost (output-maximising) combination?","options":["5","10","40","20"],"correctOption":1,"section":"Long-run Production","explanation":"Equilibrium requires K/L = w/r = 1/4, and the budget 20L + 80K = 1,600 then gives L = 40 and K = 10, so B is right. Option C is the labour used, Option D spends the whole budget on capital (1,600/80), and Option A would follow from wrongly halving L/4 again."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 700, $official_bank_source${"itemId":"a2a11293-3733-570e-a03f-cc19073b7c40","questionId":"c5fa5c5c-a3d0-52dc-b024-fe132356a07d","sourceKey":"bank:ECO201:LRP-034","payload":{"prompt":"A firm has the production function Q = K^0.5 L^0.5. The wage rate is N20, the rental rate of capital is N80 and the firm's budget is N1,600. What is the maximum output it can produce?","options":["20","400","25","50"],"correctOption":0,"section":"Long-run Production","explanation":"At the optimum L = 40 and K = 10 (from K/L = w/r = 1/4 and the budget), so Q = 10^0.5 x 40^0.5 = sqrt(400) = 20, and A is correct. Option B forgets to take the square root of K x L, while Options D and C come from using wrong input quantities instead of the tangency point."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 701, $official_bank_source${"itemId":"86457431-2e21-5c72-97bd-d7a03531b557","questionId":"728fd3a7-9898-51a6-ad89-a42f905259ef","sourceKey":"bank:ECO201:LRP-035","payload":{"prompt":"For the production function Q = 10K^0.3 L^0.7, returns to scale are","options":["decreasing, because each exponent is less than 1","increasing, because the constant 10 is greater than 1","increasing, because 0.7 is greater than 0.3","constant, because 0.3 + 0.7 = 1"],"correctOption":3,"section":"Long-run Production","explanation":"For a Cobb-Douglas function Q = A K^a L^b, returns to scale depend on a + b: here 0.3 + 0.7 = 1, so doubling both inputs exactly doubles output, which is D. Option B is wrong because A only scales the level of output, Option A confuses exponents below 1 (diminishing marginal products) with returns to scale, and Option C compares the exponents instead of adding them."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 702, $official_bank_source${"itemId":"d2221d20-8bc5-522f-ae11-b43e6b436c55","questionId":"d7d77d1c-493b-5c24-9773-d28e502c19f1","sourceKey":"bank:ECO201:LRP-036","payload":{"prompt":"For the production function Q = 2K^0.6 L^0.7, returns to scale are","options":["increasing, because 0.6 + 0.7 > 1","constant, because the constant 2 doubles output","decreasing, because each exponent is less than 1","constant, because the function is of Cobb-Douglas form"],"correctOption":0,"section":"Long-run Production","explanation":"The sum of the exponents is 0.6 + 0.7 = 1.3, which is greater than 1, so scaling both inputs by any factor raises output by a larger proportion; A is correct. Option D is wrong because a Cobb-Douglas function shows constant returns only when the exponents sum to 1, and Option C confuses diminishing marginal products with returns to scale."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 703, $official_bank_source${"itemId":"4ed2706f-781d-57dc-8ab1-76079b0229c4","questionId":"163045c1-c78c-5382-aa6d-f7abe52b64ec","sourceKey":"bank:ECO201:LRP-037","payload":{"prompt":"Which of the following production functions exhibits decreasing returns to scale?","options":["Q = 5K^0.4 L^0.5","Q = K^0.5 L^0.5","Q = 0.5K^0.6 L^0.4","Q = K^0.7 L^0.6"],"correctOption":0,"section":"Long-run Production","explanation":"Returns to scale in a Cobb-Douglas function depend on the sum of the exponents: 0.4 + 0.5 = 0.9 < 1, so A has decreasing returns. Options B and C both sum to exactly 1 (constant returns), whatever the constant in front, and Option D sums to 1.3 (increasing returns)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 704, $official_bank_source${"itemId":"19454e3d-8778-58cc-b18f-63aaf059be3b","questionId":"df75683f-0883-58ff-9873-c3af84271d04","sourceKey":"bank:ECO201:LRP-038","payload":{"prompt":"For the production function Q = K^0.5 L^0.5, what is the MRTS of labour for capital when L = 9 and K = 36?","options":["18","4","0.25","2"],"correctOption":1,"section":"Long-run Production","explanation":"MPL = 0.5K^0.5 L^-0.5 and MPK = 0.5K^-0.5 L^0.5, so MRTS = MPL/MPK = K/L = 36/9 = 4, and B is correct. Option C is L/K, which is the MRTS of capital for labour, Option A is output (sqrt(324) = 18), and Option D is the square root of the answer."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 705, $official_bank_source${"itemId":"2c68f9a7-57e8-515b-8508-d750ff74817c","questionId":"b5dcbb3b-48d7-5abc-aad1-e66006e0bec4","sourceKey":"bank:ECO201:LRP-039","payload":{"prompt":"For the production function Q = L^0.75 K^0.25, what is the MRTS of labour for capital when L = 10 and K = 20?","options":["2","6","1.5","3"],"correctOption":1,"section":"Long-run Production","explanation":"MRTS = MPL/MPK = (0.75/0.25)(K/L) = 3 x (20/10) = 6, so B is right. Option C uses L/K instead of K/L (3 x 0.5), Option A is just K/L without the ratio of exponents, and Option D is just the ratio of exponents without K/L."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 706, $official_bank_source${"itemId":"6dd3005b-5560-576d-81ed-9b81e43a0e01","questionId":"98e073c4-259b-58d9-bf17-0d6c065257f5","sourceKey":"bank:ECO201:LRP-040","payload":{"prompt":"A shoe factory in Aba produces 100 pairs a day using 10 workers and 10 machines. When it doubles both inputs to 20 workers and 20 machines, output rises to 170 pairs. The factory is experiencing","options":["decreasing returns to scale","a diminishing MRTS","constant returns to scale","increasing returns to scale"],"correctOption":0,"section":"Long-run Production","explanation":"Inputs rose by 100% but output rose by only 70% (from 100 to 170 pairs), so output grew less than in proportion to inputs, which is decreasing returns to scale; A is correct. Option D would need output above 200 pairs, Option C would need exactly 200 pairs, and Option B concerns substitution along one isoquant, not scaling up."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 707, $official_bank_source${"itemId":"f836e8f8-2a63-561b-a397-5bf1f4bec2da","questionId":"9dd55505-c7b6-5459-b757-0397d50dab88","sourceKey":"bank:ECO201:LRP-041","payload":{"prompt":"A firm has the production function Q = L^0.6 K^0.4, a budget of N10,000, a wage rate of N60 and a rental rate of capital of N40. How much labour does it employ at the least-cost (output-maximising) combination?","options":["66.67","166.67","150","100"],"correctOption":3,"section":"Long-run Production","explanation":"Setting MRTS = (0.6/0.4)(K/L) = w/r = 60/40 = 1.5 gives K = L. Substituting into 60L + 40K = 10,000 gives 100L = 10,000, so L = 100 and D is correct. Option B spends the whole budget on labour, while Options A and C swap the exponents or the input prices in the calculation."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 708, $official_bank_source${"itemId":"6044e005-0e8d-57ab-b361-983df3b8f989","questionId":"e441b45e-8a24-5543-bd39-88be678ff87a","sourceKey":"bank:ECO201:LRP-042","payload":{"prompt":"A firm with the production function Q = K^0.5 L^0.5 faces a wage rate of N50 and a rental rate of capital of N50. What is the minimum cost of producing 100 units of output?","options":["N100","N20,000","N10,000","N5,000"],"correctOption":2,"section":"Long-run Production","explanation":"With w = r the least-cost condition K/L = w/r = 1 gives K = L, and Q = sqrt(K x L) = L = 100, so L = K = 100 and cost = 50(100) + 50(100) = N10,000; C is right. Option D counts only one input, Option A is the output level rather than the cost, and Option B doubles the correct cost."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 709, $official_bank_source${"itemId":"917c9230-9fc3-5ae4-96c5-81d3d415e7e0","questionId":"5e0548f6-699d-54eb-88ba-d8ffe72817fa","sourceKey":"bank:ECO201:LRP-043","payload":{"prompt":"For the production function Q = K^0.5 L^0.5 with a wage rate of N20 and a rental rate of capital of N80, which equation describes the firm's expansion path?","options":["K = L","K = 4L","K = 0.25L","K = 2L"],"correctOption":2,"section":"Long-run Production","explanation":"Along the expansion path every point satisfies MRTS = w/r; here MRTS = K/L, so K/L = 20/80 and K = 0.25L, making C correct. Option B inverts the price ratio, and Option A would hold only if the two inputs had equal prices."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 710, $official_bank_source${"itemId":"265367e1-13a1-5d55-87aa-bae885b6b19f","questionId":"7de5efb2-f8a1-5a4a-82bf-9ceafc1dca76","sourceKey":"bank:ECO201:E201-0223","payload":{"prompt":"If a firm's long-run average cost (LRAC) curve slopes upward over some range of output, then over that range the firm is experiencing:","options":["increasing returns to scale","decreasing returns to scale (diseconomies of scale)","constant returns to scale","the law of diminishing marginal utility"],"correctOption":1,"section":"Costs of Production","explanation":"A rising LRAC means cost per unit goes up as the scale of production expands, which happens when output increases by a smaller proportion than inputs, that is, decreasing returns to scale. Option A would make LRAC slope downward, and option C would make it flat."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 711, $official_bank_source${"itemId":"d4477dbd-d40e-5123-8ef3-e94ed900af42","questionId":"568e962d-5e90-5904-9511-88c9d7bb20ba","sourceKey":"bank:ECO201:E201-0186","payload":{"prompt":"Which of the following is a variable cost?","options":["Interest payments","Raw materials costs","Property taxes","All of the above are variable costs."],"correctOption":1,"section":"Costs of Production","explanation":"A variable cost changes with the level of output, and raw materials must be bought in larger amounts as more is produced. Options A and C, interest payments and property taxes, have to be paid whatever the output, even zero, so they are fixed costs, which rules out D."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 712, $official_bank_source${"itemId":"b41df363-939d-56b3-81f8-7f2559785668","questionId":"2dc5c207-d19b-5add-8a4b-29a1b5b6e182","sourceKey":"bank:ECO201:E201-0187","payload":{"prompt":"Which of the following is an implicit cost?","options":["The salary earned by a corporate executive","Depreciation in the value of a company-owned car as it wears out","Property taxes","All of the above are implicit costs."],"correctOption":1,"section":"Costs of Production","explanation":"An implicit cost is the cost of using inputs the firm already owns, for which no fresh payment is made to an outsider; the wear and tear on a company-owned car is such a cost. Options A and C, an executive's salary and property taxes, are actual money payments to others, so they are explicit costs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 713, $official_bank_source${"itemId":"edff25dd-e86a-5702-9b3a-3551422337b2","questionId":"2e66413c-e792-56ca-b8ec-4bf4fb3855c7","sourceKey":"bank:ECO201:E201-0188","payload":{"prompt":"If the output levels at which short-run marginal and average cost curves reach a minimum are listed in order from smallest to greatest, then the order would be","options":["AVC, MC, ATC","ATC, AVC, MC","MC, AVC, ATC","AVC, ATC, MC"],"correctOption":2,"section":"Costs of Production","explanation":"MC falls faster and rises sooner, so it reaches its minimum first. It then cuts AVC at the minimum of AVC, and later cuts ATC at the minimum of ATC; ATC bottoms out last because falling AFC keeps pulling it down. So the order is MC, AVC, ATC. Option A wrongly puts AVC before MC, and B and D put MC last."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 714, $official_bank_source${"itemId":"94e6e7b0-a2d2-5647-bb7b-22af44fcf85d","questionId":"f5bc20a8-53f4-56a3-b53b-c9271e80322e","sourceKey":"bank:ECO201:E201-0190","payload":{"prompt":"If an input is owned and used by a firm, then its","options":["explicit cost is zero","implicit cost is zero","opportunity cost is zero","economic cost is zero."],"correctOption":0,"section":"Costs of Production","explanation":"When the firm owns and uses an input, it pays no money to anyone for it, so the explicit cost is zero. However, it still gives up what the input could earn elsewhere, so the implicit (opportunity) cost is not zero, which rules out B and C, and economic cost (explicit plus implicit) is not zero either, which rules out D."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 715, $official_bank_source${"itemId":"35bbcc0b-885e-54fe-ab83-404c1fb8a105","questionId":"08527a6c-1101-51a8-ad7f-719d04687690","sourceKey":"bank:ECO201:E201-0191","payload":{"prompt":"Short-run marginal cost is equal to","options":["the change in total cost divided by the change in output.","the change in total variable cost divided by the change in output.","the cost per unit of the variable input divided by the marginal product of the variable input.","all of the above."],"correctOption":3,"section":"Costs of Production","explanation":"MC = change in TC / change in Q, and since fixed cost does not change, this equals change in TVC / change in Q. With one variable input L at price w, change in TVC = w x change in L, so MC = w / (change in Q / change in L) = w/MP. All three expressions are equal, so D is correct."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 716, $official_bank_source${"itemId":"9071c6a7-acab-51d2-9854-22786e005b3f","questionId":"f025d5a1-b163-59a5-932b-adebeb3b9122","sourceKey":"bank:ECO201:E201-0192","payload":{"prompt":"Short-run average variable cost is equal to","options":["total variable cost divided by output.","average total cost minus average fixed cost.","the cost per unit of the variable input divided by the average product of the variable input.","all of the above."],"correctOption":3,"section":"Costs of Production","explanation":"AVC = TVC/Q by definition; since ATC = AFC + AVC, AVC also equals ATC - AFC; and with TVC = wL, AVC = wL/Q = w/(Q/L) = w/AP. All three expressions describe the same thing, so D is correct."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 717, $official_bank_source${"itemId":"bce96ec4-7e56-55da-8d5a-3a8dad66d2e9","questionId":"d1c7521a-efe2-5bbb-9959-72e7529ce806","sourceKey":"bank:ECO201:E201-0193","payload":{"prompt":"Which of the following short-run cost curves declines continuously?","options":["Average total cost","Marginal cost","Average fixed cost","Average variable cost"],"correctOption":2,"section":"Costs of Production","explanation":"AFC = TFC/Q, and since TFC is a constant spread over more and more units, AFC keeps falling as output rises. Options A, B and D are U-shaped: ATC, MC and AVC all fall at first and then rise because of diminishing returns."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 718, $official_bank_source${"itemId":"9d7f4f80-9166-5af4-84f9-ef95469cedf1","questionId":"434ae655-55ed-515d-af17-4c0c49d05732","sourceKey":"bank:ECO201:E201-0194","payload":{"prompt":"The law of diminishing returns begins at the level of output where","options":["marginal cost is at a minimum.","average variable cost is at a minimum.","average fixed cost is at a maximum.","None of the above is correct."],"correctOption":0,"section":"Costs of Production","explanation":"Diminishing returns begin where MP of the variable input reaches its maximum and starts to fall, and because MC = w/MP, that is exactly where MC is at its minimum. Option B is wrong because AVC is at its minimum where AP is at its maximum, which comes later, and AFC (option C) has no maximum at positive output since it falls continuously."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 719, $official_bank_source${"itemId":"6f06d2a6-2766-5cb0-9634-b769556dae33","questionId":"5b6a7984-93af-5952-bcdc-6d450f817101","sourceKey":"bank:ECO201:E201-0195","payload":{"prompt":"The long-run average cost curve is at a minimum at a level of output where","options":["the firm is experiencing constant returns to scale.","it is equal to long-run marginal cost.","the long- run average cost curve is tangent to the lowest point on a short-run average total cost curve.","all of the above occur."],"correctOption":3,"section":"Costs of Production","explanation":"At the lowest point of the LAC curve the firm has used up its economies of scale and has not yet met diseconomies, so returns to scale are constant. LMC cuts LAC at its minimum, so they are equal, and at that output the LAC is tangent to the minimum point of the optimal short-run ATC curve. All three are true, so D is correct."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 720, $official_bank_source${"itemId":"b17c4f04-54d4-56f9-af9d-6c95acd605f5","questionId":"ea19722d-f9c0-5c76-bbc7-b7db4e036065","sourceKey":"bank:ECO201:E201-0196","payload":{"prompt":"If a firm has a downward sloping long-run average cost curve, then","options":["it is experiencing decreasing returns to scale.","it is experiencing decreasing returns.","it is enjoying economies of scale.","marginal cost is greater than average cost."],"correctOption":2,"section":"Costs of Production","explanation":"A downward-sloping long-run average cost curve means cost per unit falls as the firm expands its scale, which is what economies of scale means. Options A and B are wrong because decreasing returns would push average cost up, not down, and option D is wrong because when an average is falling the marginal must be below it, so LMC < LAC."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 721, $official_bank_source${"itemId":"71fa35cb-8c15-59b9-be04-7b70296e2198","questionId":"52385c66-1088-5d66-99b4-0c8f0148ebac","sourceKey":"bank:ECO201:E201-0197","payload":{"prompt":"One reason that a firm may enjoy economies of scale is that greater levels of output make it possible for the firm to","options":["employ more specialized machinery.","obtain bulk purchase discounts.","employ a greater division of labor.","All of the above are correct."],"correctOption":3,"section":"Costs of Production","explanation":"Economies of scale arise because a bigger output lets the firm spread the cost of specialised machinery, gain bulk-purchase discounts on inputs, and organise a finer division of labour. Each of A, B and C lowers long-run average cost as the firm expands, so D is correct."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 722, $official_bank_source${"itemId":"787e9dea-294f-5e1d-b573-183e1aba288d","questionId":"79a7b8f2-8bd6-5ae4-882b-18aa75707016","sourceKey":"bank:ECO201:E201-0199","payload":{"prompt":"Economies of scope refers to the decrease in average total cost that can occur when a firm","options":["produces more than one product.","has monopoly power in world markets.","controls the raw materials used as inputs.","narrows the scope of its regional markets."],"correctOption":0,"section":"Costs of Production","explanation":"Economies of scope are the cost savings a firm gets when it produces two or more products together instead of separately, for example by sharing the same machines, staff or distribution network. Options B and C describe market power or control of inputs, which are not about producing several products, and option D, narrowing its markets, has nothing to do with scope economies."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 723, $official_bank_source${"itemId":"8c5ed396-d0ef-5be2-a210-09333b37c46e","questionId":"9296b654-d821-5a7d-9218-af59bcdbc0bf","sourceKey":"bank:ECO201:E201-0211","payload":{"prompt":"The value of inputs that a firm already owns and uses in its own production, such as its own building or the owner's own capital, is best classified as:","options":["an implicit cost","an explicit cost","an accounting cost","a cash payment made to outside suppliers"],"correctOption":0,"section":"Costs of Production","explanation":"An implicit cost is the opportunity cost of using resources the firm already owns, because no money is paid out but the firm gives up what those resources could earn elsewhere. Option B is wrong because explicit costs are actual payments to outsiders, and options C and D also describe recorded cash payments, which owned inputs do not involve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 724, $official_bank_source${"itemId":"846abbac-f3f1-57c6-9bdf-65e8789417a0","questionId":"203b8e88-7f3e-5348-a8ce-a5eaa303e75c","sourceKey":"bank:ECO201:E201-0213","payload":{"prompt":"Which of the following is correct about economic cost and accounting cost?","options":["Economic cost is generally lower than accounting cost, because it leaves out implicit costs","Economic cost and accounting cost are always exactly equal","Economic cost is generally greater than or equal to accounting cost, because it includes implicit costs as well as explicit costs","Accounting cost includes implicit costs, while economic cost includes only explicit costs"],"correctOption":2,"section":"Costs of Production","explanation":"Economic cost adds implicit costs (the opportunity cost of owned resources) to the explicit costs that accountants record, so it is usually larger than accounting cost and never smaller. Option A reverses this relationship, and option D mixes up the two terms, since accountants record only explicit, paid-out costs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 725, $official_bank_source${"itemId":"05620762-8530-5698-8f70-b9f4511f25c0","questionId":"f8a79618-b9a9-5c2a-8b68-1ebc3da8f243","sourceKey":"bank:ECO201:E201-0214","payload":{"prompt":"Accounting costs are best described as:","options":["implicit costs only","explicit costs plus implicit costs","explicit costs, that is, actual payments made for inputs bought or hired","the opportunity cost of the owner's own time and capital"],"correctOption":2,"section":"Costs of Production","explanation":"Accounting costs are the explicit costs a firm actually pays out and records in its books, such as wages, rent and raw materials. Option B, explicit plus implicit costs, is the definition of economic cost, while options A and D describe implicit costs, which accountants usually do not record."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 726, $official_bank_source${"itemId":"9ac4af6e-ac6b-5463-90ff-67119709dccf","questionId":"013a3e6c-699c-516c-a7cc-f6b8acff9955","sourceKey":"bank:ECO201:E201-0215","payload":{"prompt":"Which type of cost should NOT affect a firm's current production decisions?","options":["Marginal costs","Variable costs","Opportunity costs","Sunk costs"],"correctOption":3,"section":"Costs of Production","explanation":"Sunk costs have already been incurred and cannot be recovered whatever the firm decides now, so they should be ignored in current decisions. Marginal costs (option A), variable costs (option B) and opportunity costs (option C) all change with the choice being made, so they must be considered."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 727, $official_bank_source${"itemId":"231c2eb7-b4f7-5928-8461-677fd55b42e2","questionId":"8850ee29-8e78-5a8d-971a-8308e5b104a1","sourceKey":"bank:ECO201:E201-0216","payload":{"prompt":"In the short run, when a firm's output is zero, its total cost is equal to:","options":["total fixed cost","zero","average fixed cost","marginal cost"],"correctOption":0,"section":"Costs of Production","explanation":"In the short run some inputs are fixed, so the firm must pay its fixed costs such as rent even when it produces nothing; since TC = TFC + TVC and TVC = 0 at zero output, TC = TFC. Option B is wrong because fixed costs do not disappear in the short run, and option C is a per-unit measure that cannot even be calculated at zero output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 728, $official_bank_source${"itemId":"66d5a5e2-b6fb-5310-84c7-56adc8dc05df","questionId":"e89af7ca-d47c-5529-babe-cd9e2fe4ca72","sourceKey":"bank:ECO201:E201-0217","payload":{"prompt":"In the long run, a firm's total cost at zero output is:","options":["positive and equal to the cost of its fixed plant","equal to its short-run total cost at zero output","undefined, because average cost cannot be calculated at zero output","zero, because all inputs can be varied and no fixed costs remain"],"correctOption":3,"section":"Costs of Production","explanation":"In the long run every input can be adjusted, so all costs are variable and a firm producing nothing can avoid all costs, making total cost zero. Options A and B are wrong because a fixed plant cost exists only in the short run, and option C confuses total cost with average cost."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 729, $official_bank_source${"itemId":"67ee9d07-318c-549e-b9d7-ac58323eb435","questionId":"a80736ff-fa0f-5a72-bd74-bde208738d4c","sourceKey":"bank:ECO201:E201-0218","payload":{"prompt":"In economic theory, a firm's cost curves show:","options":["the minimum cost of producing each level of output","the maximum cost the firm could incur at each level of output","the revenue the firm earns at each level of output","the average cost of all firms in the industry"],"correctOption":0,"section":"Costs of Production","explanation":"Cost curves assume the firm uses the cheapest (most efficient) combination of inputs, so each point shows the lowest possible cost of producing that output. Option B is the opposite idea, option C describes revenue rather than cost, and option D refers to the industry rather than the firm."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 730, $official_bank_source${"itemId":"3e0be7e0-6199-5b54-9e04-80bc796977dc","questionId":"7f97e60a-7c94-5a79-b3f6-7c77b2668e10","sourceKey":"bank:ECO201:E201-0219","payload":{"prompt":"Total variable cost (TVC) is equal to:","options":["total fixed cost minus total cost (TFC - TC)","total cost plus total fixed cost (TC + TFC)","short-run total cost minus total fixed cost (TC - TFC)","average total cost minus average fixed cost (ATC - AFC)"],"correctOption":2,"section":"Costs of Production","explanation":"Since TC = TFC + TVC, rearranging gives TVC = TC - TFC; for example, if TC = N500 and TFC = N200, then TVC = N300. Option D, ATC - AFC, gives average variable cost (AVC), a per-unit figure, not total variable cost, and options A and B rearrange the identity wrongly."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 731, $official_bank_source${"itemId":"79f9bf79-2a69-5f48-8db6-7ae3510464b2","questionId":"edf5272f-6983-51a9-b89d-fdbe615e9751","sourceKey":"bank:ECO201:E201-0220","payload":{"prompt":"Which of the following best describes the shape of the average fixed cost (AFC) curve?","options":["It is U-shaped","It falls continuously as output rises, getting closer to the output axis without touching it","It is a horizontal straight line","It rises continuously as output increases"],"correctOption":1,"section":"Costs of Production","explanation":"AFC = TFC/Q, so the same fixed cost is spread over more and more units as output rises, and AFC keeps falling without ever reaching zero (a rectangular hyperbola). Option A is wrong because AFC never turns upward; it is AVC, ATC and MC that are U-shaped. Option C describes total fixed cost, not average fixed cost."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 732, $official_bank_source${"itemId":"5621f462-b7a8-5352-940f-76ce9b0f4f4d","questionId":"a315c317-2bc7-5835-9c90-0bc6cc8f8163","sourceKey":"bank:ECO201:E201-0221","payload":{"prompt":"The law of diminishing returns is reflected in which part of the short-run marginal cost (MC) curve?","options":["The downward-sloping (falling) portion","The upward-sloping (rising) portion","The portion lying below the average fixed cost curve","It is not reflected in the MC curve at all"],"correctOption":1,"section":"Costs of Production","explanation":"When diminishing returns set in, each extra unit of the variable input adds less output, so each extra unit of output costs more and MC rises. Option A is wrong because the falling part of MC reflects increasing returns to the variable input, before diminishing returns begin."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 733, $official_bank_source${"itemId":"6843e744-bda2-5425-9f8c-da2a3a81b640","questionId":"2b91a958-c517-5f3a-b6c0-558db80f7020","sourceKey":"bank:ECO201:E201-0222","payload":{"prompt":"Average total cost (ATC) is equal to marginal cost (MC) at the level of output where:","options":["ATC is at its minimum","MC is at its minimum","average fixed cost is at its minimum","total cost is at its maximum"],"correctOption":0,"section":"Costs of Production","explanation":"MC cuts the ATC curve from below at the lowest point of ATC: while MC is below ATC it pulls the average down, and once MC is above ATC it pulls the average up. Option B is the most tempting mistake, but MC reaches its minimum earlier, at a lower output than where it meets ATC."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 734, $official_bank_source${"itemId":"d5ab01ea-c927-5763-be92-a898996eefb9","questionId":"36668987-0eeb-5419-beb5-2c1e77440376","sourceKey":"bank:ECO201:E201-0224","payload":{"prompt":"The point of inflection of the short-run total variable cost (TVC) curve corresponds to the level of output where:","options":["average variable cost is at a minimum","marginal cost is at a minimum","average total cost is at a minimum","marginal cost is at a maximum"],"correctOption":1,"section":"Costs of Production","explanation":"MC is the slope of the TVC curve; at the inflection point TVC stops rising at a decreasing rate and starts rising at an increasing rate, so its slope, MC, is at its lowest there. Options A and C occur at larger outputs, where a ray from the origin is tangent to the TVC and TC curves respectively."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 735, $official_bank_source${"itemId":"c9ca96b4-1e96-5032-854e-083ce4cd27c9","questionId":"33ae336a-c4af-552c-9a26-8863915ea3a6","sourceKey":"bank:ECO201:E201-0225","payload":{"prompt":"If marginal cost (MC) is greater than average total cost (ATC), then ATC is:","options":["rising","falling","constant at its minimum","equal to average fixed cost"],"correctOption":0,"section":"Costs of Production","explanation":"When the cost of an extra unit is above the current average, adding that unit pulls the average up, just as scoring above your average raises your average score. Option B happens when MC is below ATC, and option C happens only at the single point where MC equals ATC."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 736, $official_bank_source${"itemId":"2a948417-2164-5b46-b096-6dd97c5c03bb","questionId":"678ef607-0daf-5246-8fab-06df39ece34c","sourceKey":"bank:ECO201:E201-0226","payload":{"prompt":"The vertical distance between the short-run average total cost (ATC) and average variable cost (AVC) curves at any level of output measures:","options":["average fixed cost (AFC)","marginal cost","total fixed cost","average variable cost"],"correctOption":0,"section":"Costs of Production","explanation":"Since ATC = AVC + AFC, the gap ATC - AVC equals AFC, which is why the two curves get closer together as output rises and AFC falls. Option C is tempting, but total fixed cost is a total, not a per-unit amount, and option B is the cost of one extra unit, which is not this gap."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 737, $official_bank_source${"itemId":"03f89cf9-4f75-5122-90bf-79c3aaeb89d1","questionId":"878de3ee-5367-54b5-9a94-410d2780b57c","sourceKey":"bank:ECO201:E201-0228","payload":{"prompt":"The slope of a ray drawn from the origin to any point on the total cost curve measures, at that point:","options":["marginal cost","average total cost","average fixed cost","total fixed cost"],"correctOption":1,"section":"Costs of Production","explanation":"The slope of the ray is the height of the point (TC) divided by its horizontal distance (Q), which is TC/Q = ATC. Option A is the slope of the tangent to the total cost curve, not of a ray from the origin."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 738, $official_bank_source${"itemId":"9040f826-f92a-539e-919d-c7f120063af6","questionId":"3d38481a-21ee-553f-b25e-b73eabf2f57f","sourceKey":"bank:ECO201:E201-0229","payload":{"prompt":"If a ray from the origin is just tangent to the short-run total cost curve, then at that point:","options":["marginal cost is at its minimum","average fixed cost is at its minimum","average total cost is at its minimum and equals marginal cost","total cost is at its minimum"],"correctOption":2,"section":"Costs of Production","explanation":"The slope of a ray from the origin measures ATC, and the flattest ray that still touches the TC curve is the one tangent to it, so ATC is lowest there; because it is also a tangent, its slope equals MC too. Option A occurs earlier, at the inflection point of the TC curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 739, $official_bank_source${"itemId":"cb328930-2090-5c07-a698-98421a5a39ac","questionId":"9d420ed6-701d-5bfa-9791-61f980da0e50","sourceKey":"bank:ECO201:E201-0230","payload":{"prompt":"With the price of the variable input constant, the output at which the marginal product (MP) of the variable input is at a maximum corresponds to the output at which:","options":["marginal cost is at a maximum","marginal cost is at a minimum","average variable cost is at a maximum","average fixed cost is at a minimum"],"correctOption":1,"section":"Costs of Production","explanation":"With a fixed input price w, MC = w/MP, so when MP is at its highest, MC is at its lowest; the MC curve is roughly the MP curve turned upside down. Option A reverses this inverse relationship."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 740, $official_bank_source${"itemId":"48283a4b-07fb-531d-8c12-848a0e4eca26","questionId":"3b7c3953-5175-5a99-9172-9a54557f4a2c","sourceKey":"bank:ECO201:E201-0231","payload":{"prompt":"With the price of the variable input constant, the output at which the average product (AP) of the variable input is at a maximum corresponds to the output at which:","options":["average variable cost is at a minimum","short-run average total cost is at a minimum","marginal cost is at a maximum","average fixed cost is at a minimum"],"correctOption":0,"section":"Costs of Production","explanation":"With a fixed input price w, AVC = w/AP, so when AP is at its highest, AVC is at its lowest. Option B is tempting, but ATC also includes AFC, which keeps falling, so ATC reaches its minimum at a larger output than the AP maximum."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 741, $official_bank_source${"itemId":"acc954fb-6d6c-5d7e-a708-164d6c1d874f","questionId":"7cbd4f74-e570-5721-bf23-7c9d691c3c95","sourceKey":"bank:ECO201:E201-0232","payload":{"prompt":"Which of the following is correct about costs in the long run?","options":["All costs are variable","All costs are fixed","Fixed costs remain, but variable costs disappear","Total cost is always equal to short-run total fixed cost"],"correctOption":0,"section":"Costs of Production","explanation":"The long run is a period long enough for the firm to change the quantities of all its inputs, including plant size, so there are no fixed costs and every cost is variable. Options B and C describe the opposite of this, since fixed costs exist only in the short run."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 742, $official_bank_source${"itemId":"0a31bc47-7659-5ad1-bf4a-4778890ff78f","questionId":"e4d0a49f-b82c-555d-823f-7c84d1fc48ab","sourceKey":"bank:ECO201:E201-0233","payload":{"prompt":"The long-run total cost curve is derived from the firm's:","options":["short-run total fixed cost curve","demand curve","expansion path","production possibility curve"],"correctOption":2,"section":"Costs of Production","explanation":"The expansion path joins the least-cost input combinations (tangencies of isoquants and isocost lines) for each level of output, so reading off the cost of each point gives the long-run total cost curve. Option A is a short-run concept, and options B and D relate to consumers and the whole economy rather than the firm's costs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 743, $official_bank_source${"itemId":"e1838122-cc2b-5fe5-8c9b-09a1a6e89bde","questionId":"b55f6e74-1454-5a9e-ad10-8e0c1f61def0","sourceKey":"bank:ECO201:E201-0234","payload":{"prompt":"Which of the following is correct about the long-run average cost (LAC) curve and the short-run average total cost (SATC) curves?","options":["The LAC is tangent to the lowest point of every SATC curve","The LAC is an envelope tangent to each SATC curve, but it touches an SATC curve at its minimum point only at the lowest point of the LAC","The LAC lies above all the SATC curves","The LAC cuts each SATC curve at its highest point"],"correctOption":1,"section":"Costs of Production","explanation":"The LAC envelopes the SATC curves, touching each one at a single point. When the LAC is falling, the tangency is on the falling part of the SATC, and when it is rising, it is on the rising part, so only at the lowest point of the LAC does it touch an SATC at its minimum. Option A is the common mistake, and option C is wrong because the LAC can never lie above any SATC curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 744, $official_bank_source${"itemId":"3a2ca3a4-c3f2-5d5f-9280-c153bda053dc","questionId":"a0d76fb7-4290-5c1d-a638-a56626a7dd94","sourceKey":"bank:ECO201:E201-0236","payload":{"prompt":"If long-run marginal cost (LMC) is greater than long-run average cost (LAC), the firm is experiencing:","options":["increasing returns to scale, with LAC falling","constant returns to scale, with LAC flat","the minimum point of LAC","decreasing returns to scale, with LAC rising"],"correctOption":3,"section":"Costs of Production","explanation":"When LMC is above LAC, each extra unit costs more than the average, so LAC is rising, which reflects decreasing returns to scale (diseconomies of scale). Option A occurs when LMC is below LAC, and option C is the single point where LMC equals LAC."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 745, $official_bank_source${"itemId":"1c1748dc-cdf2-5c63-ae14-9d49b0e866fe","questionId":"d6324c21-902e-5c7f-99c1-d6ee48b184ae","sourceKey":"bank:ECO201:E201-0237","payload":{"prompt":"Long-run marginal cost (LMC) is equal to short-run marginal cost (SMC) at the level of output where:","options":["short-run marginal cost is at its minimum","short-run average total cost is at its maximum","average fixed cost equals average variable cost","the corresponding short-run average total cost curve is tangent to the long-run average cost curve"],"correctOption":3,"section":"Costs of Production","explanation":"At the output where an SATC curve is tangent to the LAC, the plant is the best one for that output, so short-run and long-run total costs are equal and touch each other, which means their slopes, SMC and LMC, are equal too. Option A confuses this with the inflection point of the short-run cost curve, which is a different output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 746, $official_bank_source${"itemId":"2c2fec00-5724-59d3-8ead-f90fa68c4a58","questionId":"c0a6cbe9-af92-5207-9fc9-3198a11f7837","sourceKey":"bank:ECO201:E201-0239","payload":{"prompt":"When small and large firms are able to coexist successfully in an industry, the long-run average cost curve is most likely:","options":["steeply downward-sloping over the whole range of output","steeply upward-sloping from very low levels of output","nearly horizontal over a wide range of output","vertical"],"correctOption":2,"section":"Costs of Production","explanation":"If firms of very different sizes can all survive, none has a clear cost advantage, so cost per unit is roughly the same at small and large scales, meaning roughly constant returns to scale and a fairly flat LAC. Option A would give large firms a big cost advantage and push small ones out, while option B would do the opposite."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 747, $official_bank_source${"itemId":"48950198-4111-5a32-838f-f3b78ddf43c2","questionId":"88b3cc3c-cddc-5162-bfd9-81e3417ab2dc","sourceKey":"bank:ECO201:E201-0297","payload":{"prompt":"The average fixed cost is obtained by :","options":["TFC / Q","MC / Q","TAC / Q","AVC / Q"],"correctOption":0,"section":"Costs of Production","explanation":"Average fixed cost is total fixed cost spread over each unit of output, so AFC = TFC / Q. Because TFC does not change with output, AFC keeps falling as Q rises. Option C, TAC / Q, is not a standard cost measure, and option B, MC / Q, has no economic meaning."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 748, $official_bank_source${"itemId":"b2c562c5-d0b1-5f58-945a-ecc308f9c037","questionId":"b90c2abb-be76-5795-bc1c-e028af88f895","sourceKey":"bank:ECO201:E201-0309","payload":{"prompt":"Implicit costs are:","options":["Equal to total fixed costs.","Comprised entirely of variable costs.","\"Payments\" for self-employed resources.","Always greater in the short run than in the long run."],"correctOption":2,"section":"Costs of Production","explanation":"Implicit costs are the opportunity costs of resources the firm's owners already own and use in the business, such as their own time, building or money. No cash is paid out, so they are like \"payments\" to self-employed resources. Option A is wrong because implicit costs are not the same as fixed costs, and option B is wrong because they need not vary with output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 749, $official_bank_source${"itemId":"86cd7765-2651-58db-a294-154520d43d47","questionId":"a39705e1-d635-5528-b7ce-6927d4489ef3","sourceKey":"bank:ECO201:E201-0310","payload":{"prompt":"Which would be an implicit cost for a firm? The cost:","options":["Of worker wages and salaries for the firm.","Paid for leasing a building for the firm.","Paid for production supplies for the firm.","Of wages foregone by the owner of the firm."],"correctOption":3,"section":"Costs of Production","explanation":"An implicit cost is the value of something the firm uses without paying cash for it. The wages an owner gives up by working in his own firm instead of taking a job elsewhere is a classic example. Options A, B and C are all cash payments to outsiders (workers, a landlord, suppliers), so they are explicit costs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 750, $official_bank_source${"itemId":"b527695a-776d-5e19-bcef-65008db5d651","questionId":"0aebc7c2-9b41-539a-9eb3-606010f4daf3","sourceKey":"bank:ECO201:E201-0311","payload":{"prompt":"If a firm's revenues just cover all its opportunity costs, then:","options":["Normal profit is zero.","Economic profit is zero.","Total revenues equal its explicit costs.","Total revenues equal its implicit costs."],"correctOption":1,"section":"Costs of Production","explanation":"Economic profit is total revenue minus all opportunity costs, both explicit and implicit. If revenue just covers all of them, economic profit is zero, which means the firm earns exactly a normal profit. Option A is wrong because normal profit is positive in that case, and options C and D each leave out one part of total cost."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 751, $official_bank_source${"itemId":"d535588b-bf11-5d04-a7f6-4d48d9fbd0b4","questionId":"5cc7a025-8917-5ddf-9b13-602a5bbb9e42","sourceKey":"bank:ECO201:E201-0312","payload":{"prompt":"Suppose a firm sells its product at a price lower than the opportunity cost of the inputs used to produce it. Which is true?","options":["The firm will earn accounting and economic profits.","The firm will face accounting and economic losses.","The firm will face an accounting loss, but earn economic profits.","The firm may earn accounting profits, but will face economic losses."],"correctOption":3,"section":"Costs of Production","explanation":"If price is below the full opportunity cost of the inputs, economic profit (revenue minus explicit and implicit costs) is negative. However, accounting profit only subtracts explicit costs, so it can still be positive when implicit costs are large. Option B is too strong because an accounting loss is not guaranteed, and options A and C wrongly claim an economic profit."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 752, $official_bank_source${"itemId":"7453e4aa-aad6-5dd8-80dc-e58cbd585df3","questionId":"c20cdd06-d5d2-5fea-9b23-77b8d9577315","sourceKey":"bank:ECO201:E201-0313","payload":{"prompt":"Suppose that a firm produces 200,000 units a year and sells them all for N10 each. The explicit costs of production are N1,500,000 and the implicit costs of production are N300,000. The firm has an accounting profit of:","options":["N500,000 and an economic profit of N200,000.","N400,000 and an economic profit of N200,000.","N300,000 and an economic profit of N400,000.","N200,000 and an economic profit of N500,000."],"correctOption":0,"section":"Costs of Production","explanation":"Total revenue = 200,000 x N10 = N2,000,000. Accounting profit = TR - explicit costs = 2,000,000 - 1,500,000 = N500,000, and economic profit = TR - explicit - implicit costs = 2,000,000 - 1,500,000 - 300,000 = N200,000. Option B gets the accounting profit wrong, while options C and D mix up the two profit measures."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 753, $official_bank_source${"itemId":"1af48f1d-199b-5e66-af09-d84f01990dab","questionId":"7304bb75-cded-53ec-85ad-ca7d02d88b25","sourceKey":"bank:ECO201:E201-0320","payload":{"prompt":"Variable costs are:","options":["Sunk costs.","Multiplied by fixed costs.","Costs that change with the level of production.","Defined as the change in total cost resulting from the production of an additional unit of output."],"correctOption":2,"section":"Costs of Production","explanation":"Variable costs are costs that rise or fall as the level of output changes, such as raw materials and hourly wages. Option D is the definition of marginal cost, not variable cost, and option A is wrong because sunk costs are already incurred and cannot change with output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 754, $official_bank_source${"itemId":"64ce393d-1dce-5443-aa4f-d39cca8b977d","questionId":"89b6e8d1-7b71-53e1-a635-bed6662f2135","sourceKey":"bank:ECO201:E201-0321","payload":{"prompt":"Which is not a fixed cost?","options":["Monthly rent of N1,000 contractually specified in a one-year lease","An insurance premium of N50 per year, paid last month","An attorney's retainer of N50,000 per year","A worker's wage of N15 per hour"],"correctOption":3,"section":"Costs of Production","explanation":"A fixed cost does not change with the level of output in the short run. Rent fixed in a lease, an insurance premium and a yearly retainer must be paid however much is produced, but an hourly wage rises as more hours are worked to produce more output, so it is a variable cost. Options A, B and C are all fixed costs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 755, $official_bank_source${"itemId":"17f67764-26c9-5586-a78f-8f3e8ad20b4a","questionId":"432dcffa-95b0-5ae0-8a39-2c6debe43959","sourceKey":"bank:ECO201:E201-0322","payload":{"prompt":"If you know that with 8 units of output, average fixed cost is N12.50 and average variable cost is N81.25, then total cost at this output level is:","options":["N93.75.","N97.78.","N750.","N880."],"correctOption":2,"section":"Costs of Production","explanation":"Average total cost = AFC + AVC = 12.50 + 81.25 = N93.75, and total cost = ATC x Q = 93.75 x 8 = N750. Option A is the average total cost, not the total cost, so it forgets to multiply by output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 756, $official_bank_source${"itemId":"66814e78-7e67-5f15-b56c-15389bcf173d","questionId":"4806743e-039e-5a0c-9413-4cffa2b2af46","sourceKey":"bank:ECO201:E201-0323","payload":{"prompt":"With fixed costs of N400, a firm has average total costs of N3 and average variable costs of N2.50. Its output is:","options":["200 units.","400 units.","800 units.","1,600 units."],"correctOption":2,"section":"Costs of Production","explanation":"Average fixed cost = ATC - AVC = 3 - 2.50 = N0.50. Since AFC = TFC / Q, output Q = 400 / 0.50 = 800 units. Option A or B would come from dividing fixed cost by the wrong figure, and option D doubles the correct answer."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 757, $official_bank_source${"itemId":"8b22f92e-5328-50ef-8481-936d3ae5450e","questionId":"b71001d1-4107-5063-89c2-150fdf53bff7","sourceKey":"bank:ECO201:E201-0324","payload":{"prompt":"The reason the marginal cost curve eventually increases as output increases for the typical firm is because:","options":["Of diseconomies of scale.","Of minimum efficient scale.","Of the law of diminishing returns.","Normal profit exceeds economic profit."],"correctOption":2,"section":"Costs of Production","explanation":"In the short run, once diminishing returns set in, each extra worker adds less output, so each extra unit of output needs more variable input and costs more. That is why the marginal cost curve eventually rises. Option A, diseconomies of scale, is a long-run idea that explains the rising part of the long-run average cost curve, not the short-run MC curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 758, $official_bank_source${"itemId":"f6b440cc-d153-52bc-befa-c01ad1b1a772","questionId":"204cc80a-4d4a-52a6-b629-c28bd2f8a114","sourceKey":"bank:ECO201:E201-0325","payload":{"prompt":"If the short-run average variable costs of production for a firm are rising, then this indicates that:","options":["Average total costs are at a maximum.","Average fixed costs are constant.","Marginal costs are above average variable costs.","Average variable costs are below average fixed costs."],"correctOption":2,"section":"Costs of Production","explanation":"Average variable cost rises whenever the marginal cost of the last unit is above the current average, just as a high new score pulls up an average. So rising AVC means MC is above AVC. Option B is wrong because AFC keeps falling as output rises, and option A is wrong because ATC is U-shaped and has a minimum, not a maximum."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 759, $official_bank_source${"itemId":"c88440f6-f7be-5525-b387-d99da7fb74b1","questionId":"364946f8-44b3-52aa-8205-d9cee679faa9","sourceKey":"bank:ECO201:E201-0326","payload":{"prompt":"If a more efficient technology was discovered by a firm, there would be:","options":["An upward shift in the AVC curve.","An upward shift in the AFC curve.","A downward shift in the AFC curve.","A downward shift in the MC curve."],"correctOption":3,"section":"Costs of Production","explanation":"A more efficient technology lets the firm produce each extra unit with fewer variable inputs, so the cost of an extra unit falls and the MC curve shifts down. Options B and C are wrong because AFC depends only on fixed cost and output, not on how efficiently variable inputs are used, and option A goes in the wrong direction."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 760, $official_bank_source${"itemId":"7e74a884-85a8-526a-abcd-419414dde6be","questionId":"f86874a2-27a4-568e-9f1e-b29ffc0fcb2e","sourceKey":"bank:ECO201:E201-0327","payload":{"prompt":"The firm's short-run marginal-cost curve is increasing when:","options":["Marginal product is increasing.","Marginal product is decreasing.","Total fixed cost is increasing.","Average fixed cost is decreasing."],"correctOption":1,"section":"Costs of Production","explanation":"Marginal cost is closely linked to marginal product: when each extra worker adds less output, each extra unit of output needs more labour and so costs more. So MC rises when MP is falling. Option A is the opposite case, when MC is falling, and options C and D are about fixed cost, which has no effect on marginal cost."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 761, $official_bank_source${"itemId":"caeea4aa-36db-5466-98c6-26cfbd36e512","questionId":"95e68ced-053d-5d3e-ab1e-ab24d1ca0f25","sourceKey":"bank:ECO201:E201-0328","payload":{"prompt":"A firm encountering economies of scale over some range of output will have a:","options":["Rising long-run average cost curve.","Falling long-run average cost curve.","Constant long-run average cost curve.","Rising, then falling, then rising long-run average cost curve."],"correctOption":1,"section":"Costs of Production","explanation":"Economies of scale mean that as a firm expands its scale of production, its long-run average cost per unit falls. So over the range where they occur, the LRAC curve slopes downward. Option A describes diseconomies of scale, and option C describes constant returns to scale."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 762, $official_bank_source${"itemId":"11cadc4a-5684-5876-9dbb-2de4de48adfa","questionId":"cdb49e89-5a72-500a-b325-c40dccc2fc0d","sourceKey":"bank:ECO201:E201-0330","payload":{"prompt":"The larger the diameter of a natural gas pipeline, the lower is the average total cost of transmitting 1,000 cubic feet of gas 1,000 miles. This is an example of:","options":["Economies of scale.","Normative economies.","Diminishing marginal returns.","An increasing marginal product of labour."],"correctOption":0,"section":"Costs of Production","explanation":"A bigger pipeline carries much more gas without a matching rise in cost, so the average cost per unit falls as the scale of operation grows. That is an example of economies of scale. Option C, diminishing marginal returns, would push costs up, not down, and option D is about adding labour, not increasing the size of the plant."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 763, $official_bank_source${"itemId":"0a90a056-fe39-5035-89c1-ba955bf168fd","questionId":"3ff49f4f-1ac3-5c9d-98cf-5ef010d30047","sourceKey":"bank:ECO201:E201-0332","payload":{"prompt":"Economies and diseconomies of scale explain why the:","options":["Short-run average fixed cost curve declines so long as output increases.","Marginal cost curve must intersect the minimum point of the firm's average total cost curve.","Long-run average total cost curve is typically U-shaped.","Short-run average variable cost curve is U-shaped."],"correctOption":2,"section":"Costs of Production","explanation":"The long-run average cost curve is U-shaped because, as the firm grows, economies of scale first push average cost down, then diseconomies of scale push it up. Option D is wrong because the short-run AVC curve is U-shaped due to the law of variable proportions, not scale effects, and option A is due to spreading a fixed cost over more units."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 764, $official_bank_source${"itemId":"47f5ca00-e7d9-5d3d-b52d-ccf5fa350af1","questionId":"7f3711ff-c8a8-5b71-bb60-3cbecb4ec911","sourceKey":"bank:ECO201:E201-0337","payload":{"prompt":"Economies of scale exist if:","options":["As the firm expands its scale of production, the cost of producing each unit rises","As the firm expands its scale of production, the cost of producing each unit falls","As more of one variable input is added to a fixed plant, marginal cost rises","As more of one variable input is added to a fixed plant, its marginal physical product falls"],"correctOption":1,"section":"Costs of Production","explanation":"Economies of scale exist when a bigger scale of operation, with all inputs free to change in the long run, lowers the cost of producing each unit. Option A describes diseconomies of scale. Options C and D describe diminishing returns from adding one input to a fixed plant in the short run, which is a different idea from changing the scale of the whole firm."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 765, $official_bank_source${"itemId":"aee3184c-5f43-55bd-8d81-10b897cac32a","questionId":"60bf6b43-3b6e-549c-85ca-7f37c59527ba","sourceKey":"bank:ECO201:E201-0346","payload":{"prompt":"Costs incurred only when production occurs are known as:","options":["Explicit costs.","Fixed costs.","Variable costs.","Technological expenses."],"correctOption":2,"section":"Costs of Production","explanation":"Variable costs, such as raw materials and hourly wages, arise only when the firm actually produces and rise with output, so they are zero at zero output. Option B is wrong because fixed costs must be paid even when nothing is produced. Option A is wrong because explicit costs are any cash payments, which include fixed costs too."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 766, $official_bank_source${"itemId":"75a82490-9057-5b82-8545-9165ad18cac2","questionId":"3adbd3e0-6aee-5917-8f8e-f10c3ce4d954","sourceKey":"bank:ECO201:E201-0349","payload":{"prompt":"A curve that can never be \"U\" shaped is the:","options":["Average variable cost curve.","Marginal cost curve.","Average fixed cost curve.","Average total cost curve."],"correctOption":2,"section":"Costs of Production","explanation":"Average fixed cost is TFC / Q. Since TFC stays the same, AFC falls continuously as output rises and never turns back up, so it can never be U-shaped. Options A, B and D are U-shaped because of the law of variable proportions: they first fall and later rise."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 767, $official_bank_source${"itemId":"bbf7a924-dd40-5ea8-836f-c7dcfc2106e5","questionId":"fd910eff-9a69-555b-9767-b5349e80d33d","sourceKey":"bank:ECO201:E201-0350","payload":{"prompt":"Diminishing marginal returns are most compatible with:","options":["Economies of scale.","Advantages from specialization.","Positively-sloped marginal cost curves","Depreciation of the capital stock."],"correctOption":2,"section":"Costs of Production","explanation":"When diminishing marginal returns set in, each extra unit of output needs more of the variable input, so the cost of each extra unit rises. That gives a positively sloped (rising) marginal cost curve. Option B is wrong because advantages from specialization raise productivity and work against diminishing returns, and option A is a long-run effect that lowers costs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 768, $official_bank_source${"itemId":"5fec6aa4-cece-592e-8f96-8caa6a161b3c","questionId":"9726e247-8998-5f53-9e75-0bc491ccfedc","sourceKey":"bank:ECO201:E201-0352","payload":{"prompt":"In economic theory the costs of a firm","options":["Tend to be less than the everyday use of the term costs would suggest","Include implicit as well as explicit outlays","Always decline as more output is produced","Are usually defined in such a way that profits will be larger than the everyday use of the term costs would imply"],"correctOption":1,"section":"Costs of Production","explanation":"In economics, the cost of a firm is its full opportunity cost, which includes implicit costs (such as the owner's own time and capital) as well as explicit cash payments. This is why economic costs are usually larger than accounting costs, so options A and D have it the wrong way round. Option C is wrong because costs do not always decline as output rises."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 769, $official_bank_source${"itemId":"7b5d3399-018c-5e9d-9e15-b27a81889e7e","questionId":"4e5b385e-9d5f-51c9-80c5-aed3a4075bfd","sourceKey":"bank:ECO201:E201-0353","payload":{"prompt":"The average total costs of the firm as defined in standard economic theory","options":["Are the sum of the fixed and any variable costs divided by the number of units of labour input","Are the sum of the fixed and any variable costs","Are the sum of the average fixed and the total variable costs","Are the sum of the fixed and variable costs divided by the number of units of output"],"correctOption":3,"section":"Costs of Production","explanation":"Average total cost is total cost per unit of output: ATC = (TFC + TVC) / Q. Option B is total cost, not average cost, and option A divides by units of labour instead of units of output, which is not how the cost measure is defined."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 770, $official_bank_source${"itemId":"e75f6ff8-71cb-5f4a-ab8a-0e24aa9e6545","questionId":"39e55d4d-ecd0-55ca-beb0-a150ea44c885","sourceKey":"bank:ECO201:E201-0355","payload":{"prompt":"According to the principle of diminishing marginal physical productivity, in the short run","options":["As output increases, costs per unit of output must eventually decline","Marginal product will decrease continually as output is expanded","As output is increased, the quantity of inputs needed to produce additional units of output will increase, causing costs per unit of output to increase","Total output will become negative once marginal product begins to decline"],"correctOption":2,"section":"Costs of Production","explanation":"Once diminishing marginal productivity sets in, each extra unit of output needs more and more of the variable input, so the cost per unit of output rises. Option B is wrong because marginal product falls only after a point, not continually from the start, and option D is wrong because total output stays positive and keeps rising while MP is falling but positive."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 771, $official_bank_source${"itemId":"5482e74d-725b-5f7f-b98e-417b24b4cc99","questionId":"02db2097-4b5c-56fe-9b7d-dda852ee1956","sourceKey":"bank:ECO201:E201-0356","payload":{"prompt":"Economies of scale","options":["Set in as soon as diminishing marginal physical productivity is experienced","Are usually considered to be a phenomenon of the long run","Arise only in the short run","Help ensure that industries will be competitive rather than monopolized"],"correctOption":1,"section":"Costs of Production","explanation":"Economies of scale come from changing the scale of the whole plant, which is possible only when all inputs can be varied, so they are a long-run phenomenon. Option A confuses them with diminishing returns, which push costs up in the short run, and option C is wrong because the short run does not allow a change in scale."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 772, $official_bank_source${"itemId":"059ea697-f70d-5768-abf8-4db9314a3956","questionId":"4f504a36-bf6f-528e-9579-232d0fcaa913","sourceKey":"bank:ECO201:E201-0358","payload":{"prompt":"Marginal costs and average variable costs are equal when","options":["Average variable cost is a maximum","Average variable cost is rising","Average variable cost is falling","Average variable cost is a minimum"],"correctOption":3,"section":"Costs of Production","explanation":"Marginal cost cuts the average variable cost curve at its lowest point. While MC is below AVC it pulls AVC down, and once MC is above AVC it pulls AVC up, so MC = AVC exactly at the minimum of AVC. Options B and C describe stages where MC is above or below AVC, and AVC has no maximum on its U shape."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 773, $official_bank_source${"itemId":"2b58f490-032d-5c20-ba0c-df916545e0d1","questionId":"040c3943-29b9-5693-a966-7607e26d56ad","sourceKey":"bank:ECO201:E201-0399","payload":{"prompt":"Which cost must be incurred by a firm even if its output is zero?","options":["Opportunity cost","Fixed cost","Variable cost","Marginal cost"],"correctOption":1,"section":"Costs of Production","explanation":"Fixed cost is the cost of fixed inputs such as rent or machinery, and it must be paid even when the firm produces nothing. Variable cost (option C) falls to zero at zero output, and marginal cost (option D) is the extra cost of producing one more unit, so it only arises when output actually changes."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 774, $official_bank_source${"itemId":"a348de88-7cea-567c-bf49-f31c42bdf642","questionId":"84841bc7-f27b-518f-9fda-6e6536186f71","sourceKey":"bank:ECO201:CST-001","payload":{"prompt":"In economics, explicit costs are","options":["actual money payments made to outside suppliers of factors, such as wages and rent paid","costs that do not change as output changes","the value of resources owned by the firm itself and used in production","the extra cost of producing one more unit of output"],"correctOption":0,"section":"Costs of Production","explanation":"Explicit costs are out-of-pocket payments to others, such as wages, rent, electricity bills and raw materials, so A is correct. Option C defines implicit costs, Option B defines fixed costs, and Option D defines marginal cost."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 775, $official_bank_source${"itemId":"076bf7c1-da0c-57f7-a2b5-c6a78b317a6e","questionId":"84e994e5-c4d2-5ad3-80e6-13855790de39","sourceKey":"bank:ECO201:CST-002","payload":{"prompt":"A woman runs a fashion shop in a building she owns in Surulere. Which of the following is an implicit cost of her business?","options":["Electricity bills paid to the distribution company","Salaries paid to her two tailors","The rent she could have earned by letting the building to someone else","Fabric bought from Balogun market"],"correctOption":2,"section":"Costs of Production","explanation":"An implicit cost is the opportunity cost of using resources the owner already has, and the rent she gives up by using her own building is exactly that, so C is right. Options B, A and D are all money payments to outsiders, which makes them explicit costs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 776, $official_bank_source${"itemId":"295c2169-6c01-5ed1-b940-7b9fe5fa97fd","questionId":"173dcac3-9551-5fd3-b87f-92ecf3a583ca","sourceKey":"bank:ECO201:CST-003","payload":{"prompt":"Economic cost differs from accounting cost mainly because economic cost","options":["includes implicit costs as well as explicit costs","excludes payments made to hired labour","excludes depreciation of machinery","includes only explicit costs"],"correctOption":0,"section":"Costs of Production","explanation":"Accountants record only explicit money payments, while economists also count the opportunity cost of the owner's own time, capital and property, so A is correct. Option D actually describes accounting cost, and Options C and B are wrong because economic cost still includes depreciation and wages."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 777, $official_bank_source${"itemId":"8a32649e-97e9-5813-bbb3-eea0c51f7e1f","questionId":"2c9bd268-9b49-5bd5-8ebe-619e7c377d31","sourceKey":"bank:ECO201:CST-004","payload":{"prompt":"In economics, normal profit is best described as","options":["the minimum return needed to keep the entrepreneur in the business, counted as part of economic cost","total revenue minus total fixed cost","any profit earned above total economic cost","accounting profit before tax"],"correctOption":0,"section":"Costs of Production","explanation":"Normal profit is the return the owner could earn in the next best use of their effort and capital, so it is treated as an implicit cost; a firm earning just normal profit has zero economic profit, which makes A right. Option C describes economic (supernormal) profit, and Option D ignores implicit costs."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 778, $official_bank_source${"itemId":"2925fb6a-2cf6-5310-8f73-76754e819e11","questionId":"d74f5b1a-4e04-531b-bfa6-0534901913ef","sourceKey":"bank:ECO201:CST-005","payload":{"prompt":"In economics, the cost of using a resource is measured by","options":["the market price of the firm's output","the cash payments shown in the firm's books only","the value of the best alternative use forgone","the historical price at which the resource was bought"],"correctOption":2,"section":"Costs of Production","explanation":"Economists measure cost as opportunity cost, the value of the next best alternative given up, which is why implicit costs are included, so C is correct. Option B is the accounting view that leaves out implicit costs, and Option D is wrong because what was paid in the past may differ from what the resource could earn now."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 779, $official_bank_source${"itemId":"ca2bd9fd-462b-55a0-83c7-5157442400a3","questionId":"74503736-61a1-54dd-858e-72fd2b1bd3a9","sourceKey":"bank:ECO201:CST-006","payload":{"prompt":"Which of the following is a fixed cost in the short run for a sachet-water factory?","options":["Wages of casual packers paid per bag","Diesel used to run the machines","Rent on the factory premises","The cost of nylon for the sachets"],"correctOption":2,"section":"Costs of Production","explanation":"A fixed cost must be paid whatever the level of output, even zero, and rent on the premises is like that, so C is right. Options D, B and A all rise or fall with the number of sachets produced, which makes them variable costs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 780, $official_bank_source${"itemId":"2623a7f0-6df3-5d72-a9ff-21cc71a0bc6b","questionId":"f4da1fec-243f-566a-9066-9efdff647183","sourceKey":"bank:ECO201:CST-007","payload":{"prompt":"Which of the following is NOT a variable cost for a manufacturing firm?","options":["The insurance premium on the factory building","Raw materials","Fuel for the production machines","Wages of workers paid per unit of output"],"correctOption":0,"section":"Costs of Production","explanation":"The insurance premium is paid at the same amount however much the firm produces, so it is a fixed cost and A is the answer. Options B, C and D all increase as output rises, which is what makes them variable costs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 781, $official_bank_source${"itemId":"7fcff8d1-6a79-5cef-af3a-494b0364efff","questionId":"fb794998-f0b2-55fd-bb1f-e029611b9b62","sourceKey":"bank:ECO201:CST-008","payload":{"prompt":"When a firm produces zero output in the short run, its total cost is equal to","options":["marginal cost","zero","total fixed cost","total variable cost"],"correctOption":2,"section":"Costs of Production","explanation":"In the short run fixed costs such as rent must still be paid even if nothing is produced, while variable cost is zero, so TC = TFC at zero output and C is correct. Option B would be true only in the long run, when there are no fixed costs, and Option D is wrong because TVC is zero at zero output."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 782, $official_bank_source${"itemId":"9b3d6dc2-8955-5ebe-8ef4-f2996af9ab9b","questionId":"304759ba-de53-52fd-b082-70b068883288","sourceKey":"bank:ECO201:CST-009","payload":{"prompt":"As output increases in the short run, average fixed cost","options":["remains constant","falls continuously","first falls and then rises","rises continuously"],"correctOption":1,"section":"Costs of Production","explanation":"AFC = TFC/Q, and since TFC is a fixed amount spread over more and more units, AFC keeps falling as output rises, giving a rectangular hyperbola; B is right. Option C describes the U-shaped AVC, ATC and MC curves, and Option A describes total fixed cost, not fixed cost per unit."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 783, $official_bank_source${"itemId":"83f019ef-8139-5d62-9c64-56a0b4a56775","questionId":"973c2a8b-ccb7-578a-bea3-1d0c6ab6f328","sourceKey":"bank:ECO201:CST-010","payload":{"prompt":"The short-run average variable cost and average total cost curves are U-shaped mainly because of","options":["economies and diseconomies of scale","the law of variable proportions (diminishing returns)","rising input prices across the whole industry","constant returns to scale"],"correctOption":1,"section":"Costs of Production","explanation":"In the short run, rising and then falling marginal product of the variable input first lowers and then raises cost per unit, which gives AVC and ATC their U-shape, so B is correct. Option A explains the U-shape of the long-run average cost curve, where all inputs are variable, and Option D would give a flat long-run cost curve."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 784, $official_bank_source${"itemId":"8c20043c-e2cb-5221-a728-bf3ae189e093","questionId":"9a178924-a03f-5abb-9f15-6f924e996d99","sourceKey":"bank:ECO201:CST-011","payload":{"prompt":"The long-run average cost curve is U-shaped mainly because of","options":["economies and diseconomies of scale","the fixity of plant size","the continuous fall in average fixed cost","the law of diminishing marginal returns"],"correctOption":0,"section":"Costs of Production","explanation":"In the long run all inputs are variable, so the shape of LRAC comes from scale effects: economies of scale lower average cost as the firm grows, and diseconomies raise it beyond some size, making A right. Options D and B are short-run ideas that depend on a fixed input, and Option C cannot apply because there are no fixed costs in the long run."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 785, $official_bank_source${"itemId":"598d809c-4b64-569d-a685-e4dbf08c02c4","questionId":"9a8a3e42-1ebb-5321-8c93-86dd83850d4a","sourceKey":"bank:ECO201:CST-012","payload":{"prompt":"The marginal cost curve cuts the AVC and ATC curves","options":["where they are falling most steeply","at their minimum points","at their maximum points","only where fixed cost is zero"],"correctOption":1,"section":"Costs of Production","explanation":"When MC is below an average it pulls the average down, and when MC is above it pushes the average up, so MC must cross AVC and ATC from below exactly at their lowest points; B is correct. Option C is wrong because the U-shaped AVC and ATC have no maximum in the relevant range, and Option A is wrong because MC is below them where they are falling."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 786, $official_bank_source${"itemId":"c231a3bf-56e4-569a-a7fb-db7df887c7c7","questionId":"a32f8010-65fd-5b8e-b75c-a49df50d5fd4","sourceKey":"bank:ECO201:CST-013","payload":{"prompt":"When marginal cost is below average total cost, average total cost is","options":["rising","constant","falling","at its minimum"],"correctOption":2,"section":"Costs of Production","explanation":"If producing one more unit costs less than the current average, adding that unit pulls the average down, so ATC is falling and C is right. Option A happens when MC is above ATC, and Option D happens only where MC exactly equals ATC."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 787, $official_bank_source${"itemId":"f80615c8-5e42-5b71-8cb5-8504853ae065","questionId":"92ea0261-d739-5290-8dfa-e24ede8d9cbf","sourceKey":"bank:ECO201:CST-014","payload":{"prompt":"The minimum point of the average variable cost curve occurs","options":["at a higher output than the minimum point of the ATC curve","at a lower output than the minimum point of the ATC curve","at the output where MC is at its minimum","at the same output as the minimum point of the ATC curve"],"correctOption":1,"section":"Costs of Production","explanation":"ATC = AVC + AFC, and because AFC is still falling when AVC starts to rise, ATC keeps falling for a while after AVC has turned up; so MC cuts AVC at its minimum first and ATC at a larger output, making B correct. Option A reverses the order, and Option C is wrong because MC reaches its own minimum before it cuts AVC."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 788, $official_bank_source${"itemId":"09e4cf1d-c5ff-5ed0-9e23-ac0b3e709d2a","questionId":"124f9017-c5fa-539d-a72c-41d629900bdb","sourceKey":"bank:ECO201:CST-016","payload":{"prompt":"A restaurant in Victoria Island has its monthly shop rent (a fixed cost) increased, while its food and staff costs per plate stay the same. In the short run this will","options":["raise AVC but leave ATC unchanged","lower AFC at every level of output","raise MC and ATC","raise ATC but leave MC and AVC unchanged"],"correctOption":3,"section":"Costs of Production","explanation":"A higher fixed cost raises AFC and therefore ATC at every output, but MC and AVC depend only on variable costs, so they do not change; D is correct. Option C is wrong because fixed cost does not affect the cost of producing an extra plate, and Option B is wrong because AFC rises, not falls."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 789, $official_bank_source${"itemId":"5d808785-b952-56b3-a67c-2f46dd6f61e6","questionId":"12f55d63-afa6-5ca8-8c54-432d60a1723c","sourceKey":"bank:ECO201:CST-017","payload":{"prompt":"The addition to total cost when output increases by one unit is called","options":["average variable cost","average total cost","marginal cost","total variable cost"],"correctOption":2,"section":"Costs of Production","explanation":"Marginal cost is the change in total cost (or total variable cost) from producing one more unit, MC = change in TC / change in Q, so C is right. Option B is total cost divided by output, Option A is variable cost divided by output, and Option D is the whole of variable cost rather than the extra amount."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 790, $official_bank_source${"itemId":"63ab7394-5695-58a7-aae3-085ca7e93309","questionId":"b1e6e698-3a2a-5d25-9599-3fb6a9b30f78","sourceKey":"bank:ECO201:CST-018","payload":{"prompt":"The long-run average cost curve is described as an envelope curve because","options":["it encloses the marginal cost curves of all firms in the industry","it is the horizontal sum of all the short-run average cost curves","it passes through the minimum point of every short-run average cost curve","it is tangent to a series of short-run average cost curves, one for each plant size"],"correctOption":3,"section":"Costs of Production","explanation":"Each point on the LRAC shows the lowest average cost of producing that output when the firm can pick the best plant size, so the LRAC wraps around and touches each SRAC curve, making D correct. Option C is tempting but wrong: with a U-shaped LRAC the tangency is at the SRAC's minimum only at the lowest point of the LRAC, and Option B describes how market supply curves are built."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 791, $official_bank_source${"itemId":"0892c030-7547-5d0c-9323-407531fe9083","questionId":"08ca4a98-f1da-580e-8c05-710f5f1a9aeb","sourceKey":"bank:ECO201:CST-019","payload":{"prompt":"A large bottling company in Ikeja obtains lower prices for sugar and bottles because it buys in very large quantities. This is an example of","options":["an internal economy of scale","an external diseconomy of scale","an external economy of scale","an internal diseconomy of scale"],"correctOption":0,"section":"Costs of Production","explanation":"Bulk-buying discounts come from the firm's own size, so they are an internal (purchasing or marketing) economy of scale, and A is right. Option C would arise from the growth of the whole industry or area rather than the firm itself, and Options D and B would raise, not lower, average cost."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 792, $official_bank_source${"itemId":"97a5b234-a063-5b55-800f-af75b45d765a","questionId":"1145e4d1-b60b-5ce6-81fb-50fa2c6fc2f3","sourceKey":"bank:ECO201:CST-020","payload":{"prompt":"Which of the following is an external economy of scale?","options":["A firm spreading its advertising costs over a larger output","A firm's ability to borrow more cheaply because it is large","A large firm using specialised machines","A pool of trained workers that develops as many firms cluster in one industrial area"],"correctOption":3,"section":"Costs of Production","explanation":"External economies come from the growth of the industry or location, not of the individual firm, and a shared pool of skilled labour benefits every firm in the cluster, so D is correct. Options B, C and A arise from the firm's own size and are internal economies (financial, technical and marketing)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 793, $official_bank_source${"itemId":"c1b5fe38-df77-5a23-aa08-07f642084273","questionId":"c536be5f-c5f1-5bea-8183-435243315768","sourceKey":"bank:ECO201:CST-021","payload":{"prompt":"Which of the following is an internal diseconomy of scale?","options":["Traffic congestion caused by many firms locating in one area","Bulk-buying discounts on raw materials","The growth of specialised suppliers near an industrial cluster","Communication and coordination problems as a firm becomes very large"],"correctOption":3,"section":"Costs of Production","explanation":"An internal diseconomy is a rise in average cost caused by the firm's own growth, such as management losing control and decisions slowing down, so D is right. Option A is an external diseconomy because it comes from the growth of the area, Option B is an internal economy, and Option C is an external economy."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 794, $official_bank_source${"itemId":"22b3a82d-83f6-5512-8966-b3c32d0a2b2c","questionId":"71c42ec5-cd61-5d91-be0a-f92f95488c0d","sourceKey":"bank:ECO201:CST-022","payload":{"prompt":"As many factories crowd into the Agbara industrial area, roads become congested and land rents rise for every firm there. This is","options":["an internal economy of scale","an external diseconomy of scale","an internal diseconomy of scale","an external economy of scale"],"correctOption":1,"section":"Costs of Production","explanation":"The higher costs come from the growth of the whole area and fall on all firms, not from any one firm's size, so they are an external diseconomy of scale and B is correct. Option C would arise inside a single growing firm, while Options D and A would lower rather than raise costs."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 795, $official_bank_source${"itemId":"6ec2653a-4ae5-594a-9b8c-0c0c35e57642","questionId":"44af288e-6fa7-57ef-bcc5-84782dd5dad3","sourceKey":"bank:ECO201:CST-023","payload":{"prompt":"Minimum efficient scale (MES) is","options":["the smallest output a firm is legally allowed to produce","the lowest level of output at which long-run average cost reaches its minimum","the output at which average fixed cost equals average variable cost","the output at which short-run marginal cost is at its minimum"],"correctOption":1,"section":"Costs of Production","explanation":"MES is the smallest scale of production at which a firm has exhausted its economies of scale and reached the lowest point of the LRAC, so B is right. Option D is a short-run idea about the MC curve, and Options A and C have nothing to do with how average cost changes with scale."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 796, $official_bank_source${"itemId":"1d4d3f9c-77bd-5fd6-8b4c-09eff7d915d7","questionId":"1d4c1792-6deb-5054-a777-f91ca7d9a001","sourceKey":"bank:ECO201:CST-024","payload":{"prompt":"Which of the following is NOT an internal economy of scale?","options":["Borrowing at lower interest rates because the firm is large","Hiring specialist managers for each department","Using larger and more efficient machines as the firm grows","Better roads and power supply built for a whole industrial estate"],"correctOption":3,"section":"Costs of Production","explanation":"Improved roads and power for a whole estate benefit every firm there, so they are an external economy, which makes D the answer. Options C, B and A come from the firm's own growth and are technical, managerial and financial internal economies."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 797, $official_bank_source${"itemId":"0ec58c1d-f7ce-574a-9dbd-96ef950ebf9d","questionId":"7ece028e-be02-5a41-8d32-3a4238ff6812","sourceKey":"bank:ECO201:CST-025","payload":{"prompt":"In economics, economic profit is equal to","options":["total revenue minus explicit and implicit costs","total revenue minus explicit costs only","total revenue minus total variable cost","price minus marginal cost"],"correctOption":0,"section":"Costs of Production","explanation":"Economic profit subtracts all opportunity costs, both explicit payments and the implicit cost of the owner's own resources, from total revenue, so A is correct. Option B is accounting profit, which will be larger whenever implicit costs exist, and Option C leaves out fixed costs."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 798, $official_bank_source${"itemId":"93c51071-c2fd-540d-99a0-33348af7138a","questionId":"5fbbfb55-36af-5a10-b33d-9f1bceee3a6c","sourceKey":"bank:ECO201:CST-026","payload":{"prompt":"A bakery in Ikorodu has the following short-run total cost schedule (TC in thousands of naira): output (batches) Q = 0, 1, 2, 3, 4, 5; TC = 100, 160, 200, 230, 280, 360. What is the bakery's total fixed cost?","options":["0","100","160","360"],"correctOption":1,"section":"Costs of Production","explanation":"Total fixed cost is the cost that must be paid even when output is zero, so TFC = TC at Q = 0 = 100 (thousand naira), and B is correct. Option A confuses zero output with zero cost, Option C is total cost at Q = 1, which includes variable cost, and Option D is total cost at Q = 5."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 799, $official_bank_source${"itemId":"fe2e9b74-ef5b-5128-8ad9-26ea61289d1a","questionId":"7aae84af-f53a-5b25-b0ff-febd82d7be60","sourceKey":"bank:ECO201:CST-027","payload":{"prompt":"A bakery in Ikorodu has the following short-run total cost schedule (TC in thousands of naira): output (batches) Q = 0, 1, 2, 3, 4, 5; TC = 100, 160, 200, 230, 280, 360. What is the marginal cost of the 3rd batch?","options":["76.67","43.33","30","230"],"correctOption":2,"section":"Costs of Production","explanation":"MC is the change in total cost from one more batch: 230 - 200 = 30 (thousand naira), so C is right. Option A is ATC at Q = 3 (230/3), Option B is AVC at Q = 3 (130/3), and Option D is total cost at Q = 3."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 800, $official_bank_source${"itemId":"5404e886-c1c7-5f66-a8d4-48f24cbb8af4","questionId":"bd922849-7af7-5935-b85f-61c38b44a7da","sourceKey":"bank:ECO201:CST-028","payload":{"prompt":"A bakery in Ikorodu has the following short-run total cost schedule (TC in thousands of naira): output (batches) Q = 0, 1, 2, 3, 4, 5; TC = 100, 160, 200, 230, 280, 360. What is the average variable cost at 2 batches?","options":["40","100","50","200"],"correctOption":2,"section":"Costs of Production","explanation":"TVC at Q = 2 is TC - TFC = 200 - 100 = 100, so AVC = 100/2 = 50 (thousand naira), and C is correct. Option B is ATC (200/2), which wrongly includes fixed cost, Option A is the marginal cost of the 2nd batch (200 - 160), and Option D is total cost."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 801, $official_bank_source${"itemId":"7d156254-898f-5c62-b5b0-a270527d391e","questionId":"e317084b-80f1-53e0-b04b-3c196aa52540","sourceKey":"bank:ECO201:CST-029","payload":{"prompt":"A bakery in Ikorodu has the following short-run total cost schedule (TC in thousands of naira): output (batches) Q = 0, 1, 2, 3, 4, 5; TC = 100, 160, 200, 230, 280, 360. What is the average fixed cost at 4 batches?","options":["100","45","70","25"],"correctOption":3,"section":"Costs of Production","explanation":"AFC = TFC/Q = 100/4 = 25 (thousand naira), so D is right. Option C is ATC at Q = 4 (280/4), Option B is AVC at Q = 4 (180/4), and Option A is total fixed cost, not fixed cost per batch."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 802, $official_bank_source${"itemId":"5c0fbf2a-9c09-5f40-9ecd-a7d9edf41b68","questionId":"7266adad-aa9b-5f33-96f5-03694c9f2b20","sourceKey":"bank:ECO201:CST-030","payload":{"prompt":"A bakery in Ikorodu has the following short-run total cost schedule (TC in thousands of naira): output (batches) Q = 0, 1, 2, 3, 4, 5; TC = 100, 160, 200, 230, 280, 360. What is the average total cost at 4 batches?","options":["280","50","45","70"],"correctOption":3,"section":"Costs of Production","explanation":"ATC = TC/Q = 280/4 = 70 (thousand naira), which also equals AVC (45) plus AFC (25), so D is correct. Option C is AVC alone, Option B is the marginal cost of the 4th batch (280 - 230), and Option A is total cost."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 803, $official_bank_source${"itemId":"17195940-fb63-5968-ab09-1d52713e8bbf","questionId":"078eff6c-4cf9-5303-8b62-6be5493ce8ec","sourceKey":"bank:ECO201:CST-031","payload":{"prompt":"A bakery in Ikorodu has the following short-run total cost schedule (TC in thousands of naira): output (batches) Q = 0, 1, 2, 3, 4, 5; TC = 100, 160, 200, 230, 280, 360. At what output is average variable cost at its minimum?","options":["4 batches","2 batches","5 batches","3 batches"],"correctOption":3,"section":"Costs of Production","explanation":"AVC values for Q = 1 to 5 are 60, 50, about 43.33, 45 and 52, so AVC is lowest at 3 batches, and D is right. Option A is where ATC is lowest (70), which comes at a larger output than the AVC minimum because AFC is still falling, and Option B is before AVC has stopped falling."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 804, $official_bank_source${"itemId":"03419451-9c91-569a-be22-6d020a9e1d07","questionId":"9ba5cf25-2700-523f-b23e-4ffaa5447607","sourceKey":"bank:ECO201:CST-032","payload":{"prompt":"A bakery in Ikorodu has the following short-run total cost schedule (TC in thousands of naira): output (batches) Q = 0, 1, 2, 3, 4, 5; TC = 100, 160, 200, 230, 280, 360. What is the marginal cost of the 5th batch?","options":["360","80","52","72"],"correctOption":1,"section":"Costs of Production","explanation":"MC of the 5th batch = 360 - 280 = 80 (thousand naira), so B is correct; since this MC is above ATC at 4 batches (70), ATC rises to 72. Option D is ATC at Q = 5 (360/5), Option C is AVC at Q = 5 (260/5), and Option A is total cost."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 805, $official_bank_source${"itemId":"f062f2d7-a0e5-5b84-92b8-9d59ca66124b","questionId":"5b8ea10a-f1cb-511c-9c0b-486ba7c7f7f2","sourceKey":"bank:ECO201:CST-033","payload":{"prompt":"A firm's short-run total cost function is TC = 500 + 30Q - 6Q^2 + 0.5Q^3. What is average fixed cost when Q = 10?","options":["50","5","70","500"],"correctOption":0,"section":"Costs of Production","explanation":"Total fixed cost is the constant term, 500, because it does not change with Q; so AFC = 500/10 = 50, and A is right. Option D is TFC rather than AFC, Option B divides by 100 instead of 10, and Option C is ATC at Q = 10 (700/10)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 806, $official_bank_source${"itemId":"bc2de89b-f690-5886-8101-e25bd7a7a325","questionId":"144c9b2e-48d1-587c-a2be-e839234a6a74","sourceKey":"bank:ECO201:CST-034","payload":{"prompt":"A firm's short-run total cost function is TC = 500 + 30Q - 6Q^2 + 0.5Q^3. What is marginal cost when Q = 10?","options":["30","60","20","70"],"correctOption":1,"section":"Costs of Production","explanation":"MC = dTC/dQ = 30 - 12Q + 1.5Q^2, so at Q = 10, MC = 30 - 120 + 150 = 60, and B is correct. Option D is ATC at Q = 10, Option C is AVC at Q = 10 (30 - 60 + 50), and Option A is just the first term of the MC function."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 807, $official_bank_source${"itemId":"b48fb6c1-fce5-5c69-be21-cf3d81d32030","questionId":"675e64b8-33d5-595d-8424-f08da5359c52","sourceKey":"bank:ECO201:CST-035","payload":{"prompt":"A firm's short-run total cost function is TC = 500 + 30Q - 6Q^2 + 0.5Q^3. At what level of output is average variable cost at its minimum?","options":["Q = 4","Q = 10","Q = 6","Q = 12"],"correctOption":2,"section":"Costs of Production","explanation":"AVC = TVC/Q = 30 - 6Q + 0.5Q^2, which is lowest where dAVC/dQ = -6 + Q = 0, so Q = 6; at that output MC = AVC = 12, as theory predicts, making C right. Option A is where MC is at its minimum, which comes before the AVC minimum, and Option D is where AVC has risen back to its starting value of 30."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 808, $official_bank_source${"itemId":"c0e6dd0a-cd1d-540f-8111-4a5884ab14a5","questionId":"ab34f400-4842-524f-9e48-7b204035401d","sourceKey":"bank:ECO201:CST-036","payload":{"prompt":"A firm's short-run total cost function is TC = 500 + 30Q - 6Q^2 + 0.5Q^3. What is the minimum value of average variable cost?","options":["30","6","12","18"],"correctOption":2,"section":"Costs of Production","explanation":"AVC = 30 - 6Q + 0.5Q^2 is minimised at Q = 6, giving AVC = 30 - 36 + 18 = 12, so C is correct. Option B is the minimum value of MC (at Q = 4), Option A is the constant term of AVC, and Option D is only the last term (0.5 x 36) of the calculation."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 809, $official_bank_source${"itemId":"c89cbf79-e032-5d4e-bba4-ac811bdac1f4","questionId":"5cb79476-c228-509b-835f-1f655ddf595a","sourceKey":"bank:ECO201:CST-037","payload":{"prompt":"A firm's short-run total cost function is TC = 500 + 30Q - 6Q^2 + 0.5Q^3. At what level of output is marginal cost at its minimum?","options":["Q = 2","Q = 4","Q = 6","Q = 12"],"correctOption":1,"section":"Costs of Production","explanation":"MC = 30 - 12Q + 1.5Q^2, and dMC/dQ = -12 + 3Q = 0 gives Q = 4, so B is right. Option C is where AVC is at its minimum, which comes after the MC minimum because MC must rise to cut AVC from below, and Options A and D come from errors in differentiating."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 810, $official_bank_source${"itemId":"a3f60cad-ae63-5b99-93d3-98caf775ddf2","questionId":"801159b4-f2a7-52cb-a4d7-a5e33420f351","sourceKey":"bank:ECO201:CST-038","payload":{"prompt":"A firm's short-run total cost function is TC = 500 + 30Q - 6Q^2 + 0.5Q^3. What is total variable cost when Q = 4?","options":["556","14","56","6"],"correctOption":2,"section":"Costs of Production","explanation":"TVC is total cost minus the fixed 500: TVC = 30Q - 6Q^2 + 0.5Q^3 = 120 - 96 + 32 = 56 at Q = 4, so C is correct. Option A is total cost (it adds the 500 fixed cost), Option B is AVC (56/4), and Option D is MC at Q = 4."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 811, $official_bank_source${"itemId":"edc5408f-1778-57f0-b282-71462226a174","questionId":"a85c1463-020c-520f-8e4c-f5cc17a2d1cd","sourceKey":"bank:ECO201:CST-039","payload":{"prompt":"A firm's short-run total cost function is TC = 100 + 20Q - 4Q^2 + Q^3. What is average total cost when Q = 5?","options":["20","25","55","45"],"correctOption":3,"section":"Costs of Production","explanation":"TC at Q = 5 is 100 + 100 - 100 + 125 = 225, so ATC = 225/5 = 45, and D is right. Option B is AVC (125/5), which leaves out fixed cost, Option A is AFC (100/5), and Option C is MC at Q = 5 (20 - 40 + 75)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 812, $official_bank_source${"itemId":"c9a568b6-98c2-53b7-83fc-8965ab224d32","questionId":"7f359dd1-0ee3-5c37-b2ef-9e7fa7fe48b3","sourceKey":"bank:ECO201:CST-040","payload":{"prompt":"Mr Adeyemi left a job paying N1,200,000 a year to run his own provision store in Surulere, using N3,000,000 of his savings that could have earned N300,000 interest a year in the bank. In one year the store earned total revenue of N5,000,000 and paid explicit costs of N3,000,000. What is his accounting profit for the year?","options":["N3,500,000","N800,000","N2,000,000","N500,000"],"correctOption":2,"section":"Costs of Production","explanation":"Accounting profit = total revenue - explicit costs = 5,000,000 - 3,000,000 = N2,000,000, so C is correct. Option D is economic profit, which also subtracts implicit costs, Option B subtracts only the forgone salary, and Option A subtracts the implicit costs but leaves out the explicit ones."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 813, $official_bank_source${"itemId":"d8848620-ce3b-59dd-977c-6e945fca437b","questionId":"4be599e4-25aa-5274-a0aa-8261cc77532b","sourceKey":"bank:ECO201:CST-041","payload":{"prompt":"Mr Adeyemi left a job paying N1,200,000 a year to run his own provision store in Surulere, using N3,000,000 of his savings that could have earned N300,000 interest a year in the bank. In one year the store earned total revenue of N5,000,000 and paid explicit costs of N3,000,000. What is his economic profit for the year?","options":["N500,000","N800,000","N2,000,000","N1,700,000"],"correctOption":0,"section":"Costs of Production","explanation":"Economic profit subtracts both explicit and implicit costs: 5,000,000 - 3,000,000 - 1,200,000 - 300,000 = N500,000, so A is right. Option C is accounting profit, Option B leaves out the forgone interest, and Option D leaves out the forgone salary."}}$official_bank_source$::jsonb);
insert into private.official_bank_rows (bank, part, ordinal, value) values
  ('official_bank_eco201', 'add', 814, $official_bank_source${"itemId":"591bccb2-854f-5771-9d4e-dc8b832a45e3","questionId":"0f8cec79-b590-5198-bb23-5befb3a797be","sourceKey":"bank:ECO201:CST-042","payload":{"prompt":"Mr Adeyemi left a job paying N1,200,000 a year to run his own provision store in Surulere, using N3,000,000 of his savings that could have earned N300,000 interest a year in the bank. In one year the store earned total revenue of N5,000,000 and paid explicit costs of N3,000,000. What is the total economic cost of running the store for the year?","options":["N4,500,000","N3,000,000","N4,200,000","N1,500,000"],"correctOption":0,"section":"Costs of Production","explanation":"Economic cost = explicit costs + implicit costs = 3,000,000 + 1,200,000 + 300,000 = N4,500,000, so A is correct. Option B is accounting cost (explicit costs only), Option D is implicit costs alone, and Option C leaves out the interest forgone on his savings."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 815, $official_bank_source${"itemId":"3f8d8593-f321-5cab-8618-83b747ad947f","questionId":"d59cf6af-2d52-50b1-9c36-8a4117145990","sourceKey":"bank:ECO201:CST-043","payload":{"prompt":"A fish-feed mill has a total fixed cost of N60,000 per month and produces 300 bags in a month. What is its average fixed cost?","options":["N200","N20","N2,000","N18,000,000"],"correctOption":0,"section":"Costs of Production","explanation":"AFC = TFC / Q = 60,000 / 300 = N200 per bag, so A is right. Options C and B misplace the decimal point, and Option D multiplies TFC by output instead of dividing."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 816, $official_bank_source${"itemId":"1ca2bd8b-4264-56ef-8c8d-f45b6f588247","questionId":"43361fda-e670-5cbb-9cfa-766aba376c33","sourceKey":"bank:ECO201:CST-044","payload":{"prompt":"At an output of 50 units, a firm's average fixed cost is N15 and its average variable cost is N35. What is its total cost?","options":["N2,500","N50","N750","N1,750"],"correctOption":0,"section":"Costs of Production","explanation":"ATC = AFC + AVC = 15 + 35 = N50, and TC = ATC x Q = 50 x 50 = N2,500, so A is correct. Option B is ATC rather than total cost, Option D is total variable cost (35 x 50), and Option C is total fixed cost (15 x 50)."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 817, $official_bank_source${"itemId":"8eef3a7f-18de-5112-8ba0-3af1ac93d14a","questionId":"21169dbf-0472-58cf-8988-0148741d094b","sourceKey":"bank:ECO201:CST-045","payload":{"prompt":"When a soap factory raises output from 100 to 110 cartons, its total cost rises from N12,000 to N14,500. What is the marginal cost per carton over this range?","options":["N131.82","N250","N120","N2,500"],"correctOption":1,"section":"Costs of Production","explanation":"MC = change in TC / change in Q = (14,500 - 12,000) / (110 - 100) = 2,500/10 = N250 per carton, so B is right. Option D forgets to divide by the 10 extra cartons, Option A is ATC at 110 cartons, and Option C is ATC at 100 cartons."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 818, $official_bank_source${"itemId":"6e476950-b924-509d-9818-029aa672fa8e","questionId":"a9300f7c-b457-5aa0-8509-65c12de4c0c6","sourceKey":"bank:ECO201:CST-046","payload":{"prompt":"The average total cost of producing 10 tables is N50,000 each, and the average total cost of producing 11 tables is N48,000 each. What is the marginal cost of the 11th table?","options":["N48,000","N28,000","N2,000","N528,000"],"correctOption":1,"section":"Costs of Production","explanation":"First find total costs: TC(10) = 10 x 50,000 = N500,000 and TC(11) = 11 x 48,000 = N528,000, so MC of the 11th table = 528,000 - 500,000 = N28,000, and B is correct. Option C wrongly subtracts the two averages, Option A is ATC at 11 tables, and Option D is total cost at 11 tables."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 819, $official_bank_source${"itemId":"5a515d73-bc54-5144-bca7-71fc064d7062","questionId":"caa3ff8d-faac-55a5-a171-b203d12df379","sourceKey":"bank:ECO201:CST-047","payload":{"prompt":"A firm's total cost function is TC = 400 + 5Q. What is its average total cost when Q = 100?","options":["N5","N905","N4","N9"],"correctOption":3,"section":"Costs of Production","explanation":"TC at Q = 100 is 400 + 500 = N900, so ATC = 900/100 = N9, and D is right. Option A is MC (and AVC), which equals the constant 5 for this linear cost function, Option C is AFC (400/100), and Option B wrongly adds 400 + 500 + 5."}}$official_bank_source$::jsonb),
  ('official_bank_eco201', 'add', 820, $official_bank_source${"itemId":"9f899cda-44dc-55df-bf31-1a66a11f496f","questionId":"9eecdd12-3ac2-59a3-8b22-c0a6e98f94e9","sourceKey":"bank:ECO201:CST-048","payload":{"prompt":"A detergent maker expands its plant. At 1,000 tonnes a year its long-run total cost is N500,000; at 2,000 tonnes a year it is N800,000. This shows","options":["constant returns to scale, since output doubles","diseconomies of scale, since total cost rises when output rises","diseconomies of scale, since long-run average cost rises from N400 to N500 per tonne","economies of scale, since long-run average cost falls from N500 to N400 per tonne"],"correctOption":3,"section":"Costs of Production","explanation":"LRAC = 500,000/1,000 = N500 per tonne before and 800,000/2,000 = N400 per tonne after, so average cost falls as scale rises, which is economies of scale; D is correct. Option B is wrong because total cost almost always rises with output; what matters is cost per unit, and Option C reverses the two averages."}}$official_bank_source$::jsonb);
    insert into public.courses (id, content_key, is_shared)
